/**
 * Minimal RFC-4180-ish CSV parser shared by the VFS `csv-to-sheet` command
 * and the Office write tools' VFS-staging path (`insert_table` dataFromFile).
 *
 * Handles quoted fields, escaped quotes (`""`), and `\r\n` / `\n` line breaks.
 * Trailing empty rows are dropped.
 */
export function parseCsv(text: string): string[][] {
  const source = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const rows: string[][] = [];
  let current = "";
  let inQuotes = false;
  let row: string[] = [];

  for (let i = 0; i < source.length; i++) {
    const ch = source[i];
    const next = source[i + 1];

    if (inQuotes) {
      if (ch === '"') {
        if (next === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ",") {
        row.push(current);
        current = "";
      } else if (ch === "\n") {
        row.push(current);
        current = "";
        if (row.length > 0) rows.push(row);
        row = [];
      } else if (ch === "\r") {
        // skip, \n will handle the row break
      } else {
        current += ch;
      }
    }
  }

  // Final field/row
  row.push(current);
  if (row.some((cell) => cell !== "")) rows.push(row);

  return rows;
}
