/**
 * Get all unique countries from the database
 */
export function getCountries(): string[] {
  return [
    ...new Set(
      WORLD_CITIES.filter((r) => r.type === "country").map((r) => r.country),
    ),
  ];
}

/**
 * Search for locations by name (exact or partial match)
 */
export function searchLocations(query: string, limit = 10): CityRecord[] {
  const normalizedQuery = query.toLowerCase().trim();
  const results: CityRecord[] = [];

  for (const record of WORLD_CITIES) {
    const nameMatch = record.name.toLowerCase().includes(normalizedQuery);
    const countryMatch = record.country.toLowerCase().includes(normalizedQuery);

    if (nameMatch || countryMatch) {
      results.push(record);
      if (results.length >= limit) break;
    }
  }

  return results;
}

/**
 * Find best match for a location query
 */
export function findBestMatch(query: string): CityRecord | null {
  const normalizedQuery = query.toLowerCase().trim();

  // Exact match first
  let match = WORLD_CITIES.find(
    (r) =>
      r.name.toLowerCase() === normalizedQuery ||
      r.country.toLowerCase() === normalizedQuery,
  );
  if (match) return match;

  // Then starts with
  match = WORLD_CITIES.find((r) =>
    r.name.toLowerCase().startsWith(normalizedQuery),
  );
  if (match) return match;

  // Then includes
  match = WORLD_CITIES.find((r) =>
    r.name.toLowerCase().includes(normalizedQuery),
  );
  if (match) return match;

  // Fuzzy: check if query is in country name
  match = WORLD_CITIES.find(
    (r) =>
      r.country.toLowerCase().includes(normalizedQuery) && r.type === "country",
  );
  if (match) return match;

  return null;
}
