const BASE_MAP_ALIASES: Record<string, string> = {
  usa: "usa",
  us: "usa",
  "u.s": "usa",
  "u.s.": "usa",
  "u.s.a": "usa",
  "u.s.a.": "usa",
  "united-states": "usa",
  "united-states-of-america": "usa",
};

function buildBaseMapCandidates(baseMap: string): string[] {
  const trimmed = baseMap.trim().toLowerCase();
  if (!trimmed) return [];

  const candidates = new Set<string>();
  const pushCandidate = (value: string) => {
    const candidate = value.trim().toLowerCase();
    if (!candidate) return;
    candidates.add(candidate);
    const alias = BASE_MAP_ALIASES[candidate];
    if (alias) {
      candidates.add(alias);
    }
  };

  pushCandidate(trimmed);

  // Allow file-style inputs such as "usa.svg".
  const withoutExt = trimmed.replace(/\.svg$/i, "");
  pushCandidate(withoutExt);

  pushCandidate(trimmed.replace(/\s+/g, "-"));
  pushCandidate(trimmed.replace(/\s+/g, ""));
  pushCandidate(trimmed.replace(/[^a-z0-9.-]/g, ""));
  pushCandidate(withoutExt.replace(/\s+/g, "-"));
  pushCandidate(withoutExt.replace(/\s+/g, ""));
  pushCandidate(withoutExt.replace(/[^a-z0-9.-]/g, ""));

  return Array.from(candidates);
}

function sanitizeSvgFragment(fragment: string): string {
  let cleaned = fragment;

  // Remove XML/doctype declarations if present in fragments.
  cleaned = cleaned.replace(/<\?xml[\s\S]*?\?>/gi, "");
  cleaned = cleaned.replace(/<!DOCTYPE[\s\S]*?>/gi, "");

  // Remove metadata/editor blocks that often carry undeclared namespace prefixes.
  cleaned = cleaned.replace(/<metadata[\s\S]*?<\/metadata>/gi, "");
  cleaned = cleaned.replace(
    /<sodipodi:namedview[^>]*\/?>(?:[\s\S]*?<\/sodipodi:namedview>)?/gi,
    "",
  );

  // Remove xmlns declarations and namespaced attributes from fragment elements.
  cleaned = cleaned.replace(/\s+xmlns(?::[\w.-]+)?\s*=\s*"[^"]*"/gi, "");
  cleaned = cleaned.replace(/\s+xmlns(?::[\w.-]+)?\s*=\s*'[^']*'/gi, "");
  cleaned = cleaned.replace(/\s+[\w.-]+:[\w.-]+\s*=\s*"[^"]*"/g, "");
  cleaned = cleaned.replace(/\s+[\w.-]+:[\w.-]+\s*=\s*'[^']*'/g, "");

  // Drop namespaced element tags that remain after attribute cleanup.
  cleaned = cleaned.replace(/<\/?[\w.-]+:[^>]*>/g, "");

  return cleaned.trim();
}

function getSvgViewBox(
  viewBox?: string,
  width?: string,
  height?: string,
): { x: number; y: number; width: number; height: number } {
  if (viewBox) {
    const parts = viewBox.split(/\s+/).map(Number);
    if (parts.length === 4 && parts[2] > 0 && parts[3] > 0) {
      return {
        x: parts[0],
        y: parts[1],
        width: parts[2],
        height: parts[3],
      };
    }
  }

  if (width && height) {
    const w = Number.parseFloat(width);
    const h = Number.parseFloat(height);
    if (w > 0 && h > 0) {
      return { x: 0, y: 0, width: w, height: h };
    }
  }

  return { x: 0, y: 0, width: 1000, height: 500 };
}

