function buildMapAssetUrls(assetPath: string): string[] {
  const normalizedPath = assetPath.replace(/^\/+/, "");
  const candidates = new Set<string>();

  candidates.add(`/${normalizedPath}`);
  candidates.add(normalizedPath);

  if (typeof document !== "undefined" && document.baseURI) {
    try {
      candidates.add(new URL(normalizedPath, document.baseURI).toString());
    } catch {
      // Ignore malformed document base URI.
    }
  }

  if (typeof window !== "undefined" && window.location?.href) {
    try {
      candidates.add(new URL(normalizedPath, window.location.href).toString());
    } catch {
      // Ignore malformed URL construction and rely on relative candidates.
    }
  }

  return Array.from(candidates);
}

async function fetchFirstAvailable(urls: string[]): Promise<Response | null> {
  for (const url of urls) {
    try {
      const response = await fetch(url);
      if (response.ok) {
        return response;
      }
    } catch {
      // Try next candidate URL.
    }
  }
  return null;
}

