/**
 * Parse geographic bounds from SVG map content or use known bounds
 */
function getMapGeoBounds(
  mapId: string,
  svgContent?: string,
): { minLng: number; minLat: number; maxLng: number; maxLat: number } | null {
  // Check cache first
  if (mapBoundsCache.has(mapId)) {
    return mapBoundsCache.get(mapId)!;
  }

  // Check known bounds
  if (MAP_GEO_BOUNDS[mapId.toLowerCase()]) {
    const bounds = MAP_GEO_BOUNDS[mapId.toLowerCase()];
    mapBoundsCache.set(mapId, bounds);
    return bounds;
  }

  // Try to extract from SVG content (looking for geoViewBox or similar metadata)
  if (svgContent) {
    // Look for geoViewBox attribute common in map SVGs
    const geoMatch = svgContent.match(/geoViewBox\s*=\s*["']([^"']+)["']/i);
    if (geoMatch) {
      // Format: "minLng minLat maxLng maxLat" or "minLng maxLat maxLng minLat"
      const parts = geoMatch[1].split(/\s+/).map(Number);
      if (parts.length === 4) {
        // Assume: West North East South format (common in map SVGs)
        // or minLng maxLat maxLng minLat
        const [v1, v2, v3, v4] = parts;
        // Detect if values are lat/lng
        if (v1 >= -180 && v1 <= 180 && v3 >= -180 && v3 <= 180) {
          // v1 and v3 are longitudes
          let bounds: (typeof MAP_GEO_BOUNDS)[string];
          if (v2 > v4) {
            // Format: minLng maxLat maxLng minLat
            bounds = { minLng: v1, maxLat: v2, maxLng: v3, minLat: v4 };
          } else {
            // Format: minLng minLat maxLng maxLat
            bounds = { minLng: v1, minLat: v2, maxLng: v3, maxLat: v4 };
          }
          mapBoundsCache.set(mapId, bounds);
          return bounds;
        }
      }
    }

    // Look for viewBox to estimate bounds fallback
    const viewBoxMatch = svgContent.match(/viewBox\s*=\s*["']([^"']+)["']/i);
    if (viewBoxMatch) {
      // We could add logic here to parse viewBox if we know the map's projection
      // For now, rely on known bounds
    }
  }

  return null;
}

/**
 * Check if a point is within bounds (with optional padding)
 */
function pointInBounds(
  lat: number,
  lng: number,
  bounds: { minLng: number; minLat: number; maxLng: number; maxLat: number },
  padding = 0.01, // Small padding to allow points near boundaries
): boolean {
  return (
    lat >= bounds.minLat - padding &&
    lat <= bounds.maxLat + padding &&
    lng >= bounds.minLng - padding &&
    lng <= bounds.maxLng + padding
  );
}

/**
 * Find the best US state map for a set of points.
 * Returns null if points span multiple states or don't fit well in a state map.
 */
function findBestUSStateMap(points: Array<{ lat: number; lng: number }>): {
  mapId: string;
  bounds: { minLng: number; minLat: number; maxLng: number; maxLat: number };
} | null {
  if (points.length === 0) return null;

  // Get all state maps from MAP_GEO_BOUNDS
  const stateMaps = Object.entries(MAP_GEO_BOUNDS)
    .filter(([id]) => id.startsWith("usa-"))
    .map(([id, bounds]) => ({ id, bounds }));

  // Find state maps that contain ALL points
  const candidates: Array<{
    mapId: string;
    bounds: (typeof MAP_GEO_BOUNDS)[string];
    coverage: number;
  }> = [];

  for (const { id, bounds } of stateMaps) {
    // Check if all points fit within this state's bounds (with some margin)
    const allFit = points.every((p) =>
      pointInBounds(p.lat, p.lng, bounds, 0.05),
    );

    if (allFit) {
      // Calculate how much of the state the points actually cover
      // (we want states where points cover a significant portion, not tiny specs)
      const lats = points.map((p) => p.lat);
      const lngs = points.map((p) => p.lng);
      const pointSpanLat = Math.max(...lats) - Math.min(...lats);
      const pointSpanLng = Math.max(...lngs) - Math.min(...lngs);
      const stateSpanLat = bounds.maxLat - bounds.minLat;
      const stateSpanLng = bounds.maxLng - bounds.minLng;

      // Coverage ratio - higher means points cover more of the state
      const coverage =
        (pointSpanLat / stateSpanLat) * (pointSpanLng / stateSpanLng);

      candidates.push({ mapId: id, bounds, coverage });
    }
  }

  // Sort by coverage - prefer states where points cover more of the map
  candidates.sort((a, b) => b.coverage - a.coverage);

  // Return best candidate, or null if none found
  return candidates.length > 0
    ? { mapId: candidates[0].mapId, bounds: candidates[0].bounds }
    : null;
}

/**
 * Project lat/lng coordinates to SVG coordinates using local map bounds
 * Accounts for viewBox offsets when present
 */
function projectToLocalMap(
  lat: number,
  lng: number,
  bounds: { minLng: number; minLat: number; maxLng: number; maxLat: number },
  svgBox: { x: number; y: number; width: number; height: number },
): { x: number; y: number } {
  // Calculate normalized position (0-1) within geographic bounds
  const xNorm = (lng - bounds.minLng) / (bounds.maxLng - bounds.minLng);
  const yNorm = (lat - bounds.minLat) / (bounds.maxLat - bounds.minLat);

  // Map to SVG coordinates within the viewBox (y is inverted because SVG y=0 is at top)
  // Then add the viewBox offset to align with the base map's coordinate system
  const x = svgBox.x + xNorm * svgBox.width;
  const y = svgBox.y + (1 - yNorm) * svgBox.height;

  return {
    x: Math.round(x),
    y: Math.round(y),
  };
}

