/**
 * Mercator projection (simplified)
 */
function mercator(
  lat: number,
  lng: number,
  width: number,
  height: number,
): { x: number; y: number } {
  // Map lng to x (-180 to 180 mapped to 0-800 base)
  const x = ((lng + 180) / 360) * 800;

  // Map lat to y using Mercator formula
  const latRad = (lat * Math.PI) / 180;
  const mercY = Math.log(Math.tan(latRad) + 1 / Math.cos(latRad));
  const y = ((Math.PI - mercY) / (2 * Math.PI)) * 450 + 50; // Adjust to fit world in 500 height

  // Scale to requested dimensions
  const scaleX = width / 800;
  const scaleY = height / 500;

  return {
    x: Math.round(x * scaleX),
    y: Math.round(y * scaleY),
  };
}

/**
 * Great circle distance in kilometers
 */
function haversineDistance(
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number,
): number {
  const R = 6371; // Earth's radius in km
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLng / 2) *
      Math.sin(dLng / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

type SupportedProjectedCrs =
  | "auto-fit"
  | "epsg:3857"
  | "web-mercator"
  | "epsg:4326"
  | "wgs84";

function normalizeProjectedCrs(crs?: string): SupportedProjectedCrs {
  if (!crs || !crs.trim()) return "auto-fit";
  const normalized = crs.trim().toLowerCase();
  if (
    normalized === "epsg:3857" ||
    normalized === "3857" ||
    normalized === "webmercator" ||
    normalized === "web-mercator"
  ) {
    return "epsg:3857";
  }
  if (
    normalized === "epsg:4326" ||
    normalized === "4326" ||
    normalized === "wgs84" ||
    normalized === "wgs-84"
  ) {
    return "epsg:4326";
  }
  return "auto-fit";
}

function webMercatorToWgs84(
  x: number,
  y: number,
): { lat: number; lng: number } | null {
  // EPSG:3857 inverse transform
  const lng = (x / 20037508.34) * 180;
  const lat =
    (180 / Math.PI) * (2 * Math.atan(Math.exp(y / 6378137)) - Math.PI / 2);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return null;
  }
  if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
    return null;
  }
  return { lat, lng };
}

/**
 * Generate color scale
 */
function generateColor(
  value: number,
  min: number,
  max: number,
  colorScheme: string,
): string {
  if (max === min) return "#4f46e5"; // Default indigo

  const normalized = (value - min) / (max - min);

  switch (colorScheme) {
    case "blue": {
      // White to dark blue
      const blue = Math.round(255 * (1 - normalized));
      return `rgb(${blue}, ${blue}, 255)`;
    }
    case "red": {
      // Light pink to dark red
      const red = Math.round(255 - 100 * normalized);
      return `rgb(${red}, ${Math.round(200 * (1 - normalized))}, ${Math.round(200 * (1 - normalized))})`;
    }
    case "green": {
      // Light to dark green
      const green = Math.round(100 + 155 * normalized);
      return `rgb(${Math.round(50 * (1 - normalized))}, ${green}, ${Math.round(50 * (1 - normalized))})`;
    }
    case "heatmap": {
      // Red (high) -> Yellow -> Green (low)
      if (normalized > 0.5) {
        const intensity = (normalized - 0.5) * 2;
        return `rgb(255, ${Math.round(255 * (1 - intensity))}, 0)`;
      }
      const intensity = normalized * 2;
      return `rgb(${Math.round(255 * intensity)}, 255, 0)`;
    }
    default: {
      // Simplified viridis-like gradient
      const colors = [
        [68, 1, 84],
        [72, 35, 116],
        [64, 67, 136],
        [52, 94, 141],
        [41, 120, 142],
        [32, 144, 140],
        [34, 167, 132],
        [68, 190, 112],
        [121, 209, 81],
        [189, 223, 38],
        [253, 231, 36],
      ];
      const idx = Math.min(
        Math.floor(normalized * colors.length),
        colors.length - 1,
      );
      const color = colors[idx];
      return `rgb(${color[0]}, ${color[1]}, ${color[2]})`;
    }
  }
}

/**
 * Generate an SVG world map with points
 */
function generatePointMap(
  points: Array<{ lat: number; lng: number; label?: string; value?: number }>,
  options: {
    width: number;
    height: number;
    showLabels: boolean;
    colorScheme: string;
    title?: string;
    valueColumn?: string;
    baseMapContent?: string | null;
    baseMapId?: string | null;
    baseMapViewBox?: string;
    baseMapWidth?: string;
    baseMapHeight?: string;
    projectedSvgPoints?: Array<{
      x: number;
      y: number;
      label?: string;
      value?: number;
    }>;
  },
): string {
  const {
    width,
    height,
    showLabels,
    colorScheme,
    title,
    valueColumn,
    baseMapContent,
    baseMapId,
    baseMapViewBox,
    baseMapWidth,
    baseMapHeight,
    projectedSvgPoints = [],
  } = options;

  // Calculate value range if we have values
  const hasValues =
    valueColumn &&
    (points.some((p) => p.value !== undefined) ||
      projectedSvgPoints.some((p) => p.value !== undefined));
  const values = hasValues
    ? [...points, ...projectedSvgPoints].map((p) => p.value || 0)
    : [];
  const minValue = hasValues ? Math.min(...values) : 0;
  const maxValue = hasValues ? Math.max(...values) : 0;

  // Calculate point sizes based on values
  const maxPointSize = hasValues ? 20 : 8;
  const minPointSize = hasValues ? 5 : 5;

  // Get map bounds for proper geographic projection
  const mapBounds = baseMapId
    ? getMapGeoBounds(baseMapId, baseMapContent ?? undefined)
    : null;
  const isLocalMap = !!baseMapContent && mapBounds;

  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`;
  svg += "<style>";
  svg += "text { font-family: Arial, sans-serif; font-size: 10px; }";
  svg += ".point-label { font-size: 9px; fill: #333; }";
  svg += "</style>";

  // Background
  svg += `<rect width="${width}" height="${height}" fill="#f0f4f8"/>`;

  // Title
  if (title) {
    svg += `<text x="${width / 2}" y="20" text-anchor="middle" font-size="14" font-weight="bold" fill="#1a1a1a">${title.replace(/[<>]/g, "")}</text>`;
  }

  const chartTop = title ? 40 : 10;
  const chartHeight = height - chartTop - 30;
  const chartWidth = width - 40;

  // For local maps, we need the SVG's viewBox dimensions and offsets
  // Some maps like usa.svg have viewBox="477 421 593 318" where 477,421 are x,y offsets
  // usa-va.svg has width="84.47" height="48.33" instead of viewBox
  let localViewBox = { x: 0, y: 0, width: 1000, height: 500 }; // defaults for world map approximations

  // Use passed SVG metadata if available, otherwise parse from content (legacy fallback)
  let svgViewBox = baseMapViewBox;
  let svgWidth = baseMapWidth;
  let svgHeight = baseMapHeight;

  // If metadata not passed, try to extract from content (for backwards compatibility)
  if (
    isLocalMap &&
    baseMapContent &&
    (!svgViewBox || (!svgWidth && !svgHeight))
  ) {
    // Try to extract viewBox from the SVG content
    const viewBoxMatch = baseMapContent.match(
      /viewBox\s*=\s*["']([^"']+)["']/i,
    );
    if (viewBoxMatch) {
      svgViewBox = viewBoxMatch[1];
    }
    // Try width/height attributes
    const widthMatch = baseMapContent.match(
      /<svg[^>]*width\s*=\s*["']([\d.]+)["']/i,
    );
    const heightMatch = baseMapContent.match(
      /<svg[^>]*height\s*=\s*["']([\d.]+)["']/i,
    );
    if (widthMatch) svgWidth = widthMatch[1];
    if (heightMatch) svgHeight = heightMatch[1];
  }

  // Parse viewBox or use width/height to get local dimensions
  localViewBox = getSvgViewBox(svgViewBox, svgWidth, svgHeight);

  // Calculate zoom to data region for local maps with clustered data
  let zoomedViewBox = { ...localViewBox };
  let isZoomed = false;

  if (
    isLocalMap &&
    mapBounds &&
    projectedSvgPoints.length === 0 &&
    points.length > 0
  ) {
    // Calculate data bounds
    const lats = points.map((p) => p.lat);
    const lngs = points.map((p) => p.lng);
    const dataBounds = {
      minLat: Math.min(...lats),
      maxLat: Math.max(...lats),
      minLng: Math.min(...lngs),
      maxLng: Math.max(...lngs),
    };

    // Check if data covers less than 40% of the map in both dimensions
    const latRatio =
      (dataBounds.maxLat - dataBounds.minLat) /
      (mapBounds.maxLat - mapBounds.minLat);
    const lngRatio =
      (dataBounds.maxLng - dataBounds.minLng) /
      (mapBounds.maxLng - mapBounds.minLng);

    if (latRatio < 0.4 || lngRatio < 0.4) {
      // Add padding (50%) around data bounds
      const latPadding = (dataBounds.maxLat - dataBounds.minLat) * 0.5;
      const lngPadding = (dataBounds.maxLng - dataBounds.minLng) * 0.5;

      const paddedBounds = {
        minLat: Math.max(mapBounds.minLat, dataBounds.minLat - latPadding),
        maxLat: Math.min(mapBounds.maxLat, dataBounds.maxLat + latPadding),
        minLng: Math.max(mapBounds.minLng, dataBounds.minLng - lngPadding),
        maxLng: Math.min(mapBounds.maxLng, dataBounds.maxLng + lngPadding),
      };

      // Convert geo bounds to local SVG coordinates
      const minPos = projectToLocalMap(
        paddedBounds.minLat,
        paddedBounds.minLng,
        mapBounds,
        localViewBox,
      );
      const maxPos = projectToLocalMap(
        paddedBounds.maxLat,
        paddedBounds.maxLng,
        mapBounds,
        localViewBox,
      );

      // Calculate zoomed viewBox (SVG uses top-down y, so swap min/max for y)
      const vx = Math.min(minPos.x, maxPos.x);
      const vy = Math.min(minPos.y, maxPos.y);
      const vw = Math.abs(maxPos.x - minPos.x);
      const vh = Math.abs(maxPos.y - minPos.y);

      // Only zoom if the resulting view would be at least 20% of the original in each dimension
      // AND the zoom would result in a scale of at most 8x
      const minDimension = Math.min(vw, vh);
      const originalMinDim = Math.min(localViewBox.width, localViewBox.height);

      if (minDimension > originalMinDim * 0.2) {
        const scaleLimit = 8;
        const maxScale = Math.max(
          localViewBox.width / vw,
          localViewBox.height / vh,
        );

        if (maxScale <= scaleLimit) {
          zoomedViewBox = {
            x: vx,
            y: vy,
            width: vw,
            height: vh,
          };
          isZoomed = true;
        }
      }
    }
  }

  if (isLocalMap && projectedSvgPoints.length > 0) {
    const xs = projectedSvgPoints.map((p) => p.x);
    const ys = projectedSvgPoints.map((p) => p.y);
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
    const spanX = maxX - minX;
    const spanY = maxY - minY;

    // Zoom directly in SVG coordinates for projected datasets.
    if (spanX > 0 && spanY > 0) {
      const padX = spanX * 0.2;
      const padY = spanY * 0.2;
      zoomedViewBox = {
        x: minX - padX,
        y: minY - padY,
        width: spanX + padX * 2,
        height: spanY + padY * 2,
      };
      isZoomed = true;
    }
  }

  // Calculate scale to fit the (potentially zoomed) viewBox within the chart area
  const scaleX = chartWidth / zoomedViewBox.width;
  const scaleY = chartHeight / zoomedViewBox.height;

  // Use external base map if available, otherwise use simplified continents
  if (baseMapContent) {
    // Create a nested SVG element with the original viewBox to preserve coordinate system
    // This allows the embedded map SVG to scale properly while keeping point coordinates aligned
    svg += `<svg x="20" y="${chartTop}" width="${chartWidth}" height="${chartHeight}" viewBox="${zoomedViewBox.x} ${zoomedViewBox.y} ${zoomedViewBox.width} ${zoomedViewBox.height}" preserveAspectRatio="none">`;
    svg += `<style><![CDATA[
	path { fill: #d4c5b0 !important; stroke: #666 !important; stroke-width: 0.4 !important; }
	path:hover { fill: #b8a898 !important; }
]]></style>`;
    svg += baseMapContent;
  } else {
    // Simple world map background (water)
    svg += `<rect x="20" y="${chartTop}" width="${chartWidth}" height="${chartHeight}" fill="#a5c4d9" stroke="#666" stroke-width="0.5"/>`;

    // Draw simplified continents (very approximate)
    // Using Mercator projection reference points
    const continentPaths = [
      // North America
      "M50,30 L180,25 L280,40 L320,80 L300,130 L250,160 L200,180 L120,170 L60,140 L40,90 Z",
      // South America
      "M220,200 L270,200 L300,250 L290,320 L250,380 L210,390 L180,350 L190,280 Z",
      // Europe
      "M400,35 L470,30 L520,35 L540,60 L520,90 L480,100 L430,95 L400,75 Z",
      // Africa
      "M410,110 L470,105 L510,130 L530,190 L510,250 L460,290 L410,270 L390,210 L400,150 Z",
      // Asia
      "M520,25 L620,20 L700,35 L750,60 L760,110 L720,150 L650,170 L580,150 L550,110 L540,60 Z",
      // Australia
      "M680,260 L750,250 L780,280 L770,320 L730,340 L690,330 L670,300 Z",
    ];

    for (const path of continentPaths) {
      svg += `<path d="${path}" fill="#d4c5b0" stroke="#999" stroke-width="0.5" transform="translate(20,${chartTop}) scale(${chartWidth / 800})"/>`;
    }
  }

  // Draw grid lines (lat/lng) - only for world map
  if (!isLocalMap) {
    for (let lng = -180; lng <= 180; lng += 60) {
      const pos = mercator(0, lng, chartWidth, chartHeight);
      svg += `<line x1="${20 + pos.x}" y1="${chartTop}" x2="${20 + pos.x}" y2="${chartTop + chartHeight}" stroke="#ccc" stroke-width="0.5" opacity="0.5"/>`;
    }
    for (let lat = -60; lat <= 60; lat += 30) {
      const pos = mercator(lat, 0, chartWidth, chartHeight);
      svg += `<line x1="20" y1="${chartTop + pos.y}" x2="${20 + chartWidth}" y2="${chartTop + pos.y}" stroke="#ccc" stroke-width="0.5" opacity="0.5"/>`;
    }
  }

  // Draw points from lat/lng inputs
  for (const point of points) {
    // Calculate position
    let pos: { x: number; y: number };
    let pointRadius: number;

    if (isLocalMap && mapBounds) {
      // For local maps, project to the map's coordinate system
      pos = projectToLocalMap(point.lat, point.lng, mapBounds, localViewBox);
      // Scale radius to match the map's coordinate system (don't scale by chart size)
      pointRadius =
        hasValues && point.value !== undefined
          ? minPointSize +
            (maxValue === minValue
              ? 0.5
              : (point.value - minValue) / (maxValue - minValue)) *
              (maxPointSize - minPointSize)
          : 5;
    } else {
      // For world map, use Mercator in screen coordinates
      pos = mercator(point.lat, point.lng, chartWidth, chartHeight);
      pos.x += 20; // Add margin
      pos.y += chartTop;
      pointRadius =
        hasValues && point.value !== undefined
          ? minPointSize +
            (maxValue === minValue
              ? 0.5
              : (point.value - minValue) / (maxValue - minValue)) *
              (maxPointSize - minPointSize)
          : 5;
    }

    let color = "#e11d48"; // Default red
    if (hasValues && point.value !== undefined) {
      const normalizedValue =
        maxValue === minValue
          ? 0.5
          : (point.value - minValue) / (maxValue - minValue);
      color = generateColor(point.value, minValue, maxValue, colorScheme);
    }

    // For local maps with nested SVG, points need to be in the nested SVG's coordinate space
    // For world map, points are in absolute coordinates
    if (isLocalMap && baseMapContent) {
      // Points go inside the nested SVG element, so they use viewBox coordinates
      svg += `<circle cx="${pos.x}" cy="${pos.y}" r="${pointRadius}" fill="${color}" stroke="#fff" stroke-width="0.5"/>`;
      if (showLabels && point.label) {
        svg += `<text x="${pos.x + pointRadius + 2}" y="${pos.y + 3}" font-size="9" class="point-label">${point.label.replace(/[<>]/g, "").substring(0, 20)}</text>`;
      }
    } else {
      svg += `<circle cx="${pos.x}" cy="${pos.y}" r="${pointRadius}" fill="${color}" stroke="#fff" stroke-width="1"/>`;
      if (showLabels && point.label) {
        svg += `<text x="${pos.x + pointRadius + 2}" y="${pos.y + 3}" class="point-label">${point.label.replace(/[<>]/g, "").substring(0, 20)}</text>`;
      }
    }
  }

  // Draw points provided directly in local SVG coordinates (best for projected datasets)
  for (const point of projectedSvgPoints) {
    const pointRadius =
      hasValues && point.value !== undefined
        ? minPointSize +
          (maxValue === minValue
            ? 0.5
            : (point.value - minValue) / (maxValue - minValue)) *
            (maxPointSize - minPointSize)
        : 5;
    const color =
      hasValues && point.value !== undefined
        ? generateColor(point.value, minValue, maxValue, colorScheme)
        : "#e11d48";

    svg += `<circle cx="${point.x}" cy="${point.y}" r="${pointRadius}" fill="${color}" stroke="#fff" stroke-width="0.5"/>`;
    if (showLabels && point.label) {
      svg += `<text x="${point.x + pointRadius + 2}" y="${point.y + 3}" font-size="9" class="point-label">${point.label.replace(/[<>]/g, "").substring(0, 20)}</text>`;
    }
  }

  // Close the nested SVG if using local map
  if (baseMapContent) {
    svg += "</svg>";
  }

  // Legend for colored values
  if (hasValues) {
    const legendY = height - 20;
    svg += `<text x="20" y="${legendY - 5}" font-size="10" fill="#666">${valueColumn}:</text>`;

    for (let i = 0; i <= 5; i++) {
      const value = minValue + ((maxValue - minValue) * i) / 5;
      const color = generateColor(value, minValue, maxValue, colorScheme);
      svg += `<circle cx="${100 + i * 50}" cy="${legendY}" r="6" fill="${color}"/>`;
      svg += `<text x="${100 + i * 50}" y="${legendY + 12}" text-anchor="middle" font-size="8" fill="#666">${Math.round(value)}</text>`;
    }
  }

  // Attribution
  const attribution = baseMapContent
    ? `Map: ${baseMapId || "Custom"}`
    : "Map: Simplified projection";
  svg += `<text x="${width - 5}" y="${height - 5}" text-anchor="end" font-size="8" fill="#999">${attribution}</text>`;

  svg += "</svg>";
  return svg;
}

/**
 * Generate a choropleth (shaded region map)
 * For now, shows regions as circular areas around centroids
 */
function generateChoroplethMap(
  regions: Array<{ name: string; lat: number; lng: number; value: number }>,
  options: {
    width: number;
    height: number;
    colorScheme: string;
    title?: string;
    baseMapContent?: string | null;
  },
): string {
  const { width, height, colorScheme, title, baseMapContent } = options;

  // Calculate value range
  const values = regions.map((r) => r.value);
  const minValue = Math.min(...values);
  const maxValue = Math.max(...values);

  const chartWidth = width - 40;
  const chartHeight = height - 60;
  const chartTop = title ? 40 : 10;

  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`;
  svg += "<style>text { font-family: Arial, sans-serif; }</style>";

  // Background
  svg += `<rect width="${width}" height="${height}" fill="#f0f4f8"/>`;

  // Title
  if (title) {
    svg += `<text x="${width / 2}" y="20" text-anchor="middle" font-size="14" font-weight="bold" fill="#1a1a1a">${title.replace(/[<>]/g, "")}</text>`;
  }

  // Use external base map if available, otherwise use simplified continents
  if (baseMapContent) {
    svg += `<g transform="translate(20,${chartTop}) scale(${chartWidth / 1000}, ${chartHeight / 500})">`;
    // Add style to override the SVG path fills and strokes for better visibility
    svg += `<style><![CDATA[
	path { fill: #d4c5b0 !important; stroke: #666 !important; stroke-width: 0.4 !important; }
	path:hover { fill: #b8a898 !important; }
]]></style>`;
    svg += baseMapContent;
    svg += "</g>";
  } else {
    // Continents background
    svg += `<rect x="20" y="${chartTop}" width="${chartWidth}" height="${chartHeight}" fill="#a5c4d9" stroke="#666" stroke-width="0.5"/>`;

    const continentPaths = [
      "M50,30 L180,25 L280,40 L320,80 L300,130 L250,160 L200,180 L120,170 L60,140 L40,90 Z",
      "M220,200 L270,200 L300,250 L290,320 L250,380 L210,390 L180,350 L190,280 Z",
      "M400,35 L470,30 L520,35 L540,60 L520,90 L480,100 L430,95 L400,75 Z",
      "M410,110 L470,105 L510,130 L530,190 L510,250 L460,290 L410,270 L390,210 L400,150 Z",
      "M520,25 L620,20 L700,35 L750,60 L760,110 L720,150 L650,170 L580,150 L550,110 L540,60 Z",
      "M680,260 L750,250 L780,280 L770,320 L730,340 L690,330 L670,300 Z",
    ];

    for (const path of continentPaths) {
      svg += `<path d="${path}" fill="#d4c5b0" stroke="#999" stroke-width="0.5" transform="translate(20,${chartTop}) scale(${chartWidth / 800})"/>`;
    }
  }

  // Draw shaded regions
  for (const region of regions) {
    const pos = mercator(region.lat, region.lng, chartWidth, chartHeight);
    const color = generateColor(region.value, minValue, maxValue, colorScheme);

    // Draw as colored circle with label
    svg += `<circle cx="${20 + pos.x}" cy="${chartTop + pos.y}" r="15" fill="${color}" stroke="#fff" stroke-width="1.5" opacity="0.8"/>`;
    svg += `<text x="${20 + pos.x}" y="${chartTop + pos.y + 4}" text-anchor="middle" font-size="8" fill="#000" font-weight="bold">${region.name.substring(0, 3).toUpperCase()}</text>`;
  }

  // Legend
  const legendY = height - 25;
  svg += `<text x="20" y="${legendY - 5}" font-size="10" fill="#666">Legend:</text>`;

  for (let i = 0; i <= 5; i++) {
    const value = minValue + ((maxValue - minValue) * i) / 5;
    const color = generateColor(value, minValue, maxValue, colorScheme);
    svg += `<rect x="${80 + i * 40}" y="${legendY - 8}" width="20" height="10" fill="${color}"/>`;
    svg += `<text x="${90 + i * 40}" y="${legendY + 8}" text-anchor="middle" font-size="8" fill="#666">${Math.round(value)}</text>`;
  }

  svg += "</svg>";
  return svg;
}

/**
 * Load local map registry from public/maps/maps.json
 */
async function loadLocalMapRegistry(): Promise<MapRegistry | null> {
  if (mapRegistry) return mapRegistry;

  const now = Date.now();
  if (now - lastRegistryLoadAttempt < REGISTRY_RETRY_COOLDOWN_MS) {
    return null;
  }
  lastRegistryLoadAttempt = now;

  try {
    const response = await fetchFirstAvailable(
      buildMapAssetUrls("maps/maps.json"),
    );
    if (!response) {
      console.warn("[GenerateMapChart] Local map registry not found");
      return null;
    }
    mapRegistry = (await response.json()) as MapRegistry;
    console.log(
      `[GenerateMapChart] Loaded registry with ${mapRegistry.totalMaps} local maps`,
    );
    return mapRegistry;
  } catch (error) {
    console.warn("[GenerateMapChart] Error loading map registry:", error);
    return null;
  }
}

/**
 * Get a local map by ID (e.g., "world", "usa", "france")
 * Returns an object with the content and SVG metadata (viewBox, width, height)
 */
async function getLocalMap(mapId: string): Promise<{
  id: string;
  content: string;
  viewBox?: string;
  width?: string;
  height?: string;
} | null> {
  const normalizedId = mapId.trim().toLowerCase();
  if (!normalizedId) return null;

  const parseSvgResponse = async (
    response: Response,
    resolvedId: string,
  ): Promise<{
    id: string;
    content: string;
    viewBox?: string;
    width?: string;
    height?: string;
  } | null> => {
    if (!response) {
      return null;
    }

    const svgText = await response.text();
    const match = svgText.match(/<svg([^>]*)>([\s\S]*?)<\/svg>/i);
    if (match) {
      const attrs = match[1];
      const viewBoxMatch = attrs.match(/viewBox\s*=\s*["']([^"']+)["']/i);
      const widthMatch = attrs.match(/width\s*=\s*["']([\d.]+)["']/i);
      const heightMatch = attrs.match(/height\s*=\s*["']([\d.]+)["']/i);
      return {
        id: resolvedId,
        content: sanitizeSvgFragment(match[2]),
        viewBox: viewBoxMatch?.[1],
        width: widthMatch?.[1],
        height: heightMatch?.[1],
      };
    }
    return null;
  };

  try {
    // Prefer deterministic id->filename resolution so explicit requests like
    // "usa" always load "usa.svg" even if an older registry is cached.
    const directResponse = await fetchFirstAvailable(
      buildMapAssetUrls(`maps/${normalizedId}.svg`),
    );
    if (directResponse) {
      const parsedDirect = await parseSvgResponse(directResponse, normalizedId);
      if (parsedDirect) {
        console.log(
          `[GenerateMapChart] Successfully loaded local map: ${normalizedId}`,
        );
        return parsedDirect;
      }
    }

    const registry = await loadLocalMapRegistry();
    if (!registry) return null;

    const mapInfo = registry.maps.find((m) => m.id === normalizedId);
    if (!mapInfo) return null;

    const registryResponse = await fetchFirstAvailable(
      buildMapAssetUrls(`maps/${mapInfo.filename}`),
    );
    const parsedRegistry = registryResponse
      ? await parseSvgResponse(registryResponse, mapInfo.id)
      : null;
    if (parsedRegistry) {
      console.log(
        `[GenerateMapChart] Successfully loaded local map via registry: ${mapInfo.id}`,
      );
      return parsedRegistry;
    }

    console.warn(`[GenerateMapChart] Failed to load local map ${normalizedId}`);
    return null;
  } catch (error) {
    console.warn(`[GenerateMapChart] Error loading local map ${mapId}:`, error);
    return null;
  }
}

/**
 * Get available local map IDs for autocomplete
 */
async function getAvailableLocalMaps(): Promise<string[]> {
  const registry = await loadLocalMapRegistry();
  if (!registry) return [];
  return registry.maps.map((m) => m.id);
}

/**
 * Fetch external SVG base map
 */
async function fetchBaseMap(url: string): Promise<string | null> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      console.warn(
        `[GenerateMapChart] Failed to fetch base map: ${response.status}`,
      );
      return null;
    }
    const svgText = await response.text();
    // Extract just the inner content (paths, groups) from the SVG
    // This regex extracts content between <svg ...> and </svg>
    const match = svgText.match(/<svg[^>]*>([\s\S]*?)<\/svg>/i);
    return match ? sanitizeSvgFragment(match[1]) : null;
  } catch (error) {
    console.warn("[GenerateMapChart] Error fetching base map:", error);
    return null;
  }
}

export const generateMapChartTool = defineTool({
  name: "generate_map_chart",
  category: "deliverable",
  parallelSafe: false,
  label: "Generate Map Chart",
  description:
    "Create an SVG world map visualization from coordinate data. " +
    "Writes an SVG file to /home/user/uploads and returns its path for insertion into Excel. " +
    "Perfect for: (1) Point maps - show locations with dots, " +
    "(2) Bubble maps - circle size reflects value, " +
    "(3) Choropleth - color encoding for countries/regions. " +
    "Use after resolve_locations for named places, or pass projectedPoints for projected X/Y datasets. " +
    "Use baseMap parameter for offline/airgapped mode with local maps (world, usa, france, usa-ca, etc.). " +
    "Use baseMapUrl only for external online maps.",
  parameters: Type.Object({
    points: Type.Array(
      Type.Object({
        lat: Type.Number({ description: "Latitude (-90 to 90)" }),
        lng: Type.Number({ description: "Longitude (-180 to 180)" }),
        label: Type.Optional(
          Type.String({ description: "Optional label for this point" }),
        ),
        value: Type.Optional(
          Type.Number({
            description: "Optional numeric value (for bubble/choropleth maps)",
          }),
        ),
      }),
      { description: "Array of points to plot on the map" },
    ),
    projectedPoints: Type.Optional(
      Type.Array(
        Type.Object({
          x: Type.Number({
            description: "Projected X coordinate (for non-lat/lng datasets)",
          }),
          y: Type.Number({
            description: "Projected Y coordinate (for non-lat/lng datasets)",
          }),
          label: Type.Optional(
            Type.String({ description: "Optional label for this point" }),
          ),
          value: Type.Optional(
            Type.Number({
              description:
                "Optional numeric value (for bubble/choropleth maps)",
            }),
          ),
        }),
        {
          description:
            "Optional projected XY points. If provided, values are scaled into the selected base map geographic bounds.",
        },
      ),
    ),
    projectedBounds: Type.Optional(
      Type.Object({
        minX: Type.Number(),
        maxX: Type.Number(),
        minY: Type.Number(),
        maxY: Type.Number(),
      }),
    ),
    projectedCrs: Type.Optional(
      Type.String({
        description:
          "CRS for projectedPoints. Supported: EPSG:3857 (Web Mercator) and EPSG:4326/WGS84 (x=lng,y=lat). If omitted, tool uses auto-fit mode for local maps only.",
      }),
    ),
    mapType: Type.Optional(
      Type.Enum(
        {
          point: "point",
          bubble: "bubble",
          choropleth: "choropleth",
        },
        {
          description:
            "Type of map: point (dots), bubble (sized by value), or choropleth (color by value)",
          default: "point",
        },
      ),
    ),
    width: Type.Optional(
      Type.Number({
        description: "SVG width in pixels (default: 800)",
        default: 800,
      }),
    ),
    height: Type.Optional(
      Type.Number({
        description: "SVG height in pixels (default: 500)",
        default: 500,
      }),
    ),
    showLabels: Type.Optional(
      Type.Boolean({
        description: "Show point labels on map (default: false)",
        default: false,
      }),
    ),
    colorScheme: Type.Optional(
      Type.Enum(
        {
          viridis: "viridis",
          blue: "blue",
          red: "red",
          green: "green",
          heatmap: "heatmap",
        },
        {
          description: "Color scheme for value-based maps",
          default: "viridis",
        },
      ),
    ),
    title: Type.Optional(
      Type.String({ description: "Chart title", maxLength: 100 }),
    ),
    valueColumn: Type.Optional(
      Type.String({
        description: "Name of the value being visualized (for legend)",
      }),
    ),
    baseMap: Type.Optional(
      Type.String({
        description:
          "Local base map ID for airgapped/offline use. Available maps: world (global view), usa (United States), canada, mexico, and most countries by name (france, germany, japan, etc.), plus all US states by code (usa-ca for California, usa-tx for Texas, etc.). Maps are served locally without external network calls.",
        default: "",
      }),
    ),
    baseMapUrl: Type.Optional(
      Type.String({
        description:
          "Deprecated: Use baseMap parameter instead. Falls back to local maps or simplified built-in map.",
        default: "",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the map (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const {
        points,
        projectedPoints = [],
        projectedBounds,
        projectedCrs,
        mapType = "point",
        width = 800,
        height = 500,
        showLabels = false,
        colorScheme = "viridis",
        title,
        valueColumn,
        baseMap = "",
        baseMapUrl = "",
      } = params;

      if (points.length + projectedPoints.length > 1000) {
        return toolError("Too many points. Maximum is 1000 for performance.");
      }

      // Validate native lat/lng points
      const validNativePoints = points.filter((p) => {
        return (
          typeof p.lat === "number" &&
          typeof p.lng === "number" &&
          !Number.isNaN(p.lat) &&
          !Number.isNaN(p.lng) &&
          p.lat >= -90 &&
          p.lat <= 90 &&
          p.lng >= -180 &&
          p.lng <= 180
        );
      });

      if (validNativePoints.length < points.length) {
        console.warn(
          `[GenerateMapChart] Filtered out ${points.length - validNativePoints.length} invalid points`,
        );
      }

      // Load base map - prefer local, fallback to external URL, then simplified default
      let baseMapContent: string | null = null;
      let baseMapViewBox: string | undefined;
      let baseMapWidth: string | undefined;
      let baseMapHeight: string | undefined;
      let selectedBaseMapId: string | null = null;
      let mapSource = "simplified";

      // Try local map first (for airgap/offline mode)
      if (baseMap) {
        const baseMapCandidates = buildBaseMapCandidates(baseMap);
        for (const candidate of baseMapCandidates) {
          const localMap = await getLocalMap(candidate);
          if (!localMap) continue;

          baseMapContent = localMap.content;
          baseMapViewBox = localMap.viewBox;
          baseMapWidth = localMap.width;
          baseMapHeight = localMap.height;
          selectedBaseMapId = localMap.id;
          mapSource = `local:${localMap.id}`;
          break;
        }

        if (!baseMapContent) {
          console.warn(
            `[GenerateMapChart] Local map '${baseMap}' not found, trying alternatives...`,
          );
        }
      }

      // Fallback to external URL if provided and local not found
      if (!baseMapContent && baseMapUrl) {
        baseMapContent = await fetchBaseMap(baseMapUrl);
        if (baseMapContent) {
          mapSource = "external";
          console.log("[GenerateMapChart] Using external base map");
        }
      }

      if (!baseMapContent && baseMap && !baseMapUrl) {
        const availableMaps = await getAvailableLocalMaps();
        return toolError(
          `Requested baseMap '${baseMap}' could not be loaded from local assets. Use list_available_maps to pick a supported id. Available map count: ${availableMaps.length}.`,
        );
      }

      // Auto-select best local map based on data bounds if no map specified
      if (!baseMapContent && !baseMap && !baseMapUrl) {
        const avgLat =
          validNativePoints.length > 0
            ? validNativePoints.reduce((s, p) => s + p.lat, 0) /
              validNativePoints.length
            : null;
        const avgLng =
          validNativePoints.length > 0
            ? validNativePoints.reduce((s, p) => s + p.lng, 0) /
              validNativePoints.length
            : null;

        // Try to auto-select appropriate local map
        if (
          avgLat !== null &&
          avgLng !== null &&
          avgLat >= 24 &&
          avgLat <= 49 &&
          avgLng >= -125 &&
          avgLng <= -66
        ) {
          // Likely US data
          const usaMap = await getLocalMap("usa");
          if (usaMap) {
            baseMapContent = usaMap.content;
            baseMapViewBox = usaMap.viewBox;
            baseMapWidth = usaMap.width;
            baseMapHeight = usaMap.height;
            selectedBaseMapId = "usa";
            mapSource = "local:usa (auto)";
          }
        }
        // Default to world map if available and no better match
        if (!baseMapContent) {
          const worldMap = await getLocalMap("world");
          if (worldMap) {
            baseMapContent = worldMap.content;
            baseMapViewBox = worldMap.viewBox;
            baseMapWidth = worldMap.width;
            baseMapHeight = worldMap.height;
            selectedBaseMapId = "world";
            mapSource = "local:world (auto)";
          }
        }
      }

      const mapGeoBounds = selectedBaseMapId
        ? getMapGeoBounds(selectedBaseMapId, baseMapContent ?? undefined)
        : MAP_GEO_BOUNDS.world;

      // Validate projected XY points and convert them to lat/lng by fitting
      // the XY extent into selected map bounds.
      const validProjected = projectedPoints.filter((p) => {
        return (
          typeof p.x === "number" &&
          typeof p.y === "number" &&
          !Number.isNaN(p.x) &&
          !Number.isNaN(p.y)
        );
      });

      let convertedProjected: Array<{
        lat: number;
        lng: number;
        label?: string;
        value?: number;
      }> = [];
      let projectedSvgPoints: Array<{
        x: number;
        y: number;
        label?: string;
        value?: number;
      }> = [];

      const normalizedProjectedCrs = normalizeProjectedCrs(projectedCrs);

      if (validProjected.length > 0) {
        if (normalizedProjectedCrs === "epsg:3857") {
          const mercatorConverted = validProjected.map((p) => {
            const converted = webMercatorToWgs84(p.x, p.y);
            if (!converted) return null;
            return {
              lat: converted.lat,
              lng: converted.lng,
              label: p.label,
              value: p.value,
            };
          });
          convertedProjected = mercatorConverted.filter((p) => p !== null);

          if (convertedProjected.length === 0) {
            return toolError(
              "projectedPoints could not be converted from EPSG:3857. Verify coordinate units and CRS.",
            );
          }
        } else if (normalizedProjectedCrs === "epsg:4326") {
          convertedProjected = validProjected
            .map((p) => ({
              lat: p.y,
              lng: p.x,
              label: p.label,
              value: p.value,
            }))
            .filter(
              (p) =>
                p.lat >= -90 && p.lat <= 90 && p.lng >= -180 && p.lng <= 180,
            );

          if (convertedProjected.length === 0) {
            return toolError(
              "projectedPoints with EPSG:4326 produced no valid lat/lng pairs. Expected x=longitude and y=latitude.",
            );
          }
        }
      }

      if (
        validProjected.length > 0 &&
        convertedProjected.length === 0 &&
        mapGeoBounds
      ) {
        const broadMap =
          !selectedBaseMapId ||
          selectedBaseMapId === "world" ||
          selectedBaseMapId === "usa";

        if (broadMap) {
          return toolError(
            "Projected X/Y without CRS cannot be safely placed on world/USA maps. Provide projectedCrs (for example EPSG:3857) or pass lat/lng points.",
          );
        }

        const xs = validProjected.map((p) => p.x);
        const ys = validProjected.map((p) => p.y);
        const sourceBounds = projectedBounds ?? {
          minX: Math.min(...xs),
          maxX: Math.max(...xs),
          minY: Math.min(...ys),
          maxY: Math.max(...ys),
        };

        const spanX = sourceBounds.maxX - sourceBounds.minX;
        const spanY = sourceBounds.maxY - sourceBounds.minY;
        if (spanX <= 0 || spanY <= 0) {
          return toolError(
            "Invalid projectedBounds: min and max values must not be equal.",
          );
        }

        convertedProjected = validProjected.map((p) => {
          const xNorm = (p.x - sourceBounds.minX) / spanX;
          const yNorm = (p.y - sourceBounds.minY) / spanY;
          return {
            lat:
              mapGeoBounds.minLat +
              yNorm * (mapGeoBounds.maxLat - mapGeoBounds.minLat),
            lng:
              mapGeoBounds.minLng +
              xNorm * (mapGeoBounds.maxLng - mapGeoBounds.minLng),
            label: p.label,
            value: p.value,
          };
        });

        if (baseMapContent) {
          const localViewBox = getSvgViewBox(
            baseMapViewBox,
            baseMapWidth,
            baseMapHeight,
          );
          projectedSvgPoints = validProjected.map((p) => {
            const xNorm = (p.x - sourceBounds.minX) / spanX;
            const yNorm = (p.y - sourceBounds.minY) / spanY;
            return {
              x: localViewBox.x + xNorm * localViewBox.width,
              // Projected Y usually increases upward; SVG Y increases downward.
              y: localViewBox.y + (1 - yNorm) * localViewBox.height,
              label: p.label,
              value: p.value,
            };
          });
        }
      }

      const validPoints = [...validNativePoints, ...convertedProjected];
      if (validPoints.length === 0) {
        return toolError(
          "No plottable points. Provide valid lat/lng points or numeric projectedPoints.",
        );
      }

      console.log(`[GenerateMapChart] Using ${mapSource} base map`);

      // Generate SVG based on map type
      let svg: string;
      if (mapType === "choropleth") {
        // For choropleth, require values
        const regions = validPoints
          .filter((p) => p.label)
          .map((p) => ({
            name: p.label || "",
            lat: p.lat,
            lng: p.lng,
            value: p.value || 0,
          }));
        svg = generateChoroplethMap(regions, {
          width,
          height,
          colorScheme,
          title,
          baseMapContent,
        });
      } else {
        svg = generatePointMap(validPoints, {
          width,
          height,
          showLabels,
          colorScheme,
          title,
          valueColumn,
          baseMapContent,
          baseMapId: selectedBaseMapId,
          baseMapViewBox,
          baseMapWidth,
          baseMapHeight,
          projectedSvgPoints,
        });
      } // Calculate bounding box and summary
      const latitudes = validPoints.map((p) => p.lat);
      const longitudes = validPoints.map((p) => p.lng);
      const bounds = {
        minLat: Math.min(...latitudes),
        maxLat: Math.max(...latitudes),
        minLng: Math.min(...longitudes),
        maxLng: Math.max(...longitudes),
      };

      // Calculate center point
      const centerLat = (bounds.minLat + bounds.maxLat) / 2;
      const centerLng = (bounds.minLng + bounds.maxLng) / 2;

      // Calculate approximate span
      const spanKm = haversineDistance(
        bounds.minLat,
        bounds.minLng,
        bounds.maxLat,
        bounds.maxLng,
      );

      // Persist map SVG to VFS so the result payload stays compact and does not get truncated.
      const fileName = `map-chart-${Date.now()}.svg`;
      await writeFile(fileName, svg);
      const filePath = `/home/user/uploads/${fileName}`;

      return toolSuccess({
        success: true,
        filePath,
        fileName,
        width,
        height,
        totalPoints: validPoints.length,
        bounds,
        center: { lat: centerLat, lng: centerLng },
        spanKm,
        format: "svg",
        mapType,
        mapSource,
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error generating map";
      return toolError(message);
    }
  },
});
