export type AzureEntraCloud = "commercial" | "gcc" | "usnat";
export type AzureEnvironment = "internet" | "ts";

export interface AzureEntraCloudProfile {
  authorityHost: string;
  tokenScope: string;
}

const AZURE_ENTRA_CLOUD_PROFILES: Partial<
  Record<AzureEntraCloud, AzureEntraCloudProfile>
> = {
  commercial: {
    authorityHost: "https://login.microsoftonline.com",
    tokenScope: "https://cognitiveservices.azure.com/.default",
  },
  gcc: {
    authorityHost: "https://login.microsoftonline.us",
    tokenScope: "https://cognitiveservices.azure.us/.default",
  },
};

const AZURE_ENTRA_CLOUDS_BY_ENVIRONMENT: Record<
  AzureEnvironment,
  readonly AzureEntraCloud[]
> = {
  internet: ["commercial", "gcc"],
  ts: ["usnat"],
};

export function getAzureEntraCloudsForEnvironment(
  environment: AzureEnvironment,
): readonly AzureEntraCloud[] {
  return AZURE_ENTRA_CLOUDS_BY_ENVIRONMENT[environment];
}

export function constrainAzureEntraCloud(
  cloud: AzureEntraCloud,
  environment: AzureEnvironment,
): AzureEntraCloud {
  const allowedClouds = getAzureEntraCloudsForEnvironment(environment);
  return allowedClouds.includes(cloud) ? cloud : allowedClouds[0];
}

export function resolveAzureEntraCloudProfile(
  cloud: AzureEntraCloud | undefined,
  tokenScopeOverride?: string,
  authorityHostOverride?: string,
): AzureEntraCloudProfile {
  const profile = AZURE_ENTRA_CLOUD_PROFILES[cloud ?? "commercial"];
  const authorityHost = authorityHostOverride?.trim() || profile?.authorityHost;
  const tokenScope = tokenScopeOverride?.trim() || profile?.tokenScope;
  if (!authorityHost || !tokenScope) {
    throw new Error(
      "azureEntraAuthorityHost and azureEntraTokenScope are required for USNat",
    );
  }
  return {
    authorityHost,
    tokenScope,
  };
}
