import {
  Button,
  Caption2,
  Tag,
  Text,
  Tooltip,
  makeStyles,
  tokens,
} from "@fluentui/react-components";
import {
  AttachRegular,
  DismissRegular,
  SendRegular,
  SquareRegular,
} from "@fluentui/react-icons";
import {
  type ChangeEvent,
  type KeyboardEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { useChat } from "./use-chat";

const COLLAPSE_UPLOAD_THRESHOLD = 6;

const useStyles = makeStyles({
  root: {
    borderTop: `1px solid ${tokens.colorNeutralStroke1}`,
    padding: tokens.spacingVerticalM,
    paddingTop: tokens.spacingVerticalS,
    backgroundColor: tokens.colorNeutralBackground1,
    flexShrink: 0,
  },
  errorText: {
    color: tokens.colorStatusDangerForeground1,
    fontSize: tokens.fontSizeBase200,
    marginBottom: tokens.spacingVerticalXS,
    padding: `${tokens.spacingVerticalXS} ${tokens.spacingHorizontalS}`,
    border: `1px solid ${tokens.colorStatusDangerBorder1}`,
    borderRadius: tokens.borderRadiusMedium,
    backgroundColor: tokens.colorStatusDangerBackground1,
  },
  uploadsSection: {
    display: "flex",
    flexDirection: "column",
    gap: tokens.spacingVerticalXS,
    marginBottom: tokens.spacingVerticalS,
  },
  uploadsHeader: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: tokens.spacingHorizontalS,
    flexWrap: "wrap",
  },
  uploadSummary: {
    color: tokens.colorNeutralForeground2,
    fontSize: tokens.fontSizeBase200,
  },
  uploadsContainer: {
    display: "flex",
    flexWrap: "wrap",
    gap: tokens.spacingHorizontalXS,
    maxHeight: "112px",
    overflowY: "auto",
    paddingRight: tokens.spacingHorizontalXS,
  },
  inputContainer: {
    display: "flex",
    alignItems: "flex-end",
    gap: tokens.spacingHorizontalS,
  },
  textArea: {
    flex: 1,
    minHeight: "32px",
    maxHeight: "160px",
    boxSizing: "border-box",
    fontFamily: tokens.fontFamilyMonospace,
    fontSize: tokens.fontSizeBase300,
    lineHeight: tokens.lineHeightBase300,
    padding: tokens.spacingHorizontalS,
    border: `1px solid ${tokens.colorNeutralStroke1}`,
    borderRadius: tokens.borderRadiusMedium,
    backgroundColor: tokens.colorNeutralBackground1,
    color: tokens.colorNeutralForeground1,
    resize: "none",
    overflowY: "hidden",
    ":disabled": {
      color: tokens.colorNeutralForegroundDisabled,
      backgroundColor: tokens.colorNeutralBackgroundDisabled,
      cursor: "not-allowed",
    },
  },
  inputHelp: {
    marginTop: tokens.spacingVerticalXS,
    color: tokens.colorNeutralForeground3,
    fontSize: tokens.fontSizeBase200,
  },
  fileSize: {
    color: tokens.colorNeutralForeground3,
  },
});

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
}

export function ChatInput() {
  const { sendMessage, state, abort, processFiles, removeUpload } = useChat();
  const [input, setInput] = useState("");
  const [showAllUploads, setShowAllUploads] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploads = state.uploads;
  const isUploading = state.isUploading;
  const styles = useStyles();
  const shouldCollapseUploads = uploads.length > COLLAPSE_UPLOAD_THRESHOLD;
  const showUploadList = !shouldCollapseUploads || showAllUploads;
  const totalUploadSize = uploads.reduce((total, file) => total + file.size, 0);
  const uploadSummary = `${uploads.length} ${uploads.length === 1 ? "file" : "files"} attached${
    totalUploadSize > 0 ? ` (${formatFileSize(totalUploadSize)})` : ""
  }`;
  const promptHelpId = "officeai-chat-input-help";
  const promptErrorId = "officeai-chat-input-error";
  const promptDescriptionIds = state.error
    ? `${promptHelpId} ${promptErrorId}`
    : promptHelpId;

  useEffect(() => {
    if (showAllUploads && uploads.length <= COLLAPSE_UPLOAD_THRESHOLD) {
      setShowAllUploads(false);
    }
  }, [showAllUploads, uploads.length]);

  const resizeTextarea = useCallback(() => {
    const textarea = textareaRef.current;
    if (!textarea) return;
    textarea.style.height = "auto";
    const nextHeight = Math.min(textarea.scrollHeight, 160);
    textarea.style.height = `${nextHeight}px`;
    textarea.style.overflowY = textarea.scrollHeight > 160 ? "auto" : "hidden";
  }, []);

  useEffect(() => {
    resizeTextarea();
  }, [resizeTextarea]);

  const handleSubmit = useCallback(async () => {
    const trimmed = input.trim();
    if (!trimmed || state.isStreaming) return;
    const attachmentNames = uploads.map((u) => u.name);
    setInput("");
    window.requestAnimationFrame(resizeTextarea);
    await sendMessage(
      trimmed,
      attachmentNames.length > 0 ? attachmentNames : undefined,
    );
  }, [input, state.isStreaming, sendMessage, uploads, resizeTextarea]);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleSubmit();
      }
    },
    [handleSubmit],
  );

  const handleFileSelect = useCallback(
    async (e: ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (!files || files.length === 0) return;
      await processFiles(Array.from(files));
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    },
    [processFiles],
  );

  const openFilePicker = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  return (
    <div className={styles.root}>
      {state.error && (
        <Text
          className={styles.errorText}
          id={promptErrorId}
          role="alert"
          aria-live="assertive"
        >
          {state.error}
        </Text>
      )}

      {/* Uploaded files chips */}
      {uploads.length > 0 && (
        <div className={styles.uploadsSection}>
          {shouldCollapseUploads && (
            <div className={styles.uploadsHeader}>
              <Text className={styles.uploadSummary}>{uploadSummary}</Text>
              <Button
                appearance="subtle"
                size="small"
                onClick={() => setShowAllUploads((prev) => !prev)}
              >
                {showAllUploads ? "Hide files" : `Show ${uploads.length} files`}
              </Button>
            </div>
          )}

          {showUploadList && (
            <div className={styles.uploadsContainer}>
              {uploads.map((file) => (
                <Tag
                  key={file.name}
                  dismissible
                  onClick={() => removeUpload(file.name)}
                  dismissIcon={<DismissRegular />}
                  size="small"
                  value={file.name}
                >
                  <span title={file.name}>
                    {file.name.length > 20
                      ? `${file.name.slice(0, 18)}…`
                      : file.name}
                  </span>
                  {file.size > 0 && (
                    <Caption2 className={styles.fileSize}>
                      {formatFileSize(file.size)}
                    </Caption2>
                  )}
                </Tag>
              ))}
            </div>
          )}
        </div>
      )}

      <div className={styles.inputContainer}>
        {/* Hidden file input */}
        <input
          ref={fileInputRef}
          aria-label="Choose files to attach"
          type="file"
          multiple
          onChange={handleFileSelect}
          style={{ display: "none" }}
        />

        {/* Upload button */}
        <Tooltip content="Upload files" relationship="label">
          <Button
            appearance="outline"
            aria-label="Upload files"
            icon={<AttachRegular />}
            onClick={openFilePicker}
            disabled={isUploading || state.isStreaming}
            size="small"
          />
        </Tooltip>

        <textarea
          ref={textareaRef}
          aria-describedby={promptDescriptionIds}
          aria-label="Message OfficeAI"
          className={`${styles.textArea} officeai-chat-textarea`}
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            window.requestAnimationFrame(resizeTextarea);
          }}
          onKeyDown={handleKeyDown}
          placeholder={
            state.providerConfig
              ? "Type a message..."
              : "Configure API key in settings"
          }
          disabled={!state.providerConfig}
          rows={1}
        />
        {state.isStreaming ? (
          <Tooltip content="Stop generating" relationship="label">
            <Button
              appearance="primary"
              aria-label="Stop generating"
              icon={<SquareRegular />}
              onClick={abort}
              size="small"
            />
          </Tooltip>
        ) : (
          <Tooltip content="Send message" relationship="label">
            <Button
              appearance="primary"
              aria-label="Send message"
              icon={<SendRegular />}
              onClick={handleSubmit}
              disabled={!state.providerConfig || !input.trim()}
              size="small"
            />
          </Tooltip>
        )}
      </div>
      <Caption2 className={styles.inputHelp} id={promptHelpId}>
        Press Enter to send. Press Shift+Enter for a new line.
      </Caption2>
    </div>
  );
}
