function createBaseResult(startTime: number): Omit<JsRunResult, "ok"> {
  return {
    reported: false,
    console: [],
    timedOut: false,
    aborted: false,
    memoryExceeded: false,
    elapsedMs: Date.now() - startTime,
  };
}

function failedResult(
  startTime: number,
  error: JsRunError,
  flags: Partial<
    Pick<JsRunResult, "timedOut" | "aborted" | "memoryExceeded" | "console">
  > = {},
): JsRunResult {
  return {
    ...createBaseResult(startTime),
    ...flags,
    ok: false,
    error,
    elapsedMs: Date.now() - startTime,
  };
}

function resolveVfsPath(path: string, cwd?: string): string {
  if (path.startsWith("/")) return path;
  if (cwd) return `${cwd.replace(/\/$/, "")}/${path}`;
  return `/home/user/uploads/${path}`;
}

async function preloadTextFiles(
  files: string[] | undefined,
  options: {
    cwd?: string;
    maxPreloadFileBytes: number;
    maxPreloadTotalBytes: number;
  },
): Promise<PreloadedTextFile[]> {
  const uniqueFiles = [...new Set(files ?? [])];
  if (uniqueFiles.length === 0) return [];

  const decoder = new TextDecoder("utf-8", { fatal: true });
  const preloaded: PreloadedTextFile[] = [];
  let totalBytes = 0;

  for (const requestedPath of uniqueFiles) {
    const resolvedPath = resolveVfsPath(requestedPath, options.cwd);
    let data: Uint8Array;
    try {
      data = await readFileBuffer(resolvedPath);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw Object.assign(
        new Error(`Failed to preload ${requestedPath}: ${message}`),
        { name: VFS_PRELOAD_ERROR },
      );
    }

    if (data.byteLength > options.maxPreloadFileBytes) {
      throw Object.assign(
        new Error(
          `Preload file ${requestedPath} is ${data.byteLength} bytes, above the ${options.maxPreloadFileBytes} byte limit.`,
        ),
        { name: VFS_PRELOAD_ERROR },
      );
    }

    totalBytes += data.byteLength;
    if (totalBytes > options.maxPreloadTotalBytes) {
      throw Object.assign(
        new Error(
          `Total preload size ${totalBytes} bytes exceeds the ${options.maxPreloadTotalBytes} byte limit.`,
        ),
        { name: VFS_PRELOAD_ERROR },
      );
    }

    try {
      preloaded.push({
        requestedPath,
        resolvedPath,
        text: decoder.decode(data),
        bytes: data.byteLength,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw Object.assign(
        new Error(`Failed to decode ${requestedPath} as UTF-8: ${message}`),
        { name: VFS_PRELOAD_ERROR },
      );
    }
  }

  return preloaded;
}

function buildQuickJSError(
  name: string,
  message: string,
  stack?: string,
): JsRunError {
  return { name, message, stack };
}

function disposeHandle(handle: QuickJSHandle | undefined): void {
  if (handle?.alive) handle.dispose();
}

function drainPendingJobs(
  runtime: QuickJSRuntime,
  context: QuickJSContext,
  shouldStop: () => boolean,
): JsRunError | undefined {
  while (runtime.hasPendingJob() && !shouldStop()) {
    const jobsResult = runtime.executePendingJobs(
      DEFAULT_PENDING_JOB_BATCH_SIZE,
    );
    try {
      if ("error" in jobsResult && jobsResult.error) {
        return errorFromHandle(context, jobsResult.error);
      }
      if ("value" in jobsResult && jobsResult.value === 0) break;
    } finally {
      jobsResult.dispose();
    }
  }
  return undefined;
}

async function settleEvalResult(
  context: QuickJSContext,
  runtime: QuickJSRuntime,
  evalHandle: QuickJSHandle,
  shouldStop: () => boolean,
): Promise<JsRunError | undefined> {
  const resolvedPromise = context.resolvePromise(evalHandle);
  const jobError = drainPendingJobs(runtime, context, shouldStop);
  if (jobError) return jobError;

  const promiseState = context.getPromiseState(evalHandle);
  if (promiseState.type === "pending") {
    return buildQuickJSError(
      JS_PROMISE_PENDING_ERROR,
      "QuickJS promise did not settle after the pending job queue drained. Long-lived async work such as timers and network is not supported.",
    );
  }
  if (promiseState.type === "fulfilled") {
    disposeHandle(promiseState.value);
  } else {
    disposeHandle(promiseState.error);
  }

  const resolvedResult = await resolvedPromise;
  try {
    if ("error" in resolvedResult && resolvedResult.error) {
      return errorFromHandle(context, resolvedResult.error);
    }
  } finally {
    resolvedResult.dispose();
  }

  return undefined;
}

export async function evalJs(options: JsRunOptions): Promise<JsRunResult> {
  const startTime = Date.now();
  const limits = normalizeLimits(options);

  let preloadedFiles: PreloadedTextFile[];
  try {
    preloadedFiles = await preloadTextFiles(options.preloadFiles, {
      cwd: options.preloadCwd,
      maxPreloadFileBytes: limits.maxPreloadFileBytes,
      maxPreloadTotalBytes: limits.maxPreloadTotalBytes,
    });
  } catch (error) {
    return failedResult(startTime, errorFromUnknown(error));
  }

  let quickJsModule: QuickJSWASMModule;
  try {
    quickJsModule = await loadQuickJSModule();
  } catch (error) {
    const loadError = errorFromUnknown(error);
    return failedResult(startTime, {
      name: QUICKJS_LOAD_ERROR,
      message: loadError.message,
      stack: loadError.stack,
    });
  }

  const interruptState = createInterruptState(limits.timeoutMs);
  const abortListener = (): void => {
    interruptState.aborted = true;
  };
  options.signal?.addEventListener("abort", abortListener, { once: true });

  let runtime: QuickJSRuntime | undefined;
  let context: QuickJSContext | undefined;
  let evalHandle: QuickJSHandle | undefined;

  try {
    runtime = quickJsModule.newRuntime();
    runtime.setMemoryLimit(limits.memoryLimitBytes);
    runtime.setMaxStackSize(limits.maxStackSize);
    runtime.setInterruptHandler(() =>
      shouldInterrupt(interruptState, options.signal),
    );

    context = runtime.newContext();
    const bridge = installHostBridge(context, {
      stdin: options.stdin,
      preloadedFiles,
    });

    const evalResult = context.evalCode(
      options.code,
      options.filename ?? (options.module ? "eval.mjs" : "eval.js"),
      { type: options.module ? "module" : "global" },
    );

    if ("error" in evalResult && evalResult.error) {
      const error = errorFromHandle(context, evalResult.error);
      evalResult.dispose();
      const memoryExceeded = looksLikeMemoryExceeded(error);
      return {
        ok: false,
        error,
        console: bridge.console,
        reported: bridge.reported,
        value: bridge.value,
        timedOut: interruptState.timedOut,
        aborted: interruptState.aborted,
        memoryExceeded,
        elapsedMs: Date.now() - startTime,
      };
    }

    if (!("value" in evalResult)) {
      return {
        ok: false,
        error: {
          name: "QuickJSEvalError",
          message: "QuickJS evaluation did not return a value handle",
        },
        console: bridge.console,
        reported: bridge.reported,
        value: bridge.value,
        timedOut: interruptState.timedOut,
        aborted: interruptState.aborted,
        memoryExceeded: false,
        elapsedMs: Date.now() - startTime,
      };
    }

    evalHandle = evalResult.value;
    const asyncError = await settleEvalResult(
      context,
      runtime,
      evalHandle,
      () => shouldInterrupt(interruptState, options.signal),
    );

    if (asyncError) {
      const memoryExceeded = looksLikeMemoryExceeded(asyncError);
      return {
        ok: false,
        error: asyncError,
        console: bridge.console,
        reported: bridge.reported,
        value: bridge.value,
        timedOut:
          interruptState.timedOut ||
          asyncError.name === JS_PROMISE_PENDING_ERROR,
        aborted: interruptState.aborted,
        memoryExceeded,
        elapsedMs: Date.now() - startTime,
      };
    }

    return {
      ok: true,
      value: bridge.value,
      reported: bridge.reported,
      console: bridge.console,
      timedOut: interruptState.timedOut,
      aborted: interruptState.aborted,
      memoryExceeded: false,
      elapsedMs: Date.now() - startTime,
    };
  } catch (error) {
    const runError = errorFromUnknown(error);
    return failedResult(startTime, runError, {
      timedOut: interruptState.timedOut,
      aborted: interruptState.aborted,
      memoryExceeded: looksLikeMemoryExceeded(runError),
    });
  } finally {
    options.signal?.removeEventListener("abort", abortListener);
    disposeHandle(evalHandle);
    context?.dispose();
    runtime?.dispose();
  }
}
