import type { QuickJSContext, QuickJSHandle } from "quickjs-emscripten-core";
import { formatHostValue, marshalHandle } from "./marshal";
import type { JsConsoleLevel, JsConsoleLine, PreloadedTextFile } from "./types";
import { VFS_NOT_PRELOADED_ERROR } from "./types";

export interface HostBridgeState {
  console: JsConsoleLine[];
  reported: boolean;
  value: unknown;
}

function makeGuestError(name: string, message: string): Error {
  const error = new Error(message);
  error.name = name;
  return error;
}

function joinConsoleArgs(
  context: QuickJSContext,
  args: QuickJSHandle[],
): string {
  return args.map((arg) => formatHostValue(context.dump(arg))).join(" ");
}

function setGlobal(
  context: QuickJSContext,
  name: string,
  value: QuickJSHandle,
): void {
  context.setProp(context.global, name, value);
  value.dispose();
}

function installConsole(context: QuickJSContext, state: HostBridgeState): void {
  const consoleHandle = context.newObject();
  for (const level of ["log", "info", "warn", "error"] as JsConsoleLevel[]) {
    const fn = context.newFunction(level, (...args) => {
      state.console.push({
        level,
        text: joinConsoleArgs(context, args),
      });
    });
    context.setProp(consoleHandle, level, fn);
    fn.dispose();
  }
  setGlobal(context, "console", consoleHandle);

  const printHandle = context.newFunction("print", (...args) => {
    state.console.push({
      level: "log",
      text: joinConsoleArgs(context, args),
    });
  });
  setGlobal(context, "print", printHandle);
}

function installReport(context: QuickJSContext, state: HostBridgeState): void {
  const reportHandle = context.newFunction("report", (valueHandle) => {
    state.value = marshalHandle(context, valueHandle);
    state.reported = true;
  });
  setGlobal(context, "report", reportHandle);
}

function installStdin(context: QuickJSContext, stdin: string): void {
  const stdinHandle = context.newString(stdin);
  setGlobal(context, "stdin", stdinHandle);
}

function createPreloadLookup(files: PreloadedTextFile[]): {
  byPath: Map<string, PreloadedTextFile>;
  listedPaths: string[];
} {
  const byPath = new Map<string, PreloadedTextFile>();
  const listedPaths: string[] = [];

  for (const file of files) {
    byPath.set(file.requestedPath, file);
    byPath.set(file.resolvedPath, file);
    listedPaths.push(file.requestedPath);
  }

  return { byPath, listedPaths };
}

function installVfs(
  context: QuickJSContext,
  preloadedFiles: PreloadedTextFile[],
): void {
  const { byPath, listedPaths } = createPreloadLookup(preloadedFiles);
  const vfsHandle = context.newObject();

  const readTextHandle = context.newFunction("readText", (pathHandle) => {
    const path = context.getString(pathHandle);
    const file = byPath.get(path);
    if (!file) {
      throw makeGuestError(
        VFS_NOT_PRELOADED_ERROR,
        `File is not preloaded: ${path}. Add it to preloadFiles before calling vfs.readText(path).`,
      );
    }
    return context.newString(file.text);
  });
  context.setProp(vfsHandle, "readText", readTextHandle);
  readTextHandle.dispose();

  const existsHandle = context.newFunction("exists", (pathHandle) => {
    const path = context.getString(pathHandle);
    return byPath.has(path) ? context.true : context.false;
  });
  context.setProp(vfsHandle, "exists", existsHandle);
  existsHandle.dispose();

  const listHandle = context.newFunction("list", () => {
    const arrayHandle = context.newArray();
    listedPaths.forEach((path, index) => {
      const pathHandle = context.newString(path);
      context.setProp(arrayHandle, index, pathHandle);
      pathHandle.dispose();
    });
    return arrayHandle;
  });
  context.setProp(vfsHandle, "list", listHandle);
  listHandle.dispose();

  setGlobal(context, "vfs", vfsHandle);
}

export function installHostBridge(
  context: QuickJSContext,
  options: {
    stdin?: string;
    preloadedFiles: PreloadedTextFile[];
  },
): HostBridgeState {
  const state: HostBridgeState = {
    console: [],
    reported: false,
    value: undefined,
  };

  installConsole(context, state);
  installReport(context, state);
  installStdin(context, options.stdin ?? "");
  installVfs(context, options.preloadedFiles);

  return state;
}
