import { trackEvent } from "../../telemetry";
import { validateJsonSchema } from "../json-schema";
import { normalizeToolMetadata } from "../tool-metadata";
import type { AssistantMessage, Tool } from "../types";
import type {
  ChildAgentHandle,
  ChildAgentRunner,
  ChildTaskRequest,
} from "./types";

export const CHILD_AGENT_SYSTEM_PROMPT = `You are an isolated read-only worker.
Complete one focused task using only the supplied read tools. Do not modify Office content, email drafts, files, skills, or external systems. Return only a concise final report; omit raw tool output and intermediate reasoning. If an output schema is supplied in the task, return only valid JSON matching that schema.`;

export const PARENT_DELEGATION_PROMPT = `DELEGATION:
- Use task only for focused, multi-step read/research work whose intermediate results would crowd the main context.
- Give the child one self-contained objective and request a concise result.
- Children are read-only and cannot create Office or file deliverables. The main agent remains responsible for all mutations, verification, and the final answer.
- Do not delegate simple one-step reads.`;

export function filterChildAgentTools(tools: readonly Tool[]): Tool[] {
  return tools.filter((tool) => {
    const normalized = normalizeToolMetadata(tool);
    return (
      normalized.origin === "local" &&
      normalized.category === "read" &&
      normalized.name !== "bash" &&
      normalized.name !== "task" &&
      normalized.name !== "enable_mcp_server"
    );
  });
}

function finalAssistantText(handle: ChildAgentHandle): string {
  const message = [...handle.state.messages]
    .reverse()
    .find(
      (candidate): candidate is AssistantMessage =>
        candidate.role === "assistant" &&
        candidate.content.some((block) => block.type === "text"),
    );
  if (!message) return "";
  return message.content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n")
    .trim();
}

function parseStructuredOutput(text: string): unknown {
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return JSON.parse(fenced ? fenced[1] : text);
}

function buildChildPrompt(request: ChildTaskRequest): string {
  if (!request.outputSchema) return request.description;
  return `${request.description}\n\nReturn only JSON matching this schema:\n${JSON.stringify(
    request.outputSchema,
  )}`;
}

export function createChildAgentRunner(options: {
  createAgent: (request: ChildTaskRequest) => ChildAgentHandle;
}): ChildAgentRunner {
  return async (request, signal) => {
    const startedAt = Date.now();
    trackEvent("agent.child_task_started", {
      structured: request.outputSchema ? "true" : "false",
    });
    const child = options.createAgent(request);
    let stopReason: string | undefined;
    let runError: string | undefined;
    const unsubscribe = child.subscribe((event) => {
      if (event.type === "agent_end") {
        stopReason = event.stopReason;
        runError = event.error;
      }
    });
    const abortChild = () => child.abort(signal.reason);
    if (signal.aborted) abortChild();
    else signal.addEventListener("abort", abortChild, { once: true });

    try {
      await child.prompt(buildChildPrompt(request));
      if (signal.aborted || stopReason === "aborted") {
        throw (
          signal.reason ?? new DOMException("Child task aborted", "AbortError")
        );
      }
      if (stopReason && stopReason !== "complete") {
        throw new Error(
          runError ?? `Child task stopped before completion (${stopReason}).`,
        );
      }
      const output = finalAssistantText(child);
      if (!output) throw new Error("Child task returned no final report.");
      if (!request.outputSchema) {
        const result = {
          taskId: request.taskId,
          output,
        };
        trackEvent(
          "agent.child_task_completed",
          { structured: "false", outcome: "complete" },
          { durationMs: Date.now() - startedAt },
        );
        return result;
      }

      let structuredResponse: unknown;
      try {
        structuredResponse = parseStructuredOutput(output);
      } catch {
        throw new Error("Child task did not return valid JSON.");
      }
      if (!validateJsonSchema(request.outputSchema, structuredResponse)) {
        throw new Error("Child task JSON did not match the requested schema.");
      }
      const result = {
        taskId: request.taskId,
        output: JSON.stringify(structuredResponse),
        structuredResponse,
      };
      trackEvent(
        "agent.child_task_completed",
        { structured: "true", outcome: "complete" },
        { durationMs: Date.now() - startedAt },
      );
      return result;
    } catch (error) {
      trackEvent(
        "agent.child_task_completed",
        {
          structured: request.outputSchema ? "true" : "false",
          outcome: signal.aborted ? "aborted" : "error",
        },
        { durationMs: Date.now() - startedAt },
      );
      throw error;
    } finally {
      signal.removeEventListener("abort", abortChild);
      unsubscribe();
      child.dispose();
    }
  };
}
