/**
 * MCP connection config validation (PR-3B.1).
 *
 * Implements docs/mcp-connection-contract.md §3.3. Secrets are never
 * included in diagnostics — only secret-reference shapes are validated.
 */

import { validateEntraAuthFields } from "./entra-auth-validation";
import type {
  MCPAuthConfig,
  MCPConfigDiagnostic,
  MCPConnectionConfig,
  MCPConnectionsConfig,
  MCPNormalizedConnection,
  MCPSecretRef,
  MCPSecretScope,
  MCPTransportKind,
  MCPValidationResult,
} from "./types";

const ID_PATTERN = /^[a-z0-9][a-z0-9_-]{1,31}$/;
const SECRET_KEY_PATTERN = /^[A-Za-z0-9._:-]{3,120}$/;
const HEADER_NAME_PATTERN = /^[A-Za-z0-9-]{1,64}$/;
const TRANSPORTS: ReadonlySet<MCPTransportKind> = new Set([
  "sse",
  "streamable_http",
]);
const SCOPES: ReadonlySet<MCPSecretScope> = new Set(["session", "local"]);

const DEFAULT_REQUEST_TIMEOUT_MS = 30000;
const MIN_REQUEST_TIMEOUT_MS = 1000;
const MAX_REQUEST_TIMEOUT_MS = 120000;
const MAX_DESCRIPTION_CHARS = 200;

const LOCALHOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function pushDiag(
  out: MCPConfigDiagnostic[],
  field: string,
  message: string,
  connectionId?: string,
): void {
  out.push({ field, message, ...(connectionId ? { connectionId } : {}) });
}

function validateSecretRef(
  raw: unknown,
  field: string,
  diagnostics: MCPConfigDiagnostic[],
  connectionId: string | undefined,
): MCPSecretRef | null {
  if (!isPlainObject(raw)) {
    pushDiag(diagnostics, field, "must be an object", connectionId);
    return null;
  }

  const scope = raw.scope;
  if (!isString(scope) || !SCOPES.has(scope as MCPSecretScope)) {
    pushDiag(
      diagnostics,
      `${field}.scope`,
      "must be 'session' or 'local'",
      connectionId,
    );
    return null;
  }

  const key = raw.key;
  if (!isString(key) || !SECRET_KEY_PATTERN.test(key)) {
    pushDiag(
      diagnostics,
      `${field}.key`,
      "must match ^[A-Za-z0-9._:-]{3,120}$",
      connectionId,
    );
    return null;
  }

  return { scope: scope as MCPSecretScope, key };
}

function validateAuth(
  raw: unknown,
  diagnostics: MCPConfigDiagnostic[],
  connectionId: string,
): MCPAuthConfig | null {
  if (raw === undefined) {
    return { type: "none" };
  }
  if (!isPlainObject(raw)) {
    pushDiag(
      diagnostics,
      "auth",
      "must be an object when present",
      connectionId,
    );
    return null;
  }

  const type = raw.type;
  if (type === "none") {
    return { type: "none" };
  }
  if (type === "bearer") {
    const tokenRef = validateSecretRef(
      raw.tokenRef,
      "auth.tokenRef",
      diagnostics,
      connectionId,
    );
    if (!tokenRef) return null;
    return { type: "bearer", tokenRef };
  }
  if (type === "header") {
    const headerName = raw.headerName;
    if (!isString(headerName) || !HEADER_NAME_PATTERN.test(headerName)) {
      pushDiag(
        diagnostics,
        "auth.headerName",
        "must match ^[A-Za-z0-9-]{1,64}$",
        connectionId,
      );
      return null;
    }
    const headerValueRef = validateSecretRef(
      raw.headerValueRef,
      "auth.headerValueRef",
      diagnostics,
      connectionId,
    );
    if (!headerValueRef) return null;
    return { type: "header", headerName, headerValueRef };
  }
  if (type === "entra") {
    const validation = validateEntraAuthFields(
      {
        tenantId: raw.tenantId,
        clientId: raw.clientId,
        scopes: raw.scopes,
        redirectUri: raw.redirectUri,
      },
      { connectionId },
    );
    diagnostics.push(...validation.diagnostics);
    if (validation.diagnostics.length > 0) return null;
    return {
      type: "entra",
      tenantId: validation.tenantId as string,
      clientId: validation.clientId as string,
      scopes: validation.scopes as string[],
      ...(validation.redirectUri
        ? { redirectUri: validation.redirectUri }
        : {}),
    };
  }

  pushDiag(
    diagnostics,
    "auth.type",
    "must be 'none', 'bearer', 'header', or 'entra'",
    connectionId,
  );
  return null;
}

function validateEndpoint(
  raw: unknown,
  diagnostics: MCPConfigDiagnostic[],
  connectionId: string,
): string | null {
  if (!isString(raw)) {
    pushDiag(diagnostics, "endpoint", "must be a string", connectionId);
    return null;
  }
  const trimmed = raw.trim().replace(/\/+$/, "");
  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    pushDiag(diagnostics, "endpoint", "must be an absolute URL", connectionId);
    return null;
  }

  const isHttps = url.protocol === "https:";
  const isHttp = url.protocol === "http:";
  if (!isHttps && !isHttp) {
    pushDiag(diagnostics, "endpoint", "must use http or https", connectionId);
    return null;
  }
  if (isHttp && !LOCALHOSTS.has(url.hostname)) {
    pushDiag(
      diagnostics,
      "endpoint",
      "http is only allowed for localhost endpoints",
      connectionId,
    );
    return null;
  }

  return trimmed;
}

function validateConnection(
  raw: unknown,
  diagnostics: MCPConfigDiagnostic[],
  seenIds: Set<string>,
): MCPNormalizedConnection | null {
  if (!isPlainObject(raw)) {
    pushDiag(diagnostics, "connection", "must be an object");
    return null;
  }

  const idRaw = raw.id;
  if (!isString(idRaw) || !ID_PATTERN.test(idRaw)) {
    pushDiag(
      diagnostics,
      "id",
      "must match ^[a-z0-9][a-z0-9_-]{1,31}$",
      isString(idRaw) ? idRaw : undefined,
    );
    return null;
  }
  const id = idRaw;
  if (seenIds.has(id)) {
    pushDiag(diagnostics, "id", "must be unique", id);
    return null;
  }

  const labelRaw = raw.label;
  const label = isString(labelRaw) ? labelRaw.trim() : "";
  if (!label || label.length > 80) {
    pushDiag(diagnostics, "label", "must be 1..80 chars after trim", id);
    return null;
  }

  let description: string | undefined;
  if (raw.description !== undefined) {
    if (!isString(raw.description)) {
      pushDiag(diagnostics, "description", "must be a string", id);
      return null;
    }
    const trimmed = raw.description.replace(/\s+/g, " ").trim();
    if (trimmed.length > MAX_DESCRIPTION_CHARS) {
      pushDiag(
        diagnostics,
        "description",
        `must be ${MAX_DESCRIPTION_CHARS} chars or less after trim`,
        id,
      );
      return null;
    }
    if (trimmed) {
      description = trimmed;
    }
  }

  const transportRaw = raw.transport;
  if (
    !isString(transportRaw) ||
    !TRANSPORTS.has(transportRaw as MCPTransportKind)
  ) {
    pushDiag(
      diagnostics,
      "transport",
      "must be 'sse' or 'streamable_http'",
      id,
    );
    return null;
  }
  const transport = transportRaw as MCPTransportKind;

  const endpoint = validateEndpoint(raw.endpoint, diagnostics, id);
  if (endpoint === null) return null;

  if (typeof raw.enabled !== "boolean") {
    pushDiag(diagnostics, "enabled", "must be boolean", id);
    return null;
  }
  const enabled = raw.enabled;

  if (raw.alwaysActive !== undefined && typeof raw.alwaysActive !== "boolean") {
    pushDiag(diagnostics, "alwaysActive", "must be boolean", id);
    return null;
  }
  const alwaysActive = raw.alwaysActive === true;

  let requestTimeoutMs = DEFAULT_REQUEST_TIMEOUT_MS;
  if (raw.requestTimeoutMs !== undefined) {
    if (
      typeof raw.requestTimeoutMs !== "number" ||
      !Number.isInteger(raw.requestTimeoutMs) ||
      raw.requestTimeoutMs < MIN_REQUEST_TIMEOUT_MS ||
      raw.requestTimeoutMs > MAX_REQUEST_TIMEOUT_MS
    ) {
      pushDiag(
        diagnostics,
        "requestTimeoutMs",
        `must be integer in [${MIN_REQUEST_TIMEOUT_MS}, ${MAX_REQUEST_TIMEOUT_MS}]`,
        id,
      );
      return null;
    }
    requestTimeoutMs = raw.requestTimeoutMs;
  }

  const parallelSafeRemoteTools: string[] = [];
  if (raw.parallelSafeRemoteTools !== undefined) {
    if (!Array.isArray(raw.parallelSafeRemoteTools)) {
      pushDiag(
        diagnostics,
        "parallelSafeRemoteTools",
        "must be an array of strings",
        id,
      );
      return null;
    }
    const seen = new Set<string>();
    for (const entry of raw.parallelSafeRemoteTools) {
      if (!isString(entry)) {
        pushDiag(
          diagnostics,
          "parallelSafeRemoteTools",
          "every entry must be a string remote tool name",
          id,
        );
        return null;
      }
      const trimmed = entry.trim();
      if (!trimmed) continue;
      if (seen.has(trimmed)) continue;
      seen.add(trimmed);
      parallelSafeRemoteTools.push(trimmed);
    }
  }

  const auth = validateAuth(raw.auth, diagnostics, id);
  if (auth === null) return null;

  seenIds.add(id);
  return {
    id,
    label,
    ...(description ? { description } : {}),
    transport,
    endpoint,
    enabled,
    alwaysActive,
    auth,
    requestTimeoutMs,
    parallelSafeRemoteTools,
  };
}

/**
 * Validate and normalize an MCP connections config blob.
 *
 * Invalid connections are dropped from the active set; diagnostics
 * describe each rejection with the connection id when recoverable.
 * Secrets are NEVER included.
 */
export function validateMCPConnectionsConfig(
  raw: unknown,
): MCPValidationResult {
  const diagnostics: MCPConfigDiagnostic[] = [];

  if (!isPlainObject(raw)) {
    pushDiag(diagnostics, "<root>", "must be an object");
    return { valid: [], diagnostics };
  }

  if (raw.version !== 1) {
    pushDiag(diagnostics, "version", "must equal 1");
    return { valid: [], diagnostics };
  }

  const connectionsRaw = raw.connections;
  if (!Array.isArray(connectionsRaw)) {
    pushDiag(diagnostics, "connections", "must be an array");
    return { valid: [], diagnostics };
  }

  const valid: MCPNormalizedConnection[] = [];
  const seenIds = new Set<string>();
  for (const entry of connectionsRaw) {
    const normalized = validateConnection(entry, diagnostics, seenIds);
    if (normalized) {
      valid.push(normalized);
    }
  }

  return { valid, diagnostics };
}

/** Convenience: filter to enabled connections only. */
export function filterEnabled(
  result: MCPValidationResult,
): MCPNormalizedConnection[] {
  return result.valid.filter((c) => c.enabled);
}

/** Re-export public helpers for callers that need them. */
export {
  DEFAULT_REQUEST_TIMEOUT_MS,
  MAX_REQUEST_TIMEOUT_MS,
  MIN_REQUEST_TIMEOUT_MS,
};

/** Type guard usable elsewhere. */
export function isMCPConnectionsConfig(
  value: unknown,
): value is MCPConnectionsConfig {
  if (!isPlainObject(value)) return false;
  return value.version === 1 && Array.isArray(value.connections);
}
