const STATUS_ICONS: Record<ChatTodo["status"], string> = {
  pending: "☐",
  in_progress: "▶",
  completed: "✓",
  cancelled: "✗",
};

interface TodoCardProps {
  todos: ChatTodo[];
  toolCallsByTodoId?: Map<string, ToolCallPart[]>;
  runStatus?: {
    label: string;
    meta: string;
  };
}

export function TodoCard({
  todos,
  toolCallsByTodoId,
  runStatus,
}: TodoCardProps) {
  const styles = useStyles();
  const [isExpanded, setIsExpanded] = useState(false);
  const [expandedTodoIds, setExpandedTodoIds] = useState<Set<string>>(
    () => new Set(),
  );

  if (!todos || todos.length === 0) return null;

  const completed = todos.filter((t) => t.status === "completed").length;
  const cancelled = todos.filter((t) => t.status === "cancelled").length;
  const total = todos.length;
  const activeTodo = todos.find((t) => t.status === "in_progress");
  const progressText = `${completed}/${total - cancelled}${
    cancelled > 0 ? ` (${cancelled} cancelled)` : ""
  }`;

  const toggleTodo = (id: string) => {
    setExpandedTodoIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  return (
    <section className={styles.card} aria-label="Agent todo list">
      <button
        type="button"
        className={styles.header}
        onClick={() => setIsExpanded((v) => !v)}
        aria-expanded={isExpanded}
        aria-controls="todo-card-list"
      >
        <span className={styles.headerLabel}>
          {isExpanded ? (
            <ChevronDownRegular fontSize={12} />
          ) : (
            <ChevronRightRegular fontSize={12} />
          )}
          <span>{runStatus?.label ?? "todos"}</span>
          {!isExpanded && activeTodo ? (
            <span className={styles.headerSummary}>
              — {activeTodo.activeForm}
            </span>
          ) : null}
        </span>
        <span className={styles.progress}>
          {progressText}
          {runStatus?.meta ? ` · ${runStatus.meta}` : ""}
        </span>
      </button>
      {isExpanded ? (
        <div id="todo-card-list" className={styles.listWrap}>
          <ul className={styles.list}>
            {todos.map((todo) => {
              const styleClass =
                todo.status === "in_progress"
                  ? styles.badgeActive
                  : todo.status === "completed"
                    ? styles.badgeCompleted
                    : todo.status === "cancelled"
                      ? styles.badgeCancelled
                      : styles.badgePending;
              const display =
                todo.status === "in_progress" ? todo.activeForm : todo.content;
              const calls = toolCallsByTodoId?.get(todo.id) ?? [];
              const hasCalls = calls.length > 0;
              const todoExpanded = expandedTodoIds.has(todo.id);
              const rowClassName = hasCalls
                ? `${styles.itemRow} ${styles.itemRowButton}`
                : styles.itemRow;
              const content = (
                <>
                  <span aria-hidden="true">
                    {hasCalls ? (
                      todoExpanded ? (
                        <ChevronDownRegular fontSize={10} />
                      ) : (
                        <ChevronRightRegular fontSize={10} />
                      )
                    ) : (
                      <span style={{ display: "inline-block", width: 10 }} />
                    )}
                  </span>
                  <span aria-hidden="true">{STATUS_ICONS[todo.status]}</span>
                  <span className={styles.itemContent}>
                    {display}
                    {todo.status === "completed" && todo.evidence ? (
                      <span className={styles.evidence}>— {todo.evidence}</span>
                    ) : null}
                    {hasCalls && !todoExpanded ? (
                      <span className={styles.toolCount}>
                        ({calls.length} event{calls.length === 1 ? "" : "s"})
                      </span>
                    ) : null}
                  </span>
                </>
              );
              return (
                <li key={todo.id} className={`${styles.item} ${styleClass}`}>
                  {hasCalls ? (
                    <button
                      type="button"
                      className={rowClassName}
                      onClick={() => toggleTodo(todo.id)}
                      aria-expanded={todoExpanded}
                    >
                      {content}
                    </button>
                  ) : (
                    <div className={rowClassName}>{content}</div>
                  )}
                  {hasCalls && todoExpanded ? (
                    <ToolCallList calls={calls} />
                  ) : null}
                </li>
              );
            })}
          </ul>
        </div>
      ) : null}
    </section>
  );
}

function ToolCallList({ calls }: { calls: ToolCallPart[] }) {
  const styles = useStyles();
  return (
    <ul className={styles.toolList} aria-label="Tool calls">
      {calls.map((call) => {
        const explanation = (call.args as { explanation?: string })
          ?.explanation;
        const detail = call.statusText || explanation;
        return (
          <li key={call.id} className={styles.toolItem}>
            <ToolStatusIcon status={call.status} />
            <WrenchRegular fontSize={10} />
            <span className={styles.toolName}>{call.name}</span>
            {detail ? (
              <span className={styles.toolExplanation}>— {detail}</span>
            ) : null}
          </li>
        );
      })}
    </ul>
  );
}

function ToolStatusIcon({ status }: { status: ToolCallPart["status"] }) {
  switch (status) {
    case "complete":
      return (
        <CheckmarkCircleRegular
          fontSize={12}
          style={{ color: "var(--chat-success, #10b981)" }}
        />
      );
    case "error":
      return (
        <DismissCircleRegular
          fontSize={12}
          style={{ color: "var(--chat-error, #dc2626)" }}
        />
      );
    case "running":
      return <span aria-hidden="true">⏳</span>;
    default:
      return <span aria-hidden="true">⏳</span>;
  }
}
