function SkillsSection() {
  const { state, installSkill, uninstallSkill } = useChat();
  const styles = useStyles();
  const folderInputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [installing, setInstalling] = useState(false);

  const handleFolderSelect = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (!files || files.length === 0) return;
      setInstalling(true);
      try {
        await installSkill(Array.from(files));
      } finally {
        setInstalling(false);
        if (folderInputRef.current) folderInputRef.current.value = "";
      }
    },
    [installSkill],
  );

  const handleFileSelect = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (!files || files.length === 0) return;
      setInstalling(true);
      try {
        await installSkill(Array.from(files));
      } finally {
        setInstalling(false);
        if (fileInputRef.current) fileInputRef.current.value = "";
      }
    },
    [installSkill],
  );

  return (
    <div className={styles.section}>
      <div className={styles.sectionTitle}>agent skills</div>

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: tokens.spacingVerticalS,
        }}
      >
        {state.skills.length > 0 ? (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: tokens.spacingVerticalXS,
            }}
          >
            {state.skills.map((skill) => (
              <Card key={skill.name} className={styles.skillCard}>
                <div className={styles.skillHeader}>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <div className={styles.skillName}>{skill.name}</div>
                    <div className={styles.skillDescription}>
                      {skill.description}
                    </div>
                  </div>
                  <Tooltip content="Remove skill" relationship="label">
                    <Button
                      appearance="transparent"
                      icon={<DeleteRegular fontSize={14} />}
                      onClick={() => uninstallSkill(skill.name)}
                      size="small"
                    />
                  </Tooltip>
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <div className={styles.emptyState}>No skills installed</div>
        )}

        <div className={styles.buttonRow}>
          <Button
            appearance="outline"
            icon={<FolderOpenRegular fontSize={14} />}
            onClick={() => folderInputRef.current?.click()}
            disabled={installing}
            size="small"
            style={{ flex: 1 }}
          >
            {installing ? "Installing..." : "Install from folder"}
          </Button>
          <Button
            appearance="outline"
            icon={<AddRegular fontSize={14} />}
            onClick={() => fileInputRef.current?.click()}
            disabled={installing}
            size="small"
            style={{ flex: 1 }}
          >
            {installing ? "Installing..." : "Add files"}
          </Button>
        </div>
        <Caption2 className={styles.helpText}>
          Skills extend the agent with custom instructions.
        </Caption2>
      </div>

      <input
        ref={folderInputRef}
        type="file"
        // @ts-expect-error webkitdirectory is a non-standard attribute
        webkitdirectory="true"
        directory="true"
        multiple
        style={{ display: "none" }}
        onChange={handleFolderSelect}
      />
      <input
        ref={fileInputRef}
        type="file"
        multiple
        style={{ display: "none" }}
        onChange={handleFileSelect}
      />
    </div>
  );
}

export function SettingsPanel() {
  const { state, setProviderConfig } = useChat();

  const [saved] = useState(loadSavedConfig);
  const azureEnvironment = getRuntimeConfigSync().azureEnvironment;
  const allowedAzureEntraClouds =
    getAzureEntraCloudsForEnvironment(azureEnvironment);
  const visibleAzureEntraClouds = AZURE_ENTRA_CLOUDS.filter((cloud) =>
    allowedAzureEntraClouds.includes(cloud.value),
  );

  // Provider selection
  const [provider, setProvider] = useState<ProviderType>(
    () => saved?.provider ?? "azure",
  );

  // Model selection
  const [model, setModel] = useState(() => saved?.model ?? "");

  // Azure-specific state
  const [apiKey, setApiKey] = useState(() => saved?.apiKey ?? "");
  const [azureEndpoint, setAzureEndpoint] = useState(
    () => saved?.azureEndpoint ?? "",
  );
  const [azureDeploymentName, setAzureDeploymentName] = useState(
    () => saved?.azureDeploymentName ?? "",
  );
  const [azureApiMode, setAzureApiMode] = useState<AzureApiMode>(
    () => saved?.azureApiMode ?? "chat-completions",
  );
  const [useEntraId, setUseEntraId] = useState(
    () => saved?.useEntraId ?? false,
  );
  const [azureClientId, setAzureClientId] = useState(
    () => saved?.azureClientId ?? "",
  );
  const [azureTenantId, setAzureTenantId] = useState(
    () => saved?.azureTenantId ?? "",
  );
  const [azureEntraCloud, setAzureEntraCloud] = useState<AzureEntraCloud>(
    () => saved?.azureEntraCloud ?? allowedAzureEntraClouds[0],
  );
  const [azureEntraAuthorityHost, setAzureEntraAuthorityHost] = useState(
    () => saved?.azureEntraAuthorityHost ?? "",
  );
  const [azureEntraTokenScope, setAzureEntraTokenScope] = useState(
    () => saved?.azureEntraTokenScope ?? "",
  );

  // OpenAI-specific state
  const [openaiBaseUrl, setOpenaiBaseUrl] = useState(
    () => saved?.openaiBaseUrl ?? "",
  );

  // Document Intelligence state
  const [diEndpoint, setDiEndpoint] = useState(
    () => saved?.documentIntelligenceEndpoint ?? "",
  );
  const [diKey, setDiKey] = useState(
    () => saved?.documentIntelligenceKey ?? "",
  );
  const [showDiKey, setShowDiKey] = useState(false);

  // Common settings
  const [showKey, setShowKey] = useState(false);
  const [useProxy, setUseProxy] = useState(() => saved?.useProxy !== false);
  const [proxyUrl, setProxyUrl] = useState(() => saved?.proxyUrl ?? "");
  const [thinking, setThinking] = useState<ThinkingLevel>(
    () => saved?.thinking ?? "none",
  );

  const followMode = state.providerConfig?.followMode ?? true;
  const [saveStatus, setSaveStatus] = useState<string>("");

  // Auto-clear save status after 3 seconds
  useEffect(() => {
    if (saveStatus) {
      const timer = setTimeout(() => setSaveStatus(""), 3000);
      return () => clearTimeout(timer);
    }
    return undefined;
  }, [saveStatus]);

  // Update local state only (no auto-save)
  const updateLocalState = useCallback(
    (updates: Partial<ProviderConfig>) => {
      if ("provider" in updates)
        setProvider((updates.provider as ProviderType) ?? provider);
      if ("model" in updates) setModel(updates.model ?? model);
      if ("apiKey" in updates) setApiKey(updates.apiKey ?? apiKey);
      if ("useProxy" in updates) setUseProxy(updates.useProxy ?? useProxy);
      if ("proxyUrl" in updates) setProxyUrl(updates.proxyUrl ?? proxyUrl);
      if ("thinking" in updates) setThinking(updates.thinking ?? thinking);
      if ("azureEndpoint" in updates)
        setAzureEndpoint(updates.azureEndpoint ?? azureEndpoint);
      if ("azureDeploymentName" in updates)
        setAzureDeploymentName(
          updates.azureDeploymentName ?? azureDeploymentName,
        );
      if ("azureApiMode" in updates)
        setAzureApiMode((updates.azureApiMode as AzureApiMode) ?? azureApiMode);
      if ("useEntraId" in updates)
        setUseEntraId(updates.useEntraId ?? useEntraId);
      if ("azureClientId" in updates)
        setAzureClientId(updates.azureClientId ?? azureClientId);
      if ("azureTenantId" in updates)
        setAzureTenantId(updates.azureTenantId ?? azureTenantId);
      if ("azureEntraCloud" in updates)
        setAzureEntraCloud(updates.azureEntraCloud ?? azureEntraCloud);
      if ("azureEntraAuthorityHost" in updates)
        setAzureEntraAuthorityHost(
          updates.azureEntraAuthorityHost ?? azureEntraAuthorityHost,
        );
      if ("azureEntraTokenScope" in updates)
        setAzureEntraTokenScope(
          updates.azureEntraTokenScope ?? azureEntraTokenScope,
        );
      if ("openaiBaseUrl" in updates)
        setOpenaiBaseUrl(updates.openaiBaseUrl ?? openaiBaseUrl);
      if ("documentIntelligenceEndpoint" in updates)
        setDiEndpoint(updates.documentIntelligenceEndpoint ?? diEndpoint);
      if ("documentIntelligenceKey" in updates)
        setDiKey(updates.documentIntelligenceKey ?? diKey);
    },
    [
      provider,
      model,
      apiKey,
      useProxy,
      proxyUrl,
      thinking,
      azureEndpoint,
      azureDeploymentName,
      azureApiMode,
      useEntraId,
      azureClientId,
      azureTenantId,
      azureEntraCloud,
      azureEntraAuthorityHost,
      azureEntraTokenScope,
      openaiBaseUrl,
      diEndpoint,
      diKey,
    ],
  );

  // Manual save function
  const handleSave = useCallback(() => {
    const config: ProviderConfig = {
      provider,
      apiKey,
      model,
      useProxy,
      proxyUrl,
      thinking,
      followMode,
      azureEndpoint,
      azureDeploymentName,
      azureApiMode,
      useEntraId,
      azureClientId,
      azureTenantId,
      azureEntraCloud,
      azureEntraAuthorityHost,
      azureEntraTokenScope,
      openaiBaseUrl,
      documentIntelligenceEndpoint: diEndpoint,
      documentIntelligenceKey: diKey,
      myAiBaseUrl: "",
    };

    // Check validity with specific error message based on provider
    const missingFields: string[] = [];
    if (provider === "azure") {
      if (!config.azureEndpoint?.trim()) missingFields.push("Endpoint");
      if (!config.azureDeploymentName?.trim())
        missingFields.push("Deployment Name");
      if (config.useEntraId && !config.azureClientId?.trim())
        missingFields.push("Entra Client ID");
      if (
        config.useEntraId &&
        config.azureEntraCloud === "usnat" &&
        !config.azureEntraAuthorityHost.trim()
      )
        missingFields.push("Entra Authority Host");
      if (
        config.useEntraId &&
        config.azureEntraCloud === "usnat" &&
        !config.azureEntraTokenScope.trim()
      )
        missingFields.push("Azure OpenAI Token Scope");
      if (!config.useEntraId && !config.apiKey?.trim())
        missingFields.push("API Key");
    } else if (provider === "my-ai") {
      if (!config.apiKey?.trim()) missingFields.push("API Key");
      if (!config.model?.trim()) missingFields.push("Model");
    }

    if (missingFields.length > 0) {
      setSaveStatus(`Missing: ${missingFields.join(", ")}`);
      return;
    }

    const constrainedConfig = saveConfig(config);
    setProviderConfig(constrainedConfig);
    setSaveStatus("Saved successfully");
  }, [
    provider,
    apiKey,
    model,
    useProxy,
    proxyUrl,
    thinking,
    followMode,
    azureEndpoint,
    azureDeploymentName,
    azureApiMode,
    useEntraId,
    azureClientId,
    azureTenantId,
    azureEntraCloud,
    azureEntraAuthorityHost,
    azureEntraTokenScope,
    openaiBaseUrl,
    diEndpoint,
    diKey,
    setProviderConfig,
  ]);

  // Legacy function for backwards compatibility with toggle/switch controls
  const updateAndSync = useCallback(
    (updates: Partial<ProviderConfig>) => {
      updateLocalState(updates);
    },
    [updateLocalState],
  );

  const isConfigured = state.providerConfig !== null;
  const styles = useStyles();
  const missingFieldSet = saveStatus.startsWith("Missing: ")
    ? new Set(saveStatus.replace("Missing: ", "").split(", "))
    : new Set<string>();
  const keyVisibilityLabel = showKey ? "Hide API key" : "Show API key";
  const diKeyVisibilityLabel = showDiKey
    ? "Hide Document Intelligence API key"
    : "Show Document Intelligence API key";
  const configuredProviderName =
    state.providerConfig?.provider === "my-ai" ? "My AI" : "Azure OpenAI";
  const configuredAuthSuffix =
    state.providerConfig?.provider === "azure" &&
    state.providerConfig.useEntraId
      ? " via Entra ID"
      : "";

  return (
    <div className={styles.root}>
      {/* Provider Selection */}
      <div className={styles.section}>
        <div className={styles.sectionTitle}>AI Provider</div>
        <div className={styles.inputRow}>
          <Label size="small">Provider</Label>
          <fieldset aria-label="AI provider" className={styles.toggleGroup}>
            {PROVIDERS.map((p) => (
              <Button
                key={p.id}
                aria-pressed={provider === p.id}
                appearance={provider === p.id ? "primary" : "outline"}
                onClick={() => updateAndSync({ provider: p.id })}
                size="small"
                style={{ flex: 1 }}
              >
                {p.name}
              </Button>
            ))}
          </fieldset>
        </div>
      </div>
      {/* Azure Configuration */}
      {provider === "azure" && (
        <div className={styles.section}>
          <div className={styles.sectionTitle}>Azure OpenAI Configuration</div>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: tokens.spacingVerticalM,
            }}
          >
            {/* Azure Endpoint */}
            <div className={styles.inputRow}>
              <Label size="small">Azure Endpoint</Label>
              <Input
                aria-invalid={missingFieldSet.has("Endpoint")}
                aria-required
                type="text"
                value={azureEndpoint}
                onChange={(e) =>
                  updateAndSync({ azureEndpoint: e.target.value })
                }
                placeholder="https://your-resource.openai.azure.com/"
                size="small"
              />
              <Caption2 className={styles.helpText}>
                Your Azure OpenAI resource endpoint URL
              </Caption2>
            </div>

            {/* Deployment Name */}
            <div className={styles.inputRow}>
              <Label size="small">Deployment Name</Label>
              <Input
                aria-invalid={missingFieldSet.has("Deployment Name")}
                aria-required
                type="text"
                value={azureDeploymentName}
                onChange={(e) =>
                  updateAndSync({ azureDeploymentName: e.target.value })
                }
                placeholder="your-deployment-name"
                size="small"
              />
              <Caption2 className={styles.helpText}>
                The deployment name from Azure OpenAI Studio
              </Caption2>
            </div>

            {/* Azure API Mode */}
            <div className={styles.inputRow}>
              <Label size="small">Azure API</Label>
              <fieldset
                aria-label="Azure API mode"
                className={styles.toggleGroup}
              >
                <Button
                  aria-pressed={azureApiMode === "chat-completions"}
                  appearance={
                    azureApiMode === "chat-completions" ? "primary" : "outline"
                  }
                  onClick={() =>
                    updateAndSync({ azureApiMode: "chat-completions" })
                  }
                  size="small"
                  style={{ flex: 1 }}
                >
                  Chat Completions
                </Button>
                <Button
                  aria-pressed={azureApiMode === "responses"}
                  appearance={
                    azureApiMode === "responses" ? "primary" : "outline"
                  }
                  onClick={() => updateAndSync({ azureApiMode: "responses" })}
                  size="small"
                  style={{ flex: 1 }}
                >
                  Responses
                </Button>
              </fieldset>
              <Caption2 className={styles.helpText}>
                Select the operation supported by your Azure model deployment.
              </Caption2>
            </div>

            {/* Authentication method */}
            <div className={styles.inputRow}>
              <Label size="small">Authentication</Label>
              <fieldset
                aria-label="Authentication method"
                className={styles.toggleGroup}
              >
                <Button
                  aria-pressed={!useEntraId}
                  appearance={!useEntraId ? "primary" : "outline"}
                  onClick={() => updateAndSync({ useEntraId: false })}
                  size="small"
                  style={{ flex: 1 }}
                >
                  API Key
                </Button>
                <Button
                  aria-pressed={useEntraId}
                  appearance={useEntraId ? "primary" : "outline"}
                  onClick={() => updateAndSync({ useEntraId: true })}
                  size="small"
                  style={{ flex: 1 }}
                >
                  Entra ID
                </Button>
              </fieldset>
              <Caption2 className={styles.helpText}>
                {useEntraId
                  ? "Use interactive browser authentication (Microsoft Entra ID)"
                  : "Use Azure OpenAI API key"}
              </Caption2>
            </div>

            {/* API Key - only show when not using Entra ID */}
            {!useEntraId && (
              <div className={styles.inputRow}>
                <Label size="small">API Key</Label>
                <div className={styles.inputWithButton}>
                  <Input
                    aria-invalid={missingFieldSet.has("API Key")}
                    aria-required
                    type={showKey ? "text" : "password"}
                    value={apiKey}
                    onChange={(e) => updateAndSync({ apiKey: e.target.value })}
                    placeholder="Enter your Azure OpenAI API key"
                    size="small"
                    style={{ flex: 1 }}
                  />
                  <Tooltip content={keyVisibilityLabel} relationship="label">
                    <Button
                      appearance="transparent"
                      aria-label={keyVisibilityLabel}
                      icon={
                        showKey ? (
                          <EyeOffRegular fontSize={14} />
                        ) : (
                          <EyeRegular fontSize={14} />
                        )
                      }
                      onClick={() => setShowKey(!showKey)}
                      size="small"
                    />
                  </Tooltip>
                </div>
              </div>
            )}

            {/* Entra settings */}
            {useEntraId && (
              <div className={styles.inputRow}>
                <Label size="small">Azure cloud</Label>
                <fieldset
                  aria-label="Azure cloud"
                  className={styles.toggleGroup}
                >
                  {visibleAzureEntraClouds.map((cloud) => (
                    <Button
                      key={cloud.value}
                      aria-pressed={azureEntraCloud === cloud.value}
                      appearance={
                        azureEntraCloud === cloud.value ? "primary" : "outline"
                      }
                      onClick={() =>
                        updateAndSync({ azureEntraCloud: cloud.value })
                      }
                      size="small"
                      style={{ flex: 1 }}
                    >
                      {cloud.label}
                    </Button>
                  ))}
                </fieldset>
                <Caption2 className={styles.helpText}>
                  {azureEnvironment === "ts"
                    ? "Restricted to USNat by runtime configuration."
                    : "Standard GCC uses Commercial. GCC High and DoD use the US Government authority."}
                </Caption2>
              </div>
            )}

            {useEntraId && azureEntraCloud === "usnat" && (
              <div className={styles.inputRow}>
                <Label size="small">Entra authority host</Label>
                <Input
                  type="text"
                  value={azureEntraAuthorityHost}
                  onChange={(e) =>
                    updateAndSync({ azureEntraAuthorityHost: e.target.value })
                  }
                  placeholder="https://login.restricted.example"
                  size="small"
                />
                <Caption2 className={styles.helpText}>
                  Required. Use the authority host supplied by your deployment
                  operator.
                </Caption2>
              </div>
            )}

            {useEntraId && azureEntraCloud === "usnat" && (
              <div className={styles.inputRow}>
                <Label size="small">Azure OpenAI token scope</Label>
                <Input
                  type="text"
                  value={azureEntraTokenScope}
                  onChange={(e) =>
                    updateAndSync({ azureEntraTokenScope: e.target.value })
                  }
                  placeholder="https://cognitiveservices.restricted.example/.default"
                  size="small"
                />
                <Caption2 className={styles.helpText}>
                  Required. Use the scope supplied by your deployment operator.
                </Caption2>
              </div>
            )}

            {useEntraId && (
              <div className={styles.inputRow}>
                <Label size="small">Entra Client ID</Label>
                <Input
                  aria-invalid={missingFieldSet.has("Entra Client ID")}
                  aria-required
                  type="text"
                  value={azureClientId}
                  onChange={(e) =>
                    updateAndSync({ azureClientId: e.target.value })
                  }
                  placeholder="00000000-0000-0000-0000-000000000000"
                  size="small"
                />
                <Caption2 className={styles.helpText}>
                  Application (client) ID from your Microsoft Entra app
                  registration
                </Caption2>
              </div>
            )}

            {/* Entra Tenant ID - only show when using Entra ID */}
            {useEntraId && (
              <div className={styles.inputRow}>
                <Label size="small">Entra Tenant ID</Label>
                <Input
                  type="text"
                  value={azureTenantId}
                  onChange={(e) =>
                    updateAndSync({ azureTenantId: e.target.value })
                  }
                  placeholder="common"
                  size="small"
                />
                <Caption2 className={styles.helpText}>
                  Directory (tenant) ID, or common / organizations / consumers.
                  Defaults to common when left blank.
                </Caption2>
              </div>
            )}

            {/* Save Button */}
            <div className={styles.saveButtonContainer}>
              <Button appearance="primary" onClick={handleSave} size="small">
                Save Configuration
              </Button>
              {saveStatus && (
                <span
                  aria-live="polite"
                  className={styles.saveStatus}
                  role={saveStatus.startsWith("Missing: ") ? "alert" : "status"}
                >
                  {saveStatus}
                </span>
              )}
            </div>

            {/* CORS Proxy */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
              }}
            >
              <div>
                <Label size="small">CORS Proxy</Label>
                <Caption2 className={styles.helpText}>
                  May be needed for certain Azure connections
                </Caption2>
              </div>
              <Switch
                aria-label="Use CORS proxy"
                checked={useProxy}
                onChange={() => updateAndSync({ useProxy: !useProxy })}
              />
            </div>

            {useProxy && (
              <div className={styles.inputRow}>
                <Label size="small">Proxy URL</Label>
                <Input
                  type="text"
                  value={proxyUrl}
                  onChange={(e) => updateAndSync({ proxyUrl: e.target.value })}
                  placeholder="https://your-proxy.com/proxy"
                  size="small"
                />
                <Caption2 className={styles.helpText}>
                  Your proxy should accept ?url=encoded_url format
                </Caption2>
              </div>
            )}

            {/* Thinking Level */}
            <div className={styles.inputRow}>
              <Label size="small">Thinking Level</Label>
              <fieldset
                aria-label="Thinking level"
                className={styles.toggleGroup}
              >
                {THINKING_LEVELS.map((level) => (
                  <Button
                    key={level.value}
                    aria-pressed={thinking === level.value}
                    appearance={
                      thinking === level.value ? "primary" : "outline"
                    }
                    onClick={() => updateAndSync({ thinking: level.value })}
                    size="small"
                    style={{ flex: 1 }}
                  >
                    {level.label}
                  </Button>
                ))}
              </fieldset>
              <Caption2 className={styles.helpText}>
                Extended thinking for supported models
              </Caption2>
            </div>
          </div>
        </div>
      )}
      {/* OpenAI Configuration */}
      {provider === "my-ai" && (
        <div className={styles.section}>
          <div className={styles.sectionTitle}>
            My AI (OpenAI-compatible) Configuration
          </div>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: tokens.spacingVerticalM,
            }}
          >
            {/* Model Input */}
            <div className={styles.inputRow}>
              <Label size="small">Model</Label>
              <Input
                aria-invalid={missingFieldSet.has("Model")}
                aria-required
                type="text"
                value={model}
                onChange={(e) => updateAndSync({ model: e.target.value })}
                placeholder="e.g., gpt-4o, llama-3-70b, codellama-13b"
                size="small"
              />
              <Caption2 className={styles.helpText}>
                Enter the model name for your OpenAI-compatible API endpoint
                (e.g., gpt-4o, mixtral-8x7b)
              </Caption2>
            </div>

            {/* API Key */}
            <div className={styles.inputRow}>
              <Label size="small">API Key</Label>
              <div className={styles.inputWithButton}>
                <Input
                  aria-invalid={missingFieldSet.has("API Key")}
                  aria-required
                  type={showKey ? "text" : "password"}
                  value={apiKey}
                  onChange={(e) => updateAndSync({ apiKey: e.target.value })}
                  placeholder="Enter your API key"
                  size="small"
                  style={{ flex: 1 }}
                />
                <Tooltip content={keyVisibilityLabel} relationship="label">
                  <Button
                    appearance="transparent"
                    aria-label={keyVisibilityLabel}
                    icon={
                      showKey ? (
                        <EyeOffRegular fontSize={14} />
                      ) : (
                        <EyeRegular fontSize={14} />
                      )
                    }
                    onClick={() => setShowKey(!showKey)}
                    size="small"
                  />
                </Tooltip>
              </div>
              <Caption2 className={styles.helpText}>
                Your API key for the OpenAI-compatible endpoint
              </Caption2>
            </div>

            {/* Base URL (optional) */}
            <div className={styles.inputRow}>
              <Label size="small">Base URL (Optional)</Label>
              <Input
                type="text"
                value={openaiBaseUrl}
                onChange={(e) =>
                  updateAndSync({ openaiBaseUrl: e.target.value })
                }
                placeholder="https://api.openai.com/v1"
                size="small"
              />
              <Caption2 className={styles.helpText}>
                Custom base URL for OpenAI-compatible APIs
              </Caption2>
            </div>

            {/* Save Button */}
            <div className={styles.saveButtonContainer}>
              <Button appearance="primary" onClick={handleSave} size="small">
                Save Configuration
              </Button>
              {saveStatus && (
                <span
                  aria-live="polite"
                  className={styles.saveStatus}
                  role={saveStatus.startsWith("Missing: ") ? "alert" : "status"}
                >
                  {saveStatus}
                </span>
              )}
            </div>

            {/* Thinking Level */}
            <div className={styles.inputRow}>
              <Label size="small">Thinking Level</Label>
              <fieldset
                aria-label="Thinking level"
                className={styles.toggleGroup}
              >
                {THINKING_LEVELS.map((level) => (
                  <Button
                    key={level.value}
                    aria-pressed={thinking === level.value}
                    appearance={
                      thinking === level.value ? "primary" : "outline"
                    }
                    onClick={() => updateAndSync({ thinking: level.value })}
                    size="small"
                    style={{ flex: 1 }}
                  >
                    {level.label}
                  </Button>
                ))}
              </fieldset>
              <Caption2 className={styles.helpText}>
                Extended thinking for supported models
              </Caption2>
            </div>
          </div>
        </div>
      )}
      <Divider /> {/* Document Intelligence Configuration */}
      <div className={styles.section}>
        <div className={styles.sectionTitle}>Document Intelligence</div>
        <Caption2
          className={styles.helpText}
          style={{ marginBottom: tokens.spacingVerticalS }}
        >
          Automatically extract text from PDFs, Word docs, and images using
          Azure AI Document Intelligence
        </Caption2>

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: tokens.spacingVerticalM,
          }}
        >
          {/* DI Endpoint */}
          <div className={styles.inputRow}>
            <Label size="small">Endpoint</Label>
            <Input
              type="text"
              value={diEndpoint}
              onChange={(e) =>
                updateAndSync({ documentIntelligenceEndpoint: e.target.value })
              }
              placeholder="https://your-resource.cognitiveservices.azure.com/"
              size="small"
            />
            <Caption2 className={styles.helpText}>
              Your Document Intelligence resource endpoint URL
            </Caption2>
          </div>

          {/* DI API Key */}
          <div className={styles.inputRow}>
            <Label size="small">API Key</Label>
            <div className={styles.inputWithButton}>
              <Input
                type={showDiKey ? "text" : "password"}
                value={diKey}
                onChange={(e) =>
                  updateAndSync({ documentIntelligenceKey: e.target.value })
                }
                placeholder="Enter your Document Intelligence API key"
                size="small"
                style={{ flex: 1 }}
              />
              <Tooltip content={diKeyVisibilityLabel} relationship="label">
                <Button
                  appearance="transparent"
                  aria-label={diKeyVisibilityLabel}
                  icon={
                    showDiKey ? (
                      <EyeOffRegular fontSize={14} />
                    ) : (
                      <EyeRegular fontSize={14} />
                    )
                  }
                  onClick={() => setShowDiKey(!showDiKey)}
                  size="small"
                />
              </Tooltip>
            </div>
          </div>
        </div>
      </div>
      <Divider />
      <MCPConnectionsSection />
      <Divider />
      {/* Status */}
      <div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: tokens.spacingHorizontalXS,
          }}
        >
          {isConfigured ? (
            <>
              <CheckmarkRegular
                fontSize={14}
                style={{ color: tokens.colorStatusSuccessForeground1 }}
              />
              <Caption2 style={{ color: tokens.colorNeutralForeground2 }}>
                Connected to {configuredProviderName}
                {configuredAuthSuffix}
              </Caption2>
            </>
          ) : (
            <Caption2 style={{ color: tokens.colorNeutralForeground3 }}>
              Fill in all fields above to get started
            </Caption2>
          )}
        </div>
      </div>
      <Divider />
      {/* Skills */}
      <SkillsSection />
      <Divider />
      {/* About */}
      <div className={styles.section}>
        <div className={styles.sectionTitle}>about</div>
        <Text
          size={300}
          style={{
            color: tokens.colorNeutralForeground2,
            lineHeight: tokens.lineHeightBase300,
          }}
        >
          OfficeAI uses your configured AI provider. API keys are stored locally
          in the browser.
        </Text>
        <Caption2
          style={{
            color: tokens.colorNeutralForeground3,
            marginTop: tokens.spacingVerticalS,
          }}
        >
          v{__APP_VERSION__}
        </Caption2>
        <Caption2
          style={{
            color: tokens.colorNeutralForeground3,
          }}
        >
          Built {new Date(__BUILD_TIME__).toLocaleString()}
        </Caption2>
      </div>
    </div>
  );
}
