/**
 * Streaming JSON arguments extractor.
 *
 * Parses a JSON object value that arrives in arbitrary chunks (typically
 * the `function.arguments` field of a tool-call streamed by an OpenAI-
 * compatible provider). Emits incremental events for top-level keys:
 *
 *   - String values: `onStringStart` -> N x `onStringDelta(decoded)` ->
 *     `onStringEnd`. Decoded means JSON escapes have been resolved
 *     (`\n`, `\t`, `\uXXXX`, surrogate pairs, etc.).
 *   - Non-string values (numbers, booleans, null, nested objects/arrays):
 *     buffered internally and emitted once via `onValue(key, value)`.
 *
 * Only top-level keys produce events. Nested string values are not
 * emitted incrementally — their containing object/array is buffered and
 * emitted as a single parsed value via `onValue`.
 *
 * The parser is fully restartable across `feed(chunk)` calls: partial
 * escape sequences (`\u`, `\n`), partial unicode hex digits, and lone
 * high surrogates are buffered across chunk boundaries.
 *
 * `finish()` reports whether the input completed cleanly and, if the
 * parser was suspended mid-string-value, which key was open. This lets
 * a consumer commit partial bytes when the model hits
 * `finish_reason: "length"` mid-`content`.
 *
 * Stream-to-VFS Plan: Phase A.
 */

export interface StreamingArgsExtractorEvents {
  onValue?(key: string, value: unknown): void;
  onStringStart?(key: string): void;
  onStringDelta?(key: string, decoded: string): void;
  onStringEnd?(key: string): void;
  onError?(err: Error): void;
}

export interface StreamingArgsFinish {
  /** True iff the parser observed the closing `}` of the top-level object. */
  complete: boolean;
  /** Set when the parser was suspended mid-string-value at finish time. */
  openStringKey?: string;
  /** Set when the parser entered an unrecoverable error state. */
  error?: string;
}

type State =
  | "before-object"
  | "expect-key-or-close"
  | "in-key"
  | "expect-colon"
  | "expect-value"
  | "in-string-value"
  | "in-primitive-value"
  | "in-nested-value"
  | "expect-comma-or-close"
  | "done"
  | "error";

type StringTarget = "key" | "value";

function isWhitespace(c: string): boolean {
  return c === " " || c === "\t" || c === "\n" || c === "\r";
}

function isHexDigit(c: string): boolean {
  return (
    (c >= "0" && c <= "9") || (c >= "a" && c <= "f") || (c >= "A" && c <= "F")
  );
}

export class StreamingArgsExtractor {
  private readonly events: StreamingArgsExtractorEvents;

  private state: State = "before-object";
  private buf = "";
  private pos = 0;
  private finished = false;
  private errorMsg?: string;

  private currentKey = "";

  // String-decoding state (shared by key and value strings).
  private stringTarget: StringTarget = "key";
  private keyChars: string[] = [];
  private stringEscape = false;
  private collectingUnicode = false;
  private unicodeHexBuf = "";
  private highSurrogate: number | null = null;

  // Primitive value (number/true/false/null) accumulator.
  private primitiveBuf = "";

  // Nested value (object/array) tokenizer state.
  private nestDepth = 0;
  private nestInString = false;
  private nestStringEscape = false;
  private nestRaw = "";

  constructor(events: StreamingArgsExtractorEvents) {
    this.events = events;
  }

  feed(chunk: string): void {
    if (this.finished || !chunk) return;
    if (this.state === "done" || this.state === "error") return;
    // Compact consumed prefix so buf doesn't grow without bound.
    if (this.pos > 0) {
      this.buf = this.buf.slice(this.pos);
      this.pos = 0;
    }
    this.buf += chunk;
    this.run();
  }

  finish(): StreamingArgsFinish {
    this.finished = true;
    if (this.state === "done") return { complete: true };
    if (this.state === "error") {
      return { complete: false, error: this.errorMsg ?? "parse error" };
    }
    if (this.state === "in-string-value") {
      // Flush a pending high surrogate so the consumer sees a sensible tail.
      if (this.highSurrogate !== null) {
        try {
          this.events.onStringDelta?.(this.currentKey, "\uFFFD");
        } catch (e) {
          // propagate via onError; don't swallow silently
          this.reportSinkError(e);
        }
        this.highSurrogate = null;
      }
      return { complete: false, openStringKey: this.currentKey };
    }
    return { complete: false };
  }

  // ---------- main loop ----------

  private run(): void {
    while (this.pos < this.buf.length) {
      if (this.state === "done" || this.state === "error") return;
      switch (this.state) {
        case "before-object":
          if (!this.handleBeforeObject()) return;
          break;
        case "expect-key-or-close":
          if (!this.handleExpectKeyOrClose()) return;
          break;
        case "in-key":
          if (!this.processStringChars()) return;
          this.currentKey = this.keyChars.join("");
          this.keyChars = [];
          this.state = "expect-colon";
          break;
        case "expect-colon":
          if (!this.handleExpectColon()) return;
          break;
        case "expect-value":
          if (!this.handleExpectValue()) return;
          break;
        case "in-string-value":
          if (!this.processStringChars()) return;
          try {
            this.events.onStringEnd?.(this.currentKey);
          } catch (e) {
            this.reportSinkError(e);
          }
          this.state = "expect-comma-or-close";
          break;
        case "in-primitive-value":
          if (!this.handlePrimitiveValue()) return;
          break;
        case "in-nested-value":
          if (!this.handleNestedValue()) return;
          break;
        case "expect-comma-or-close":
          if (!this.handleExpectCommaOrClose()) return;
          break;
      }
    }
  }

  private handleBeforeObject(): boolean {
    this.skipWhitespace();
    if (this.pos >= this.buf.length) return false;
    const c = this.buf[this.pos];
    if (c !== "{") {
      this.fail(`expected '{' at start, got ${JSON.stringify(c)}`);
      return false;
    }
    this.pos++;
    this.state = "expect-key-or-close";
    return true;
  }

  private handleExpectKeyOrClose(): boolean {
    this.skipWhitespace();
    if (this.pos >= this.buf.length) return false;
    const c = this.buf[this.pos];
    if (c === "}") {
      this.pos++;
      this.state = "done";
      return false; // signal stop; outer loop will check state on next iter
    }
    if (c === '"') {
      this.pos++;
      this.state = "in-key";
      this.stringTarget = "key";
      this.keyChars = [];
      this.resetStringDecodeState();
      return true;
    }
    this.fail(`expected '"' or '}', got ${JSON.stringify(c)}`);
    return false;
  }

  private handleExpectColon(): boolean {
    this.skipWhitespace();
    if (this.pos >= this.buf.length) return false;
    const c = this.buf[this.pos];
    if (c !== ":") {
      this.fail(`expected ':', got ${JSON.stringify(c)}`);
      return false;
    }
    this.pos++;
    this.state = "expect-value";
    return true;
  }

  private handleExpectValue(): boolean {
    this.skipWhitespace();
    if (this.pos >= this.buf.length) return false;
    const c = this.buf[this.pos];
    if (c === '"') {
      this.pos++;
      this.state = "in-string-value";
      this.stringTarget = "value";
      this.resetStringDecodeState();
      try {
        this.events.onStringStart?.(this.currentKey);
      } catch (e) {
        this.reportSinkError(e);
      }
      return true;
    }
    if (c === "{" || c === "[") {
      this.state = "in-nested-value";
      this.nestDepth = 1;
      this.nestInString = false;
      this.nestStringEscape = false;
      this.nestRaw = c;
      this.pos++;
      return true;
    }
    // Primitive: number, true, false, null
    this.state = "in-primitive-value";
    this.primitiveBuf = "";
    return true;
  }

  private handlePrimitiveValue(): boolean {
    while (this.pos < this.buf.length) {
      const c = this.buf[this.pos];
      if (c === "," || c === "}" || isWhitespace(c)) break;
      this.primitiveBuf += c;
      this.pos++;
    }
    if (this.pos >= this.buf.length) return false; // need more data
    let parsed: unknown;
    try {
      parsed = JSON.parse(this.primitiveBuf);
    } catch {
      this.fail(`invalid primitive value ${JSON.stringify(this.primitiveBuf)}`);
      return false;
    }
    try {
      this.events.onValue?.(this.currentKey, parsed);
    } catch (e) {
      this.reportSinkError(e);
    }
    this.state = "expect-comma-or-close";
    return true;
  }

  private handleNestedValue(): boolean {
    while (this.pos < this.buf.length) {
      const c = this.buf[this.pos];
      this.nestRaw += c;
      this.pos++;
      if (this.nestInString) {
        if (this.nestStringEscape) {
          this.nestStringEscape = false;
        } else if (c === "\\") {
          this.nestStringEscape = true;
        } else if (c === '"') {
          this.nestInString = false;
        }
        continue;
      }
      if (c === '"') {
        this.nestInString = true;
        continue;
      }
      if (c === "{" || c === "[") {
        this.nestDepth++;
        continue;
      }
      if (c === "}" || c === "]") {
        this.nestDepth--;
        if (this.nestDepth === 0) {
          let parsed: unknown;
          try {
            parsed = JSON.parse(this.nestRaw);
          } catch {
            this.fail(
              `invalid nested value for key ${JSON.stringify(this.currentKey)}`,
            );
            return false;
          }
          try {
            this.events.onValue?.(this.currentKey, parsed);
          } catch (e) {
            this.reportSinkError(e);
          }
          this.state = "expect-comma-or-close";
          return true;
        }
      }
    }
    return false; // need more data
  }

  private handleExpectCommaOrClose(): boolean {
    this.skipWhitespace();
    if (this.pos >= this.buf.length) return false;
    const c = this.buf[this.pos];
    if (c === ",") {
      this.pos++;
      this.state = "expect-key-or-close";
      return true;
    }
    if (c === "}") {
      this.pos++;
      this.state = "done";
      return false;
    }
    this.fail(`expected ',' or '}', got ${JSON.stringify(c)}`);
    return false;
  }

  // ---------- string decoding ----------

  /**
   * Consume characters of the current string literal (key or top-level
   * value). Returns `true` when the closing `"` was consumed; `false`
   * if the buffer is exhausted mid-string.
   */
  private processStringChars(): boolean {
    while (this.pos < this.buf.length) {
      if (this.collectingUnicode) {
        while (this.pos < this.buf.length && this.unicodeHexBuf.length < 4) {
          const c = this.buf[this.pos];
          if (!isHexDigit(c)) {
            this.fail(`invalid unicode escape '\\u${this.unicodeHexBuf}${c}'`);
            return false;
          }
          this.unicodeHexBuf += c;
          this.pos++;
        }
        if (this.unicodeHexBuf.length < 4) return false;
        const cp = Number.parseInt(this.unicodeHexBuf, 16);
        this.unicodeHexBuf = "";
        this.collectingUnicode = false;
        this.appendCodePoint(cp);
        continue;
      }

      if (this.stringEscape) {
        const ch = this.buf[this.pos];
        this.pos++;
        this.stringEscape = false;
        if (ch === "u") {
          this.collectingUnicode = true;
          continue;
        }
        let decoded: string;
        switch (ch) {
          case '"':
            decoded = '"';
            break;
          case "\\":
            decoded = "\\";
            break;
          case "/":
            decoded = "/";
            break;
          case "b":
            decoded = "\b";
            break;
          case "f":
            decoded = "\f";
            break;
          case "n":
            decoded = "\n";
            break;
          case "r":
            decoded = "\r";
            break;
          case "t":
            decoded = "\t";
            break;
          default:
            this.fail(`invalid escape '\\${ch}'`);
            return false;
        }
        this.flushPendingHighSurrogate();
        this.emitDecoded(decoded);
        continue;
      }

      // Plain run: scan forward to next interesting char.
      const start = this.pos;
      while (this.pos < this.buf.length) {
        const c = this.buf[this.pos];
        if (c === '"' || c === "\\") break;
        const code = c.charCodeAt(0);
        if (code < 0x20) {
          this.fail(
            `unescaped control char U+${code.toString(16).padStart(4, "0")}`,
          );
          return false;
        }
        this.pos++;
      }
      if (this.pos > start) {
        this.flushPendingHighSurrogate();
        this.emitDecoded(this.buf.slice(start, this.pos));
      }
      if (this.pos >= this.buf.length) return false;

      const next = this.buf[this.pos];
      if (next === '"') {
        this.pos++;
        // String ended. Lone pending high surrogate becomes U+FFFD.
        this.flushPendingHighSurrogate();
        return true;
      }
      // next === '\\'
      this.pos++;
      this.stringEscape = true;
    }
    return false;
  }

  private appendCodePoint(cp: number): void {
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate.
      if (this.highSurrogate !== null) this.emitDecoded("\ufffd");
      this.highSurrogate = cp;
      return;
    }
    if (cp >= 0xdc00 && cp <= 0xdfff) {
      // Low surrogate.
      if (this.highSurrogate !== null) {
        const combined =
          0x10000 + ((this.highSurrogate - 0xd800) << 10) + (cp - 0xdc00);
        this.highSurrogate = null;
        this.emitDecoded(String.fromCodePoint(combined));
      } else {
        this.emitDecoded("\ufffd");
      }
      return;
    }
    this.flushPendingHighSurrogate();
    this.emitDecoded(String.fromCodePoint(cp));
  }

  private flushPendingHighSurrogate(): void {
    if (this.highSurrogate !== null) {
      this.emitDecoded("\ufffd");
      this.highSurrogate = null;
    }
  }

  private emitDecoded(s: string): void {
    if (!s) return;
    if (this.stringTarget === "key") {
      this.keyChars.push(s);
    } else {
      try {
        this.events.onStringDelta?.(this.currentKey, s);
      } catch (e) {
        this.reportSinkError(e);
      }
    }
  }

  private resetStringDecodeState(): void {
    this.stringEscape = false;
    this.collectingUnicode = false;
    this.unicodeHexBuf = "";
    this.highSurrogate = null;
  }

  // ---------- utilities ----------

  private skipWhitespace(): void {
    while (this.pos < this.buf.length && isWhitespace(this.buf[this.pos])) {
      this.pos++;
    }
  }

  private fail(message: string): void {
    if (this.state === "error") return;
    this.state = "error";
    this.errorMsg = message;
    try {
      this.events.onError?.(new Error(message));
    } catch {
      // ignore handler errors when reporting an error
    }
  }

  private reportSinkError(err: unknown): void {
    const wrapped = err instanceof Error ? err : new Error(String(err));
    try {
      this.events.onError?.(wrapped);
    } catch {
      // ignore
    }
  }
}
