import type { WorkflowManager } from "../../workflow";

interface ChildToolOptions {
  maxRetries?: number;
  onStatus?: (statusText: string) => void;
}

/**
 * Share provider quota/circuit accounting with the parent without re-entering
 * its tool request queue. The parent `task` call occupies that queue until the
 * child returns; queueing child-local reads behind it would deadlock when
 * `maxConcurrent` is one.
 */
export function createChildWorkflowManagerView(
  parent: WorkflowManager,
): WorkflowManager {
  const view = {
    async executeTool<R>(
      _toolName: string,
      _params: Record<string, unknown>,
      execute: () => Promise<R>,
      options: ChildToolOptions = {},
    ): Promise<R> {
      const maxRetries = Math.max(0, Math.floor(options.maxRetries ?? 0));
      let lastError: unknown;
      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          options.onStatus?.(
            attempt === 0
              ? "Running in child context"
              : `Retrying child read (${attempt}/${maxRetries})`,
          );
          return await execute();
        } catch (error) {
          lastError = error;
        }
      }
      throw lastError;
    },
    acquireRateLimitToken: parent.acquireRateLimitToken.bind(parent),
    acquireTokenBudget: parent.acquireTokenBudget.bind(parent),
    observeProviderTokenQuota: parent.observeProviderTokenQuota.bind(parent),
    reportRecoverableHttpError: parent.reportRecoverableHttpError.bind(parent),
    reportSuccess: parent.reportSuccess.bind(parent),
    updateRateLimitConfig() {},
    dispose() {},
  };
  return view as unknown as WorkflowManager;
}
