/**
 * VFS-first content staging for Office write tools.
 *
 * Large document content (long HTML/text blocks, tables, email bodies) is
 * error-prone to pass inline as a tool-call argument: it inflates the request,
 * can be truncated mid-stream by `max_completion_tokens`, and forces the model
 * to regenerate the whole payload on any retry. Instead the model can stage the
 * content in the VFS once (via `write_file` / `append_file` / `edit_file`, or a
 * `bash`/`js` redirection) and then point the Office tool at that path. This
 * mirrors the Excel `csv-to-sheet` bridge and keeps insertions/edits reliable.
 *
 * Tools accept BOTH an inline value and a `*FromFile` VFS path; the file path
 * wins when both are present.
 */

import { fileExists, readFile } from "../vfs";
import { findInternalContentPlaceholder } from "./file-content-guard";

export interface ResolvedStagedContent {
  ok: true;
  content: string;
  /** Absolute VFS path the content was read from, or `null` when inline. */
  sourcePath: string | null;
}

export interface StagedContentError {
  ok: false;
  error: string;
}

function toAbsoluteUploadsPath(path: string): string {
  const trimmed = path.trim();
  return trimmed.startsWith("/") ? trimmed : `/home/user/uploads/${trimmed}`;
}

/**
 * Resolve text content for an Office write tool from either an inline string or
 * a VFS file staged earlier. When `fromFile` is provided it takes precedence
 * and is validated: the file must exist, be non-empty, and not contain an
 * internal history placeholder (which would mean the real bytes were never
 * persisted). Returns a discriminated result so callers can surface a precise
 * `toolError` without throwing.
 */
export async function resolveStagedTextContent(params: {
  content?: string;
  fromFile?: string;
  /** Field name shown in error hints, e.g. "content" / "replaceText". */
  inlineFieldName?: string;
  /** Field name shown in error hints, e.g. "contentFromFile". */
  fileFieldName?: string;
}): Promise<ResolvedStagedContent | StagedContentError> {
  const inlineName = params.inlineFieldName ?? "content";
  const fileName = params.fileFieldName ?? "contentFromFile";
  const fromFile = params.fromFile?.trim();

  if (fromFile) {
    const fullPath = toAbsoluteUploadsPath(fromFile);
    if (!(await fileExists(fullPath))) {
      return {
        ok: false,
        error: `${fileName} not found in the virtual filesystem: ${fullPath}. Stage it first with write_file (or bash/js redirection), then retry.`,
      };
    }
    let text: string;
    try {
      text = await readFile(fullPath);
    } catch (err) {
      return {
        ok: false,
        error: `Failed to read ${fileName} ${fullPath}: ${
          err instanceof Error ? err.message : String(err)
        }`,
      };
    }
    const placeholder = findInternalContentPlaceholder(text);
    if (placeholder) {
      return {
        ok: false,
        error: `${fileName} ${fullPath} contains an internal placeholder ("${placeholder}"), not real content. Re-generate the file with write_file before inserting.`,
      };
    }
    if (text.trim().length === 0) {
      return {
        ok: false,
        error: `${fileName} ${fullPath} is empty. Write the content to it first.`,
      };
    }
    return { ok: true, content: text, sourcePath: fullPath };
  }

  if (typeof params.content === "string" && params.content.length > 0) {
    return { ok: true, content: params.content, sourcePath: null };
  }

  return {
    ok: false,
    error: `Provide either '${inlineName}' (inline) or '${fileName}' (a VFS path staged with write_file).`,
  };
}
