export type ThinkingLevel = "none" | "low" | "medium" | "high";
export type AzureApiMode = "chat-completions" | "responses";

export type ProviderType = "azure" | "my-ai";

export interface ProviderConfig {
  provider: ProviderType;
  apiKey: string;
  /** Model identifier (optional for Azure, used for capabilities) */
  model?: string;
  useProxy: boolean;
  proxyUrl: string;
  thinking: ThinkingLevel;
  followMode: boolean;
  /** Azure OpenAI endpoint URL (e.g., https://myresource.openai.azure.com/) */
  azureEndpoint: string;
  /** Azure OpenAI deployment name */
  azureDeploymentName: string;
  /** Azure OpenAI operation to use for this deployment */
  azureApiMode: AzureApiMode;
  /** Use Entra ID (interactive browser auth) instead of API key */
  useEntraId: boolean;
  /** Microsoft Entra application (client) ID for interactive browser auth */
  azureClientId: string;
  /**
   * Microsoft Entra tenant ID for interactive browser auth. Accepts a tenant
   * GUID or one of `common` / `organizations` / `consumers`. Defaults to
   * `common` when left blank.
   */
  azureTenantId: string;
  /** Azure cloud used for Entra authority and Azure OpenAI token audience. */
  azureEntraCloud: AzureEntraCloud;
  /** Entra authority host supplied by the operator for restricted clouds. */
  azureEntraAuthorityHost: string;
  /** Azure OpenAI token scope supplied by the operator for restricted clouds. */
  azureEntraTokenScope: string;
  /** Azure Document Intelligence endpoint URL (e.g., https://myresource.cognitiveservices.azure.com/) */
  documentIntelligenceEndpoint: string;
  /** Azure Document Intelligence API key */
  documentIntelligenceKey: string;
  /** OpenAI base URL - defaults to https://api.openai.com/v1 */
  openaiBaseUrl: string;
  /** My AI base URL (e.g., http://10.23.32.44:1234/v1) */
  myAiBaseUrl: string;
}

