/**
 * Deploy-time Settings defaults sourced from `runtime-config.json`
 * (`providerDefaults`). These seed the Settings tab and can auto-configure the
 * agent when they include working auth, so users don't have to retype shared
 * deployment details. Saved user config always overrides these.
 */
export function getRuntimeProviderDefaults(): Partial<ProviderConfig> {
  return { ...getRuntimeConfigSync().providerDefaults };
}

export function constrainProviderConfigToAzureEnvironment(
  config: ProviderConfig,
  environment: AzureEnvironment = getRuntimeConfigSync().azureEnvironment,
): ProviderConfig {
  const azureEntraCloud = constrainAzureEntraCloud(
    config.azureEntraCloud,
    environment,
  );
  return {
    ...config,
    azureEntraCloud,
    azureEntraAuthorityHost:
      azureEntraCloud === "usnat" ? config.azureEntraAuthorityHost : "",
    azureEntraTokenScope:
      azureEntraCloud === "usnat" ? config.azureEntraTokenScope : "",
  };
}

export function loadSavedConfig(): ProviderConfig | null {
  const runtimeConfig = getRuntimeConfigSync();
  const runtimeDefaults = { ...runtimeConfig.providerDefaults };

  let saved: Partial<ProviderConfig> | null = null;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) saved = JSON.parse(raw) as Partial<ProviderConfig>;
  } catch {
    saved = null;
  }

  // Nothing persisted and no deploy-time defaults: treat as unconfigured so
  // the UI keeps prompting for setup (preserves the historical null contract).
  if (!saved && Object.keys(runtimeDefaults).length === 0) {
    return null;
  }

  // Saved values remain sticky unless they violate the deployment's network
  // boundary, which takes precedence over browser-local configuration.
  return constrainProviderConfigToAzureEnvironment(
    {
      ...BASE_PROVIDER_CONFIG,
      ...runtimeDefaults,
      ...(saved ?? {}),
    },
    runtimeConfig.azureEnvironment,
  );
}

export function saveConfig(config: ProviderConfig): ProviderConfig {
  const constrainedConfig = constrainProviderConfigToAzureEnvironment(config);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(constrainedConfig));
  return constrainedConfig;
}

/** Azure OpenAI-specific model configuration */
export interface AzureModelConfig {
  /** Maximum context window for model */
  contextWindow: number;
  /** Maximum tokens to generate */
  maxTokens: number;
}

export function getDefaultAzureModelConfig(): AzureModelConfig {
  return {
    contextWindow: 128000,
    maxTokens: 32000,
  };
}
