/**
 * Planner module (PR-6 step 6.2).
 *
 * Thin wrapper around `provider.runStructured?` for the planner phases:
 *
 *   - {@link submitPlan}      — phase 1 (PLAN)
 *   - {@link submitQcReport}  — phase 3 (QUALITY CHECK)
 *
 * Both helpers return a non-throwing fallback outcome when:
 *   - The provider does not implement `runStructured` (no escape hatch).
 *   - The structured call throws (transport, abort, etc.).
 *   - The returned payload fails schema validation.
 *
 * The orchestrator treats any non-`ok` outcome as a signal to fall back
 * to the prose-driven planner prompt (`buildPlannerExecutionPrompt`).
 * This keeps providers without structured-output support working
 * unchanged while letting providers that do support it skip the prose
 * phases entirely.
 *
 * Per blueprint §3 the planner module owns plan submission + step
 * iteration, but PR-6 ships only the submission half — step iteration is
 * still managed by the existing tool-execution loop in `agent.ts`.
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §3 / §7
 *   - docs/agent-refactor-implementation-plan.md §6.2
 */

import { trackEvent } from "../../telemetry";
import { nudgeCeiling } from "../loop/nudges";
import type {
  JSONSchema,
  LLMProvider,
  LLMTurnRequest,
} from "../providers/provider";
import type { AgentMessage, UserMessage } from "../types";
import {
  type PlannerValidationResult,
  SUBMIT_PLAN_TOOL_NAME,
  SUBMIT_QC_REPORT_TOOL_NAME,
  type SubmitPlan,
  SubmitPlanSchema,
  type SubmitQcReport,
  SubmitQcReportSchema,
  validateSubmitPlan,
  validateSubmitQcReport,
} from "./plan-schema";

export interface PlannerSubmissionContext {
  provider: LLMProvider;
  /** Already-budgeted message list (orchestrator owns budget policy). */
  request: LLMTurnRequest;
  /** Run id used for telemetry correlation. */
  runId?: string;
}

/**
 * Outcome of a planner-phase structured submission. The orchestrator
 * keys off `kind` to decide whether to continue with the structured
 * artifact or fall back to the prose phase.
 */
export type PlannerSubmissionOutcome<T> =
  | { kind: "ok"; value: T }
  | { kind: "unsupported" }
  | { kind: "validation_failed"; errors: string[] }
  | { kind: "error"; error: unknown };

async function submitStructured<T>(
  ctx: PlannerSubmissionContext,
  schema: JSONSchema,
  validate: (candidate: unknown) => PlannerValidationResult<T>,
  toolName: string,
): Promise<PlannerSubmissionOutcome<T>> {
  if (typeof ctx.provider.runStructured !== "function") {
    trackEvent("planner.structured_unsupported", {
      providerId: ctx.provider.id,
      toolName,
      ...(ctx.runId ? { runId: ctx.runId } : {}),
    });
    return { kind: "unsupported" };
  }

  try {
    const candidate = await ctx.provider.runStructured<unknown>(
      ctx.request,
      schema,
      { toolName },
    );
    const result = validate(candidate);
    if (!result.ok) {
      // Narrow explicitly: with `strict: false` in tsconfig, TS does not
      // always narrow discriminated unions through the `!result.ok`
      // guard, so destructure off the failure-branch shape.
      const { errors } = result as { ok: false; errors: string[] };
      trackEvent("planner.structured_validation_failed", {
        providerId: ctx.provider.id,
        toolName,
        errorCount: String(errors.length),
        ...(ctx.runId ? { runId: ctx.runId } : {}),
      });
      return { kind: "validation_failed", errors };
    }
    trackEvent("planner.structured_submission_succeeded", {
      providerId: ctx.provider.id,
      toolName,
      ...(ctx.runId ? { runId: ctx.runId } : {}),
    });
    return { kind: "ok", value: result.value };
  } catch (error) {
    if (ctx.request.abortSignal.aborted) {
      // Abort is an orchestrator-level concern; surface it without
      // wrapping so the caller can re-classify.
      return { kind: "error", error };
    }
    trackEvent("planner.structured_submission_failed", {
      providerId: ctx.provider.id,
      toolName,
      ...(ctx.runId ? { runId: ctx.runId } : {}),
    });
    return { kind: "error", error };
  }
}

/**
 * Phase 1 — PLAN. Asks the provider for a structured execution plan
 * matching {@link SubmitPlanSchema}.
 */
export function submitPlan(
  ctx: PlannerSubmissionContext,
): Promise<PlannerSubmissionOutcome<SubmitPlan>> {
  return submitStructured<SubmitPlan>(
    ctx,
    SubmitPlanSchema as unknown as JSONSchema,
    validateSubmitPlan,
    SUBMIT_PLAN_TOOL_NAME,
  );
}

/**
 * Phase 3 — QUALITY CHECK. Asks the provider for a structured QC report
 * matching {@link SubmitQcReportSchema}.
 */
export function submitQcReport(
  ctx: PlannerSubmissionContext,
): Promise<PlannerSubmissionOutcome<SubmitQcReport>> {
  return submitStructured<SubmitQcReport>(
    ctx,
    SubmitQcReportSchema as unknown as JSONSchema,
    validateSubmitQcReport,
    SUBMIT_QC_REPORT_TOOL_NAME,
  );
}

// ============ retry-with-feedback (PR-6 §9.1) ============

/**
 * Maximum number of structured-submission attempts before falling back
 * to the prose-driven planner prompt.
 *
 * Per blueprint §9.1: "Validation failure triggers a
 * `nudge_and_retry('plan_schema_invalid')` (≤2x); subsequent failure
 * aborts the planner phase and falls back to non-planner execution."
 *
 * The orchestrator runs `submitPlan` opportunistically before the first
 * loop iteration, so the retry mechanism lives entirely inside this
 * helper rather than going through the FSM nudge path. The nudge ceiling
 * is consulted as the canonical source of `≤2x`.
 */
export const PLAN_SCHEMA_INVALID_MAX_ATTEMPTS = nudgeCeiling(
  "plan_schema_invalid",
);

function buildRetryFeedbackMessage(
  toolName: string,
  errors: readonly string[],
): UserMessage {
  const formatted = errors.map((err) => `- ${err}`).join("\n");
  return {
    role: "user",
    timestamp: Date.now(),
    content: `Your previous \`${toolName}\` submission failed schema validation:\n${formatted}\n\nPlease re-submit using the documented schema with all required fields and correct types.`,
  };
}

/**
 * Outcome of a retry-with-feedback submission. Adds an `attempts` field
 * for telemetry / test assertions and a typed `kind: "fallback"` for
 * exhausted retries (so callers can distinguish "tried and gave up"
 * from "validation_failed once and gave up").
 */
export type PlannerRetryOutcome<T> =
  | { kind: "ok"; value: T; attempts: number }
  | { kind: "unsupported"; attempts: 0 }
  | {
      kind: "fallback";
      attempts: number;
      lastErrors: string[];
      reason: "validation_failed" | "error";
    }
  | { kind: "aborted"; error: unknown };

async function submitWithRetry<T>(
  ctx: PlannerSubmissionContext,
  submit: (
    ctx: PlannerSubmissionContext,
  ) => Promise<PlannerSubmissionOutcome<T>>,
  toolName: string,
  maxAttempts: number,
): Promise<PlannerRetryOutcome<T>> {
  const attemptLimit = Math.max(1, Math.floor(maxAttempts));

  // Mutable message list that grows with retry feedback.
  const messages: AgentMessage[] = [...ctx.request.messages];
  let lastErrors: string[] = [];
  let lastReason: "validation_failed" | "error" = "validation_failed";
  let attemptsRun = 0;

  for (let attempt = 1; attempt <= attemptLimit; attempt += 1) {
    if (ctx.request.abortSignal.aborted) {
      return {
        kind: "aborted",
        error: new Error("planner submission aborted"),
      };
    }

    attemptsRun = attempt;
    const attemptCtx: PlannerSubmissionContext = {
      ...ctx,
      request: { ...ctx.request, messages: [...messages] },
    };
    const outcome = await submit(attemptCtx);

    if (outcome.kind === "ok") {
      if (attempt > 1) {
        trackEvent("planner.structured_retry_succeeded", {
          providerId: ctx.provider.id,
          toolName,
          attempts: String(attempt),
          ...(ctx.runId ? { runId: ctx.runId } : {}),
        });
      }
      return { kind: "ok", value: outcome.value, attempts: attempt };
    }

    if (outcome.kind === "unsupported") {
      // Provider lost runStructured between attempts (defensive).
      return { kind: "unsupported", attempts: 0 };
    }

    if (outcome.kind === "validation_failed") {
      lastErrors = outcome.errors;
      lastReason = "validation_failed";
      if (attempt < attemptLimit) {
        trackEvent("planner.structured_retry_attempt", {
          providerId: ctx.provider.id,
          toolName,
          attempt: String(attempt),
          maxAttempts: String(attemptLimit),
          errorCount: String(outcome.errors.length),
          ...(ctx.runId ? { runId: ctx.runId } : {}),
        });
        messages.push(buildRetryFeedbackMessage(toolName, outcome.errors));
        continue;
      }
      // Exhausted: fall through to fallback.
      break;
    }

    // outcome.kind === "error"
    lastErrors = [String((outcome as { error: unknown }).error ?? "error")];
    lastReason = "error";
    if (ctx.request.abortSignal.aborted) {
      return { kind: "aborted", error: (outcome as { error: unknown }).error };
    }
    // Errors are not retried (transport / provider failures should
    // surface to the orchestrator immediately so the prose path runs).
    break;
  }

  trackEvent("planner.structured_fallback_to_prose", {
    providerId: ctx.provider.id,
    toolName,
    attempts: String(attemptsRun),
    reason: lastReason,
    ...(ctx.runId ? { runId: ctx.runId } : {}),
  });

  return {
    kind: "fallback",
    attempts: attemptsRun,
    lastErrors,
    reason: lastReason,
  };
}

/**
 * `submitPlan` with structured-validation retry per blueprint §9.1.
 *
 * Calls the provider up to {@link PLAN_SCHEMA_INVALID_MAX_ATTEMPTS}
 * times. On `validation_failed`, the validator errors are appended to
 * the next attempt's message list as a synthetic user-message
 * (`Your previous \`submit_plan\` submission failed schema validation:
 * ...`) so the model can self-correct. On `error` (transport / provider
 * failure) the helper does NOT retry — those surface immediately so the
 * orchestrator can fall back to prose without burning attempts.
 */
export function submitPlanWithRetry(
  ctx: PlannerSubmissionContext,
  options?: { maxAttempts?: number },
): Promise<PlannerRetryOutcome<SubmitPlan>> {
  const maxAttempts = options?.maxAttempts ?? PLAN_SCHEMA_INVALID_MAX_ATTEMPTS;
  return submitWithRetry<SubmitPlan>(
    ctx,
    submitPlan,
    SUBMIT_PLAN_TOOL_NAME,
    maxAttempts,
  );
}

/**
 * `submitQcReport` with structured-validation retry per blueprint §9.1.
 * Mirrors {@link submitPlanWithRetry} for the QC phase.
 */
export function submitQcReportWithRetry(
  ctx: PlannerSubmissionContext,
  options?: { maxAttempts?: number },
): Promise<PlannerRetryOutcome<SubmitQcReport>> {
  const maxAttempts = options?.maxAttempts ?? PLAN_SCHEMA_INVALID_MAX_ATTEMPTS;
  return submitWithRetry<SubmitQcReport>(
    ctx,
    submitQcReport,
    SUBMIT_QC_REPORT_TOOL_NAME,
    maxAttempts,
  );
}

/**
 * Convert a validated {@link SubmitPlan} into the prose checklist the
 * existing executor loop expects to see in the system/user prompt.
 *
 * This is the bridge from the structured surface (PR-6 §6.1 / §6.2) to
 * the legacy `buildPlannerExecutionPrompt` consumers (§6.3). Once every
 * provider implements `runStructured`, the prose phases can be deleted
 * entirely and this helper becomes the single source of phase content.
 */
export function formatPlanAsChecklist(plan: SubmitPlan): string {
  const lines: string[] = [];
  lines.push(`Objective: ${plan.objective}`);
  if (plan.assumptions && plan.assumptions.length > 0) {
    lines.push("Assumptions:");
    for (const a of plan.assumptions) {
      lines.push(`- ${a}`);
    }
  }
  lines.push("Plan:");
  for (let i = 0; i < plan.steps.length; i += 1) {
    const step = plan.steps[i];
    const tools =
      step.tools && step.tools.length > 0
        ? ` (tools: ${step.tools.join(", ")})`
        : "";
    lines.push(`${i + 1}. ${step.title}${tools}`);
    if (step.detail) {
      lines.push(`   ${step.detail}`);
    }
  }
  if (plan.risks && plan.risks.length > 0) {
    lines.push("Known risks:");
    for (const r of plan.risks) {
      lines.push(`- ${r}`);
    }
  }
  return lines.join("\n");
}
