/* global Office */

export interface OutlookRecipient {
  name: string;
  email: string;
}

export interface OutlookMailboxMetadata {
  success: boolean;
  hasItem: boolean;
  mode?: "read" | "compose";
  itemType?: "message" | "appointment";
  subject?: string;
  from?: OutlookRecipient | null;
  to?: OutlookRecipient[];
  cc?: OutlookRecipient[];
  attachmentCount?: number;
  attachmentNames?: string[];
  bodyPreview?: string;
  received?: string;
}

const BODY_PREVIEW_MAX = 800;
const MAX_RECIPIENTS = 20;
const MAX_ATTACHMENT_NAMES = 20;

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

function parseRecipients(
  recipients: Office.EmailAddressDetails[] | undefined,
): OutlookRecipient[] {
  if (!recipients) return [];
  return recipients.slice(0, MAX_RECIPIENTS).map((r) => ({
    name: r.displayName,
    email: r.emailAddress,
  }));
}

function getAsyncValue<T>(
  run: (callback: (result: Office.AsyncResult<T>) => void) => void,
): Promise<T | undefined> {
  return new Promise((resolve) => {
    try {
      run((result) => {
        resolve(
          result.status === Office.AsyncResultStatus.Succeeded
            ? result.value
            : undefined,
        );
      });
    } catch {
      resolve(undefined);
    }
  });
}

export async function getMailboxMetadata(): Promise<OutlookMailboxMetadata> {
  const item = Office.context?.mailbox?.item;
  if (!item) {
    return { success: true, hasItem: false };
  }

  const itemType =
    item.itemType === Office.MailboxEnums.ItemType.Message
      ? "message"
      : "appointment";

  const isReadMode =
    "displayReplyForm" in item &&
    typeof (item as Office.MessageRead).displayReplyForm === "function";

  const bodyText = await getAsyncValue<string>((cb) =>
    item.body.getAsync(Office.CoercionType.Text, cb),
  );
  const bodyPreview = truncate((bodyText ?? "").trim(), BODY_PREVIEW_MAX);

  if (isReadMode) {
    const msg = item as Office.MessageRead;
    const attachments = Array.isArray(msg.attachments) ? msg.attachments : [];
    return {
      success: true,
      hasItem: true,
      mode: "read",
      itemType,
      subject: msg.subject ?? "",
      from: msg.from
        ? { name: msg.from.displayName, email: msg.from.emailAddress }
        : null,
      to: parseRecipients(Array.isArray(msg.to) ? msg.to : undefined),
      cc: parseRecipients(Array.isArray(msg.cc) ? msg.cc : undefined),
      attachmentCount: attachments.length,
      attachmentNames: attachments
        .slice(0, MAX_ATTACHMENT_NAMES)
        .map((a) => a.name),
      bodyPreview,
      received: msg.dateTimeCreated
        ? new Date(msg.dateTimeCreated).toISOString()
        : undefined,
    };
  }

  const msg = item as Office.MessageCompose;
  const [subject, to, cc] = await Promise.all([
    msg.subject
      ? getAsyncValue<string>((cb) => msg.subject.getAsync(cb))
      : Promise.resolve(undefined),
    msg.to
      ? getAsyncValue<Office.EmailAddressDetails[]>((cb) => msg.to.getAsync(cb))
      : Promise.resolve(undefined),
    msg.cc
      ? getAsyncValue<Office.EmailAddressDetails[]>((cb) => msg.cc.getAsync(cb))
      : Promise.resolve(undefined),
  ]);

  return {
    success: true,
    hasItem: true,
    mode: "compose",
    itemType,
    subject: subject ?? "",
    from: null,
    to: parseRecipients(to),
    cc: parseRecipients(cc),
    bodyPreview,
  };
}
