/**
 * `StreamingToolController` — Phase C.
 *
 * Per-run owner of {@link WriteFileStreamingSession} instances and the
 * bridge between {@link DecoderStreamingHooks} (provider-facing) and
 * the session lifecycle (VFS-facing). One controller per agent run;
 * one {@link TurnRegistry} per LLM turn within that run.
 *
 * Flow per turn:
 *
 *   1. The Agent calls {@link StreamingToolController.beginTurn} to
 *      obtain a fresh {@link TurnRegistry}, then
 *      {@link StreamingToolController.hooksFor} to get the
 *      `DecoderStreamingHooks` instance to pass into the provider.
 *   2. As the decoder reads `tool_calls` deltas, it fires
 *      `onToolName` once a tool name is known, and `onArgumentsDelta`
 *      for each fragment of the JSON arguments.
 *   3. The controller maintains a per-`streamIndex` session for
 *      streamable tool names (currently `write_file`). Non-streamable
 *      tools are tracked just enough to detect D1 collisions; their
 *      arguments are not intercepted.
 *   4. After the stream completes, the decoder calls
 *      `finalize(...)` for each tool call. The controller commits the
 *      session's temp file, emits telemetry, and returns a
 *      {@link StreamedToolResult}; non-streamed tools return `null`.
 *   5. On unhandled exceptions in the decoder loop, the decoder calls
 *      `abort(reason)`, which aborts every still-open session and
 *      emits abort telemetry.
 *
 * D-decision invariants enforced here:
 *   - D1: two different tool names declared for the same
 *     `streamIndex` in a single turn → log
 *     `agent.write_file_stream_index_collision`, abort the
 *     in-progress session, drop the slot.
 *   - D9: telemetry events
 *     (`agent.write_file_streamed`,
 *     `agent.write_file_stream_failed`,
 *     `agent.write_file_stream_aborted`,
 *     `agent.write_file_stream_index_collision`,
 *     `agent.write_file_stream_commit_cleanup_failed`)
 *     are fired here with string-only property values.
 *   - D10: two sessions targeting the same path within one turn → the
 *     first wins; the second is marked failed with
 *     `STREAM_TARGET_CONFLICT` and its finalize returns a tool error.
 */

import { trackEvent } from "../../telemetry";
import type {
  DecoderStreamingHooks,
  StreamedToolResult,
  StreamingArgumentsDeltaCtx,
  StreamingFinalizeCtx,
  StreamingToolNameCtx,
} from "../providers/provider";
import { StreamingArgsExtractor } from "../providers/shared/streaming-json-args";
import type { StreamingWriteResult } from "./types";
import { WriteFileStreamingSession } from "./write-file-session";

/**
 * Tool names eligible for stream-to-VFS interception. Only `write_file`
 * is supported today; the set is the single source of truth for
 * `onToolName`'s session-creation decision.
 */
export const STREAMABLE_TOOL_NAMES: ReadonlySet<string> = new Set([
  "write_file",
]);

interface SessionState {
  session: WriteFileStreamingSession;
  extractor: StreamingArgsExtractor;
  name: string;
  toolCallId?: string;
  /**
   * True once the controller has registered this session's resolved
   * target path into `resolvedTargets` (or marked it as a conflict).
   * Prevents repeated conflict checks on every subsequent delta.
   */
  targetClaimed: boolean;
}

export interface StreamingToolControllerOptions {
  /** Override for testing. Defaults to `Date.now`. */
  nowMs?: () => number;
}

export class StreamingToolController {
  private readonly runId: string;
  private readonly turns = new Map<number, TurnRegistry>();
  private readonly nowMs: () => number;

  constructor(runId: string, opts: StreamingToolControllerOptions = {}) {
    this.runId = runId;
    this.nowMs = opts.nowMs ?? (() => Date.now());
  }

  beginTurn(turnIndex: number): TurnRegistry {
    const registry = new TurnRegistry(this.runId, turnIndex, this.nowMs);
    this.turns.set(turnIndex, registry);
    return registry;
  }

  endTurn(turnIndex: number): void {
    this.turns.delete(turnIndex);
  }

  hooksFor(registry: TurnRegistry): DecoderStreamingHooks {
    return registry.makeHooks();
  }

  /**
   * Abort every still-open session across every turn in this run.
   * Used by callers that need to tear the controller down (e.g.
   * unhandled error in the orchestrator). Idempotent.
   */
  async abortAll(reason: unknown): Promise<void> {
    for (const registry of this.turns.values()) {
      await registry.abortAll(reason);
    }
  }

  /**
   * Final cleanup at run-end: abort any sessions still open and
   * release per-turn registries. The session-level `safeCleanupTemp`
   * deletes individual temp files; this method intentionally does NOT
   * walk the temp directory itself because the VFS layer has no
   * directory-recursive delete primitive today.
   */
  async cleanup(): Promise<void> {
    await this.abortAll("run_ended");
    this.turns.clear();
  }
}

export class TurnRegistry {
  readonly runId: string;
  readonly turnIndex: number;
  private readonly nowMs: () => number;

  private readonly declaredNames = new Map<number, string>();
  private readonly declaredIds = new Map<number, string>();
  private readonly collisionAborted = new Set<number>();
  private readonly sessions = new Map<number, SessionState>();
  /** target path → first `streamIndex` to claim it (D10). */
  private readonly resolvedTargets = new Map<string, number>();
  private readonly startTimes = new Map<number, number>();

  constructor(runId: string, turnIndex: number, nowMs: () => number) {
    this.runId = runId;
    this.turnIndex = turnIndex;
    this.nowMs = nowMs;
  }

  makeHooks(): DecoderStreamingHooks {
    return {
      onToolName: (ctx) => this.handleToolName(ctx),
      onArgumentsDelta: (ctx) => this.handleArgumentsDelta(ctx),
      finalize: (ctx) => this.handleFinalize(ctx),
      abort: (reason) => this.abortAll(reason),
    };
  }

  /** Visible for tests. */
  hasSession(streamIndex: number): boolean {
    return this.sessions.has(streamIndex);
  }

  /** Visible for tests. */
  getDeclaredName(streamIndex: number): string | undefined {
    return this.declaredNames.get(streamIndex);
  }

  // ---------- hook handlers ----------

  private handleToolName(ctx: StreamingToolNameCtx): void {
    const { streamIndex, toolCallId, name } = ctx;
    const prev = this.declaredNames.get(streamIndex);
    if (prev && prev !== name) {
      // D1: stream-index collision. Two different tool names for the
      // same delta index in a single turn — the controller cannot
      // know which session the subsequent argument deltas belong to,
      // so the existing session is aborted and the slot is poisoned.
      // The decoder will still surface both tool calls (the second
      // gets parsed via the standard path because no session exists
      // for it after this point) so the agent loop can dispatch it.
      trackEvent("agent.write_file_stream_index_collision", {
        runId: this.runId,
        turnIndex: String(this.turnIndex),
        streamIndex: String(streamIndex),
        previousName: prev,
        newName: name,
      });
      this.collisionAborted.add(streamIndex);
      const existing = this.sessions.get(streamIndex);
      if (existing) {
        void existing.session.abort();
        this.sessions.delete(streamIndex);
      }
      return;
    }
    if (!prev) {
      this.declaredNames.set(streamIndex, name);
    }
    if (toolCallId) {
      const existingId = this.declaredIds.get(streamIndex);
      if (!existingId) this.declaredIds.set(streamIndex, toolCallId);
    }
    if (this.collisionAborted.has(streamIndex)) return;

    if (STREAMABLE_TOOL_NAMES.has(name) && !this.sessions.has(streamIndex)) {
      const session = new WriteFileStreamingSession({
        runId: this.runId,
        turnIndex: this.turnIndex,
        streamIndex,
        toolCallId: this.declaredIds.get(streamIndex) ?? toolCallId,
      });
      // The extractor's events fire synchronously from inside
      // `feed(...)`. The session enqueues flush work on its internal
      // queue and we drain that queue in `handleArgumentsDelta`
      // before returning to the decoder. This keeps argument-delta
      // backpressure correct without requiring async events.
      const extractor = new StreamingArgsExtractor({
        onValue: (k, v) => session.onValue(k, v),
        onStringStart: (k) => session.onStringStart(k),
        onStringDelta: (k, d) => {
          // Fire-and-forget: the session enqueues flush work
          // synchronously; the awaited `drainFlushes()` in
          // `handleArgumentsDelta` covers backpressure.
          void session.onStringDelta(k, d);
        },
        onStringEnd: (k) => session.onStringEnd(k),
        onError: (err) => {
          // Mark the session as failed; finalize will surface a
          // STREAM_INVALID_ARGS / STREAM_SINK_ERROR result. The
          // extractor swallows further input once it errors, so no
          // additional bytes will be written.
          session.markFailed(
            "STREAM_INVALID_ARGS",
            `extractor error: ${err.message}`,
          );
        },
      });
      this.sessions.set(streamIndex, {
        session,
        extractor,
        name,
        toolCallId: this.declaredIds.get(streamIndex) ?? toolCallId,
        targetClaimed: false,
      });
      this.startTimes.set(streamIndex, this.nowMs());
    }
  }

  private async handleArgumentsDelta(
    ctx: StreamingArgumentsDeltaCtx,
  ): Promise<void> {
    const { streamIndex, toolCallId, delta } = ctx;
    const state = this.sessions.get(streamIndex);
    if (!state) return;
    if (toolCallId && !state.toolCallId) state.toolCallId = toolCallId;

    state.extractor.feed(delta);
    await state.session.drainFlushes();

    if (!state.targetClaimed) {
      const target = state.session.getTargetPath();
      if (target !== undefined) {
        state.targetClaimed = true;
        const existing = this.resolvedTargets.get(target);
        if (existing !== undefined && existing !== streamIndex) {
          // D10 same-target conflict.
          state.session.markFailed(
            "STREAM_TARGET_CONFLICT",
            `another concurrent streamed write_file already targets ${target}`,
          );
          trackEvent("agent.write_file_stream_failed", {
            runId: this.runId,
            turnIndex: String(this.turnIndex),
            streamIndex: String(streamIndex),
            errorCode: "STREAM_TARGET_CONFLICT",
            basename: basename(target),
          });
        } else {
          this.resolvedTargets.set(target, streamIndex);
        }
      }
    }
  }

  private async handleFinalize(
    ctx: StreamingFinalizeCtx,
  ): Promise<StreamedToolResult | null> {
    const { streamIndex, toolCallId, name } = ctx;
    const state = this.sessions.get(streamIndex);
    if (!state) return null;

    // Let the extractor settle any in-flight string for symmetry; for
    // a cleanly terminated stream this fires the trailing `onStringEnd`
    // event, and for a truncated stream it surfaces the open key on
    // the extractor's `finish()` result (which we don't currently
    // consume — the session's `truncated` flag is the source of truth).
    state.extractor.finish();

    const startMs = this.startTimes.get(streamIndex) ?? this.nowMs();
    const durationMs = this.nowMs() - startMs;

    let writeResult: StreamingWriteResult;
    try {
      writeResult = await state.session.finalize({
        truncated: ctx.truncated,
      });
    } catch (err) {
      // Defensive: session.finalize is documented not to throw, but a
      // bug in the VFS layer should not crash the decoder.
      this.sessions.delete(streamIndex);
      this.startTimes.delete(streamIndex);
      const message = err instanceof Error ? err.message : String(err);
      trackEvent("agent.write_file_stream_failed", {
        runId: this.runId,
        turnIndex: String(this.turnIndex),
        streamIndex: String(streamIndex),
        errorCode: "STREAM_SINK_ERROR",
        durationMs: String(durationMs),
      });
      return {
        toolCallId: toolCallId || state.toolCallId || "",
        streamIndex,
        name,
        arguments: makeUnexpectedErrorArgs(),
        resultText: `write_file streaming failed unexpectedly: ${message}`,
        isError: true,
        errorCode: "STREAM_SINK_ERROR",
        bytesWritten: 0,
        truncated: ctx.truncated,
      };
    }

    this.sessions.delete(streamIndex);
    this.startTimes.delete(streamIndex);

    const target = state.session.getTargetPath();
    const resolvedToolCallId =
      writeResult.toolCallId || toolCallId || state.toolCallId || "";
    const baseProps: Record<string, string> = {
      runId: this.runId,
      turnIndex: String(this.turnIndex),
      streamIndex: String(streamIndex),
      toolCallId: resolvedToolCallId,
      name,
      bytesWritten: String(writeResult.bytesWritten),
      truncated: String(writeResult.truncated),
      durationMs: String(durationMs),
      basename: target ? basename(target) : "",
    };
    if (writeResult.isError) {
      trackEvent("agent.write_file_stream_failed", {
        ...baseProps,
        errorCode: writeResult.errorCode ?? "STREAM_SINK_ERROR",
      });
    } else {
      trackEvent("agent.write_file_streamed", baseProps);
    }
    // D9 telemetry sub-event when commit succeeded but temp-file
    // cleanup failed. The success event above already fired; this
    // one carries the diagnostic so operators can find leaked
    // temps without scraping the success event.
    if (
      !writeResult.isError &&
      writeResult.resultText.includes("temp cleanup failed")
    ) {
      trackEvent("agent.write_file_stream_commit_cleanup_failed", {
        runId: this.runId,
        turnIndex: String(this.turnIndex),
        streamIndex: String(streamIndex),
        basename: target ? basename(target) : "",
      });
    }

    return {
      toolCallId: writeResult.toolCallId || toolCallId || "",
      streamIndex: writeResult.streamIndex,
      name: writeResult.name,
      arguments: writeResult.arguments,
      resultText: writeResult.resultText,
      isError: writeResult.isError,
      errorCode: writeResult.errorCode,
      bytesWritten: writeResult.bytesWritten,
      truncated: writeResult.truncated,
      tailAnchor: writeResult.tailAnchor,
    };
  }

  async abortAll(reason: unknown): Promise<void> {
    const _reason = reason; // surfaced via telemetry attribute below
    for (const [streamIndex, state] of this.sessions.entries()) {
      try {
        await state.session.abort();
      } catch {
        // ignore — abort is best-effort
      }
      const target = state.session.getTargetPath();
      trackEvent("agent.write_file_stream_aborted", {
        runId: this.runId,
        turnIndex: String(this.turnIndex),
        streamIndex: String(streamIndex),
        basename: target ? basename(target) : "",
        reason:
          typeof _reason === "string"
            ? _reason
            : _reason instanceof Error
              ? _reason.message
              : "unknown",
      });
    }
    this.sessions.clear();
    this.startTimes.clear();
  }
}

function basename(p: string): string {
  const i = p.lastIndexOf("/");
  return i >= 0 ? p.slice(i + 1) : p;
}

function makeUnexpectedErrorArgs(): Record<string, unknown> {
  return {
    path: "",
    content: "[streaming session crashed; no bytes written]",
  };
}
