import { Type } from "@sinclair/typebox";
import type { DirtyRange } from "../dirty-tracker";
import { replaceData } from "../excel/api";
import { defineTool, toolError, toolSuccess } from "./types";

export const replaceExcelContentTool = defineTool({
  name: "replace_content",
  category: "deliverable",
  parallelSafe: false,
  label: "Replace Content",
  description:
    "Find and replace literal content in Excel using native bulk replacement. " +
    "Searches all used worksheet ranges by default, or can target one worksheet and A1 range. " +
    "Supports case-sensitive and whole-cell matching. " +
    "Returns replacement counts for every searched scope.",
  parameters: Type.Object({
    searchText: Type.String({
      description: "The literal text to find",
      minLength: 1,
    }),
    replaceText: Type.String({
      description:
        "The replacement text; use an empty string to delete matches",
    }),
    sheetId: Type.Optional(
      Type.Number({ description: "Limit replacement to one worksheet ID" }),
    ),
    range: Type.Optional(
      Type.String({
        description:
          "Limit replacement to an A1 range, such as 'A1:Z100'. Applied to every searched worksheet.",
      }),
    ),
    matchCase: Type.Optional(
      Type.Boolean({
        description: "Match case exactly. Default: false",
        default: false,
      }),
    ),
    matchEntireCell: Type.Optional(
      Type.Boolean({
        description: "Match the entire cell content. Default: false",
        default: false,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're replacing (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  dirtyTracking: {
    getRanges: (_params, result) => getChangedRanges(result),
  },
  execute: async (_toolCallId, params, signal) => {
    try {
      const result = await replaceData(params.searchText, params.replaceText, {
        sheetId: params.sheetId,
        range: params.range,
        matchCase: params.matchCase,
        matchEntireCell: params.matchEntireCell,
        signal,
      });
      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error replacing content";
      return toolError(message);
    }
  },
});

function getChangedRanges(result: unknown): DirtyRange[] {
  if (!result || typeof result !== "object" || !("scopes" in result)) {
    return [];
  }

  const scopes = (result as { scopes?: unknown }).scopes;
  if (!Array.isArray(scopes)) return [];

  return scopes.flatMap((scope) => {
    if (
      !scope ||
      typeof scope !== "object" ||
      !("sheetId" in scope) ||
      !("range" in scope) ||
      !("replacements" in scope)
    ) {
      return [];
    }

    const { sheetId, range, replacements } = scope as {
      sheetId: unknown;
      range: unknown;
      replacements: unknown;
    };
    return typeof sheetId === "number" &&
      typeof range === "string" &&
      typeof replacements === "number" &&
      replacements > 0
      ? [{ sheetId, range }]
      : [];
  });
}
