import type {
  AgentMessage,
  AssistantMessage,
  ToolContent,
  ToolUiResourcePayload,
  UserMessage,
} from "./agent/types";

export type ToolCallStatus = "pending" | "running" | "complete" | "error";

/**
 * Renderer-side payload for an MCP App UI returned by a remote MCP
 * tool. The chat surface mounts a sandboxed iframe per part keyed by
 * `toolCallId` so re-renders of the parent message don't reset the
 * iframe's internal state. `resultText` is the text fallback the model
 * also receives, surfaced so the part can show a one-line summary
 * before the iframe boots. `content`, `structuredContent`, and
 * `meta` carry the MCP-shaped tool result through to the iframe so
 * apps that key off `structuredContent` (the common case) or read
 * `_meta` see the same data the model does.
 */
export interface McpUiAppPart {
  type: "mcpUiApp";
  toolCallId: string;
  toolName: string;
  ui: ToolUiResourcePayload;
  input: Record<string, unknown>;
  /** Plain-text fallback rendered above the iframe / when blocked. */
  resultText?: string;
  /** Full MCP-shaped content array forwarded to the iframe verbatim. */
  content?: ToolContent[];
  /** MCP `structuredContent` passthrough so UI apps can render typed data. */
  structuredContent?: unknown;
  /** Raw `_meta` from the originating `tools/call` result. */
  meta?: Record<string, unknown>;
}

export type TranscriptPart =
  | { type: "text"; text: string }
  | { type: "thinking"; thinking: string }
  | McpUiAppPart;

export type ToolCallPart = {
  type: "toolCall";
  id: string;
  name: string;
  args: Record<string, unknown>;
  status: ToolCallStatus;
  result?: string;
  statusText?: string;
};

export type MessagePart = TranscriptPart | ToolCallPart;

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  parts: TranscriptPart[];
  timestamp: number;
  transient?: boolean;
}

export type WarningLevel = "ok" | "warning" | "critical";

export interface SessionStats {
  inputTokens: number;
  outputTokens: number;
  cacheRead: number;
  cacheWrite: number;
  contextWindow: number;
  lastInputTokens: number;
  /** Estimated total tokens in context (including history, system prompt, tools) */
  estimatedTokens: number;
  /** Warning level based on context usage */
  warningLevel: WarningLevel;
}

const INTERNAL_ATTACHMENT_PREFIXES = ["wiki/", "working-set/"];
const INTERNAL_ATTACHMENT_NAMES = new Set([
  ".officeai-todos.json",
  ".officeai-workflow-progress.md",
]);
const LEGACY_LLM_WIKI_BLOCK_PATTERN = /^<llm_wiki>\n[\s\S]*?\n<\/llm_wiki>\n\n/;

function normalizeAttachmentName(name: string): string {
  return name.replace(/\\/g, "/").replace(/^\/+/, "").trim();
}

function isInternalAttachment(name: string): boolean {
  const normalized = normalizeAttachmentName(name).toLowerCase();
  if (!normalized) {
    return false;
  }

  if (INTERNAL_ATTACHMENT_NAMES.has(normalized)) {
    return true;
  }

  return INTERNAL_ATTACHMENT_PREFIXES.some((prefix) =>
    normalized.startsWith(prefix),
  );
}

export function resolveAttachmentNames(
  requestedAttachments?: string[],
  liveUploads?: string[],
): string[] | undefined {
  const merged = new Set<string>();

  for (const name of requestedAttachments ?? []) {
    const normalized = normalizeAttachmentName(name);
    if (normalized.length > 0 && !isInternalAttachment(normalized)) {
      merged.add(normalized);
    }
  }

  for (const name of liveUploads ?? []) {
    const normalized = normalizeAttachmentName(name);
    if (normalized.length > 0 && !isInternalAttachment(normalized)) {
      merged.add(normalized);
    }
  }

  return merged.size > 0 ? [...merged] : undefined;
}

export function buildAttachmentsEnrichment(attachments?: string[]): string {
  if (!attachments || attachments.length === 0) {
    return "";
  }

  const filteredAttachments = attachments
    .map((name) => normalizeAttachmentName(name))
    .filter((name) => name.length > 0 && !isInternalAttachment(name));

  if (filteredAttachments.length === 0) {
    return "";
  }

  const attachmentPaths = filteredAttachments
    .map((name) => `/home/user/uploads/${name}`)
    .join("\n");

  return `<attachments>\n${attachmentPaths}\n</attachments>\n\n`;
}

export function stripEnrichment(
  content: string | { type: string; text?: string }[],
): string {
  let text: string;
  if (typeof content === "string") {
    text = content;
  } else {
    text = content
      .filter((c) => c.type === "text")
      .map((c) => c.text ?? "")
      .join("\n");
  }
  text = text.replace(LEGACY_LLM_WIKI_BLOCK_PATTERN, "");
  text = text.replace(/^<attachments>\n[\s\S]*?\n<\/attachments>\n\n/, "");
  text = text.replace(/^<wb_context>\n[\s\S]*?\n<\/wb_context>\n\n/, "");
  return text;
}

export function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export function extractTranscriptPartsFromAssistantMessage(
  message: AgentMessage,
  existingParts: TranscriptPart[] = [],
): TranscriptPart[] {
  if (message.role !== "assistant") return existingParts;

  const assistantMsg = message as AssistantMessage;
  return assistantMsg.content.flatMap((block): TranscriptPart[] => {
    if (block.type === "text") {
      return [{ type: "text", text: block.text }];
    }
    if (block.type === "thinking") {
      return [{ type: "thinking", thinking: block.thinking }];
    }
    return [];
  });
}

export function agentMessagesToChatMessages(
  agentMessages: AgentMessage[],
): ChatMessage[] {
  const result: ChatMessage[] = [];
  for (const msg of agentMessages) {
    if (msg.role === "user") {
      const text = stripEnrichment((msg as UserMessage).content);
      // Skip known internal user-role messages carried in outbound history.
      // A literal user prompt that starts with `[SYSTEM:` should still render.
      if (isInternalSystemUserMessage(text)) {
        continue;
      }
      result.push({
        id: generateId(),
        role: "user",
        parts: [{ type: "text", text }],
        timestamp: msg.timestamp,
      });
    } else if (msg.role === "assistant") {
      const parts = extractTranscriptPartsFromAssistantMessage(msg);
      if (parts.length === 0) continue;
      result.push({
        id: generateId(),
        role: "assistant",
        parts,
        timestamp: msg.timestamp,
      });
    }
  }
  return result;
}

const INTERNAL_SYSTEM_USER_MESSAGE_PREFIXES = [
  "[SYSTEM: Conversation summary (older turns dropped for fresh context):",
  "[SYSTEM: Current TODO state (managed by you via update_todos).",
  "[SYSTEM: Previous conversation summary (",
] as const;

function isInternalSystemUserMessage(text: string): boolean {
  const trimmed = text.trimStart();
  return INTERNAL_SYSTEM_USER_MESSAGE_PREFIXES.some((prefix) =>
    trimmed.startsWith(prefix),
  );
}

export function dropTransientMessages(messages: ChatMessage[]): ChatMessage[] {
  if (!messages.some((message) => message.transient === true)) {
    return messages;
  }
  return messages.filter((message) => message.transient !== true);
}

export function deriveStats(
  agentMessages: AgentMessage[],
  estimatedTokens = 0,
): Omit<SessionStats, "contextWindow"> {
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheRead = 0;
  let cacheWrite = 0;
  let lastInputTokens = 0;
  for (const msg of agentMessages) {
    if (msg.role === "assistant") {
      const u = (msg as AssistantMessage).usage;
      if (u) {
        inputTokens += u.input;
        outputTokens += u.output;
        cacheRead += u.cacheRead ?? 0;
        cacheWrite += u.cacheWrite ?? 0;
        // Azure/OpenAI cached tokens are a subset of prompt/input tokens,
        // not additional context. Keep them as a separate efficiency metric.
        lastInputTokens = u.input;
      }
    }
  }

  // Determine warning level based on estimated tokens vs last input tokens
  let warningLevel: WarningLevel = "ok";
  if (estimatedTokens > 0) {
    const contextWindow =
      lastInputTokens > 0 ? lastInputTokens * 2 : estimatedTokens;
    const usageRatio = estimatedTokens / contextWindow;
    if (usageRatio > 0.9) warningLevel = "critical";
    else if (usageRatio > 0.75) warningLevel = "warning";
  } else if (lastInputTokens > 0) {
    // Fallback: estimate based on last input
    const estimatedTotal = inputTokens + outputTokens + lastInputTokens * 0.5;
    const usageRatio = estimatedTotal / (lastInputTokens * 1.5);
    if (usageRatio > 0.9) warningLevel = "critical";
    else if (usageRatio > 0.75) warningLevel = "warning";
  }

  return {
    inputTokens,
    outputTokens,
    cacheRead,
    cacheWrite,
    lastInputTokens,
    estimatedTokens,
    warningLevel,
  };
}
