export const QUICKJS_LOAD_ERROR = "QuickJSLoadError";
export const VFS_PRELOAD_ERROR = "VfsPreloadError";
export const VFS_NOT_PRELOADED_ERROR = "VfsNotPreloadedError";
export const JS_PROMISE_PENDING_ERROR = "JsPromisePendingError";

export type JsConsoleLevel = "log" | "info" | "warn" | "error";

export interface JsConsoleLine {
  level: JsConsoleLevel;
  text: string;
}

export interface JsRunError {
  name: string;
  message: string;
  stack?: string;
}

export interface JsRunOptions {
  code: string;
  module?: boolean;
  filename?: string;
  timeoutMs?: number;
  memoryLimitBytes?: number;
  maxStackSize?: number;
  preloadFiles?: string[];
  preloadCwd?: string;
  stdin?: string;
  signal?: AbortSignal;
  maxPreloadFileBytes?: number;
  maxPreloadTotalBytes?: number;
}

export interface JsRunResult {
  ok: boolean;
  value?: unknown;
  reported: boolean;
  error?: JsRunError;
  console: JsConsoleLine[];
  timedOut: boolean;
  aborted: boolean;
  memoryExceeded: boolean;
  elapsedMs: number;
}

export interface PreloadedTextFile {
  requestedPath: string;
  resolvedPath: string;
  text: string;
  bytes: number;
}
