/**
 * Pure helper for surfacing "the agent might be looping" warnings in
 * the chat UI.
 *
 * The detector keeps a bounded sliding window of recent tool-call
 * fingerprints (`name` + a short, deterministic argument digest) and
 * raises a warning when the same fingerprint appears strictly more than
 * {@link LoopDetectorOptions.threshold} times consecutively at the tail.
 *
 * Why "strictly more than": the agent often legitimately calls the same
 * tool twice in a row (e.g. read → read with different paths). The
 * threshold defaults to `3`, so a warning only fires once the same call
 * has repeated four times back-to-back — which is a strong signal of an
 * unproductive loop, not normal retry behavior.
 *
 * Dedup-suppressed dispatcher results are skipped entirely: those are
 * already a sign the orchestrator is doing its job, not the model
 * looping. See `ToolDispatcher` TOOL_DEDUP_SUPPRESSED.
 *
 * The detector is intentionally pure (no React, no state mutations) so
 * it can be unit tested and reset between runs without DOM cleanup.
 */

export interface LoopDetectorEntry {
  /** Tool name as reported by the dispatcher / tool_execution_start event. */
  name: string;
  /**
   * Stable, bounded fingerprint of the call arguments. Computed by
   * {@link fingerprintArgs} so the caller does not have to worry about
   * unstable key ordering or oversized payloads.
   */
  argsDigest: string;
  /** True iff the dispatcher reported TOOL_DEDUP_SUPPRESSED for this call. */
  dedupSuppressed?: boolean;
}

export interface LoopWarning {
  /** Repeating tool name. */
  toolName: string;
  /** Number of consecutive identical occurrences observed. */
  count: number;
  /** Last seen arguments fingerprint, included for the UI tooltip. */
  argsDigest: string;
  /** UI-friendly summary, e.g. `read_file ×4`. */
  summary: string;
}

export interface LoopDetectorOptions {
  /**
   * Maximum window size. Older entries beyond this are evicted from the
   * front. Defaults to 8 — enough to cover a multi-tool batch followed
   * by repeats without retaining unbounded history.
   */
  windowSize?: number;
  /**
   * Strict consecutive-repeat threshold. A warning fires when the same
   * fingerprint appears `threshold + 1` or more times in a row at the
   * tail of the window. Defaults to 3 (i.e. fires on the 4th repeat).
   */
  threshold?: number;
  /**
   * Maximum number of characters retained from the JSON-serialized
   * arguments when computing the fingerprint. Defaults to 200 — large
   * enough to distinguish typical arg sets, small enough to ignore
   * embedded huge content (e.g. a file body that legitimately changes
   * between calls but whose head is identical).
   */
  argsDigestMaxChars?: number;
  /**
   * Tool names whose calls are skipped by the detector entirely (no
   * window entry, no warning). Use this to exclude bookkeeping-category
   * tools whose repetition is expected and not a loop signal — e.g.
   * `update_todos` is called as live workflow status changes with the
   * full replacement list, so repeated submissions are normal.
   * Defaults to `["update_todos"]`.
   */
  ignoreToolNames?: readonly string[];
}

const DEFAULT_WINDOW_SIZE = 8;
const DEFAULT_THRESHOLD = 3;
const DEFAULT_ARGS_DIGEST_MAX_CHARS = 200;
const DEFAULT_IGNORE_TOOL_NAMES: readonly string[] = ["update_todos"];

/**
 * Produce a deterministic, bounded digest of tool call arguments.
 *
 * Object keys are sorted to avoid spurious mismatches from
 * implementation-defined ordering. The result is truncated to keep
 * memory + comparison work bounded; this is acceptable because the
 * detector only needs a *consistent* identifier for "same call args
 * roughly", not a cryptographic hash.
 *
 * Returns the literal string `"<unserializable>"` when `JSON.stringify`
 * throws (e.g. cyclic structures); two unserializable calls will
 * still match each other and contribute to the loop count, which is
 * the correct conservative behavior.
 */
export function fingerprintArgs(
  args: unknown,
  maxChars: number = DEFAULT_ARGS_DIGEST_MAX_CHARS,
): string {
  try {
    const json = JSON.stringify(args, sortedKeysReplacer);
    if (json === undefined) return "<undefined>";
    return json.length > maxChars ? json.slice(0, maxChars) : json;
  } catch {
    return "<unserializable>";
  }
}

function sortedKeysReplacer(_key: string, value: unknown): unknown {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const sorted: Record<string, unknown> = {};
    for (const k of Object.keys(value as Record<string, unknown>).sort()) {
      sorted[k] = (value as Record<string, unknown>)[k];
    }
    return sorted;
  }
  return value;
}

/**
 * Stateful loop detector. The class is intentionally tiny so callers
 * can create one per chat session and clear it via {@link reset}
 * whenever a new run starts.
 */
export class LoopDetector {
  private readonly windowSize: number;
  private readonly threshold: number;
  private readonly argsDigestMaxChars: number;
  private readonly ignoreToolNames: ReadonlySet<string>;
  private readonly window: LoopDetectorEntry[] = [];

  constructor(options: LoopDetectorOptions = {}) {
    this.windowSize = options.windowSize ?? DEFAULT_WINDOW_SIZE;
    this.threshold = options.threshold ?? DEFAULT_THRESHOLD;
    this.argsDigestMaxChars =
      options.argsDigestMaxChars ?? DEFAULT_ARGS_DIGEST_MAX_CHARS;
    this.ignoreToolNames = new Set(
      options.ignoreToolNames ?? DEFAULT_IGNORE_TOOL_NAMES,
    );
  }

  /**
   * Append a single tool execution to the sliding window and return a
   * {@link LoopWarning} if the tail now exceeds the threshold; returns
   * `null` otherwise. Dedup-suppressed entries are recorded but never
   * trigger a warning (they cannot be a productive-but-repeating call).
   * Calls whose `name` is in {@link LoopDetectorOptions.ignoreToolNames}
   * are skipped entirely — no window entry is created so they cannot
   * truncate an otherwise-valid run of identical real calls.
   */
  record(
    name: string,
    args: unknown,
    options?: { dedupSuppressed?: boolean },
  ): LoopWarning | null {
    if (this.ignoreToolNames.has(name)) return null;
    const entry: LoopDetectorEntry = {
      name,
      argsDigest: fingerprintArgs(args, this.argsDigestMaxChars),
      dedupSuppressed: options?.dedupSuppressed,
    };
    this.window.push(entry);
    if (this.window.length > this.windowSize) {
      this.window.splice(0, this.window.length - this.windowSize);
    }

    if (entry.dedupSuppressed) return null;

    let consecutive = 1;
    for (let i = this.window.length - 2; i >= 0; i--) {
      const prev = this.window[i];
      if (prev.dedupSuppressed) {
        // A dedup-suppressed call breaks the chain: it means the
        // dispatcher already short-circuited a would-be repeat. We
        // should not count that as a real loop signal.
        break;
      }
      if (prev.name === entry.name && prev.argsDigest === entry.argsDigest) {
        consecutive++;
      } else {
        break;
      }
    }

    if (consecutive > this.threshold) {
      return {
        toolName: name,
        count: consecutive,
        argsDigest: entry.argsDigest,
        summary: `${name} ×${consecutive}`,
      };
    }
    return null;
  }

  reset(): void {
    this.window.length = 0;
  }

  /** Test seam: shallow copy of the current window. */
  snapshot(): LoopDetectorEntry[] {
    return [...this.window];
  }
}
