/* global Word */

export function throwIfToolAborted(signal?: AbortSignal): void {
  if (signal?.aborted) {
    throw new Error("Tool execution cancelled");
  }
}

export async function syncWordContext(
  context: Word.RequestContext,
  signal?: AbortSignal,
): Promise<void> {
  throwIfToolAborted(signal);
  await context.sync();
  throwIfToolAborted(signal);
}
