const HISTORY_STRING_ARG_MAX_CHARS = 1200;
const HISTORY_STRING_ARG_PREVIEW_CHARS = 240;

const COMPACTABLE_STRING_ARGS: Readonly<Record<string, readonly string[]>> = {
  write_file: ["content"],
};

const COMPACTABLE_ARRAY_ARGS: Readonly<Record<string, readonly string[]>> = {
  update_todos: ["todos"],
};

/**
 * Internal sentinel keys produced by streaming pipelines (e.g. the
 * Phase C `StreamingToolController` adds `__streamed` to `write_file`
 * arguments). These keys MUST never leak into the outbound provider
 * payload (chat-completions `tool_calls[i].function.arguments` or
 * responses-API `function_call.arguments`) because:
 *   - The model never declared them, so seeing them back violates the
 *     wire contract and risks confusing the planner.
 *   - They expose implementation-internal metadata to the model.
 *   - They inflate replay fixtures and token budgets unnecessarily.
 *
 * Source of truth lives here so any future internal-only argument keys
 * are stripped centrally before history serialization.
 */
const INTERNAL_TOOL_ARGUMENT_KEYS: ReadonlySet<string> = new Set([
  "__streamed",
]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Strip {@link INTERNAL_TOOL_ARGUMENT_KEYS} from a tool-argument record
 * without mutating the input. Returns the original reference when no
 * keys needed removal (avoids unnecessary allocations on the hot path).
 */
export function stripInternalToolArgumentMetadata(
  args: Record<string, unknown>,
): Record<string, unknown> {
  if (!isRecord(args)) return args;
  let stripped: Record<string, unknown> | null = null;
  for (const key of Object.keys(args)) {
    if (INTERNAL_TOOL_ARGUMENT_KEYS.has(key)) {
      if (stripped === null) stripped = { ...args };
      delete stripped[key];
    }
  }
  return stripped ?? args;
}

function compactWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function compactLargeStringArg(
  toolName: string,
  argName: string,
  value: string,
  args: Record<string, unknown>,
): string {
  const path = typeof args.path === "string" ? args.path : undefined;
  const pathText = path ? ` for ${path}` : "";
  const preview = compactWhitespace(value).slice(
    0,
    HISTORY_STRING_ARG_PREVIEW_CHARS,
  );
  const previewText = preview
    ? ` Preview: ${preview}${value.length > preview.length ? " ..." : ""}`
    : "";
  return `[${argName} omitted from model history: ${value.length} characters were supplied to ${toolName}${pathText}. The tool already received the full value; use read_file on the path if the content is needed.${previewText}]`;
}

function compactLargeArrayArg(
  toolName: string,
  argName: string,
  value: unknown[],
  serialized: string,
): string {
  return `[${argName} omitted from model history: ${value.length} item(s) totaling ${serialized.length} characters were supplied to ${toolName}. The tool already received the full value; the latest state is re-injected each turn.]`;
}

export function compactToolArgumentsForHistory(
  toolName: string,
  args: Record<string, unknown>,
): Record<string, unknown> {
  if (!isRecord(args)) return args;

  // Phase E: drop internal-only sentinel keys (e.g. `__streamed`)
  // before any compaction so they never appear in the outbound
  // wire payload. `stripInternalToolArgumentMetadata` returns the
  // original reference when nothing was stripped, so the no-op case
  // remains allocation-free.
  const cleaned = stripInternalToolArgumentMetadata(args);

  const argNames = COMPACTABLE_STRING_ARGS[toolName];
  const arrayArgNames = COMPACTABLE_ARRAY_ARGS[toolName];
  if (!argNames && !arrayArgNames) return cleaned;

  let changed = false;
  const compacted: Record<string, unknown> = { ...cleaned };
  if (argNames) {
    for (const argName of argNames) {
      const value = compacted[argName];
      if (typeof value !== "string") continue;
      if (value.length <= HISTORY_STRING_ARG_MAX_CHARS) continue;
      compacted[argName] = compactLargeStringArg(
        toolName,
        argName,
        value,
        compacted,
      );
      changed = true;
    }
  }
  if (arrayArgNames) {
    for (const argName of arrayArgNames) {
      const value = compacted[argName];
      if (!Array.isArray(value)) continue;
      let serialized: string;
      try {
        serialized = JSON.stringify(value);
      } catch {
        continue;
      }
      if (serialized.length <= HISTORY_STRING_ARG_MAX_CHARS) continue;
      compacted[argName] = compactLargeArrayArg(
        toolName,
        argName,
        value,
        serialized,
      );
      changed = true;
    }
  }

  return changed ? compacted : cleaned;
}

export function stringifyToolArgumentsForHistory(
  toolName: string,
  args: Record<string, unknown>,
): string {
  try {
    return JSON.stringify(compactToolArgumentsForHistory(toolName, args) ?? {});
  } catch {
    return "{}";
  }
}

export function estimateToolArgumentsLengthForHistory(
  toolName: string,
  args: Record<string, unknown>,
): number {
  return stringifyToolArgumentsForHistory(toolName, args).length;
}
