import { getRuntimeConfigSync } from "./runtime-config";

/**
 * Air-Gapped Environment Configuration
 *
 * Optimized for:
 * - Offline/air-gapped deployments with older library versions
 * - Strict rate limiting (low RPM)
 * - Smaller context windows (<40k tokens)
 * - Unreliable/limited network connectivity
 */

export const AIRGAP_CONFIG = {
  // Token Management
  tokens: {
    maxContextTokens: 32000, // Conservative limit from 40k capacity
    maxInputTokens: 8000, // Max tokens for user input
    maxToolResultTokens: 2000, // Truncate tool results at this limit
    charsPerToken: 3.5, // Conservative estimate
  },

  // Rate Limiting
  rateLimit: {
    defaultDelayMs: 5000, // 5s between tool execution rounds
    maxRetries: 5, // Max retries for rate limited requests
    baseRetryDelayMs: 5000, // Base exponential backoff delay
    maxRetryDelayMs: 60000, // Cap retry delay at 60s
    jitterPercent: 0.2, // ±20% jitter on retry delays
  },

  // Circuit Breaker
  circuitBreaker: {
    enabled: true,
    failureThreshold: 5, // Open circuit after 5 failures
    cooldownMs: 60000, // 1 minute cooldown before retry
  },

  // Data Chunking
  chunking: {
    maxCellsPerRequest: 1000, // Max cells to read/write at once
    maxCsvSize: 50000, // Max CSV characters (50KB)
    batchSize: 100, // Batch size for large operations
  },

  // API Timeouts
  timeouts: {
    // Response-header ceiling for the provider fetch. Long reasoning +
    // large document generations were hitting
    // the old 2 min wall; raised to 5 min. Override per-endpoint via
    // runtime-config `agentTuning.{azure,openai}.requestTimeoutMs`.
    requestTimeoutMs: 300000, // 5 minute API timeout
    streamIdleTimeoutMs: 180000, // Allow long reasoning before the first SSE bytes
    meaningfulStreamTimeoutMs: 240000, // Bound keepalive-only / empty streams
    toolExecutionTimeoutMs: 180000, // 3 minute Office/VFS tool timeout
  },

  // Offline / Resilience
  offline: {
    enableRequestQueue: true, // Queue requests when offline
    maxQueueSize: 10, // Max queued requests
    healthCheckIntervalMs: 30000, // Check connectivity every 30s
  },

  // UI / UX
  ui: {
    showTokenWarnings: true, // Warn when approaching token limit
    tokenWarningThreshold: 0.8, // Warn at 80% capacity
    enableProgressIndicators: true, // Show progress for long operations
  },
} as const;

// Feature flags for gradual deployment
export const AIRGAP_FEATURES = {
  // Set to false to disable for initial testing
  enableTokenManager: true,
  enableCircuitBreaker: true,
  enableRateLimitJitter: true,
  enableOfflineQueue: false, // Enable after testing
  // Disable SES sandbox for compatibility with older polyfills (buffer@6, etc.)
  enableSESSandbox: false,
} as const;

// Export shorter, more concise tool descriptions for smaller context windows
export const CONCISE_TOOL_DESCRIPTIONS = {
  get_cell_ranges:
    "Reads cell values from specified worksheet ranges. Returns sparse object with A1 keys.",
  set_cell_range:
    "Writes cell values/formulas to a worksheet range. Use batch updates for many cells.",
  search_data:
    "Searches worksheets for matching text, returns ranges containing matches.",
  get_all_objects:
    "Lists all worksheets, tables, charts, named ranges in the workbook.",
  modify_sheet_structure: "Adds, deletes, or renames worksheets.",
  modify_workbook_structure: "Creates tables, charts, named ranges.",
  clear_cell_range:
    "Clears cell contents, formatting, or formulas from a range.",
  copy_to:
    "Copies values/formulas between worksheet ranges (same or different sheets)",
  modify_object: "Modifies charts, tables, or other workbook objects.",
  resize_range: "Expands or contracts a range to include adjacent data.",
  eval_officejs: "Executes raw Office.js script (use as last resort).",
  read_file:
    "Reads uploaded file content (PDFs, Word docs, etc) from virtual filesystem.",
  bash: "Executes bash command in sandboxed environment.",
} as const;

if (
  AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs >
    AIRGAP_CONFIG.timeouts.requestTimeoutMs ||
  AIRGAP_CONFIG.timeouts.meaningfulStreamTimeoutMs >
    AIRGAP_CONFIG.timeouts.requestTimeoutMs
) {
  throw new Error(
    "AIRGAP_CONFIG stream timeouts must not exceed requestTimeoutMs.",
  );
}

/**
 * Get description based on deployment mode
 */
export function getToolDescription(
  toolName: keyof typeof CONCISE_TOOL_DESCRIPTIONS,
  concise = true,
): string {
  if (!concise) {
    return ""; // Fall back to default descriptions
  }
  return CONCISE_TOOL_DESCRIPTIONS[toolName] ?? "";
}

/**
 * Check if running in air-gapped mode based on URL or config
 */
export function isAirGappedMode(): boolean {
  // Check URL query param
  if (typeof window !== "undefined") {
    const url = new URL(window.location.href);
    if (url.searchParams.get("airgap") === "true") {
      return true;
    }
  }

  // Check runtime-config.json (loaded at app startup)
  if (getRuntimeConfigSync().airGappedMode) {
    return true;
  }

  // Check environment (build-time)
  try {
    const env = (
      import.meta as unknown as Record<string, Record<string, string>>
    ).env;
    return env?.VITE_AIRGAP_MODE === "true";
  } catch {
    // ignore
  }
  return false;
}
