function StatsBar() {
  const { state } = useChat();
  const { sessionStats, providerConfig } = state;
  const styles = useStyles();

  if (!providerConfig) return null;

  const contextPct =
    sessionStats.contextWindow > 0 && sessionStats.lastInputTokens > 0
      ? (
          (sessionStats.lastInputTokens / sessionStats.contextWindow) *
          100
        ).toFixed(1)
      : "0";

  // Calculate estimated context usage if we have estimated tokens
  const estimatedContextPct =
    sessionStats.estimatedTokens > 0 && sessionStats.contextWindow > 0
      ? (
          (sessionStats.estimatedTokens / sessionStats.contextWindow) *
          100
        ).toFixed(1)
      : contextPct;

  // Determine colors based on warning level
  const getContextColor = (): string => {
    switch (sessionStats.warningLevel) {
      case "critical":
        return tokens.colorPaletteRedForeground1;
      case "warning":
        return tokens.colorPaletteYellowForeground1;
      default:
        return tokens.colorNeutralForeground2;
    }
  };

  const getContextTooltip = (): string => {
    if (sessionStats.warningLevel === "critical") {
      return `Context window nearly full! ${estimatedContextPct}% used (${formatTokens(sessionStats.estimatedTokens)} tokens). Clear the chat soon to reset context.`;
    }
    if (sessionStats.warningLevel === "warning") {
      return `Context window getting full: ${estimatedContextPct}% used (${formatTokens(sessionStats.estimatedTokens)} tokens)`;
    }
    return `Context usage: ${estimatedContextPct}%`;
  };

  const contextUsagePercent = Math.max(
    0,
    Math.min(100, Number.parseFloat(estimatedContextPct)),
  );
  const contextColor = getContextColor();
  const providerLabel =
    providerConfig.provider === "my-ai" ? "My AI" : "Azure OpenAI";
  const modelLabel = providerConfig.model || providerConfig.azureDeploymentName;

  return (
    <div className={styles.statsBar} aria-label="Chat usage">
      <div className={styles.statsLeft}>
        <Tooltip
          content="Input tokens sent in this chat"
          relationship="description"
        >
          <span className={styles.statChip}>
            <Caption2>Input {formatTokens(sessionStats.inputTokens)}</Caption2>
          </span>
        </Tooltip>
        <Tooltip
          content="Output tokens received in this chat"
          relationship="description"
        >
          <span className={styles.statChip}>
            <Caption2>
              Output {formatTokens(sessionStats.outputTokens)}
            </Caption2>
          </span>
        </Tooltip>
        {sessionStats.cacheRead > 0 && (
          <Tooltip content="Cache read tokens" relationship="description">
            <span className={styles.statChip}>
              <Caption2>
                Cache read {formatTokens(sessionStats.cacheRead)}
              </Caption2>
            </span>
          </Tooltip>
        )}
        {sessionStats.cacheWrite > 0 && (
          <Tooltip content="Cache write tokens" relationship="description">
            <span className={styles.statChip}>
              <Caption2>
                Cache write {formatTokens(sessionStats.cacheWrite)}
              </Caption2>
            </span>
          </Tooltip>
        )}
        {sessionStats.contextWindow > 0 && (
          <Tooltip content={getContextTooltip()} relationship="description">
            <span
              className={styles.contextChip}
              style={{ color: contextColor }}
            >
              <Caption2>Context {estimatedContextPct}%</Caption2>
              <span className={styles.contextMeter} aria-hidden="true">
                <span
                  className={styles.contextMeterFill}
                  style={{
                    width: `${contextUsagePercent}%`,
                    backgroundColor: contextColor,
                  }}
                />
              </span>
              <Caption2>{formatTokens(sessionStats.contextWindow)}</Caption2>
            </span>
          </Tooltip>
        )}
      </div>
      <div className={styles.statsRight}>
        <Caption2 className={styles.providerPill}>{providerLabel}</Caption2>
        <Caption2
          className={styles.providerPill}
          style={{ color: tokens.colorNeutralForeground2 }}
          title={modelLabel}
        >
          {modelLabel}
        </Caption2>
        {providerConfig.thinking !== "none" && (
          <Caption2 className={styles.thinkingBadge}>
            • {providerConfig.thinking}
          </Caption2>
        )}
      </div>
    </div>
  );
}

function ChatHeader({
  activeTab,
  onTabChange,
  theme,
  onThemeToggle,
}: {
  activeTab: ChatTab;
  onTabChange: (tab: ChatTab) => void;
  theme: "light" | "dark";
  onThemeToggle: () => void;
}) {
  const { clearMessages, state, toggleFollowMode } = useChat();
  const styles = useStyles();
  const followMode = state.providerConfig?.followMode ?? true;

  const handleTabSelect = (_: unknown, data: { value: string }) => {
    onTabChange(data.value as ChatTab);
  };

  return (
    <div className={styles.header}>
      <div className={styles.headerLeft}>
        <TabList
          selectedValue={activeTab}
          onTabSelect={handleTabSelect}
          size="small"
        >
          <Tab icon={<MailRegular />} value="chat">
            Chat
          </Tab>
          <Tab icon={<SettingsRegular />} value="settings">
            Settings
          </Tab>
        </TabList>
      </div>
      <div className={styles.headerRight}>
        <Tooltip content="Open IDE" relationship="label">
          <Button
            appearance="transparent"
            icon={<CodeRegular />}
            onClick={() => {
              window.location.hash = "#ide";
            }}
            size="small"
          />
        </Tooltip>
        {activeTab === "chat" && (
          <Tooltip
            content={
              followMode
                ? "Follow mode: ON - Click to disable"
                : "Follow mode: OFF - Click to enable"
            }
            relationship="label"
          >
            <Button
              appearance="transparent"
              icon={followMode ? <EyeRegular /> : <EyeOffRegular />}
              onClick={toggleFollowMode}
              size="small"
              style={
                followMode ? { color: tokens.colorBrandForeground1 } : undefined
              }
            />
          </Tooltip>
        )}
        <Tooltip
          content={
            theme === "dark" ? "Switch to light mode" : "Switch to dark mode"
          }
          relationship="label"
        >
          <Button
            appearance="transparent"
            icon={
              theme === "dark" ? (
                <WeatherSunnyRegular />
              ) : (
                <WeatherMoonRegular />
              )
            }
            onClick={onThemeToggle}
            size="small"
          />
        </Tooltip>
        {activeTab === "chat" && state.messages.length > 0 && (
          <Tooltip content="Clear messages" relationship="label">
            <Button
              appearance="transparent"
              icon={<DeleteRegular />}
              onClick={clearMessages}
              size="small"
            />
          </Tooltip>
        )}
      </div>
    </div>
  );
}

function ChatContent() {
  const [activeTab, setActiveTab] = useState<ChatTab>("chat");
  const { theme, toggleTheme } = useTheme();
  const { processFiles } = useChat();
  const [isDragOver, setIsDragOver] = useState(false);
  const dragCounterRef = useRef(0);
  const styles = useStyles();

  const handleDragEnter = useCallback((e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current++;
    if (e.dataTransfer.types.includes("Files")) {
      setIsDragOver(true);
    }
  }, []);

  const handleDragLeave = useCallback((e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current--;
    if (dragCounterRef.current === 0) {
      setIsDragOver(false);
    }
  }, []);

  const handleDragOver = useCallback((e: DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback(
    (e: DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      dragCounterRef.current = 0;
      setIsDragOver(false);
      const files = Array.from(e.dataTransfer.files);
      if (files.length > 0) {
        processFiles(files);
      }
    },
    [processFiles],
  );

  return (
    <div
      role="application"
      className={styles.root}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      <ChatHeader
        activeTab={activeTab}
        onTabChange={setActiveTab}
        theme={theme}
        onThemeToggle={toggleTheme}
      />
      {activeTab === "chat" ? (
        <div className={styles.chatContainer}>
          <StatsBar />
          <AgentStatusBar />
          <ToolApprovalPanel />
          <MessageList onOpenSettings={() => setActiveTab("settings")} />
          <McpAppDock />
          <ChatInput />
        </div>
      ) : (
        <SettingsPanel />
      )}

      {/* Drag-and-drop overlay */}
      {isDragOver && (
        <div className={styles.dragOverlay}>
          <div className={styles.dragContent}>
            <ArrowUploadRegular
              style={{ fontSize: "32px", color: tokens.colorBrandForeground1 }}
            />
            <Caption1>Drop files here</Caption1>
          </div>
        </div>
      )}
    </div>
  );
}

export function ChatInterface() {
  return <ChatContent />;
}
