/**
 * Run-level circuit breaker (PR-10c).
 *
 * Distinct from the per-tool MCP breaker in `src/lib/agent/mcp/circuit-breaker.ts`.
 * The MCP breaker disables a single failing tool for the rest of a run;
 * this run-level breaker shields the entire agent loop after repeated
 * provider-level failures so we don't hammer a degraded backend.
 *
 * Replaces the ad-hoc `isOpen` flag + lifetime failure counter that
 * previously lived inline in `Agent` (pre-PR-10c). Two concrete
 * improvements:
 *   - explicit `closed | open | half-open` FSM, so callers can reason
 *     about the probe-on-recovery path instead of the implicit
 *     "cooldown elapsed → reset to clean closed" jump.
 *   - windowed failure counting (rolling window of length `windowMs`)
 *     instead of a lifetime counter that could spuriously trip after
 *     long uptime with sporadic, unrelated failures.
 *
 * Default thresholds (5 failures, 60s cooldown, 60s window) preserve
 * the prior behaviour for production. Tests inject a {@link Clock} so
 * cooldown / windowing transitions are deterministic.
 *
 * See:
 *   - docs/post-pr7-cleanup-plan.md PR-10c
 *   - docs/agent-refactor-blueprint.md §10 (circuit breaker)
 */

import type { Clock } from "./clock";

export type RunCircuitBreakerState = "closed" | "open" | "half-open";

/** Default failure threshold within `windowMs` before the circuit opens. */
export const DEFAULT_RUN_BREAKER_THRESHOLD = 5;

/** Default rolling window for failure counting (matches legacy cooldown). */
export const DEFAULT_RUN_BREAKER_WINDOW_MS = 60_000;

/** Default cooldown the circuit must remain open before allowing a probe. */
export const DEFAULT_RUN_BREAKER_COOLDOWN_MS = 60_000;

export interface RunCircuitBreakerOptions {
  clock: Clock;
  /** Failures within `windowMs` to open the circuit. Default: 5. */
  threshold?: number;
  /** Rolling window length for failure counting. Default: 60_000ms. */
  windowMs?: number;
  /** How long the circuit stays open before allowing a half-open probe. Default: 60_000ms. */
  cooldownMs?: number;
  /** Optional hook called once when the circuit opens (legacy `console.warn`). */
  onOpen?: () => void;
}

export class RunCircuitBreaker {
  private status: RunCircuitBreakerState = "closed";
  private failureTimestamps: number[] = [];
  private openedAt = 0;
  private readonly clock: Clock;
  private readonly threshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly onOpen: (() => void) | undefined;

  constructor(opts: RunCircuitBreakerOptions) {
    this.clock = opts.clock;
    this.threshold = opts.threshold ?? DEFAULT_RUN_BREAKER_THRESHOLD;
    this.windowMs = opts.windowMs ?? DEFAULT_RUN_BREAKER_WINDOW_MS;
    this.cooldownMs = opts.cooldownMs ?? DEFAULT_RUN_BREAKER_COOLDOWN_MS;
    this.onOpen = opts.onOpen;
  }

  /**
   * Returns true if a new run should be blocked. Side effect: when in
   * `open` and the cooldown has elapsed, transitions to `half-open` and
   * returns false (allow exactly one probe).
   */
  shouldBlock(): boolean {
    if (this.status === "open") {
      const now = this.clock.now();
      if (now - this.openedAt > this.cooldownMs) {
        this.status = "half-open";
        return false;
      }
      return true;
    }
    return false;
  }

  /**
   * Record a provider-level failure.
   *   - In `half-open`: re-open immediately (the probe failed).
   *   - In `closed`: append a timestamp, prune the window, and open if
   *     the in-window count crosses the threshold.
   */
  recordFailure(): void {
    const now = this.clock.now();
    if (this.status === "half-open") {
      this.openCircuit(now);
      return;
    }
    this.failureTimestamps.push(now);
    this.pruneWindow(now);
    if (this.failureTimestamps.length >= this.threshold) {
      this.openCircuit(now);
    }
  }

  /**
   * Record a successful turn.
   *   - In `half-open`: close fully and clear in-window failures.
   *   - In `closed`: drop the most recent in-window failure timestamp
   *     so transient blips don't accumulate toward the threshold.
   */
  recordSuccess(): void {
    if (this.status === "half-open") {
      this.status = "closed";
      this.failureTimestamps = [];
      return;
    }
    if (this.failureTimestamps.length > 0) {
      this.failureTimestamps.pop();
    }
  }

  /** Inspection for tests / telemetry. */
  state(): RunCircuitBreakerState {
    return this.status;
  }

  /** In-window failure count after pruning expired entries. */
  failureCount(): number {
    this.pruneWindow(this.clock.now());
    return this.failureTimestamps.length;
  }

  private pruneWindow(now: number): void {
    const cutoff = now - this.windowMs;
    while (
      this.failureTimestamps.length > 0 &&
      this.failureTimestamps[0] < cutoff
    ) {
      this.failureTimestamps.shift();
    }
  }

  private openCircuit(now: number): void {
    const wasOpen = this.status === "open";
    this.status = "open";
    this.openedAt = now;
    if (!wasOpen) {
      this.onOpen?.();
    }
  }
}
