import type { Todo } from "./planner";

export const TODO_STATE_FILE_PATH = "/home/user/uploads/.officeai-todos.json";
export const TODO_CONTEXT_MAX_CHARS = 4000;
export const TODO_TRUNCATION_MARKER =
  "[... todo list truncated for context ...]";
export const TODO_STATUS_ICONS: Readonly<Record<string, string>> = {
  pending: "☐",
  in_progress: "▶",
  completed: "✓",
  cancelled: "✗",
};

const TODO_CONTEXT_HEADER =
  "[SYSTEM: Current TODO state (managed by you via update_todos). Updating todos is bookkeeping and does NOT satisfy the deliverable gate.]";

export function renderTodoContext(todos: readonly Todo[]): string | null {
  if (todos.length === 0) return null;
  const lines: string[] = [TODO_CONTEXT_HEADER];
  for (const todo of todos) {
    const icon = TODO_STATUS_ICONS[todo.status] ?? "·";
    const evidence = todo.evidence ? ` — ${todo.evidence}` : "";
    lines.push(`${icon} ${todo.content}${evidence}`);
  }
  const body = lines.join("\n");
  return body.length <= TODO_CONTEXT_MAX_CHARS
    ? body
    : truncateHeadTail(body, TODO_CONTEXT_MAX_CHARS, TODO_TRUNCATION_MARKER);
}

export function truncateHeadTail(
  text: string,
  maxChars: number,
  markerText: string,
): string {
  if (text.length <= maxChars) return text;
  const marker = `\n\n${markerText}\n\n`;
  const available = Math.max(0, maxChars - marker.length);
  const headChars = Math.ceil(available / 2);
  const tailChars = Math.floor(available / 2);
  return `${text.slice(0, headChars)}${marker}${text.slice(-tailChars)}`;
}
