/**
 * Planner prompt builders (PR-10a).
 *
 * Pure builders extracted from `agent.ts` per
 * docs/post-pr7-cleanup-plan.md §PR-10a. The functions return the exact
 * same prose the orchestrator was inlining before the extraction; the
 * only behavioral change is that all `this.` access has been replaced by
 * an explicit `PlannerPromptContext`. Snapshot tests in
 * `tests/agent/planner/prompts.test.ts` pin the output byte-for-byte so
 * any future drift is reviewable in a diff.
 *
 * The orchestrator now owns nothing about how planner prompts are
 * composed beyond calling these two functions.
 */

/**
 * Per-call inputs the orchestrator must supply. Captures every piece of
 * agent state the legacy `this.`-bound prompt builders read so the
 * extracted functions stay pure.
 */
export interface PlannerPromptContext {
  /**
   * Pre-formatted structured-plan checklist text from the most recent
   * successful `submit_plan` call (PR-6 §6.3). When non-null, takes
   * precedence over the prose phases — the structured composer is used
   * instead of the prose builder. Pass `null` to force the prose path.
   */
  cachedStructuredPlanText: string | null;

  /** Predicate used to decide which optional tool guidance is available. */
  hasToolNamed: (toolName: string) => boolean;
}

/**
 * Optional per-iteration tuning the orchestrator computes from FSM
 * state before each planner directive injection.
 */
export interface PlannerExecutionPromptOptions {
  complexMode?: boolean;
  forceCompaction?: boolean;
  executedToolCalls?: number;
}

function buildFileOutputDiscipline(ctx: PlannerPromptContext): string {
  const hasFileWriteTool =
    ctx.hasToolNamed("write_file") ||
    ctx.hasToolNamed("append_file") ||
    ctx.hasToolNamed("edit_file");
  const hasBulkProcessingTool =
    ctx.hasToolNamed("bash") || ctx.hasToolNamed("js");
  if (!hasFileWriteTool && !hasBulkProcessingTool) return "";

  return "File-output discipline: For large or generated files, do not route bulk generated content through model text or one giant write_file call. Use bash/js with VFS redirection when transforming uploaded files, sheets, or CSV data (for example `js build.mjs > matches.json`, or `>> matches.json` to append). If continuing an existing file, use `append_file` or `write_file` with `append: true` for only the missing suffix; if changing the middle, use `edit_file`. Verify with read-back, count, or parse before finalizing.";
}

/**
 * Build the planner prompt the orchestrator injects as a synthetic
 * user message at the top of each planner-mode turn.
 *
 * Behaviour-preserving extraction of the legacy
 * `Agent.buildPlannerExecutionPrompt`. When a structured plan is
 * cached, delegates to {@link composeStructuredPlannerInstruction};
 * otherwise emits the prose phases (planner / continuation, optionally
 * with the complex-workflow QC + bookkeeping rules).
 */
export function buildPlannerExecutionPrompt(
  ctx: PlannerPromptContext,
  hasExecutedToolsInRun: boolean,
  options?: PlannerExecutionPromptOptions,
): string {
  const complexMode = options?.complexMode ?? false;
  const forceCompaction = options?.forceCompaction ?? false;
  const executedToolCalls = options?.executedToolCalls ?? 0;
  const fileOutputDiscipline = buildFileOutputDiscipline(ctx);

  // PR-6 §6.3: when a structured plan was successfully submitted before
  // the loop started, prefer it over the prose phases. The plan text is
  // a deterministic checklist; the prose execution-discipline footer is
  // still appended so deliverable gating, bookkeeping rules, and
  // QC-before-finalize rules remain consistent across both paths.
  if (ctx.cachedStructuredPlanText) {
    return composeStructuredPlannerInstruction(
      ctx,
      ctx.cachedStructuredPlanText,
      hasExecutedToolsInRun,
      { complexMode, forceCompaction, executedToolCalls },
    );
  }

  if (complexMode) {
    const canUseTodos = ctx.hasToolNamed("update_todos");
    const progressFileInstructions = canUseTodos
      ? "Context freshness + structured todos (required): Maintain live workflow progress via `update_todos`.\n- Call `update_todos` at the start of execution to establish your checklist, then call it again when item statuses/evidence change.\n- Always submit the full list. Preserve stable non-empty `id` values for existing items; mark obsolete work `cancelled` instead of deleting it.\n- Each item must include concise `content`, present-continuous `activeForm`, and `status`. Use `pending`, `in_progress`, `completed`, or `cancelled` to reflect the current forward workflow state.\n- TODOs are UI/bookkeeping only; after each TODO update, continue directly to deliverable/read/verification tools, or provide the final answer when the current workbook/context already satisfies a read-only request.\n- The current TODO state is re-injected each turn; do not restate it verbatim in your prose."
      : "Context freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history.";

    const compactionInstruction =
      forceCompaction && !canUseTodos
        ? "Compaction checkpoint: perform a compaction update now before further execution."
        : "";

    const progressBookkeepingDoesNotCountRule = canUseTodos
      ? `IMPORTANT - Bookkeeping does NOT satisfy EXECUTION: Updating TODOs (\`update_todos\`), writing/updating the run log, any "wiki", "log", "task", "plan", or "notes" markdown file, or any other progress/bookkeeping file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable (e.g., reading source data, transforming it, and writing it to the workbook/sheet/document the user asked for) or providing the final prose answer when the current workbook/context is sufficient for a read-only request. In every iteration where you have not yet performed at least one such deliverable-producing tool call and the current context is not already sufficient to answer, you must call one before writing or updating any progress/bookkeeping file. Never end a turn after only writing bookkeeping files when the user's deliverable is incomplete.`
      : `IMPORTANT - Bookkeeping does NOT satisfy EXECUTION: Writing/updating the run log, any "wiki", "log", "task", "plan", or "notes" markdown file, or any other progress/bookkeeping file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable (e.g., reading source data, transforming it, and writing it to the workbook/sheet/document the user asked for). In every iteration where you have not yet performed at least one such deliverable-producing tool call, you must call one before writing or updating any progress/bookkeeping file. Never end a turn after only writing bookkeeping files when the user's deliverable is incomplete.`;
    const fileOutputSection = fileOutputDiscipline
      ? `\n${fileOutputDiscipline}`
      : "";

    if (!hasExecutedToolsInRun) {
      return `Planner mode (complex workload): make one forward pass through the three phases below to complete the request.\nPhase 1 - PLAN: create a short actionable checklist tied to the user request.\nPhase 2 - EXECUTION: execute the checklist items using the available tools.\nPhase 3 - QUALITY CHECK: before the final answer, verify outcomes against requirements and run at least one concrete validation/read-back step.\nDo not return to PLAN or revise the checklist mid-run. If the request becomes blocked, ambiguous, or needs changed instructions, finish the current pass and ask the user in the final answer.\n${progressFileInstructions}${fileOutputSection}\n${progressBookkeepingDoesNotCountRule}\n${compactionInstruction}\nAfter producing the plan, continue forward by invoking the relevant tools. Additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.`;
    }

    return `Planner mode (complex workload): continue the current forward pass. Do not return to PLAN or revise the checklist mid-run.\nExecution status: ${executedToolCalls} tool call(s) executed in this run.\nIf prior planner state is missing or requirements are ambiguous, use the existing tool results and conversation context to finish the current pass; ask the user for updated instructions in the final answer instead of re-planning.\nRequired QUALITY CHECK before the final answer:\n- Confirm each user requirement is satisfied.\n- Run concrete verification using available tools (for example read-back, search, or inspection).\n- Report residual risk or gaps explicitly.\n${progressFileInstructions}${fileOutputSection}\n${progressBookkeepingDoesNotCountRule}\n${compactionInstruction}\nPrior checklists or planner output do not need to be re-shared. Provide the final answer once execution and quality checks are complete.`;
  }

  const simpleFileOutputSection = fileOutputDiscipline
    ? ` ${fileOutputDiscipline}`
    : "";

  if (!hasExecutedToolsInRun) {
    return `Planner mode: create a short execution plan from the current request and available conversation context, then invoke the required tools to carry it out in a single forward pass.${simpleFileOutputSection} Do not return to planning mid-run; if instructions need to change, finish the current pass and ask the user in the final answer. After producing the plan, continue by invoking the relevant tools; additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.`;
  }
  return `Planner mode: continue executing the remaining tool steps until complete without returning to planning. If prior planner state is missing or instructions are ambiguous, finish the current pass using tool results and conversation context; ask the user for updated instructions in the final answer.${simpleFileOutputSection} Prior checklists or planner output do not need to be re-shared. Provide the final answer once tool execution is complete.`;
}

/**
 * Compose the structured-plan variant of the planner instruction.
 *
 * Behaviour-preserving extraction of the legacy
 * `Agent.composeStructuredPlannerInstruction`. The structured plan
 * checklist (already formatted by `formatPlanAsChecklist`) is wrapped
 * with the same QC/bookkeeping/progress-file footers the prose path
 * uses, so the two surfaces stay interchangeable from the model's
 * perspective.
 */
export function composeStructuredPlannerInstruction(
  ctx: PlannerPromptContext,
  structuredPlanText: string,
  hasExecutedToolsInRun: boolean,
  options: {
    complexMode: boolean;
    forceCompaction: boolean;
    executedToolCalls: number;
  },
): string {
  const compactionInstruction = options.forceCompaction
    ? "\nCompaction checkpoint: perform a compaction update now before further execution."
    : "";

  const canUseTodos = ctx.hasToolNamed("update_todos");
  const progressFileInstructions = options.complexMode
    ? canUseTodos
      ? "\nContext freshness + structured todos (required): Maintain live workflow progress via `update_todos`. Call it at the start of execution to establish your checklist, then call it again when item statuses/evidence change. Always submit the full list, preserve stable ids for existing items, and mark obsolete work cancelled instead of deleting it. After each TODO update, proceed directly to deliverable/read/verification tools, or provide the final answer when the current workbook/context already satisfies a read-only request. The current TODO state is re-injected each turn."
      : "\nContext freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history."
    : "";

  const bookkeepingRule = options.complexMode
    ? canUseTodos
      ? `\nIMPORTANT - Bookkeeping does NOT satisfy EXECUTION: updating todos (\`update_todos\`) or writing/updating any progress/wiki/log/checklist file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable or providing the final prose answer when the current workbook/context is sufficient for a read-only request. Never end a turn after only bookkeeping calls when the user's deliverable is incomplete.`
      : `\nIMPORTANT - Bookkeeping does NOT satisfy EXECUTION: writing or updating any progress/wiki/log/checklist file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable. Never end a turn after only writing bookkeeping files when the user's deliverable is incomplete.`
    : "";

  const qcRule = options.complexMode
    ? "\nQUALITY CHECK before final answer: confirm each user requirement is satisfied, run concrete verification using available tools (read-back, search, or inspection), and report residual risk or gaps explicitly."
    : "";

  const fileOutputRule = buildFileOutputDiscipline(ctx);
  const fileOutputSection = fileOutputRule ? `\n${fileOutputRule}` : "";

  const continuationFooter = hasExecutedToolsInRun
    ? `\nExecution status: ${options.executedToolCalls} tool call(s) executed in this run. Continue the current forward pass without returning to PLAN. Provide the final answer once all steps and quality checks are complete; if instructions need to change, ask the user in that final answer.`
    : "\nPlease carry out the steps above using the available tools in one forward pass. After producing the plan, continue by invoking the relevant tools; do not return to PLAN mid-run. Additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.";

  return `Planner mode (structured plan):\n${structuredPlanText}${continuationFooter}${qcRule}${progressFileInstructions}${fileOutputSection}${bookkeepingRule}${compactionInstruction}`;
}
