import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import {
  getResolvedDocumentParagraphRange,
  resolveDocumentParagraphIndexes,
} from "./word-anchor-utils";

/* global Word */

const RANGE_FONT_LOAD =
  "font/bold,font/italic,font/underline,font/name,font/size,font/color";
const PARAGRAPH_TEXT_LOAD = "items/text";
const PARAGRAPH_FORMAT_LOAD =
  "items/alignment,items/leftIndent,items/rightIndent,items/firstLineIndent,items/lineSpacing,items/spaceBefore,items/spaceAfter";
const PARAGRAPH_PREVIEW_LENGTH = 80;
const TRUNCATION_SUFFIX = "\n\n[Content truncated...]";

export const getDocumentContentTool = defineTool({
  name: "get_document_content",
  category: "read",
  parallelSafe: true,
  label: "Get Document Content",
  description:
    "Read text content from the Word document. " +
    "Can read the entire document body, current selection, or a specific range by paragraph indices. " +
    "Use this to inspect document content before modifying it. " +
    "Returns paragraph anchor metadata to help target later edits more reliably.",
  parameters: Type.Object({
    scope: Type.Union(
      [
        Type.Literal("body", { description: "Read entire document body" }),
        Type.Literal("selection", {
          description: "Read currently selected text",
        }),
        Type.Literal("range", { description: "Read specific paragraph range" }),
      ],
      { description: "What part of the document to read" },
    ),
    startParagraph: Type.Optional(
      Type.Number({
        description: "Starting paragraph index (0-based) when scope is 'range'",
        default: 0,
      }),
    ),
    endParagraph: Type.Optional(
      Type.Number({
        description: "Ending paragraph index (inclusive) when scope is 'range'",
      }),
    ),
    includeFormatting: Type.Optional(
      Type.Boolean({
        description:
          "Include formatting info (bold, italic, etc.). Default: false",
        default: false,
      }),
    ),
    maxLength: Type.Optional(
      Type.Number({
        description: "Maximum character length to return. Default: 10000",
        default: 10000,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of what you're reading (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      const result = await Word.run(async (context) => {
        const includeFormatting = params.includeFormatting ?? false;
        const maxLength = params.maxLength ?? 10000;
        let textContent = "";
        let targetRange: Word.Range | null = null;
        let relevantParagraphs: Word.Paragraph[] = [];
        let documentStartParagraph: number | null = null;
        let resolvedDocumentParagraphIndexes: Array<number | null> | undefined;

        switch (params.scope) {
          case "selection": {
            targetRange = context.document.getSelection();
            targetRange.load("text");
            if (includeFormatting) {
              targetRange.load(RANGE_FONT_LOAD);
            }
            const paragraphs = targetRange.paragraphs;
            paragraphs.load(PARAGRAPH_TEXT_LOAD);
            if (includeFormatting) {
              paragraphs.load(PARAGRAPH_FORMAT_LOAD);
            }
            const documentParagraphs = context.document.body.paragraphs;
            documentParagraphs.load(PARAGRAPH_TEXT_LOAD);
            await context.sync();
            textContent = targetRange.text ?? "";
            relevantParagraphs = paragraphs.items;
            resolvedDocumentParagraphIndexes = resolveDocumentParagraphIndexes(
              relevantParagraphs.map((paragraph) => paragraph.text ?? ""),
              documentParagraphs.items.map((paragraph) => paragraph.text ?? ""),
            );
            break;
          }
          case "range": {
            const start = params.startParagraph ?? 0;
            const end = params.endParagraph ?? start;
            const paragraphs = context.document.body.paragraphs;
            paragraphs.load(PARAGRAPH_TEXT_LOAD);
            if (includeFormatting) {
              paragraphs.load(PARAGRAPH_FORMAT_LOAD);
            }
            await context.sync();

            if (paragraphs.items.length === 0) {
              return {
                text: "",
                length: 0,
                originalLength: 0,
                truncated: false,
                scope: params.scope,
                paragraphCount: 0,
                scopeRange: {
                  startParagraph: null,
                  endParagraph: null,
                  documentIndexed: true,
                },
                paragraphs: [],
                paragraphsTruncated: false,
                omittedParagraphCount: 0,
              };
            }

            if (!Number.isInteger(start) || start < 0) {
              throw new Error("startParagraph must be a non-negative integer");
            }

            if (!Number.isInteger(end) || end < start) {
              throw new Error(
                "endParagraph must be an integer greater than or equal to startParagraph",
              );
            }

            if (start >= paragraphs.items.length) {
              throw new Error(
                `startParagraph ${start} is out of range (0-${paragraphs.items.length - 1})`,
              );
            }

            const actualEnd = Math.min(end, paragraphs.items.length - 1);
            relevantParagraphs = paragraphs.items.slice(start, actualEnd + 1);
            documentStartParagraph = start;
            targetRange = relevantParagraphs[0]
              .getRange()
              .expandTo(
                relevantParagraphs[relevantParagraphs.length - 1].getRange(),
              );
            targetRange.load("text");
            if (includeFormatting) {
              targetRange.load(RANGE_FONT_LOAD);
            }
            await context.sync();
            textContent =
              targetRange.text ??
              relevantParagraphs
                .map((paragraph) => paragraph.text ?? "")
                .join("\n");
            break;
          }
          default: {
            targetRange = context.document.body.getRange();
            targetRange.load("text");
            if (includeFormatting) {
              targetRange.load(RANGE_FONT_LOAD);
            }
            const paragraphs = context.document.body.paragraphs;
            paragraphs.load(PARAGRAPH_TEXT_LOAD);
            if (includeFormatting) {
              paragraphs.load(PARAGRAPH_FORMAT_LOAD);
            }
            await context.sync();
            textContent = targetRange.text ?? "";
            relevantParagraphs = paragraphs.items;
            if (relevantParagraphs.length > 0) {
              documentStartParagraph = 0;
            }
            break;
          }
        }

        const originalLength = textContent.length;
        const truncated = originalLength > maxLength;
        const visibleTextLimit = truncated ? maxLength : undefined;
        const { paragraphs, omittedParagraphCount } = buildParagraphAnchors(
          relevantParagraphs,
          {
            documentStartParagraph,
            documentParagraphIndexes: resolvedDocumentParagraphIndexes,
            includeFormatting,
            visibleTextLimit,
          },
        );

        if (truncated) {
          textContent = textContent.substring(0, maxLength) + TRUNCATION_SUFFIX;
        }

        const resolvedDocumentRange = getResolvedDocumentParagraphRange(
          resolvedDocumentParagraphIndexes,
        );
        const documentEndParagraph =
          documentStartParagraph === null || relevantParagraphs.length === 0
            ? resolvedDocumentRange.endParagraph
            : documentStartParagraph + relevantParagraphs.length - 1;

        return {
          text: textContent,
          length: textContent.length,
          originalLength,
          truncated,
          scope: params.scope,
          paragraphCount: relevantParagraphs.length,
          scopeRange: {
            startParagraph:
              documentStartParagraph ?? resolvedDocumentRange.startParagraph,
            endParagraph: documentEndParagraph,
            documentIndexed:
              documentStartParagraph !== null ||
              resolvedDocumentRange.documentIndexed,
          },
          paragraphs,
          paragraphsTruncated: omittedParagraphCount > 0,
          omittedParagraphCount,
          formatting:
            includeFormatting && targetRange
              ? serializeRangeFormatting(targetRange)
              : undefined,
        };
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error reading document content";
      return toolError(message);
    }
  },
});

function buildParagraphAnchors(
  paragraphs: Word.Paragraph[],
  options: {
    documentStartParagraph: number | null;
    documentParagraphIndexes?: Array<number | null>;
    includeFormatting: boolean;
    visibleTextLimit?: number;
  },
): {
  paragraphs: Array<{
    paragraphIndex: number | null;
    scopeParagraphIndex: number;
    startOffset: number;
    endOffset: number;
    length: number;
    anchor: {
      paragraphIndex: number | null;
      scopeParagraphIndex: number;
      startOffset: number;
      endOffset: number;
      textPreview: string;
    };
    formatting?: {
      alignment: unknown;
      lineSpacing: unknown;
      spaceBefore: unknown;
      spaceAfter: unknown;
      leftIndent: unknown;
      rightIndent: unknown;
      firstLineIndent: unknown;
    };
  }>;
  omittedParagraphCount: number;
} {
  let currentOffset = 0;
  let omittedParagraphCount = 0;
  const anchors: Array<{
    paragraphIndex: number | null;
    scopeParagraphIndex: number;
    startOffset: number;
    endOffset: number;
    length: number;
    anchor: {
      paragraphIndex: number | null;
      scopeParagraphIndex: number;
      startOffset: number;
      endOffset: number;
      textPreview: string;
    };
    formatting?: {
      alignment: unknown;
      lineSpacing: unknown;
      spaceBefore: unknown;
      spaceAfter: unknown;
      leftIndent: unknown;
      rightIndent: unknown;
      firstLineIndent: unknown;
    };
  }> = [];

  for (const [scopeParagraphIndex, paragraph] of paragraphs.entries()) {
    const text = paragraph.text ?? "";
    const startOffset = currentOffset;
    const endOffset = startOffset + text.length;
    currentOffset = endOffset + 1;

    if (
      options.visibleTextLimit !== undefined &&
      startOffset >= options.visibleTextLimit
    ) {
      omittedParagraphCount++;
      continue;
    }

    const paragraphIndex =
      options.documentParagraphIndexes?.[scopeParagraphIndex] ??
      (options.documentStartParagraph === null
        ? null
        : options.documentStartParagraph + scopeParagraphIndex);

    anchors.push({
      paragraphIndex,
      scopeParagraphIndex,
      startOffset,
      endOffset,
      length: text.length,
      anchor: {
        paragraphIndex,
        scopeParagraphIndex,
        startOffset,
        endOffset,
        textPreview: createPreview(text, PARAGRAPH_PREVIEW_LENGTH),
      },
      formatting: options.includeFormatting
        ? serializeParagraphFormatting(paragraph)
        : undefined,
    });
  }

  return {
    paragraphs: anchors,
    omittedParagraphCount,
  };
}

function serializeRangeFormatting(range: Word.Range): {
  bold: unknown;
  italic: unknown;
  underline: unknown;
  fontName: unknown;
  fontSize: unknown;
  fontColor: unknown;
} {
  return {
    bold: range.font.bold,
    italic: range.font.italic,
    underline: range.font.underline,
    fontName: range.font.name,
    fontSize: range.font.size,
    fontColor: range.font.color,
  };
}

function serializeParagraphFormatting(paragraph: Word.Paragraph): {
  alignment: unknown;
  lineSpacing: unknown;
  spaceBefore: unknown;
  spaceAfter: unknown;
  leftIndent: unknown;
  rightIndent: unknown;
  firstLineIndent: unknown;
} {
  return {
    alignment: paragraph.alignment,
    lineSpacing: paragraph.lineSpacing,
    spaceBefore: paragraph.spaceBefore,
    spaceAfter: paragraph.spaceAfter,
    leftIndent: paragraph.leftIndent,
    rightIndent: paragraph.rightIndent,
    firstLineIndent: paragraph.firstLineIndent,
  };
}

function createPreview(text: string, maxLength: number): string {
  const normalizedText = text.replace(/\s+/g, " ").trim();
  if (normalizedText.length <= maxLength) {
    return normalizedText;
  }

  return `${normalizedText.substring(0, maxLength - 3)}...`;
}
