/**
 * MCP tool adapter (PR-3B.1).
 *
 * Maps remote MCP tool descriptors into internal {@link Tool} records
 * with namespaced names per docs/mcp-connection-contract.md §4 and
 * docs/agent-refactor-blueprint.md §4.2.
 *
 * Default metadata for every adapted MCP tool is `parallelSafe: false`,
 * `origin: "mcp"`. A tool without behavior annotations is `unknown`: it is
 * serialized, receives no automatic retries, is never deduplicated, and
 * cannot release the concrete-execution latch. `readOnlyHint: true` maps to
 * `read`; explicit `readOnlyHint: false` maps to `effectful`, or to
 * `non_idempotent` when `idempotentHint: false` is also declared.
 * Server-advertised hints are advisory: they may only make categorization
 * MORE conservative and MUST NOT upgrade `category` to `deliverable` or flip
 * `parallelSafe`.
 *
 * Operators MAY opt specific remote tools into parallel-safe
 * dispatch via the connection's `parallelSafeRemoteTools` allowlist
 * (see {@link MCPConnectionConfig.parallelSafeRemoteTools}); the adapter
 * only consults the allowlist passed through {@link AdaptMCPToolOptions},
 * never the `inputSchema`, so a malicious server cannot self-elevate.
 *
 * Note on suffix hash: blueprint §4.2 specifies sha256 + base32-lower.
 * PR-3B.1 uses a deterministic 32-bit FNV-1a hash encoded in
 * base32-lower for the truncation suffix to keep the adapter
 * synchronous (Web Crypto digest is async). The suffix is a
 * disambiguator for over-length names, not a security primitive;
 * collision resistance at 30 bits is adequate for the per-connection
 * adaptation set. PR-3B.2 may revisit if the catalog grows large.
 */

import { fileExists, readFile } from "../../vfs";
import { createAgentError } from "../errors";
import type {
  Tool,
  ToolCategory,
  ToolResult,
  ToolUiResourcePayload,
} from "../types";
import type { MCPInvocationClient } from "./client";
import type { MCPRemoteToolDescriptor } from "./types";
import {
  MCP_UI_RESOURCE_MIME,
  extractEmbeddedUiResource,
  getToolUiResourceUri,
  isUiResourceUri,
  payloadFromReadResourceResult,
} from "./ui";

const NAMESPACE_PREFIX = "mcp__";
const NAME_MAX_LEN = 64;
const NAME_PATTERN = /^[a-zA-Z0-9_-]{1,64}$/;
const SAFE_CHAR = /[^a-zA-Z0-9_-]/g;
const SUFFIX_LEN = 6;
/** Base32 alphabet (lowercase, RFC 4648 without padding). */
const BASE32_ALPHABET = "abcdefghijklmnopqrstuvwxyz234567";
const VFS_REF_PREFIX = "vfs://";
const SALVAGE_SCRATCH_PREFIX = "/tmp/salvage/";
/**
 * Hard upper bound on the resolved bytes the adapter will inline into a
 * remote MCP tool argument. Crossed only when the staged VFS file is
 * larger than this; the model is then asked to chunk or stream instead
 * of re-introducing the very token-budget problem `vfs://` was meant to
 * solve. 1 MiB is large enough for typical staged HTML/JSON payloads
 * while still flagging runaway content.
 */
const VFS_CONTENT_REFERENCE_MAX_BYTES = 1 * 1024 * 1024;
const MCP_CONTENT_REFERENCE_FIELDS: ReadonlySet<string> = new Set([
  "body",
  "code",
  "content",
  "data",
  "html",
  "markdown",
  "source",
  "text",
  "value",
]);

export function categorizeMCPTool(
  descriptor: MCPRemoteToolDescriptor,
): ToolCategory {
  const annotations = descriptor.annotations;
  if (annotations?.readOnlyHint === true) return "read";
  if (annotations?.readOnlyHint === false) {
    return annotations.idempotentHint === false
      ? "non_idempotent"
      : "effectful";
  }
  return "unknown";
}

/** Sanitize a single name segment per contract §4. */
export function sanitizeNameSegment(segment: string): string {
  return segment.replace(SAFE_CHAR, "-");
}

/** FNV-1a 32-bit hash of a UTF-16 string (sufficient for §4.2 disambiguation). */
function fnv1a32(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i) & 0xff;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

/** 30 bits of `value` rendered as 6 base32-lower chars. */
function toBase32Lower6(value: number): string {
  let result = "";
  let v = value >>> 0;
  for (let i = 0; i < SUFFIX_LEN; i++) {
    result = BASE32_ALPHABET[v & 0x1f] + result;
    v >>>= 5;
  }
  return result;
}

/**
 * Build a namespaced tool name from a connection id and remote tool name.
 *
 * Returns `null` if the connection id segment alone (with the prefix and
 * separator) already exceeds the length budget — the connection id is
 * never truncated per blueprint §4.2.
 */
export function buildNamespacedToolName(
  connectionId: string,
  remoteToolName: string,
): string | null {
  const idSeg = sanitizeNameSegment(connectionId);
  const remoteSeg = sanitizeNameSegment(remoteToolName);
  const fixed = `${NAMESPACE_PREFIX}${idSeg}__`;

  // Connection id segment is never truncated.
  if (fixed.length >= NAME_MAX_LEN) {
    return null;
  }

  const naive = `${fixed}${remoteSeg}`;
  if (naive.length <= NAME_MAX_LEN && NAME_PATTERN.test(naive)) {
    return naive;
  }

  // Truncate remote segment and append a deterministic 6-char suffix
  // hash of the original full name.
  const fullOriginal = `${NAMESPACE_PREFIX}${connectionId}__${remoteToolName}`;
  const suffix = toBase32Lower6(fnv1a32(fullOriginal));
  const remoteBudget = NAME_MAX_LEN - fixed.length - SUFFIX_LEN;
  if (remoteBudget < 1) {
    return null;
  }
  const truncated = remoteSeg.slice(0, remoteBudget);
  const candidate = `${fixed}${truncated}${suffix}`;
  return NAME_PATTERN.test(candidate) ? candidate : null;
}

/** Sanitize a description for prompt-safety (plain text + size limit). */
export function sanitizeToolDescription(
  raw: string | undefined,
  remoteToolName: string,
  serverLabel: string,
): string {
  const fallback = `MCP tool ${remoteToolName} from ${serverLabel}`;
  if (!raw) return fallback;
  const stripped = raw
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!stripped) return fallback;
  return stripped.length > 1024 ? `${stripped.slice(0, 1021)}...` : stripped;
}

export interface AdaptedMCPTool {
  tool: Tool;
  /** Original remote tool name (pre-namespacing). */
  remoteToolName: string;
}

export interface AdaptMCPToolOptions {
  connectionId: string;
  serverLabel: string;
  client: MCPInvocationClient;
  /**
   * Operator-managed allowlist of remote tool names (pre-namespacing)
   * for which the adapter should set `parallelSafe: true`. Defaults
   * empty so the documented `parallelSafe: false` default still applies
   * to every server that does not explicitly opt in. See
   * {@link MCPConnectionConfig.parallelSafeRemoteTools}.
   */
  parallelSafeRemoteTools?: ReadonlySet<string>;
}

function parseVfsContentReference(value: string): string | null {
  const trimmed = value.trim();
  if (trimmed.startsWith(VFS_REF_PREFIX)) {
    const path = trimmed.slice(VFS_REF_PREFIX.length);
    return path.startsWith("/") ? path : `/${path}`;
  }
  if (trimmed.startsWith(SALVAGE_SCRATCH_PREFIX)) return trimmed;
  return null;
}

async function resolveMCPContentReferences(
  remoteToolName: string,
  params: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  let resolved: Record<string, unknown> | null = null;

  for (const [fieldName, value] of Object.entries(params)) {
    if (!MCP_CONTENT_REFERENCE_FIELDS.has(fieldName)) continue;
    if (typeof value !== "string") continue;

    const path = parseVfsContentReference(value);
    if (!path) continue;

    if (path.startsWith(SALVAGE_SCRATCH_PREFIX)) {
      throw createAgentError(
        "MCP_TOOL_INVOCATION_FAILED",
        `MCP tool ${remoteToolName} received ${fieldName} as ${path}, but /tmp/salvage files are truncated scratch prefixes. Stage the full final content to /home/user/uploads/... and pass it as vfs:///home/user/uploads/... instead.`,
        { details: { toolName: remoteToolName, path, retryable: false } },
      );
    }

    if (!(await fileExists(path))) {
      throw createAgentError(
        "MCP_TOOL_INVOCATION_FAILED",
        `MCP tool ${remoteToolName} received ${fieldName} as a VFS reference, but ${path} does not exist.`,
        { details: { toolName: remoteToolName, path, retryable: false } },
      );
    }

    const referencedContent = await readFile(path);
    if (referencedContent.trim().length === 0) {
      throw createAgentError(
        "MCP_TOOL_INVOCATION_FAILED",
        `MCP tool ${remoteToolName} received ${fieldName} as a VFS reference, but ${path} is empty. Regenerate the full content, validate the staged file is non-empty, then retry with vfs://${path}.`,
        { details: { toolName: remoteToolName, path, retryable: false } },
      );
    }

    // UTF-16-code-unit length is a tight upper bound on the eventual
    // UTF-8 byte count for the strings that flow through the VFS; using
    // it here avoids re-encoding the (potentially large) payload just
    // to compute the guard. A real over-limit payload triggers the
    // error well before we approach realistic memory pressure.
    if (referencedContent.length > VFS_CONTENT_REFERENCE_MAX_BYTES) {
      throw createAgentError(
        "MCP_TOOL_INVOCATION_FAILED",
        `MCP tool ${remoteToolName} received ${fieldName} as vfs://${path}, but the staged file is ${referencedContent.length} characters (> ${VFS_CONTENT_REFERENCE_MAX_BYTES}). Inlining it would re-introduce the token-budget problem the vfs:// reference was meant to avoid. Split the content across multiple tool calls if the remote API supports chunking, or reduce the payload before retrying.`,
        {
          details: {
            toolName: remoteToolName,
            path,
            size: referencedContent.length,
            limit: VFS_CONTENT_REFERENCE_MAX_BYTES,
            retryable: false,
          },
        },
      );
    }

    resolved ??= { ...params };
    resolved[fieldName] = referencedContent;
  }

  return resolved ?? params;
}

/**
 * Adapt a single remote MCP tool descriptor into an internal Tool.
 * Returns `null` when namespacing fails (see {@link buildNamespacedToolName}).
 */
export function adaptMCPTool(
  descriptor: MCPRemoteToolDescriptor,
  options: AdaptMCPToolOptions,
): AdaptedMCPTool | null {
  const namespaced = buildNamespacedToolName(
    options.connectionId,
    descriptor.name,
  );
  if (!namespaced) return null;

  const description = sanitizeToolDescription(
    descriptor.description,
    descriptor.name,
    options.serverLabel,
  );

  const isParallelSafe =
    options.parallelSafeRemoteTools?.has(descriptor.name) === true;

  // MCP Apps (SEP-1865): tools may declare an interactive UI via
  // `_meta.ui.resourceUri` (or the legacy `_meta["ui/resourceUri"]`).
  // We capture the URI here so we can resolve the HTML via
  // `resources/read` on each call, AND still detect the URI when the
  // server only attaches it to call results (some servers do this when
  // the resource URI depends on per-call input).
  const declaredUiResourceUri = getToolUiResourceUri(descriptor);

  const tool: Tool = {
    name: namespaced,
    label: `${options.serverLabel}: ${descriptor.name}`,
    description,
    parameters:
      descriptor.inputSchema &&
      typeof descriptor.inputSchema === "object" &&
      !Array.isArray(descriptor.inputSchema)
        ? descriptor.inputSchema
        : { type: "object", properties: {}, additionalProperties: true },
    category: categorizeMCPTool(descriptor),
    destructive: descriptor.annotations?.destructiveHint === true,
    parallelSafe: isParallelSafe,
    origin: "mcp",
    mcpRef: {
      connectionId: options.connectionId,
      serverLabel: options.serverLabel,
      remoteToolName: descriptor.name,
    },
    execute: async (
      _toolCallId: string,
      params: Record<string, unknown>,
      signal?: AbortSignal,
    ): Promise<ToolResult> => {
      const resolvedParams = await resolveMCPContentReferences(
        descriptor.name,
        params,
      );
      const result = await options.client.callTool({
        connectionId: options.connectionId,
        remoteToolName: descriptor.name,
        arguments: resolvedParams,
        signal,
      });

      // Surface MCP App UI payload if the server advertises one. We try
      // three sources in order:
      //   1. Tool descriptor `_meta.ui.resourceUri` (captured above).
      //   2. Per-call result `_meta.ui.resourceUri` (lets the server
      //      pick a UI dynamically based on arguments).
      //   3. An embedded `resource` content block with mime
      //      `text/html;profile=mcp-app` (single-roundtrip path).
      // Failures are non-fatal: the tool result is still returned with
      // its text content so the model isn't blocked by a missing UI.
      const ui = await resolveUiResourcePayload(
        options,
        descriptor.name,
        declaredUiResourceUri,
        result,
        signal,
      );
      if (ui) {
        return { ...result, ui };
      }
      return result;
    },
  };

  return { tool, remoteToolName: descriptor.name };
}

async function resolveUiResourcePayload(
  options: AdaptMCPToolOptions,
  remoteToolName: string,
  declaredUiResourceUri: string | undefined,
  result: ToolResult,
  signal?: AbortSignal,
): Promise<ToolUiResourcePayload | undefined> {
  const stamp = (payload: ToolUiResourcePayload): ToolUiResourcePayload => ({
    ...payload,
    connectionId: options.connectionId,
    serverLabel: options.serverLabel,
  });

  // 3a. Inline embedded resource — preferred when present because it
  // avoids a follow-up RTT.
  const embedded = extractEmbeddedUiResource(result.content);
  if (embedded) {
    return stamp({
      uri: embedded.uri,
      html: embedded.html,
      mimeType: embedded.mimeType || MCP_UI_RESOURCE_MIME,
      csp: embedded.csp,
      permissions: embedded.permissions,
      meta: embedded.meta,
    });
  }

  // Resolve URI: per-call `_meta` wins (server-dynamic), otherwise the
  // tool-descriptor declaration. Reject anything that doesn't look like
  // a `ui://` URI so a server can't trick us into fetching arbitrary
  // resources and rendering them.
  const callMetaUri = getToolUiResourceUri({ _meta: result.meta });
  const uri = callMetaUri ?? declaredUiResourceUri;
  if (!uri || !isUiResourceUri(uri)) return undefined;
  if (!options.client.readResource) return undefined;

  try {
    const read = await options.client.readResource({
      connectionId: options.connectionId,
      uri,
      signal,
      interactiveAllowed: false,
    });
    const payload = payloadFromReadResourceResult(uri, read);
    return payload ? stamp(payload) : undefined;
  } catch (err) {
    console.warn(
      `[MCP tool-adapter] failed to read UI resource ${uri} for ${remoteToolName} on ${options.connectionId}:`,
      err,
    );
    return undefined;
  }
}
