import type { Tool } from "../types";

export const ENABLE_MCP_SERVER_TOOL_NAME = "enable_mcp_server";

export interface MCPServerToolSummary {
  name: string;
  description: string;
  argumentNames: string[];
}

export interface MCPServerActivationSuccessPayload {
  ok: true;
  server_id: string;
  label: string;
  already_active: boolean;
  tool_count: number;
  tools: MCPServerToolSummary[];
}

export interface MCPServerActivationErrorPayload {
  ok: false;
  error: {
    code:
      | "INVALID_PAYLOAD"
      | "MCP_UNKNOWN_SERVER"
      | "MCP_CONNECTION_UNAVAILABLE";
    message: string;
    server_id?: string;
    retryable: boolean;
  };
}

export type MCPServerActivationPayload =
  | MCPServerActivationSuccessPayload
  | MCPServerActivationErrorPayload;

export type MCPServerActivationResult =
  | { ok: true; payload: MCPServerActivationSuccessPayload }
  | {
      ok: false;
      payload: MCPServerActivationErrorPayload;
      errorCode: MCPServerActivationErrorPayload["error"]["code"];
    };

export interface MCPServerActivationProvider {
  activateServer(
    serverId: string,
    activeServerIds: ReadonlySet<string>,
  ): MCPServerActivationResult;
}

export function validateEnableMcpServerArguments(
  args: Record<string, unknown>,
): { ok: true; serverId: string } | { ok: false; errors: string[] } {
  const raw = args.server_id;
  if (typeof raw !== "string") {
    return { ok: false, errors: ["server_id must be a string"] };
  }
  const serverId = raw.trim();
  if (!serverId) {
    return { ok: false, errors: ["server_id must be non-empty"] };
  }
  return { ok: true, serverId };
}

export function topLevelArgumentNames(
  tool: Pick<Tool, "parameters">,
): string[] {
  const parameters = tool.parameters;
  if (
    !parameters ||
    typeof parameters !== "object" ||
    Array.isArray(parameters)
  ) {
    return [];
  }

  const properties = (parameters as { properties?: unknown }).properties;
  if (
    !properties ||
    typeof properties !== "object" ||
    Array.isArray(properties)
  ) {
    return [];
  }

  return Object.keys(properties).sort();
}
