/**
 * Shell keywords and command wrappers to skip over when scanning for the
 * "real" command at the head of each shell segment. Keeps `then git clone`
 * and `command git status` recognizable as a `git` invocation while leaving
 * `echo git is cool` alone.
 */
const SHELL_PASSTHROUGH_TOKENS: ReadonlySet<string> = new Set([
  "if",
  "then",
  "else",
  "elif",
  "fi",
  "for",
  "while",
  "until",
  "do",
  "done",
  "case",
  "esac",
  "in",
  "function",
  "select",
  "coproc",
  "time",
  "!",
  "{",
  "}",
  "(",
  ")",
  "[",
  "]",
  "[[",
  "]]",
  "command",
  "exec",
  "builtin",
  "eval",
  "nohup",
  "setsid",
  "env",
  "nice",
]);

const ASSIGNMENT_RE = /^[A-Za-z_][A-Za-z0-9_]*=/;
const SEGMENT_SPLIT_RE = /\r?\n|;|&&|\|\||\|/;
const HEREDOC_RE = /<<-?\s*(?:"([^"]+)"|'([^']+)'|\\?([^\s;&|<>]+))/g;

function firstCommandToken(segment: string): string | null {
  const tokens = segment.trim().split(/\s+/);
  for (const raw of tokens) {
    if (!raw) continue;
    const token = raw.startsWith("\\") ? raw.slice(1) : raw;
    if (SHELL_PASSTHROUGH_TOKENS.has(token)) continue;
    if (ASSIGNMENT_RE.test(token)) continue;
    return token;
  }
  return null;
}

function stripHeredocBodies(command: string): string {
  const lines = command.split(/\r?\n/);
  const executableLines: string[] = [];
  const pendingDelimiters: string[] = [];

  for (const line of lines) {
    if (pendingDelimiters.length > 0) {
      if (line.trim() === pendingDelimiters[0]) {
        pendingDelimiters.shift();
      }
      continue;
    }

    executableLines.push(line);
    HEREDOC_RE.lastIndex = 0;

    let match = HEREDOC_RE.exec(line);
    while (match !== null) {
      const delimiter = match[1] ?? match[2] ?? match[3];
      if (delimiter) {
        pendingDelimiters.push(delimiter);
      }
      match = HEREDOC_RE.exec(line);
    }
  }

  return executableLines.join("\n");
}

/**
 * Best-effort scan for the first command token of each shell segment.
 * Splits naively on `;`, `&&`, `||`, `|`, and newlines after skipping common
 * heredoc bodies. It does not fully honor shell quoting. False positives are
 * bounded (the offending text usually would invoke the unavailable command);
 * false negatives only mean we fall through to the existing exit-code-127 path.
 */
export function detectUnavailableCommand(
  command: string,
): { name: string; hint: string } | null {
  for (const segment of stripHeredocBodies(command).split(SEGMENT_SPLIT_RE)) {
    const trimmed = segment.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const head = firstCommandToken(trimmed);
    if (!head) continue;
    const hint = UNAVAILABLE_COMMANDS.get(head);
    if (hint) return { name: head, hint };
  }
  return null;
}

export interface BashExecutionOptions {
  signal?: AbortSignal;
  timeoutMs?: number;
}

export interface BashExecutionResult {
  output: string;
  exitCode: number;
  timedOut: boolean;
  aborted: boolean;
  truncation?: TruncationResult;
}

function normalizeBashOutput(result: {
  stdout?: string;
  stderr?: string;
  exitCode: number;
}): string {
  let output = "";

  if (result.stdout) {
    output += result.stdout;
  }

  if (result.stderr) {
    if (output && !output.endsWith("\n")) output += "\n";
    output += `stderr: ${result.stderr}`;
  }

  if (result.exitCode !== 0) {
    if (output && !output.endsWith("\n")) output += "\n";
    output += `[exit code: ${result.exitCode}]`;
  }

  return output.trim() || "[no output]";
}

function formatTruncatedOutput(truncation: TruncationResult): string {
  let outputText = truncation.content;

  if (!truncation.truncated) {
    return outputText;
  }

  const startLine = truncation.totalLines - truncation.outputLines + 1;
  const endLine = truncation.totalLines;

  if (truncation.truncatedBy === "lines") {
    outputText += `\n\n[Showing last ${truncation.outputLines} of ${truncation.totalLines} lines. Output truncated.]`;
  } else {
    outputText += `\n\n[Showing lines ${startLine}-${endLine} of ${truncation.totalLines} (${formatSize(truncation.maxBytes)} limit). Output truncated.]`;
  }

  return outputText;
}

async function executeBashCommand(
  command: string,
  options: BashExecutionOptions = {},
): Promise<BashExecutionResult> {
  const bash = getBash();
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  let timedOut = false;
  let aborted = false;

  const execPromise = bash.exec(command);

  const timeoutPromise = new Promise<never>((_, reject) => {
    const timer = setTimeout(() => {
      timedOut = true;
      reject(
        new Error(
          `Command timed out after ${timeoutMs}ms. Consider filtering data or using smaller files.`,
        ),
      );
    }, timeoutMs);

    options.signal?.addEventListener(
      "abort",
      () => {
        aborted = true;
        clearTimeout(timer);
        reject(new Error("Command aborted"));
      },
      { once: true },
    );
  });

  try {
    const result = await Promise.race([execPromise, timeoutPromise]);
    const rawOutput = normalizeBashOutput(result);
    const truncation = truncateTail(rawOutput);

    return {
      output: formatTruncatedOutput(truncation),
      exitCode: result.exitCode,
      timedOut: false,
      aborted: false,
      truncation: truncation.truncated ? truncation : undefined,
    };
  } catch (error) {
    if (timedOut || aborted) {
      return {
        output:
          error instanceof Error ? error.message : "Bash execution interrupted",
        exitCode: -1,
        timedOut,
        aborted,
      };
    }

    throw error;
  }
}

export const bashTool = defineTool({
  name: "bash",
  category: "read",
  parallelSafe: false,
  maxRetries: 0,
  label: "Bash",
  description: `Execute bash commands in a sandboxed in-browser virtual environment (just-bash). Output is truncated to last ${DEFAULT_MAX_LINES} lines or ${DEFAULT_MAX_BYTES / 1024}KB (whichever is hit first). The filesystem is in-memory with user uploads in /home/user/uploads/. Useful for: file operations (ls, cat, grep, find), text processing (awk, sed, jq, sort, uniq), data analysis (wc, cut, paste), and general scripting. Custom commands available: csv-to-sheet, sheet-to-csv, xlsx-to-csv, pdf-to-text, pdf-to-images, docx-to-text, and js (QuickJS-NG JavaScript runtime, supports ESM). For programmatic data transforms (CSV/JSON/text), use the js command; do NOT probe for other language runtimes. For bulk generated file output, write directly to VFS with redirection (> to replace, >> to append), for example: js build.mjs > matches.json. Network access is disabled. No external language runtimes or networked tools are installed: git, curl/wget, ssh/scp/rsync, npm/pnpm/yarn/node/nodejs/deno/bun, python/python3/pip, ruby, perl, lua, php, docker/kubectl, apt/brew/yum, make/cmake/gcc/clang/cargo/go/java/mvn and similar binaries are all unavailable. These commands are blocked at preflight and will return a structured tool-error with a hint pointing at the correct alternative (e.g. mcp__github__* tools for repository operations, the bash \`js\` command for data transforms, or asking the user to upload files). The tool also reports any non-zero shell exit code as a tool-error (with the full output and exit code in the error payload) rather than silently succeeding.`,
  parameters: Type.Object({
    command: Type.String({
      description:
        "Bash command(s) to execute. Can be a single command or a script with multiple lines. Supports pipes (|), redirections (>, >>), command chaining (&&, ||, ;), variables, loops, conditionals, and functions.",
    }),
    timeoutMs: Type.Optional(
      Type.Number({
        description: "Optional timeout in milliseconds",
        minimum: 1,
        maximum: 120000,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    console.log(
      `[BashTool] Executing command: ${params.command.slice(0, 100)}...`,
    );

    const unavailable = detectUnavailableCommand(params.command);
    if (unavailable) {
      console.info(
        `[BashTool] Preflight blocked: ${unavailable.name} is not available in the sandbox`,
      );
      throw createAgentError(
        "TOOL_UNAVAILABLE",
        `bash: ${unavailable.name}: not available in the sandbox. ${unavailable.hint}`,
        {
          details: {
            unavailable: unavailable.name,
            hint: unavailable.hint,
            command: params.command,
          },
        },
      );
    }

    const result = await executeBashCommand(params.command, {
      signal,
      timeoutMs: params.timeoutMs,
    });
    notifyVfsMutation({ type: "shell" });

    console.log(
      `[BashTool] Completed, exitCode=${result.exitCode}, timedOut=${result.timedOut}, aborted=${result.aborted}`,
    );

    if (result.exitCode !== 0 && !result.aborted && !result.timedOut) {
      throw createAgentError(
        "TOOL_EXCEPTION",
        `bash command failed with exit code ${result.exitCode}`,
        {
          details: {
            exitCode: result.exitCode,
            output: result.output,
            truncation: result.truncation,
          },
        },
      );
    }

    return toolSuccess({
      output: result.output,
      exitCode: result.exitCode,
      timedOut: result.timedOut,
      aborted: result.aborted,
      truncation: result.truncation,
    });
  },
});
