import { preloadSheetIds } from "./sheet-id-map";

export type PowerBiSourceScope = "sheet" | "workbook";

export interface PowerBiSourceRange {
  columnCount: number;
  range: string;
  rowCount: number;
  sheetId: number;
  sheetName: string;
}

export interface GetPowerBiSourceRangesOptions {
  range?: string;
  scope: PowerBiSourceScope;
  sheetId?: number;
}

function rangeAddress(address: string): string {
  const separator = address.lastIndexOf("!");
  return separator >= 0 ? address.slice(separator + 1) : address;
}

export async function getPowerBiSourceRanges(
  options: GetPowerBiSourceRangesOptions,
): Promise<PowerBiSourceRange[]> {
  if (options.scope === "workbook" && options.range) {
    throw new Error("range can only be used with scope='sheet'");
  }
  if (options.scope === "workbook" && options.sheetId !== undefined) {
    throw new Error("sheetId can only be used with scope='sheet'");
  }

  return Excel.run(async (context) => {
    const worksheets = context.workbook.worksheets;
    worksheets.load("items");
    const activeSheet =
      options.scope === "sheet" && options.sheetId === undefined
        ? worksheets.getActiveWorksheet()
        : null;
    activeSheet?.load("id,name");
    await context.sync();

    for (const sheet of worksheets.items) sheet.load("id,name");
    await context.sync();

    const stableIds = await preloadSheetIds(worksheets.items);
    let selectedSheets: Excel.Worksheet[];
    if (options.scope === "workbook") {
      selectedSheets = worksheets.items;
    } else if (options.sheetId !== undefined) {
      const selected = worksheets.items.find(
        (sheet) => stableIds.get(sheet.id) === options.sheetId,
      );
      if (!selected) {
        throw new Error(`Worksheet with ID ${options.sheetId} not found`);
      }
      selectedSheets = [selected];
    } else {
      const selected = worksheets.items.find(
        (sheet) => sheet.id === activeSheet?.id,
      );
      if (!selected) throw new Error("Active worksheet not found");
      selectedSheets = [selected];
    }

    const ranges = selectedSheets.map((sheet) => {
      const range = options.range
        ? sheet.getRange(options.range)
        : sheet.getUsedRangeOrNullObject(true);
      range.load("address,rowCount,columnCount");
      return { range, sheet };
    });
    await context.sync();

    return ranges.flatMap(({ range, sheet }) => {
      if (range.isNullObject) return [];
      const sheetId = stableIds.get(sheet.id);
      if (sheetId === undefined) return [];
      return [
        {
          columnCount: range.columnCount,
          range: rangeAddress(range.address),
          rowCount: range.rowCount,
          sheetId,
          sheetName: sheet.name,
        },
      ];
    });
  });
}
