import { Type } from "@sinclair/typebox";
import { resolveStagedTextContent } from "./staged-content";
import { defineTool, toolError, toolSuccess } from "./types";

export const emailForwardTool = defineTool({
  name: "email_forward",
  category: "non_idempotent",
  parallelSafe: false,
  maxRetries: 0,
  label: "Forward Email",
  description:
    "Forward the currently open email in Outlook to specified recipients. " +
    "The forwarded message will include the original email as an attachment or inline, " +
    "and the draft will be displayed for the user to review and send.",
  parameters: Type.Object({
    to: Type.Union([
      Type.String({
        description:
          "Recipient email address(es), comma-separated for multiple",
      }),
      Type.Array(
        Type.String({
          description: "Recipient email address(es)",
        }),
      ),
    ]),
    cc: Type.Optional(
      Type.Union([
        Type.String({
          description:
            "CC recipient email address(es), comma-separated for multiple",
        }),
        Type.Array(
          Type.String({
            description: "CC recipient email address(es)",
          }),
        ),
      ]),
    ),
    bcc: Type.Optional(
      Type.Union([
        Type.String({
          description:
            "BCC recipient email address(es), comma-separated for multiple",
        }),
        Type.Array(
          Type.String({
            description: "BCC recipient email address(es)",
          }),
        ),
      ]),
    ),
    body: Type.Optional(
      Type.String({
        description:
          "Additional message to include with the forward (optional). Use HTML formatting with <p> tags and professional structure for best appearance.",
        default: "",
      }),
    ),
    bodyFromFile: Type.Optional(
      Type.String({
        description:
          "VFS path containing the optional forward message. Stage substantial content with write_file.",
      }),
    ),
    bodyFormat: Type.Optional(
      Type.String({
        enum: ["text", "html"],
        description:
          "Format of the additional body. Use 'html' for professional formatting. Default: 'html'",
        default: "html",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of why forwarding (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      let body = params.body ?? "";
      const bodyFormat = params.bodyFormat ?? "html";
      if (params.bodyFromFile?.trim()) {
        const stagedBody = await resolveStagedTextContent({
          content: body,
          fromFile: params.bodyFromFile,
          inlineFieldName: "body",
          fileFieldName: "bodyFromFile",
        });
        if ("error" in stagedBody) return toolError(stagedBody.error);
        body = stagedBody.content;
      }

      const item = Office.context.mailbox.item;

      if (!item) {
        return toolError("No email item is currently open");
      }

      if (item.itemType !== Office.MailboxEnums.ItemType.Message) {
        return toolError("Current item is not an email message");
      }

      const messageRead = item as Office.MessageRead;
      const originalItemId = messageRead.itemId?.trim();
      if (!originalItemId) {
        return toolError(
          "Cannot forward this message safely because Outlook did not provide an item ID for the original message.",
        );
      }

      // Normalize recipients
      const normalizeRecipients = (
        recipients: string | string[] | undefined,
      ): string[] => {
        if (!recipients) return [];
        if (typeof recipients === "string") {
          return recipients
            .split(",")
            .map((e) => e.trim())
            .filter(Boolean);
        }
        return recipients;
      };

      const toList = normalizeRecipients(params.to);
      const ccList = normalizeRecipients(params.cc);
      const bccList = normalizeRecipients(params.bcc);

      if (toList.length === 0 && ccList.length === 0 && bccList.length === 0) {
        return toolError("At least one recipient (to, cc, or bcc) is required");
      }

      // Build form parameters inline - types not exported from Office.js types
      // Note: displayNewMessageForm only supports: toRecipients, ccRecipients, bccRecipients, body, htmlBody, attachments
      // Subject is set by the user in the compose form that opens
      const formParams: {
        toRecipients: string[];
        ccRecipients?: string[];
        bccRecipients?: string[];
        body?: string;
        htmlBody?: string;
        subject?: string;
        attachments?: Array<{
          type: Office.MailboxEnums.AttachmentType | string;
          name: string;
          itemId: string;
        }>;
      } = {
        toRecipients: toList,
      };

      if (ccList.length > 0) {
        formParams.ccRecipients = ccList;
      }
      if (bccList.length > 0) {
        formParams.bccRecipients = bccList;
      }

      // Build body with forwarding header - use HTML for better compatibility
      const originalSubject = messageRead.subject || "No Subject";
      formParams.subject = originalSubject.startsWith("Fwd:")
        ? originalSubject
        : `Fwd: ${originalSubject}`;
      formParams.attachments = [
        {
          type: Office.MailboxEnums.AttachmentType.Item,
          name: originalSubject,
          itemId: originalItemId,
        },
      ];
      const forwardHeaderHtml = `<br><br><hr><p><b>Forwarded message</b><br>From: ${messageRead.from?.displayName || ""} &lt;${messageRead.from?.emailAddress || ""}&gt;<br>Subject: ${originalSubject}</p><hr><br>`;

      if (bodyFormat === "html") {
        formParams.htmlBody = `${body}${forwardHeaderHtml}`;
      } else {
        // Convert plain text to HTML
        const escapedBody = body
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/\n/g, "<br>");
        formParams.htmlBody = `<pre style="font-family: Arial, sans-serif; white-space: pre-wrap;">${escapedBody}</pre>${forwardHeaderHtml}`;
      }

      try {
        Office.context.mailbox.displayNewMessageForm(formParams);
      } catch (e) {
        return toolError(
          `Failed to open new message form: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      const successMessage = "Forward draft created and opened";

      return toolSuccess({
        success: true,
        message: successMessage,
        to: toList,
        cc: ccList,
        bcc: bccList,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error forwarding email";
      return toolError(message);
    }
  },
});
