import type { Static, TObject } from "@sinclair/typebox";
import { normalizeToolMetadata } from "../agent/tool-metadata";
import type {
  Tool,
  ToolCategory,
  ToolOrigin,
  ToolResult,
} from "../agent/types";
import { AIRGAP_CONFIG } from "../airgap-config";
import type { DirtyRange } from "../dirty-tracker";
import { trackEvent } from "../telemetry";
import { truncateToolResult } from "../token-manager";

export type { Tool, ToolResult };
export { truncateToolResult };

export interface DirtyTrackingConfig<T> {
  /** Derive dirty ranges from params and optionally the result (for success only) */
  getRanges: (params: T, result?: unknown) => DirtyRange[];
}

interface ToolConfig<T extends TObject> {
  name: string;
  label: string;
  description: string;
  parameters: T;
  /**
   * PR-1c: tool metadata is co-located with the tool's `execute` body.
   * `category` / `parallelSafe` / `origin` are still optional in this
   * type so omission falls back to the safe defaults applied by
   * {@link normalizeToolMetadata} (`read`, `false`, `local`). In dev
   * builds, omission emits a one-shot console warning so missing
   * declarations stay visible (plan step 0.3b). PR-7 deletes the
   * legacy hardcoded sets that used to back this policy.
   */
  category?: ToolCategory;
  destructive?: boolean;
  parallelSafe?: boolean;
  origin?: ToolOrigin;
  maxRetries?: number;
  execute: (
    toolCallId: string,
    params: Static<T>,
    signal?: AbortSignal,
  ) => Promise<ToolResult>;
  dirtyTracking?: DirtyTrackingConfig<Static<T>>;
}

/**
 * Per-process set of tool names that have already triggered a default-
 * usage warning, so we warn once per tool rather than once per import.
 */
const warnedDefaultTools = new Set<string>();

function isDevEnvironment(): boolean {
  try {
    const env = (import.meta as unknown as { env?: Record<string, unknown> })
      .env;
    if (env?.DEV === true) return true;
    if (env?.MODE === "development") return true;
  } catch {
    // import.meta.env is unavailable (e.g. node test runner without Vite).
  }
  if (typeof process !== "undefined") {
    const nodeEnv = process.env?.NODE_ENV;
    if (
      nodeEnv === "development" ||
      nodeEnv === "test" ||
      nodeEnv === undefined
    ) {
      return true;
    }
  }
  return false;
}

function warnIfMetadataMissing<T extends TObject>(config: ToolConfig<T>): void {
  if (!isDevEnvironment()) return;
  const missing: string[] = [];
  if (config.category === undefined) missing.push("category");
  if (config.parallelSafe === undefined) missing.push("parallelSafe");
  if (missing.length === 0) return;
  if (warnedDefaultTools.has(config.name)) return;
  warnedDefaultTools.add(config.name);
  try {
    trackEvent("tool_metadata_default_used", {
      toolName: config.name,
      missingFields: missing.join(","),
    });
  } catch {
    // Telemetry must never block tool registration.
  }
  console.warn(
    `[defineTool] Tool '${config.name}' is missing explicit metadata: ${missing.join(", ")}. Falling back to PR-1c defaults (category='read', parallelSafe=false, origin='local'). Declare these fields next to execute() in src/lib/tools/<tool>.ts. See docs/agent-refactor-implementation-plan.md PR-1c step 0.3b.`,
  );
}

export function defineTool<T extends TObject>(config: ToolConfig<T>): Tool {
  warnIfMetadataMissing(config);

  if (!config.dirtyTracking) {
    return normalizeToolMetadata(config as unknown as Tool);
  }

  const { dirtyTracking, execute, ...rest } = config;

  const wrappedExecute = async (
    toolCallId: string,
    params: Static<T>,
    signal?: AbortSignal,
  ): Promise<ToolResult> => {
    const result = await execute(toolCallId, params, signal);
    const first = result.content[0];
    if (!first || first.type !== "text") return result;
    const text = first.text;

    try {
      const parsed = JSON.parse(text);
      if (parsed.error) return result; // Don't track errors

      const dirtyRanges = dirtyTracking.getRanges(params, parsed);
      if (dirtyRanges.length > 0) {
        parsed._dirtyRanges = dirtyRanges;
        return {
          content: [{ type: "text", text: JSON.stringify(parsed) }],
          details: undefined,
        };
      }
    } catch {
      // Invalid JSON, return as-is
    }
    return result;
  };

  return normalizeToolMetadata({
    ...rest,
    execute: wrappedExecute,
  } as unknown as Tool);
}

export function toolSuccess(data: unknown): ToolResult {
  const result =
    typeof data === "object" && data !== null ? { ...data } : { result: data };
  let resultText = JSON.stringify(result);

  // Truncate large results for air-gapped environments with token limits
  resultText = truncateToolResult(
    resultText,
    AIRGAP_CONFIG.tokens.maxToolResultTokens,
  );

  return {
    content: [{ type: "text", text: resultText }],
    details: undefined,
  };
}

export function toolError(message: string): ToolResult {
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify({ success: false, error: message }),
      },
    ],
    details: undefined,
  };
}

export function toolText(text: string): ToolResult {
  return {
    content: [{ type: "text", text }],
    details: undefined,
  };
}
