/**
 * Agent-loop hook that detects truncated tool calls surfaced by the
 * stream decoder, salvages the recoverable bytes to the VFS, and
 * produces an ephemeral resume message instructing the model how to
 * continue without re-emitting the same oversize call.
 *
 * Two salvage paths are tried per dropped call, in order:
 *
 *   1. `write_file` salvage: parseable prefix of `content` is
 *      appended to the model's own target path; resume message tells
 *      the model to continue with `append: true`.
 *   2. Generic salvage: for any other tool whose largest top-level
 *      string field survived enough bytes to be useful, the prefix
 *      is parked in `/tmp/salvage/<tool>-<callId>.txt` and the
 *      resume message describes the surviving non-content args plus
 *      concrete recovery strategies (stage via `write_file`, split
 *      into smaller calls, or pivot to a bash/`js` redirection
 *      pipeline). This covers remote MCP adapters such as the GitHub
 *      `create_or_update_file` upload tool that the legacy salvage
 *      path could not help.
 *
 * Extracted from {@link `../agent.ts`} so the salvage policy (which
 * touches the VFS) can be unit-tested independently of the agent FSM.
 */

import type { DroppedTruncatedToolCall } from "../providers/provider";
import type { AgentMessage } from "../types";
import {
  type GenericSalvageReportEntry,
  type SalvageReportEntry,
  buildGenericSalvageResumeMessage,
  buildSalvageResumeMessage,
  extractTailAnchor,
  salvageTruncatedGenericContent,
  salvageTruncatedWriteFile,
} from "./salvage-truncated-write";

/**
 * Minimal VFS surface required to salvage truncated writes. Production
 * callers wire {@link `../../vfs`}`.appendFile`; tests inject a fake.
 */
export type AppendFileFn = (path: string, content: string) => Promise<void>;

/**
 * Optional VFS write primitive for generic salvages, where each
 * scratch file is freshly written per truncated call (the toolCallId
 * is unique, so collisions are not expected, but overwriting is the
 * safer semantic). When omitted the hook falls back to `appendFile`
 * which still works because each scratch path is unique.
 */
export type WriteFileFn = (path: string, content: string) => Promise<void>;

export interface PerformSalvageDeps {
  appendFile: AppendFileFn;
  /**
   * Optional VFS writer used for the generic-salvage scratch files.
   * Falls back to {@link PerformSalvageDeps.appendFile} when not
   * provided — both produce the same final bytes because the
   * scratch path is per-call-id unique.
   */
  writeFile?: WriteFileFn;
  /** Wall-clock sample used for the ephemeral message's `timestamp`. */
  nowMs: () => number;
  /** Optional sink for non-fatal salvage errors (parse miss, VFS error). */
  onError?: (err: unknown, ctx: { path?: string; toolCallId: string }) => void;
}

export interface SalvageOutcome {
  /** Per-call entries for which the `write_file` prefix was appended to VFS. */
  salvaged: SalvageReportEntry[];
  /**
   * Per-call entries for which the generic salvage parked the
   * largest string field of a non-`write_file` tool in
   * `/tmp/salvage/...`. Empty when no dropped call qualified.
   */
  genericSalvaged: GenericSalvageReportEntry[];
  /** Ephemeral user messages describing each salvage path (empty when nothing salvaged). */
  ephemeralMessages: AgentMessage[];
  /** Total characters appended across all salvaged entries (both paths). */
  totalCharsSalvaged: number;
}

/**
 * Attempt to salvage every entry in `dropped`. Returns the
 * aggregated outcome including up to two ephemeral resume messages
 * (one per salvage path that produced at least one entry) ready to
 * push into {@link `./state`}`.ephemeralMessages`. Entries that
 * cannot be salvaged (malformed prefix, no content-bearing field
 * large enough, VFS error) are silently skipped — the generic
 * `length_truncated_tool_args` nudge remains the fallback for those
 * cases.
 */
export async function performTruncatedWriteSalvage(
  dropped: ReadonlyArray<DroppedTruncatedToolCall>,
  deps: PerformSalvageDeps,
): Promise<SalvageOutcome> {
  const salvaged: SalvageReportEntry[] = [];
  const genericSalvaged: GenericSalvageReportEntry[] = [];
  let totalCharsSalvaged = 0;

  const writeFile: WriteFileFn = deps.writeFile ?? deps.appendFile;

  for (const call of dropped) {
    const writeRecovered = salvageTruncatedWriteFile(
      call.name,
      call.accumulatedArgs,
    );
    if (writeRecovered) {
      try {
        await deps.appendFile(
          writeRecovered.path,
          writeRecovered.partialContent,
        );
      } catch (err) {
        deps.onError?.(err, {
          path: writeRecovered.path,
          toolCallId: call.id,
        });
        continue;
      }

      salvaged.push({
        path: writeRecovered.path,
        bytesSalvaged: writeRecovered.partialContent.length,
        tailAnchor: extractTailAnchor(writeRecovered.partialContent),
      });
      totalCharsSalvaged += writeRecovered.partialContent.length;
      continue;
    }

    const genericRecovered = salvageTruncatedGenericContent(
      call.name,
      call.id,
      call.accumulatedArgs,
    );
    if (!genericRecovered) continue;

    try {
      await writeFile(
        genericRecovered.scratchPath,
        genericRecovered.partialContent,
      );
    } catch (err) {
      deps.onError?.(err, {
        path: genericRecovered.scratchPath,
        toolCallId: call.id,
      });
      continue;
    }

    genericSalvaged.push({
      toolName: genericRecovered.toolName,
      toolCallId: genericRecovered.toolCallId,
      scratchPath: genericRecovered.scratchPath,
      contentFieldName: genericRecovered.contentFieldName,
      bytesSalvaged: genericRecovered.partialContent.length,
      tailAnchor: extractTailAnchor(genericRecovered.partialContent),
      argsPreview: genericRecovered.argsPreview,
    });
    totalCharsSalvaged += genericRecovered.partialContent.length;
  }

  const ephemeralMessages: AgentMessage[] = [];
  const timestamp = deps.nowMs();
  if (salvaged.length > 0) {
    ephemeralMessages.push({
      role: "user",
      content: buildSalvageResumeMessage(salvaged),
      timestamp,
    });
  }
  if (genericSalvaged.length > 0) {
    ephemeralMessages.push({
      role: "user",
      content: buildGenericSalvageResumeMessage(genericSalvaged),
      timestamp,
    });
  }

  return { salvaged, genericSalvaged, ephemeralMessages, totalCharsSalvaged };
}
