const ENTRA_USERNAME_KEY = "officeai-entra-username";
const ENTRA_OID_KEY = "officeai-entra-oid";

function decodeBase64Url(value: string): string {
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - (normalized.length % 4)) % 4);
  return atob(padded);
}

function parseJwtPayload(token: string): Record<string, unknown> | null {
  const parts = token.split(".");
  if (parts.length < 2) return null;

  try {
    const payloadJson = decodeBase64Url(parts[1]);
    return JSON.parse(payloadJson) as Record<string, unknown>;
  } catch {
    return null;
  }
}

export function captureEntraIdentityFromAccessToken(token: string): void {
  if (typeof window === "undefined") return;
  const claims = parseJwtPayload(token);
  if (!claims) return;

  const username =
    (claims.preferred_username as string | undefined) ||
    (claims.upn as string | undefined) ||
    (claims.email as string | undefined) ||
    (claims.unique_name as string | undefined) ||
    "";

  const oid =
    (claims.oid as string | undefined) ||
    (claims.sub as string | undefined) ||
    "";

  try {
    if (username.trim()) {
      window.sessionStorage.setItem(ENTRA_USERNAME_KEY, username.trim());
    }
    if (oid.trim()) {
      window.sessionStorage.setItem(ENTRA_OID_KEY, oid.trim());
    }
  } catch {
    // Ignore storage errors in restricted browser contexts.
  }
}

export function getStoredEntraUsername(): string | null {
  if (typeof window === "undefined") return null;
  try {
    const value = window.sessionStorage.getItem(ENTRA_USERNAME_KEY);
    return value?.trim() ? value : null;
  } catch {
    return null;
  }
}
