/**
 * Token Management for Air-Gapped Environments
 *
 * For environments with limited context windows (<40k tokens):
 * - Estimates token count from text
 * - Truncates message history when approaching limit
 * - Summarizes older messages to preserve context
 * - Conservative estimates (1 token ≈ 4 chars for English text)
 */

import { estimateToolArgumentsLengthForHistory } from "./agent/tool-argument-history";
import type {
  AgentMessage,
  AssistantMessage,
  ToolResultMessage,
  UserMessage,
} from "./agent/types";

// Constants for air-gapped environment
export const MAX_CONTEXT_TOKENS = 32000; // Leave 8k buffer from 40k limit for safety
export const MAX_INPUT_TOKENS = 8000; // Max tokens for a single user message
export const TOKEN_OVERHEAD = 4; // Per-message overhead
export const CHARS_PER_TOKEN = 3.5; // Conservative estimate

export interface TokenCount {
  total: number;
  system: number;
  messages: number;
  tools: number;
}

export interface TruncationResult {
  messages: AgentMessage[];
  summaryMessage?: string;
  tokensRemaining: number;
  wasTruncated: boolean;
}

/**
 * Estimate token count from text or content length
 * Uses a conservative estimate for safety
 */
export function estimateTokens(text: string | number): number {
  const length = typeof text === "string" ? text.length : text;
  if (!length) return 0;
  // Conservative: assume 3.5 chars = 1 token (vs typical 4)
  return Math.ceil(length / CHARS_PER_TOKEN);
}

/**
 * Calculate tokens for a single message
 */
export function estimateMessageTokens(message: AgentMessage): number {
  let contentLength = 0;

  if (message.role === "user") {
    contentLength = (message as UserMessage).content?.length || 0;
  } else if (message.role === "assistant") {
    const assistantMsg = message as AssistantMessage;
    for (const block of assistantMsg.content) {
      if (block.type === "text") {
        contentLength += block.text.length;
      } else if (block.type === "thinking") {
        contentLength += block.thinking.length;
      } else if (block.type === "tool_call") {
        contentLength += estimateToolArgumentsLengthForHistory(
          block.name,
          block.arguments,
        );
      }
    }
  } else if (message.role === "tool") {
    // Tool results often have verbose JSON, count carefully
    contentLength = JSON.stringify(message.content).length;
  }

  return estimateTokens(contentLength) + TOKEN_OVERHEAD;
}

/**
 * Calculate total token count for all messages
 */
export function calculateTotalTokens(
  messages: AgentMessage[],
  systemPrompt: string,
  toolsJson: string,
): TokenCount {
  const system = estimateTokens(systemPrompt);
  const tools = estimateTokens(toolsJson);

  let messagesTokens = 0;
  for (const msg of messages) {
    messagesTokens += estimateMessageTokens(msg);
  }

  return {
    total: system + messagesTokens + tools,
    system,
    messages: messagesTokens,
    tools,
  };
}

/**
 * Compress message content for token reduction
 */
function compressContent(text: string): string {
  return (
    text
      // Remove extra whitespace
      .replace(/\n\s*\n/g, "\n")
      // Truncate long numeric sequences
      .replace(/(\d{10,})/g, (m) => `${m.slice(0, 5)}...${m.slice(-5)}`)
      // Truncate repeated characters
      .replace(/(.)(\1{10,})/g, "$1...")
      // Limit line length in tables
      .split("\n")
      .map((line) => (line.length > 500 ? `${line.slice(0, 500)}...` : line))
      .join("\n")
  );
}

/**
 * Summarize older messages to reduce token count
 * Keeps the most recent messages intact, summarizes older ones
 */
export function summarizeMessageHistory(
  messages: AgentMessage[],
  targetTokens: number,
  systemPrompt: string,
  toolsJson: string,
): TruncationResult {
  if (messages.length === 0) {
    return {
      messages: [],
      tokensRemaining: targetTokens,
      wasTruncated: false,
    };
  }

  // Always keep the latest conversational tail, and preserve the most recent
  // tool-call/result chain so retries can continue without re-fetching.
  const PRESERVE_RECENT = 6;
  const basePreserveStart = Math.max(0, messages.length - PRESERVE_RECENT);
  const preserveStart = findPreserveStartIndex(messages, basePreserveStart);
  const recentMessages = messages.slice(preserveStart);
  const olderMessages = messages.slice(0, preserveStart);

  // Calculate current tokens
  const recentTokens = recentMessages.reduce(
    (sum, m) => sum + estimateMessageTokens(m),
    0,
  );
  const systemAndTools =
    estimateTokens(systemPrompt) + estimateTokens(toolsJson);
  const availableForOlder = targetTokens - recentTokens - systemAndTools;

  if (olderMessages.length === 0 || availableForOlder <= 0) {
    return {
      messages: recentMessages,
      tokensRemaining: targetTokens - recentTokens - systemAndTools,
      wasTruncated: olderMessages.length > 0,
    };
  }

  // Build a summary from older messages
  const summary: string[] = [];
  let currentTokenCount = 0;

  for (const msg of olderMessages) {
    if (msg.role === "user") {
      const content = (msg as UserMessage).content;
      const compressed = compressContent(content);
      const tokens = estimateTokens(compressed);

      if (currentTokenCount + tokens < availableForOlder * 0.7) {
        summary.push(`User asked: ${compressed.slice(0, 200)}`);
        currentTokenCount += tokens;
      }
    } else if (msg.role === "assistant") {
      const assistantMsg = msg as AssistantMessage;
      const hasToolCalls = assistantMsg.content.some(
        (b) => b.type === "tool_call",
      );

      if (hasToolCalls) {
        summary.push("Assistant invoked Office tools");
        currentTokenCount += 5;
      }
      // Skip summarizing text responses - they're already in recent context
    }
    if (msg.role === "tool") {
      const toolMsg = msg as ToolResultMessage;
      const toolOutput = toolMsg.content
        .filter((c): c is { type: "text"; text: string } => c.type === "text")
        .map((c) => c.text)
        .join("\n");

      if (toolOutput) {
        const compressed = compressContent(toolOutput).slice(0, 220);
        const tokens = estimateTokens(compressed);
        if (currentTokenCount + tokens < availableForOlder * 0.7) {
          summary.push(`Tool result snapshot: ${compressed}`);
          currentTokenCount += tokens;
        }
      }
    }
  }

  if (summary.length === 0) {
    return {
      messages: recentMessages,
      tokensRemaining: availableForOlder,
      wasTruncated: true,
    };
  }

  const summaryText = `Previous conversation summary (${olderMessages.length} earlier messages): ${summary.join("; ")}. Recent context follows:`;

  // Create a synthetic user message for the summary
  const summaryMessage: UserMessage = {
    role: "user",
    content: `[SYSTEM: ${summaryText}]`,
    timestamp: olderMessages[0]?.timestamp || Date.now(),
  };

  return {
    messages: [summaryMessage, ...recentMessages],
    summaryMessage: summaryText,
    tokensRemaining: availableForOlder - estimateTokens(summaryText),
    wasTruncated: true,
  };
}

function findPreserveStartIndex(
  messages: AgentMessage[],
  basePreserveStart: number,
): number {
  let preserveStart = basePreserveStart;

  // Moving the boundary backward can expose additional tool results, so
  // repeat until every retained result has its announcing assistant call.
  // Do not rewind to the originating user message: in a long single run that
  // would retain every completed tool exchange and make compaction a no-op.
  while (true) {
    let expandedStart = preserveStart;
    for (let i = preserveStart; i < messages.length; i++) {
      const message = messages[i];
      if (message?.role !== "tool") continue;

      const toolCallId = (message as ToolResultMessage).toolCallId;
      for (let j = i - 1; j >= 0; j--) {
        const candidate = messages[j];
        if (candidate?.role !== "assistant") continue;

        const hasMatchingToolCall = (
          candidate as AssistantMessage
        ).content.some(
          (block) => block.type === "tool_call" && block.id === toolCallId,
        );
        if (hasMatchingToolCall) {
          expandedStart = Math.min(expandedStart, j);
          break;
        }
      }
    }

    if (expandedStart === preserveStart) break;
    preserveStart = expandedStart;
  }

  return preserveStart;
}

/**
 * Truncate tool results that are too long
 */
export function truncateToolResult(result: string, maxTokens = 2000): string {
  const maxChars = Math.floor(maxTokens * CHARS_PER_TOKEN);

  if (result.length <= maxChars) {
    return result;
  }

  // Keep beginning and end, truncate middle
  const keepEach = Math.floor(maxChars / 2) - 100;
  return `${result.slice(0, keepEach)}\n\n[... ${result.length - 2 * keepEach} characters truncated for token limit ...]\n\n${result.slice(-keepEach)}`;
}

/**
 * Prepare messages for API call with token limit enforcement
 */
export function prepareMessagesForApi(
  messages: AgentMessage[],
  systemPrompt: string,
  toolsJson: string,
  maxTokens: number = MAX_CONTEXT_TOKENS,
): {
  preparedMessages: AgentMessage[];
  tokenCount: TokenCount;
  wasTruncated: boolean;
} {
  // First, check if we need truncation
  const initialCount = calculateTotalTokens(messages, systemPrompt, toolsJson);

  if (initialCount.total <= maxTokens) {
    return {
      preparedMessages: messages,
      tokenCount: initialCount,
      wasTruncated: false,
    };
  }

  // Need to truncate - summarize older messages
  const truncated = summarizeMessageHistory(
    messages,
    maxTokens,
    systemPrompt,
    toolsJson,
  );

  // Recalculate with truncated messages
  const finalCount = calculateTotalTokens(
    truncated.messages,
    systemPrompt,
    toolsJson,
  );

  return {
    preparedMessages: truncated.messages,
    tokenCount: finalCount,
    wasTruncated: truncated.wasTruncated,
  };
}

export type WarningLevel = "ok" | "warning" | "critical";

/**
 * Get warning level based on token usage ratio
 */
export function getWarningLevel(
  used: number,
  max: number = MAX_CONTEXT_TOKENS,
): WarningLevel {
  const ratio = used / max;
  if (ratio > 0.9) return "critical";
  if (ratio > 0.75) return "warning";
  return "ok";
}

/**
 * Get user-friendly warning about token usage
 */
export function getTokenWarning(
  used: number,
  max: number = MAX_CONTEXT_TOKENS,
): string | null {
  const ratio = used / max;

  if (ratio > 0.95) {
    return `Context window nearly full (${Math.round(ratio * 100)}%). Older messages will be summarized.`;
  }
  if (ratio > 0.8) {
    return `Context window ${Math.round(ratio * 100)}% full. Consider starting a new session soon.`;
  }
  return null;
}
