/**
 * Tool metadata defaults + normalization.
 *
 * PR-1b: `Tool.category`, `Tool.parallelSafe`, and `Tool.origin` are
 * optional fields on the {@link Tool} interface. Safe defaults are
 * applied at registration time by {@link normalizeToolMetadata} so the
 * orchestrator (PR-2 dispatcher) can read normalized values without
 * scattered fallback logic.
 *
 * See docs/agent-refactor-blueprint.md §4 and
 * docs/agent-refactor-implementation-plan.md PR-1b / PR-1c.
 */

import type { Tool, ToolCategory, ToolOrigin } from "./types";

/** Default category when a tool omits an explicit declaration. */
export const DEFAULT_TOOL_CATEGORY: ToolCategory = "read";

/** Default parallel-safety when a tool omits an explicit declaration. */
export const DEFAULT_TOOL_PARALLEL_SAFE = false;

/** Default origin when a tool omits an explicit declaration. */
export const DEFAULT_TOOL_ORIGIN: ToolOrigin = "local";

/** Categories whose successful execution proves that a mutation ran. */
export function isConcreteExecutionCategory(category: ToolCategory): boolean {
  return (
    category === "deliverable" ||
    category === "effectful" ||
    category === "non_idempotent"
  );
}

/**
 * Apply safe defaults to optional metadata fields on a Tool record.
 * Returns the same object reference when all fields are already set
 * (no allocation in the hot path) and a shallow-cloned object with
 * defaults filled in otherwise.
 *
 * Idempotent: calling twice yields the same result.
 */
export function normalizeToolMetadata(tool: Tool): Tool {
  const hasAllDefaults =
    tool.category !== undefined &&
    tool.parallelSafe !== undefined &&
    tool.origin !== undefined;
  if (hasAllDefaults) return tool;

  return {
    ...tool,
    category: tool.category ?? DEFAULT_TOOL_CATEGORY,
    parallelSafe: tool.parallelSafe ?? DEFAULT_TOOL_PARALLEL_SAFE,
    origin: tool.origin ?? DEFAULT_TOOL_ORIGIN,
  };
}
