/**
 * Stream-to-VFS — shared types (Phase B).
 *
 * Phase-local types used by `WriteFileStreamingSession` (Phase B) and
 * `StreamingToolController` (Phase C). Kept independent of the
 * provider layer so Phase B can ship before any provider/agent
 * changes. Phase D will adapt these into the provider's
 * `StreamedToolResult` shape declared in
 * `src/lib/agent/providers/provider.ts`.
 */

/**
 * Number of decoded `content` characters buffered before the session
 * flushes to its temp file. Picked to amortize per-write overhead
 * (each flush is one in-memory VFS `appendFile`) without holding so
 * much data that a mid-stream abort loses substantial bytes.
 */
export const STREAM_WRITE_FLUSH_CHARS = 8192;

/**
 * Number of trailing decoded characters captured as the tail anchor
 * the model can use to resume an `append: true` continuation without
 * duplicating content. The anchor is computed over decoded content
 * (post-JSON-decode), not raw stream bytes.
 */
export const STREAM_TAIL_ANCHOR_CHARS = 64;

/**
 * Root directory under which per-run temp files live. Sessions place
 * partial files at
 * `${STREAM_TEMP_ROOT}/<runId>/<turnIndex>-<streamIndex>.partial`.
 */
export const STREAM_TEMP_ROOT = "/tmp/officeai-streamed-writes";

export interface WriteFileStreamingSessionInit {
  runId: string;
  turnIndex: number;
  streamIndex: number;
  toolCallId?: string;
  /** Override the default flush threshold (testing only). */
  flushChars?: number;
  /** Override the default tail anchor window (testing only). */
  tailAnchorChars?: number;
}

/**
 * Error codes emitted by a streaming `write_file` session on failure.
 * The dispatcher surfaces these to the model in the precomputed tool
 * result so it can recover (retry with a different path, fall back
 * to non-streamed `write_file`, etc.).
 */
export type StreamingWriteErrorCode =
  | "STREAM_MISSING_PATH"
  | "STREAM_MISSING_CONTENT"
  | "STREAM_INVALID_ARGS"
  | "STREAM_SINK_ERROR"
  | "STREAM_COMMIT_FAILED"
  | "STREAM_TARGET_CONFLICT";

/**
 * Final outcome of a streaming `write_file` call. Returned by
 * `WriteFileStreamingSession.finalize(...)` (Phase B) and surfaced
 * by the controller as a `StreamedToolResult` (Phase C/D).
 */
export interface StreamingWriteResult {
  toolCallId?: string;
  streamIndex: number;
  name: "write_file";
  /**
   * Compact "D3-shape" arguments suitable for both the recorded
   * tool-call summary and the next outbound provider history turn.
   * `content` is a small placeholder string; the real bytes are on
   * disk at `path`.
   */
  arguments: Record<string, unknown>;
  /**
   * Tool-result text the dispatcher returns to the model. Mirrors
   * the non-streamed `write_file` result text so the model sees a
   * familiar shape and can continue with `append: true` on
   * truncation.
   */
  resultText: string;
  isError: boolean;
  errorCode?: StreamingWriteErrorCode;
  bytesWritten: number;
  truncated: boolean;
  /** Last N decoded characters of the committed content, if any. */
  tailAnchor?: string;
}
