/**
 * Rate Limiter - Token Bucket Algorithm with Adaptive Limiting
 *
 * Implements a token bucket rate limiter with adaptive throttling based on
 * 429 responses. Automatically reduces rate limits when hitting API limits
 * and gradually recovers when requests succeed.
 */

import type { RateLimitConfig, RateLimitResult, RateLimitState } from "./types";

const DEFAULT_CONFIG: Required<RateLimitConfig> = {
  maxRequests: 60,
  windowMs: 60000,
  burstCapacity: 60,
  adaptiveLimiting: true,
  adaptiveReductionFactor: 0.7,
};

export class RateLimiter {
  private config: Required<RateLimitConfig>;
  private state: RateLimitState;
  private eventHandlers: Array<
    (event: { type: string; data?: unknown }) => void
  > = [];

  constructor(config: Partial<RateLimitConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };

    const maxTokens = this.config.burstCapacity ?? this.config.maxRequests;
    this.state = {
      tokens: maxTokens,
      maxTokens,
      lastRefill: Date.now(),
      currentWindowMs: this.config.windowMs,
      rateLimitHits: 0,
      isThrottled: false,
    };

    // Start periodic token refill
    this.startRefillLoop();
  }

  /**
   * Subscribe to rate limiter events
   */
  subscribe(
    handler: (event: { type: string; data?: unknown }) => void,
  ): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emit(event: { type: string; data?: unknown }): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error("[RateLimiter] Event handler error:", err);
      }
    }
  }

  /**
   * Check if a request is allowed without consuming a token
   */
  peek(): RateLimitResult {
    this.refillTokens();

    if (this.state.tokens >= 1) {
      return {
        allowed: true,
        remaining: Math.floor(this.state.tokens),
        retryAfterMs: 0,
        consumed: false,
      };
    }

    const waitMs = this.calculateWaitTime();
    return {
      allowed: false,
      remaining: 0,
      retryAfterMs: waitMs,
      consumed: false,
    };
  }

  /**
   * Try to consume a token for a request
   */
  tryAcquire(): RateLimitResult {
    this.refillTokens();

    if (this.state.tokens >= 1) {
      this.state.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(this.state.tokens),
        retryAfterMs: 0,
        consumed: true,
      };
    }

    const waitMs = this.calculateWaitTime();
    return {
      allowed: false,
      remaining: 0,
      retryAfterMs: waitMs,
      consumed: false,
    };
  }

  /**
   * Block until a token is available (with timeout)
   */
  async acquire(timeoutMs = 30000): Promise<RateLimitResult> {
    const startTime = Date.now();

    while (Date.now() - startTime < timeoutMs) {
      const result = this.tryAcquire();
      if (result.allowed) {
        return result;
      }

      // Wait before retrying
      const waitTime = Math.min(result.retryAfterMs, 1000);
      await sleep(waitTime);
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfterMs: 0,
      consumed: false,
    };
  }

  /**
   * Report a rate limit hit (429 response) - triggers adaptive throttling
   */
  reportRateLimitHit(retryAfterMs?: number): void {
    this.state.rateLimitHits++;

    if (this.config.adaptiveLimiting) {
      this.adaptRateLimit();
    }

    this.emit({
      type: "rate_limit_hit",
      data: {
        retryAfterMs,
        rateLimitHits: this.state.rateLimitHits,
        currentMaxTokens: this.state.maxTokens,
      },
    });

    // If server specified retry-after, respect it
    if (retryAfterMs && retryAfterMs > 0) {
      this.state.isThrottled = true;
      setTimeout(() => {
        this.state.isThrottled = false;
        this.emit({ type: "rate_limit_recovered" });
      }, retryAfterMs);
    }
  }

  /**
   * Report a successful request - helps recover from throttling
   */
  reportSuccess(): void {
    if (this.state.rateLimitHits > 0) {
      this.state.rateLimitHits = Math.max(0, this.state.rateLimitHits - 1);
    }

    // Gradually restore rate limit if we've been below capacity
    const targetTokens = this.config.burstCapacity ?? this.config.maxRequests;
    if (this.state.maxTokens < targetTokens) {
      const restoreAmount = 0.1; // Restore 10% of burst per success
      const newMaxTokens = Math.min(
        targetTokens,
        this.state.maxTokens + targetTokens * restoreAmount,
      );

      if (newMaxTokens > this.state.maxTokens) {
        this.state.maxTokens = newMaxTokens;
        this.emit({
          type: "rate_limit_recovered",
          data: { newMaxTokens },
        });
      }
    }

    // Clear isThrottled when fully recovered
    if (
      this.state.isThrottled &&
      this.state.maxTokens >= targetTokens &&
      this.state.rateLimitHits === 0
    ) {
      console.log("[RateLimiter] Fully recovered from throttling");
      this.state.isThrottled = false;
      this.emit({ type: "rate_limit_recovered" });
    }
  }

  /**
   * Get current rate limit state
   */
  getState(): RateLimitState {
    this.refillTokens();
    return { ...this.state };
  }

  /**
   * Update rate limit configuration at runtime
   */
  updateConfig(config: Partial<RateLimitConfig>): void {
    this.config = { ...this.config, ...config };

    // Adjust max tokens if burst capacity changed
    if (
      config.burstCapacity !== undefined ||
      config.maxRequests !== undefined
    ) {
      const newMaxTokens = this.config.burstCapacity ?? this.config.maxRequests;
      this.state.maxTokens = newMaxTokens;
      this.state.tokens = Math.min(this.state.tokens, newMaxTokens);
    }

    // Adjust window if changed
    if (config.windowMs !== undefined) {
      this.state.currentWindowMs = config.windowMs;
    }
  }

  /**
   * Reset rate limiter to initial state
   */
  reset(): void {
    const maxTokens = this.config.burstCapacity ?? this.config.maxRequests;
    this.state = {
      tokens: maxTokens,
      maxTokens,
      lastRefill: Date.now(),
      currentWindowMs: this.config.windowMs,
      rateLimitHits: 0,
      isThrottled: false,
    };
  }

  /**
   * Dispose of the rate limiter
   */
  dispose(): void {
    this.eventHandlers = [];
  }

  private refillTokens(): void {
    const now = Date.now();
    const elapsedMs = now - this.state.lastRefill;

    if (elapsedMs <= 0) return;

    // Calculate tokens to add based on elapsed time
    const tokensPerMs = this.config.maxRequests / this.state.currentWindowMs;
    const tokensToAdd = elapsedMs * tokensPerMs;

    this.state.tokens = Math.min(
      this.state.maxTokens,
      this.state.tokens + tokensToAdd,
    );
    this.state.lastRefill = now;
  }

  private calculateWaitTime(): number {
    const tokensPerMs = this.config.maxRequests / this.state.currentWindowMs;
    const tokensNeeded = 1 - this.state.tokens;
    return Math.ceil(tokensNeeded / tokensPerMs);
  }

  private adaptRateLimit(): void {
    if (!this.config.adaptiveLimiting) return;

    // Reduce max tokens when hitting rate limits
    const newMaxTokens = Math.max(
      1, // Always allow at least 1 request
      Math.floor(this.state.maxTokens * this.config.adaptiveReductionFactor),
    );

    if (newMaxTokens < this.state.maxTokens) {
      console.warn(
        `[RateLimiter] Adaptive throttling: reducing request rate limit from ${this.state.maxTokens} to ${newMaxTokens} req/min`,
      );
      this.state.maxTokens = newMaxTokens;
      this.state.tokens = Math.min(this.state.tokens, newMaxTokens);
      this.state.isThrottled = true;

      this.emit({
        type: "rate_limit_throttled",
        data: {
          newMaxTokens,
          reductionFactor: this.config.adaptiveReductionFactor,
        },
      });
    }
  }

  private startRefillLoop(): void {
    // Periodic refill check every 100ms to ensure tokens are available
    const refillInterval = setInterval(() => {
      this.refillTokens();
    }, 100);

    // Clean up interval when page unloads
    if (typeof window !== "undefined") {
      window.addEventListener("beforeunload", () => {
        clearInterval(refillInterval);
      });
    }
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Create a rate limiter with provider-specific defaults
 */
export function createRateLimiter(
  provider: string,
  customConfig?: Partial<RateLimitConfig>,
): RateLimiter {
  const defaults: Record<string, Partial<RateLimitConfig>> = {
    openai: {
      maxRequests: 50,
      windowMs: 60000,
      burstCapacity: 50,
    },
    azure: {
      maxRequests: 120,
      windowMs: 60000,
      burstCapacity: 120,
    },
    anthropic: {
      maxRequests: 40,
      windowMs: 60000,
      burstCapacity: 40,
    },
    google: {
      maxRequests: 60,
      windowMs: 60000,
      burstCapacity: 60,
    },
    groq: {
      maxRequests: 30,
      windowMs: 60000,
      burstCapacity: 30,
    },
    // Generic defaults for unknown providers
    default: {
      maxRequests: 60,
      windowMs: 60000,
      burstCapacity: 60,
    },
  };

  const providerConfig = defaults[provider] ?? defaults.default;
  return new RateLimiter({ ...providerConfig, ...customConfig });
}
