/**
 * update_todos — structured TODO state tool (PR-B).
 *
 * See:
 *   - docs/structured-todos-blueprint.md §5
 *   - docs/structured-todos-implementation-plan.md PR-B
 *
 * Calls to this tool are handled INLINE by the FSM reducer
 * (`apply(execute_tools)` in `src/lib/agent/loop/state.ts`): the reducer
 * validates `arguments`, mutates live `AgentRunState.todos`, and emits
 * a synthetic tool result so the model
 * sees a normal `toolSuccess` reply. The `execute()` defined here is a
 * fallback no-op kept for shape parity; the dispatcher never invokes it
 * because the reducer claims the call before dispatch runs.
 *
 * Category: "bookkeeping" — DOES NOT satisfy the deliverable gate. See
 * `loop/decide.ts` rules 8-10: `update_todos` alone never advances
 * `executedToolsThisStep.filter(t => t.category === "deliverable")`, so
 * the model must still call a deliverable-category tool to complete the
 * user's request.
 */

import { UpdateTodosRequestSchema } from "../agent/planner";
import { defineTool, toolSuccess } from "./types";

export const updateTodosTool = defineTool({
  name: "update_todos",
  category: "bookkeeping",
  parallelSafe: false,
  label: "Update TODOs",
  description:
    "Replace the live TODO checklist with the full current list. Use this " +
    "throughout the run to establish the plan, mark work in_progress, mark " +
    "completed items with concise evidence, and add/cancel quality-check " +
    "items as needed. Always preserve stable non-empty `id` values for " +
    "existing items and include the full list; omitted items are dropped. " +
    "Each item MUST include concise `content`, present-continuous " +
    "`activeForm`, and `status`. Updating todos is bookkeeping; it does " +
    "NOT satisfy the deliverable requirement. You must still call a " +
    "deliverable tool (e.g. set_cell_range, insert_content, email_create) " +
    "to complete the user's request.",
  parameters: UpdateTodosRequestSchema,
  execute: async (_toolCallId, params) =>
    toolSuccess({
      ok: true,
      message: `Updated ${params.todos.length} todo(s)`,
      count: params.todos.length,
    }),
});
