/* global Word */

export interface WordHeading {
  index: number;
  level: string;
  text: string;
}

export interface WordDocumentMetadata {
  success: boolean;
  paragraphCount: number;
  characterCount: number;
  listItemCount: number;
  headings: WordHeading[];
  hasSelection: boolean;
  selectionPreview?: string;
  bodyPreview: string;
}

const MAX_HEADINGS = 40;
const HEADING_TEXT_MAX = 120;
const SELECTION_PREVIEW_MAX = 240;
const BODY_PREVIEW_MAX = 800;
const HEADING_STYLE_RE = /(heading|title|subtitle)/i;

function truncate(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export async function getDocumentMetadata(): Promise<WordDocumentMetadata> {
  return Word.run(async (context) => {
    const body = context.document.body;
    body.load("text");

    const paragraphs = body.paragraphs;
    paragraphs.load(
      "items/text,items/styleBuiltIn,items/style,items/isListItem",
    );

    const selection = context.document.getSelection();
    selection.load("text");

    await context.sync();

    const selectionText = (selection.text ?? "").trim();
    const bodyText = body.text ?? "";

    const headings: WordHeading[] = [];
    let listItemCount = 0;

    paragraphs.items.forEach((paragraph, index) => {
      if (paragraph.isListItem) {
        listItemCount += 1;
      }

      const text = (paragraph.text ?? "").trim();
      if (!text || headings.length >= MAX_HEADINGS) {
        return;
      }

      const styleName =
        `${paragraph.styleBuiltIn ?? ""} ${paragraph.style ?? ""}`.trim();
      if (HEADING_STYLE_RE.test(styleName)) {
        headings.push({
          index,
          level: (
            paragraph.styleBuiltIn ||
            paragraph.style ||
            "Heading"
          ).toString(),
          text: truncate(text, HEADING_TEXT_MAX),
        });
      }
    });

    return {
      success: true,
      paragraphCount: paragraphs.items.length,
      characterCount: bodyText.length,
      listItemCount,
      headings,
      hasSelection: selectionText.length > 0,
      selectionPreview: selectionText
        ? truncate(selectionText, SELECTION_PREVIEW_MAX)
        : undefined,
      bodyPreview: truncate(bodyText, BODY_PREVIEW_MAX),
    };
  });
}
