export const DEFAULT_TIMEOUT_MS = 5_000;
export const MIN_TIMEOUT_MS = 50;
export const MAX_TIMEOUT_MS = 30_000;

export const DEFAULT_MEMORY_LIMIT_BYTES = 64 * 1024 * 1024;
export const MIN_MEMORY_LIMIT_BYTES = 1 * 1024 * 1024;
export const MAX_MEMORY_LIMIT_BYTES = 256 * 1024 * 1024;

export const DEFAULT_MAX_STACK_SIZE_BYTES = 1 * 1024 * 1024;
export const DEFAULT_PENDING_JOB_BATCH_SIZE = 1_000;

export const DEFAULT_MAX_PRELOAD_FILE_BYTES = 5 * 1024 * 1024;
export const DEFAULT_MAX_PRELOAD_TOTAL_BYTES = 10 * 1024 * 1024;

export interface NormalizedJsLimits {
  timeoutMs: number;
  memoryLimitBytes: number;
  maxStackSize: number;
  maxPreloadFileBytes: number;
  maxPreloadTotalBytes: number;
}

function clamp(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, Math.floor(value)));
}

export function normalizeLimits(options: {
  timeoutMs?: number;
  memoryLimitBytes?: number;
  maxStackSize?: number;
  maxPreloadFileBytes?: number;
  maxPreloadTotalBytes?: number;
}): NormalizedJsLimits {
  return {
    timeoutMs: clamp(
      options.timeoutMs ?? DEFAULT_TIMEOUT_MS,
      MIN_TIMEOUT_MS,
      MAX_TIMEOUT_MS,
    ),
    memoryLimitBytes: clamp(
      options.memoryLimitBytes ?? DEFAULT_MEMORY_LIMIT_BYTES,
      MIN_MEMORY_LIMIT_BYTES,
      MAX_MEMORY_LIMIT_BYTES,
    ),
    maxStackSize: Math.max(
      64 * 1024,
      Math.floor(options.maxStackSize ?? DEFAULT_MAX_STACK_SIZE_BYTES),
    ),
    maxPreloadFileBytes: Math.max(
      1,
      Math.floor(options.maxPreloadFileBytes ?? DEFAULT_MAX_PRELOAD_FILE_BYTES),
    ),
    maxPreloadTotalBytes: Math.max(
      1,
      Math.floor(
        options.maxPreloadTotalBytes ?? DEFAULT_MAX_PRELOAD_TOTAL_BYTES,
      ),
    ),
  };
}

export interface InterruptState {
  readonly deadlineMs: number;
  timedOut: boolean;
  aborted: boolean;
}

export function createInterruptState(timeoutMs: number): InterruptState {
  return {
    deadlineMs: Date.now() + timeoutMs,
    timedOut: false,
    aborted: false,
  };
}

export function shouldInterrupt(
  state: InterruptState,
  signal?: AbortSignal,
): boolean {
  if (signal?.aborted) {
    state.aborted = true;
    return true;
  }
  if (Date.now() > state.deadlineMs) {
    state.timedOut = true;
    return true;
  }
  return false;
}

export function looksLikeMemoryExceeded(error?: {
  name?: string;
  message?: string;
}): boolean {
  if (!error) return false;
  const text = `${error.name ?? ""} ${error.message ?? ""}`.toLowerCase();
  return (
    text.includes("out of memory") ||
    text.includes("memory limit") ||
    text.includes("allocation failed")
  );
}
