/**
 * Read-concurrency single-owner invariant.
 *
 * See docs/agent-concurrency-map.md for the contract this file enforces.
 *
 * Intent: as the refactor introduces an orchestrator-level dispatcher
 * (PR-2 / PR-5), prevent the dispatcher and `WorkflowManager` batching
 * from racing on the same call path. The dispatcher MUST call
 * `assertSingleReadConcurrencyOwner({...})` immediately before delegating
 * to `WorkflowManager.executeTool(...)` whenever it claims ownership.
 */

export type ReadConcurrencyOwner =
  | "WorkflowManagerBatching"
  | "OrchestratorDispatcher";

/**
 * Sole owner as of PR-5. ToolDispatcher decides whether a model-emitted
 * batch runs serially or concurrently, and bypasses WorkflowManager's
 * legacy read batching on that path.
 */
export const CURRENT_READ_CONCURRENCY_OWNER: ReadConcurrencyOwner =
  "OrchestratorDispatcher";

export interface ReadConcurrencyOwnershipClaim {
  /** Owner the caller is claiming for this dispatch. */
  owner: ReadConcurrencyOwner;
  /**
   * Value of `isReadOperation` the caller will pass to
   * `WorkflowManager.executeTool(...)` for this dispatch.
   */
  isReadOperationFlag: boolean;
}

interface ToolMetadataProbe {
  name?: unknown;
  parallelSafe?: unknown;
}

export class ReadConcurrencyOwnershipError extends Error {
  readonly code = "TOOL_PARALLEL_GUARD_VIOLATION";
  constructor(message: string) {
    super(message);
    this.name = "ReadConcurrencyOwnershipError";
  }
}

/**
 * Throws when the orchestrator dispatcher claims ownership for a call but
 * still asks `WorkflowManager` to batch the read. That combination is the
 * exact double-scheduling bug PR-1a's invariant exists to prevent.
 *
 * Returns the claim unchanged on success so callers can chain inline.
 */
export function assertSingleReadConcurrencyOwner(
  claim: ReadConcurrencyOwnershipClaim,
): ReadConcurrencyOwnershipClaim {
  if (
    claim.owner === "OrchestratorDispatcher" &&
    claim.isReadOperationFlag === true
  ) {
    throw new ReadConcurrencyOwnershipError(
      "OrchestratorDispatcher claimed read-concurrency ownership but " +
        "WorkflowManager.executeTool(...) was still called with " +
        "isReadOperation: true. Pass isReadOperation: false on this path " +
        "(see docs/agent-concurrency-map.md §3).",
    );
  }
  return claim;
}

function isDevBuild(): boolean {
  try {
    const env = (
      import.meta as unknown as Record<string, Record<string, unknown>>
    ).env;
    const devFlag = env?.DEV;
    if (typeof devFlag === "boolean") {
      return devFlag;
    }
    if (devFlag === "true") {
      return true;
    }
    if (devFlag === "false") {
      return false;
    }

    const mode = env?.MODE;
    if (typeof mode === "string") {
      return mode !== "production";
    }
  } catch {
    // Ignore environments without Vite-style import.meta.env.
  }

  return false;
}

export function assertParallelSafeReadBatchingInDev(
  tool: ToolMetadataProbe,
  isReadOperationFlag: boolean,
): void {
  if (!isDevBuild() || tool.parallelSafe !== true) {
    return;
  }

  try {
    assertSingleReadConcurrencyOwner({
      owner: "OrchestratorDispatcher",
      isReadOperationFlag,
    });
  } catch (error) {
    if (error instanceof ReadConcurrencyOwnershipError) {
      const toolName =
        typeof tool.name === "string" ? tool.name : "unknown tool";
      throw new ReadConcurrencyOwnershipError(
        `Tool \"${toolName}\" is marked parallelSafe but is still being dispatched with WorkflowManager read batching enabled. ${error.message}`,
      );
    }
    throw error;
  }
}
