import { Type } from "@sinclair/typebox";
import { parseCsv } from "../csv";
import { type CellInput, setCellRange } from "../excel/api";
import { resolveStagedTextContent } from "./staged-content";
import { defineTool, toolError, toolSuccess } from "./types";

const BorderStyleSchema = Type.Optional(
  Type.Object({
    style: Type.Optional(
      Type.Union([
        Type.Literal("solid"),
        Type.Literal("dashed"),
        Type.Literal("dotted"),
        Type.Literal("double"),
      ]),
    ),
    weight: Type.Optional(
      Type.Union([
        Type.Literal("thin"),
        Type.Literal("medium"),
        Type.Literal("thick"),
      ]),
    ),
    color: Type.Optional(Type.String()),
  }),
);

const CellStylesSchema = Type.Optional(
  Type.Object({
    fontWeight: Type.Optional(
      Type.Union([Type.Literal("normal"), Type.Literal("bold")]),
    ),
    fontStyle: Type.Optional(
      Type.Union([Type.Literal("normal"), Type.Literal("italic")]),
    ),
    fontLine: Type.Optional(
      Type.Union([
        Type.Literal("none"),
        Type.Literal("underline"),
        Type.Literal("line-through"),
      ]),
    ),
    fontSize: Type.Optional(Type.Number()),
    fontFamily: Type.Optional(Type.String()),
    fontColor: Type.Optional(Type.String()),
    backgroundColor: Type.Optional(Type.String()),
    horizontalAlignment: Type.Optional(
      Type.Union([
        Type.Literal("left"),
        Type.Literal("center"),
        Type.Literal("right"),
      ]),
    ),
    numberFormat: Type.Optional(Type.String()),
  }),
);

const BorderStylesSchema = Type.Optional(
  Type.Object({
    top: BorderStyleSchema,
    bottom: BorderStyleSchema,
    left: BorderStyleSchema,
    right: BorderStyleSchema,
  }),
);

const CellSchema = Type.Object({
  value: Type.Optional(Type.Any()),
  formula: Type.Optional(Type.String()),
  note: Type.Optional(Type.String()),
  cellStyles: CellStylesSchema,
  borderStyles: BorderStylesSchema,
});

const ResizeSchema = Type.Optional(
  Type.Object({
    type: Type.Union([Type.Literal("points"), Type.Literal("standard")]),
    value: Type.Number({
      description:
        "Size value. Use 0 to autofit columns/rows instead of hiding.",
    }),
  }),
);

export const setCellRangeTool = defineTool({
  name: "set_cell_range",
  category: "deliverable",
  parallelSafe: false,
  label: "Set Cell Range",
  description:
    "WRITE. Write values, formulas, and formatting to cells. " +
    "IMPORTANT: The cells array MUST exactly match the range dimensions. " +
    "cells is a 2D array: outer array = rows, inner arrays = columns. " +
    "For range A1:C1 (1 row, 3 cols), cells must be [[cellA1, cellB1, cellC1]]. " +
    "For range A1:A3 (3 rows, 1 col), cells must be [[cellA1], [cellA2], [cellA3]]. " +
    "Set resizeWidth/resizeHeight value to 0 to autofit after writing. " +
    "OVERWRITE PROTECTION: By default, fails if target cells contain data. " +
    "If the tool returns an overwrite error, read those cells to see what's there, " +
    "confirm with the user, then retry with allow_overwrite=true. " +
    "Only set allow_overwrite=true on first attempt if user explicitly says 'replace' or 'overwrite'. " +
    "For substantial matrices, stage JSON or CSV with write_file and pass cellsFromFile instead of inline cells. " +
    "Use copyToRange to expand a pattern to a larger area.",
  parameters: Type.Object({
    sheetId: Type.Number({ description: "The worksheet ID (1-based index)" }),
    range: Type.String({
      description: "Target range in A1 notation, must match cells dimensions",
    }),
    cells: Type.Optional(
      Type.Array(Type.Array(CellSchema), {
        description:
          "2D array of cell data matching range dimensions. Optional when cellsFromFile is provided.",
      }),
    ),
    cellsFromFile: Type.Optional(
      Type.String({
        description:
          "VFS path to a staged JSON 2D matrix (cell objects or primitive values) or CSV. Preferred for substantial writes.",
      }),
    ),
    copyToRange: Type.Optional(
      Type.String({
        description: "Expand pattern to larger range after writing",
      }),
    ),
    resizeWidth: ResizeSchema,
    resizeHeight: ResizeSchema,
    allow_overwrite: Type.Optional(
      Type.Boolean({ description: "Confirm overwriting existing data" }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  dirtyTracking: {
    getRanges: (p) => {
      const ranges = [{ sheetId: p.sheetId, range: p.range }];
      if (p.copyToRange) {
        ranges.push({ sheetId: p.sheetId, range: p.copyToRange });
      }
      return ranges;
    },
  },
  execute: async (_toolCallId, params, signal) => {
    try {
      const resolvedCells = await resolveCellMatrix(params);
      if ("error" in resolvedCells) return toolError(resolvedCells.error);
      const result = await setCellRange(
        params.sheetId,
        params.range,
        resolvedCells.cells,
        {
          copyToRange: params.copyToRange,
          resizeWidth: params.resizeWidth,
          resizeHeight: params.resizeHeight,
          allowOverwrite: params.allow_overwrite,
          signal,
        },
      );
      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error writing cells";
      return toolError(message);
    }
  },
});

type CellMatrixResult = { cells: CellInput[][] } | { error: string };

export async function resolveCellMatrix(params: {
  cells?: CellInput[][];
  cellsFromFile?: string;
}): Promise<CellMatrixResult> {
  if (!params.cellsFromFile?.trim()) {
    return params.cells && params.cells.length > 0
      ? { cells: params.cells }
      : {
          error:
            "Provide either cells or cellsFromFile (staged JSON/CSV in the VFS).",
        };
  }

  const staged = await resolveStagedTextContent({
    fromFile: params.cellsFromFile,
    fileFieldName: "cellsFromFile",
  });
  if ("error" in staged) return { error: staged.error };

  const text = staged.content.trim();
  if (text.startsWith("[")) {
    try {
      const parsed = JSON.parse(text) as unknown;
      if (!Array.isArray(parsed) || !parsed.every(Array.isArray)) {
        return { error: "cellsFromFile JSON must be a 2D array." };
      }
      const rows = parsed as unknown[][];
      if (rows.length === 0 || rows[0].length === 0) {
        return { error: "cellsFromFile JSON matrix must not be empty." };
      }
      const width = rows[0].length;
      const raggedRow = rows.findIndex((row) => row.length !== width);
      if (raggedRow >= 0) {
        return {
          error: `cellsFromFile JSON row ${raggedRow + 1} has ${rows[raggedRow].length} cells; expected ${width}.`,
        };
      }
      return {
        cells: rows.map((row) => row.map((cell) => normalizeCellInput(cell))),
      };
    } catch (error) {
      return {
        error: `Failed to parse cellsFromFile JSON: ${
          error instanceof Error ? error.message : String(error)
        }`,
      };
    }
  }

  const csvRows = parseCsv(staged.content);
  if (csvRows.length === 0) {
    return { error: "cellsFromFile CSV must contain at least one row." };
  }
  const width = Math.max(...csvRows.map((row) => row.length));
  return {
    cells: csvRows.map((row) => {
      const padded = [...row];
      while (padded.length < width) padded.push("");
      return padded.map((value) => ({ value }));
    }),
  };
}

function normalizeCellInput(value: unknown): CellInput {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as CellInput;
  }
  return { value };
}
