/**
 * Virtual Filesystem (VFS) for the agent
 *
 * Provides an in-memory filesystem using just-bash that allows:
 * - Users to upload files (images, CSVs, etc.)
 * - Agent to read files via read_file tool
 * - Agent to execute bash commands via bash tool
 */

import {
  Bash,
  type BufferEncoding,
  type CpOptions,
  type FileContent,
  InMemoryFs,
  type InitialFiles,
  type RmOptions,
} from "just-bash/browser";
import { getCustomCommands } from "./custom-commands";

// Singleton instances
const READ_ONLY_VFS_PREFIXES = ["/home/skills"];
type VfsWriteOptions = { encoding?: BufferEncoding } | BufferEncoding;

function normalizedPolicyPath(path: string): string {
  const normalized = new InMemoryFs().resolvePath("/", path);
  return normalized.length > 1 ? normalized.replace(/\/+$/, "") : normalized;
}

function assertWritableVfsPath(path: string): void {
  const normalized = normalizedPolicyPath(path);
  if (
    READ_ONLY_VFS_PREFIXES.some(
      (prefix) => normalized === prefix || normalized.startsWith(`${prefix}/`),
    )
  ) {
    throw new Error(`VFS path is read-only: ${normalized}`);
  }
}

function dirname(path: string): string {
  const normalized = normalizedPolicyPath(path);
  const slash = normalized.lastIndexOf("/");
  return slash <= 0 ? "/" : normalized.slice(0, slash);
}

function assertWritableSymlinkTarget(target: string, linkPath: string): void {
  const resolvedTarget = target.startsWith("/")
    ? target
    : new InMemoryFs().resolvePath(dirname(linkPath), target);
  assertWritableVfsPath(resolvedTarget);
}

export class ProtectedInMemoryFs extends InMemoryFs {
  private protectionEnabled = false;

  constructor(initialFiles?: InitialFiles) {
    super(initialFiles);
    this.protectionEnabled = true;
  }

  override writeFileSync(
    path: string,
    content: FileContent,
    options?: VfsWriteOptions,
    metadata?: { mode?: number; mtime?: Date },
  ): void {
    if (this.protectionEnabled) assertWritableVfsPath(path);
    super.writeFileSync(path, content, options, metadata);
  }

  async writeFile(
    path: string,
    content: FileContent,
    options?: VfsWriteOptions,
  ): Promise<void> {
    assertWritableVfsPath(path);
    return super.writeFile(path, content, options);
  }

  async appendFile(
    path: string,
    content: FileContent,
    options?: VfsWriteOptions,
  ): Promise<void> {
    assertWritableVfsPath(path);
    return super.appendFile(path, content, options);
  }

  async mkdir(path: string, options?: { recursive?: boolean }): Promise<void> {
    assertWritableVfsPath(path);
    return super.mkdir(path, options);
  }

  override mkdirSync(path: string, options?: { recursive?: boolean }): void {
    if (this.protectionEnabled) assertWritableVfsPath(path);
    super.mkdirSync(path, options);
  }

  async rm(path: string, options?: RmOptions): Promise<void> {
    assertWritableVfsPath(path);
    return super.rm(path, options);
  }

  async cp(src: string, dest: string, options?: CpOptions): Promise<void> {
    assertWritableVfsPath(dest);
    return super.cp(src, dest, options);
  }

  async mv(src: string, dest: string): Promise<void> {
    assertWritableVfsPath(src);
    assertWritableVfsPath(dest);
    return super.mv(src, dest);
  }

  async symlink(target: string, linkPath: string): Promise<void> {
    assertWritableVfsPath(linkPath);
    assertWritableSymlinkTarget(target, linkPath);
    return super.symlink(target, linkPath);
  }

  async link(existingPath: string, newPath: string): Promise<void> {
    assertWritableVfsPath(existingPath);
    assertWritableVfsPath(newPath);
    return super.link(existingPath, newPath);
  }

  async chmod(path: string, mode: number): Promise<void> {
    assertWritableVfsPath(path);
    return super.chmod(path, mode);
  }

  async utimes(path: string, atime: Date, mtime: Date): Promise<void> {
    assertWritableVfsPath(path);
    return super.utimes(path, atime, mtime);
  }
}

let fs: ProtectedInMemoryFs | null = null;
let bash: Bash | null = null;

export interface VfsMutationEvent {
  type: "write" | "append" | "delete" | "reset" | "restore" | "shell";
  path?: string;
  version: number;
}

type VfsMutationListener = (event: VfsMutationEvent) => void;
const mutationListeners = new Set<VfsMutationListener>();
let mutationVersion = 0;

export function subscribeVfsMutations(
  listener: VfsMutationListener,
): () => void {
  mutationListeners.add(listener);
  return () => mutationListeners.delete(listener);
}

export function notifyVfsMutation(
  event: Omit<VfsMutationEvent, "version">,
): void {
  mutationVersion += 1;
  const withVersion = { ...event, version: mutationVersion };
  for (const listener of mutationListeners) {
    try {
      listener(withVersion);
    } catch (error) {
      console.error("[VFS] Mutation listener failed", error);
    }
  }
}

// Skill files are mounted on every VFS creation (global, not per-session)
let skillFilesCache: Record<string, Uint8Array | string> = {};

const INTERNAL_UPLOAD_NAMES = new Set([
  ".officeai-todos.json",
  ".officeai-workflow-progress.md",
]);
const INTERNAL_UPLOAD_PREFIXES = ["wiki/", "working-set/"];

function isUserVisibleUpload(path: string): boolean {
  const normalized = path.replace(/\\/g, "/").replace(/^\/+/, "").trim();
  if (!normalized) return false;
  if (INTERNAL_UPLOAD_NAMES.has(normalized.toLowerCase())) return false;
  return !INTERNAL_UPLOAD_PREFIXES.some((prefix) =>
    normalized.toLowerCase().startsWith(prefix),
  );
}

export function setSkillFiles(
  files: Record<string, Uint8Array | string>,
): void {
  skillFilesCache = files;
}

/**
 * Get or create the virtual filesystem instance
 */
export function getVfs(): ProtectedInMemoryFs {
  if (!fs) {
    fs = new ProtectedInMemoryFs({
      "/home/user/uploads/.keep": "",
      ...skillFilesCache,
    });
  }
  return fs;
}

/**
 * Get or create the Bash instance
 */
export function getBash(): Bash {
  if (!bash) {
    bash = new Bash({
      fs: getVfs(),
      cwd: "/home/user",
      customCommands: getCustomCommands(),
    });
  }
  return bash;
}

/**
 * Reset the VFS (clears all files, creates fresh instances)
 */
export function resetVfs(): void {
  fs = null;
  bash = null;
  notifyVfsMutation({ type: "reset" });
}

/**
 * Snapshot all files in the VFS as path→Uint8Array pairs.
 * Only captures files (not directories or symlinks).
 */
export async function snapshotVfs(): Promise<
  { path: string; data: Uint8Array }[]
> {
  const vfs = getVfs();
  const allPaths = vfs.getAllPaths();
  const files: { path: string; data: Uint8Array }[] = [];

  for (const p of allPaths) {
    // Skip skill files — they're managed globally, not per-session
    if (p.startsWith("/home/skills/")) continue;
    try {
      const stat = await vfs.stat(p);
      if (stat.isFile) {
        const data = await vfs.readFileBuffer(p);
        // Create a copy of the data so snapshots do not share mutable buffers
        const dataCopy = new Uint8Array(data.byteLength);
        dataCopy.set(data);
        files.push({ path: p, data: dataCopy });
      }
    } catch {
      // skip unreadable entries
    }
  }

  return files;
}

/**
 * Restore VFS from a snapshot. Resets existing state and writes all files.
 */
export async function restoreVfs(
  files: { path: string; data: Uint8Array }[],
): Promise<void> {
  resetVfs();

  if (files.length === 0) {
    // Just initialize the default VFS (includes skills from cache)
    getVfs();
    notifyVfsMutation({ type: "restore" });
    return;
  }

  // Build InitialFiles record: skills (global) + session files
  const initialFiles: Record<string, Uint8Array | string> = {
    "/home/user/uploads/.keep": "",
    ...skillFilesCache,
  };
  for (const f of files) {
    initialFiles[f.path] = f.data;
  }

  fs = new ProtectedInMemoryFs(initialFiles);
  bash = null; // will be lazily created with the new fs
  notifyVfsMutation({ type: "restore" });
}

/**
 * Write a file to the VFS
 */
export async function writeFile(
  path: string,
  content: string | Uint8Array,
): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;

  // Ensure parent directory exists
  const dir = fullPath.substring(0, fullPath.lastIndexOf("/"));
  if (dir && dir !== "/") {
    try {
      await vfs.mkdir(dir, { recursive: true });
    } catch {
      // Directory might already exist
    }
  }

  await vfs.writeFile(fullPath, content);
  notifyVfsMutation({ type: "write", path: fullPath });
}

/**
 * Append content to a file in the VFS. Creates the file (and any missing
 * parent directories) if it does not yet exist, matching POSIX `>>`
 * semantics. Used by `write_file` when the model needs to recover from
 * a tool call truncated by `max_completion_tokens` by chunking the
 * payload across multiple turns.
 */
export async function appendFile(
  path: string,
  content: string | Uint8Array,
): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;

  // Ensure parent directory exists
  const dir = fullPath.substring(0, fullPath.lastIndexOf("/"));
  if (dir && dir !== "/") {
    try {
      await vfs.mkdir(dir, { recursive: true });
    } catch {
      // Directory might already exist
    }
  }

  await vfs.appendFile(fullPath, content);
  notifyVfsMutation({ type: "append", path: fullPath });
}

/**
 * Read a file from the VFS
 */
export async function readFile(path: string): Promise<string> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.readFile(fullPath);
}

/**
 * Read a file as binary from the VFS
 */
export async function readFileBuffer(path: string): Promise<Uint8Array> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.readFileBuffer(fullPath);
}

/**
 * Check if a file exists in the VFS
 */
export async function fileExists(path: string): Promise<boolean> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.exists(fullPath);
}

/**
 * Delete a file from the VFS
 */
export async function deleteFile(path: string): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  await vfs.rm(fullPath);
  notifyVfsMutation({ type: "delete", path: fullPath });
}

/**
 * Result of {@link commitTempFile}.
 *
 * `bytesWritten` reports the byte length of the data committed to the
 * target path (read back from the temp file just before commit).
 *
 * `cleanupError` is populated only when the commit to the target
 * succeeded but the subsequent temp-file deletion failed. The caller
 * is expected to log this as a non-fatal telemetry event (see
 * `agent.write_file_stream_commit_cleanup_failed` in the
 * Stream-to-VFS plan). The helper itself does not emit telemetry so
 * the VFS layer stays free of agent imports.
 */
export interface CommitTempFileResult {
  bytesWritten: number;
  cleanupError?: unknown;
}

/**
 * Atomically promote a temp file to its target path.
 *
 * Used by the streaming `write_file` pipeline (Stream-to-VFS plan,
 * Phase B / D12) to commit bytes that were progressively appended to
 * `tempPath` during a streamed tool call. The helper deliberately
 * avoids assuming a `rename` primitive in `just-bash`: it reads the
 * temp buffer, writes/appends to the target via the existing
 * {@link writeFile} / {@link appendFile} helpers (which apply the
 * usual `/home/user/uploads/` defaulting for relative paths), and
 * then deletes the temp file.
 *
 * If the target write throws, the error propagates (the caller is
 * responsible for any temp cleanup). If only the temp delete throws
 * after a successful target write, the result returns
 * `cleanupError` so the caller can emit a non-fatal telemetry event
 * without losing the successful commit.
 */
export async function commitTempFile(
  tempPath: string,
  targetPath: string,
  mode: "overwrite" | "append",
): Promise<CommitTempFileResult> {
  const data = await readFileBuffer(tempPath);
  if (mode === "append") {
    await appendFile(targetPath, data);
  } else {
    await writeFile(targetPath, data);
  }
  let cleanupError: unknown | undefined;
  try {
    await deleteFile(tempPath);
  } catch (err) {
    cleanupError = err;
  }
  return { bytesWritten: data.byteLength, cleanupError };
}

/**
 * List files in the VFS uploads directory
 */
export async function listUploads(): Promise<string[]> {
  const vfs = getVfs();
  try {
    // Recursively list all files under /home/user/uploads
    const walk = async (dir: string): Promise<string[]> => {
      const entries = await vfs.readdir(dir);
      const results: string[] = [];
      for (const entry of entries) {
        if (entry === ".keep") continue;
        const fullPath = `${dir}/${entry}`;
        try {
          const stat = await vfs.stat(fullPath);
          if (stat.isDirectory) {
            const nested = await walk(fullPath);
            results.push(...nested);
          } else if (stat.isFile) {
            results.push(fullPath);
          }
        } catch {
          // ignore
        }
      }
      return results;
    };

    const files = await walk("/home/user/uploads");
    return files
      .map((p) => p.replace("/home/user/uploads/", ""))
      .filter(isUserVisibleUpload);
  } catch {
    return [];
  }
}

/** List every file in the in-memory VFS using absolute paths. */
export async function listVfsFiles(): Promise<string[]> {
  const vfs = getVfs();
  const files: string[] = [];
  for (const path of vfs.getAllPaths()) {
    if (path.endsWith("/.keep")) continue;
    try {
      const stat = await vfs.stat(path);
      if (stat.isFile) files.push(path);
    } catch {
      // A path may disappear between getAllPaths and stat after a mutation.
    }
  }
  return files.sort((left, right) => left.localeCompare(right));
}

/**
 * Check if a file is empty (size === 0)
 */
export async function isFileEmpty(path: string): Promise<boolean> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  try {
    const stat = await vfs.stat(fullPath);
    return stat.isFile && stat.size === 0;
  } catch {
    return false;
  }
}

/**
 * Get file stats from VFS
 */
export async function getFileStat(path: string): Promise<{
  exists: boolean;
  isFile: boolean;
  size: number;
} | null> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  try {
    const stat = await vfs.stat(fullPath);
    return {
      exists: true,
      isFile: stat.isFile,
      size: stat.size,
    };
  } catch {
    return null;
  }
}

/**
 * Download a file from VFS to the user's computer
 * Creates a temporary anchor element with download attribute
 */
export async function downloadFile(
  path: string,
  filename?: string,
): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  const data = await vfs.readFileBuffer(fullPath);

  // Determine MIME type from filename
  const actualFilename = filename || fullPath.split("/").pop() || "download";
  const { mimeType } = getFileType(actualFilename);

  // Create blob and download - copy data to ensure ArrayBuffer compatibility
  const dataCopy = new Uint8Array(data);
  const blob = new Blob([dataCopy], { type: mimeType });
  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");
  link.href = url;
  link.download = actualFilename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  URL.revokeObjectURL(url);
}

/**
 * Get file type (helper for determining if it's an image, etc.)
 */
export function getFileType(filename: string): {
  isImage: boolean;
  mimeType: string;
} {
  const ext = filename.toLowerCase().split(".").pop() || "";
  const imageExts: Record<string, string> = {
    png: "image/png",
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    gif: "image/gif",
    webp: "image/webp",
    svg: "image/svg+xml",
    bmp: "image/bmp",
    ico: "image/x-icon",
  };

  if (ext in imageExts) {
    return { isImage: true, mimeType: imageExts[ext] };
  }

  const mimeTypes: Record<string, string> = {
    txt: "text/plain",
    csv: "text/csv",
    json: "application/json",
    xml: "application/xml",
    html: "text/html",
    css: "text/css",
    js: "application/javascript",
    ts: "application/typescript",
    md: "text/markdown",
    pdf: "application/pdf",
  };

  return {
    isImage: false,
    mimeType: mimeTypes[ext] || "application/octet-stream",
  };
}

/**
 * Convert ArrayBuffer/Uint8Array to base64
 */
export function toBase64(data: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < data.length; i++) {
    binary += String.fromCharCode(data[i]);
  }
  return btoa(binary);
}
