/**
 * Token budget owner (blueprint §8.1).
 *
 * The orchestrator merges `state.ephemeralMessages` onto the persistent
 * history immediately before calling `provider.runTurn(...)`. Compaction
 * runs against the persistent half only — ephemeral nudges are sent
 * verbatim and accounted against the budget last.
 *
 * PR-4A scaffolds the entry point and delegates compaction to the
 * existing `prepareMessagesForApi` path so behavior remains identical to
 * the legacy loop while the FSM ships dark. PR-5 / PR-6 may switch the
 * compactor implementation; the entry-point shape and degradation
 * semantics are normative.
 */

import {
  MAX_CONTEXT_TOKENS,
  type TokenCount,
  calculateTotalTokens,
  prepareMessagesForApi,
} from "../../token-manager";
import type { LLMProvider } from "../providers/provider";
import type {
  AgentMessage,
  AssistantMessage,
  ToolContent,
  ToolResultMessage,
} from "../types";

export interface TokenBudgetLimits {
  /** Provider hard ceiling (input + output). */
  maxContextTokens: number;
  /** Tokens reserved for the model's reply. */
  reservedOutputTokens: number;
  /** Tokens reserved for verbatim ephemeral nudges. */
  reservedEphemeralTokens: number;
  /** Safety margin for tokenizer drift. */
  safetyMarginTokens: number;
}

export const DEFAULT_TOKEN_BUDGET: TokenBudgetLimits = {
  maxContextTokens: MAX_CONTEXT_TOKENS,
  reservedOutputTokens: 4096,
  reservedEphemeralTokens: 512,
  safetyMarginTokens: 256,
};

export interface PrepareOutboundResult {
  messages: AgentMessage[];
  compacted: boolean;
  /** Number of old tool-result messages capped in this outbound request. */
  cappedToolResults: number;
  /** Number of text characters removed by old tool-result capping. */
  removedToolResultChars: number;
  /** Number of ephemeral messages dropped to fit the budget (0 in the
   * happy path). */
  droppedEphemeral: number;
  /** True when `availableForPersistent <= 0` and history was discarded. */
  degraded: boolean;
  tokenCount: TokenCount;
}

export interface PrepareOutboundEvents {
  onNudgeDroppedForBudget?: (reason?: string) => void;
  onBudgetInfeasibleDegraded?: (info: {
    availableForPersistent: number;
    systemPromptTokens: number;
    toolSchemaTokens: number;
    droppedPersistent: number;
    droppedEphemeral: number;
  }) => void;
}

/**
 * Max aggregate text characters retained for an old tool-result message. A
 * one-time large read / CSV export / MCP payload otherwise re-inflates the
 * prompt on every
 * subsequent turn (prefill latency and cost scale with input tokens). Older
 * oversized results are head/tail truncated with a marker; the most recent
 * results stay verbatim so the model keeps full fidelity on the turn right
 * after a tool runs. Mirrors the existing tool-CALL argument compaction in
 * `stringifyToolArgumentsForHistory`.
 */
export const TOOL_RESULT_HISTORY_MAX_CHARS = 4000;

function buildToolResultElisionMarker(removedChars: number): string {
  return `\n\n[... ${removedChars} characters elided from an earlier tool result; re-read the source if needed. ...]\n\n`;
}

function capToolResultText(text: string, maxChars: number): string | null {
  const limit = Math.max(0, Math.floor(maxChars));
  if (text.length <= limit) return null;

  let retainedChars = limit;
  let marker = "";
  for (let attempt = 0; attempt < 8; attempt++) {
    marker = buildToolResultElisionMarker(text.length - retainedChars);
    const nextRetained = Math.max(0, limit - marker.length);
    if (nextRetained === retainedChars) break;
    retainedChars = nextRetained;
  }
  marker = buildToolResultElisionMarker(text.length - retainedChars);

  if (retainedChars === 0) return marker.slice(0, limit);

  const headChars = Math.floor(retainedChars * 0.75);
  const tailChars = retainedChars - headChars;
  const head = text.slice(0, headChars);
  const tail = tailChars > 0 ? text.slice(text.length - tailChars) : "";
  return `${head}${marker}${tail}`.slice(0, limit);
}

function capToolResultMessage(
  msg: ToolResultMessage,
  maxChars: number,
): ToolResultMessage {
  if (msg.reference) return msg;
  const combinedText = msg.content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n");
  const capped = capToolResultText(combinedText, maxChars);
  if (capped === null) return msg;

  let insertedText = false;
  const content: ToolContent[] = [];
  for (const block of msg.content) {
    if (block.type !== "text") {
      content.push(block);
    } else if (!insertedText) {
      content.push({ type: "text", text: capped });
      insertedText = true;
    }
  }
  return { ...msg, content };
}

export interface CapOldToolResultsResult {
  messages: AgentMessage[];
  cappedToolResults: number;
  removedChars: number;
}

function toolResultWireTextLength(message: ToolResultMessage): number {
  return message.content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n").length;
}

function newestUnconsumedToolCallIds(
  messages: AgentMessage[],
): ReadonlySet<string> {
  let index = messages.length - 1;
  while (index >= 0 && messages[index].role === "tool") index--;
  if (index < 0 || messages[index].role !== "assistant") return new Set();

  const assistant = messages[index] as AssistantMessage;
  return new Set(
    assistant.content
      .filter((block) => block.type === "tool_call")
      .map((block) => block.id),
  );
}

/**
 * Truncate oversized results from already-consumed tool-call groups. If the
 * history ends with an assistant tool-call message plus its results, that
 * complete newest protocol group remains verbatim so every parallel sibling
 * reaches the model once at full fidelity. Input is never mutated; full
 * originals stay on `internalState.messages` for the UI inspector. Images and
 * MCP resource blocks pass through untouched. Capping is deterministic, so an
 * already-capped prefix remains byte-stable on later turns.
 */
export function capOldToolResults(
  messages: AgentMessage[],
  maxChars: number = TOOL_RESULT_HISTORY_MAX_CHARS,
): CapOldToolResultsResult {
  if (messages.length === 0) {
    return { messages, cappedToolResults: 0, removedChars: 0 };
  }

  const preservedToolCallIds = newestUnconsumedToolCallIds(messages);
  let changed = false;
  let cappedToolResults = 0;
  let removedChars = 0;
  const out: AgentMessage[] = new Array(messages.length);
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (msg.role !== "tool") {
      out[i] = msg;
      continue;
    }
    if (preservedToolCallIds.has(msg.toolCallId)) {
      out[i] = msg;
      continue;
    }
    const capped = capToolResultMessage(msg as ToolResultMessage, maxChars);
    if (capped !== msg) {
      changed = true;
      cappedToolResults++;
      const beforeChars = toolResultWireTextLength(msg);
      const afterChars = toolResultWireTextLength(capped);
      removedChars += Math.max(0, beforeChars - afterChars);
    }
    out[i] = capped;
  }
  return {
    messages: changed ? out : messages,
    cappedToolResults,
    removedChars,
  };
}

/**
 * prepareOutboundMessages — orchestrator-owned token budget pass.
 *
 * Today: delegates compaction of the persistent half to
 * `prepareMessagesForApi` and then appends ephemeral messages verbatim.
 * If the combined estimated total exceeds the limit, ephemerals are
 * dropped oldest-first; if even the system prompt + tools cannot fit,
 * the persistent + ephemeral history is discarded entirely except for
 * the latest user message (blueprint §8.1 infeasible-budget degradation).
 *
 * `toolsJson` is the JSON-serialized tool schema as the provider would
 * send it on the wire; it is required because `prepareMessagesForApi`
 * uses it for tool-schema token math. Provider-side ephemeral estimation
 * uses `provider.estimateTokens(messages, "", [])` (no tools) since the
 * tools block is already accounted for in `tokenCount.tools`.
 */
export function prepareOutboundMessages(
  persistentRaw: AgentMessage[],
  ephemeral: AgentMessage[],
  systemPrompt: string,
  provider: LLMProvider,
  toolsJson: string,
  limits: TokenBudgetLimits = DEFAULT_TOKEN_BUDGET,
  events: PrepareOutboundEvents = {},
): PrepareOutboundResult {
  // Cap oversized OLD tool results before compaction so a one-time large
  // read / CSV / MCP payload stops re-inflating every subsequent turn's
  // prompt. The most recent results stay verbatim; `internalState` history
  // is untouched (new objects are created only for capped messages).
  const capResult = capOldToolResults(persistentRaw);
  const persistent = capResult.messages;
  const reserved =
    limits.reservedOutputTokens +
    limits.reservedEphemeralTokens +
    limits.safetyMarginTokens;
  const effectiveContext = Math.max(0, limits.maxContextTokens - reserved);

  // Compact the persistent half against the orchestrator's reduced budget.
  const { preparedMessages, tokenCount } = prepareMessagesForApi(
    persistent,
    systemPrompt,
    toolsJson,
    effectiveContext + limits.reservedEphemeralTokens, // ephemerals share space if unused
  );

  const compacted =
    capResult.cappedToolResults > 0 ||
    preparedMessages.length !== persistent.length;

  // Estimate ephemeral cost via the provider's tokenizer.
  const ephemeralEstimate =
    ephemeral.length === 0
      ? { inputTokens: 0, perMessageOverhead: 0, toolSchemaTokens: 0 }
      : provider.estimateTokens(ephemeral, "", []);

  let droppedEphemeral = 0;
  let outboundEphemeral = ephemeral;

  // System+tools-only check (infeasible-budget degradation).
  const systemAndToolsCost = tokenCount.system + tokenCount.tools;
  const availableForPersistent =
    limits.maxContextTokens - reserved - systemAndToolsCost;
  if (availableForPersistent <= 0) {
    // Drop everything except the latest user message.
    const latestUser = [...persistent].reverse().find((m) => m.role === "user");
    const fallback = latestUser ? [latestUser] : [];
    events.onBudgetInfeasibleDegraded?.({
      availableForPersistent,
      systemPromptTokens: tokenCount.system,
      toolSchemaTokens: tokenCount.tools,
      droppedPersistent: persistent.length - fallback.length,
      droppedEphemeral: ephemeral.length,
    });
    return {
      messages: fallback,
      compacted: true,
      cappedToolResults: capResult.cappedToolResults,
      removedToolResultChars: capResult.removedChars,
      droppedEphemeral: ephemeral.length,
      degraded: true,
      tokenCount: calculateTotalTokens(fallback, systemPrompt, toolsJson),
    };
  }

  // Drop oldest ephemerals while their estimate would push us over the
  // ephemeral reserve plus any unused persistent slack.
  const persistentSlack = Math.max(0, effectiveContext - tokenCount.messages);
  const ephemeralBudget = limits.reservedEphemeralTokens + persistentSlack;
  if (ephemeralEstimate.inputTokens > ephemeralBudget && ephemeral.length > 0) {
    // Coarse drop: each ephemeral is roughly equal-cost; pop oldest until
    // the remaining list's estimate fits.
    const remaining = [...ephemeral];
    while (remaining.length > 0) {
      const est = provider.estimateTokens(remaining, "", []);
      if (est.inputTokens <= ephemeralBudget) break;
      remaining.shift();
      droppedEphemeral++;
      events.onNudgeDroppedForBudget?.();
    }
    outboundEphemeral = remaining;
  }

  const messages = [...preparedMessages, ...outboundEphemeral];
  return {
    messages,
    compacted: compacted || droppedEphemeral > 0,
    cappedToolResults: capResult.cappedToolResults,
    removedToolResultChars: capResult.removedChars,
    droppedEphemeral,
    degraded: false,
    tokenCount: calculateTotalTokens(messages, systemPrompt, toolsJson),
  };
}
