import { Type } from "@sinclair/typebox";
import { fileExists, readFile, writeFile } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

/**
 * Surgical replacement for existing VFS files. Use this for partial
 * updates instead of re-emitting whole files with `write_file`, which
 * can hit the output-token limit on large HTML/code artifacts.
 *
 * `old_str` must appear exactly once. Matching is exact text matching:
 * no regex, no normalization, and whitespace/punctuation must match
 * verbatim. The tool is serialized because it performs read-modify-write
 * mutations against the shared in-memory VFS.
 */
export const editFileTool = defineTool({
  name: "edit_file",
  category: "deliverable",
  parallelSafe: false,
  label: "Edit File",
  description:
    "Replace EXACTLY ONE occurrence of `old_str` with `new_str` in an existing file. " +
    "Use this as the PRIMARY way to update files instead of re-emitting the whole file with `write_file` — partial edits avoid the output-token limit that causes large `write_file` calls to be truncated mid-stream. " +
    "`path` can be absolute (starting with /) or relative to /home/user/uploads/. " +
    "`old_str` MUST match the file text exactly (no regex, no normalization) and MUST appear exactly once — include enough surrounding context (a few lines above and below the change) to make the match unique. " +
    "If you need to make several non-overlapping edits, issue several `edit_file` calls in the same turn rather than one giant `write_file`. " +
    "Use `write_file` only for brand-new files or when you genuinely intend to overwrite the entire file. " +
    "Use `update_todos` for workflow progress bookkeeping instead of writing markdown progress files.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file to edit. Can be absolute (starting with /) or relative to /home/user/uploads/. The file MUST already exist; this tool does not create new files (use `write_file` for that).",
    }),
    old_str: Type.String({
      minLength: 1,
      description:
        "The exact substring to find in the file. Must match the file text exactly (no regex). Must occur EXACTLY ONCE in the file — include enough surrounding context to disambiguate if needed.",
    }),
    new_str: Type.String({
      description:
        "The replacement text. May be the empty string to delete `old_str`.",
    }),
  }),
  execute: async (_toolCallId, params) => {
    const { path, old_str, new_str } = params;

    if (typeof old_str !== "string" || old_str.length === 0) {
      return toolError(
        "edit_file requires a non-empty `old_str`. To create a new file, use write_file. To append to an existing file, use write_file with append: true.",
      );
    }

    if (old_str === new_str) {
      return toolError(
        "edit_file received identical `old_str` and `new_str` — no change would be made. Skip the call or supply a different replacement.",
      );
    }

    try {
      if (!(await fileExists(path))) {
        return toolError(
          `File not found: ${path}. edit_file only modifies existing files; use write_file to create one.`,
        );
      }

      const original = await readFile(path);
      const firstIdx = original.indexOf(old_str);
      if (firstIdx === -1) {
        return toolError(
          `edit_file: \`old_str\` was not found in ${path}. Re-read the file (e.g. via the read tool) to confirm the exact text — matching is literal, including whitespace and punctuation.`,
        );
      }

      const secondIdx = original.indexOf(old_str, firstIdx + 1);
      if (secondIdx !== -1) {
        const occurrences = countOccurrences(original, old_str);
        return toolError(
          `edit_file: \`old_str\` matched ${occurrences} times in ${path} — it must match exactly once. Expand \`old_str\` with more surrounding context (e.g. include the preceding or following line) so the match is unique, then retry.`,
        );
      }

      const updated =
        original.slice(0, firstIdx) +
        new_str +
        original.slice(firstIdx + old_str.length);

      await writeFile(path, updated);

      const delta = new_str.length - old_str.length;
      const deltaStr = delta >= 0 ? `+${delta}` : `${delta}`;
      return toolSuccess(
        `Edited ${path} (${deltaStr} chars; replaced 1 occurrence).`,
      );
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error editing file";
      return toolError(message);
    }
  },
});

function countOccurrences(haystack: string, needle: string): number {
  if (needle.length === 0) return 0;
  let count = 0;
  let idx = 0;
  while (true) {
    const next = haystack.indexOf(needle, idx);
    if (next === -1) return count;
    count += 1;
    idx = next + 1;
  }
}
