/**
 * MCP App "dock" — a single, persistent mount point for all interactive
 * MCP App iframes that have appeared in the current chat session.
 *
 * Why this exists: every MCP tool call that returns a `ui://` payload
 * arrives as a fresh `McpUiAppPart` with a brand-new `toolCallId`.
 * Rendering each part inline in the message list means React mounts a
 * new iframe per tool call — the iframe loses all its in-page state
 * (URL bar contents, form input, scroll position) every time the model
 * calls the same MCP tool again.
 *
 * The dock fixes that by:
 *   1. Walking every assistant-message part across the visible chat
 *      and grouping all `mcpUiApp` parts by their stable identity
 *      `${ui.connectionId}::${ui.uri}` (an MCP App is the same App
 *      whenever those two match — different tool calls just push new
 *      `tool-input` + `tool-result` into the same view).
 *   2. Rendering one `<McpUiApp />` per group with a stable React key.
 *      The component never unmounts across tool calls; instead its
 *      post-mount push effect calls `sendToolInput` / `sendToolResult`
 *      on the existing bridge, so the iframe updates in place.
 *
 * Dismissal: users can hide an MCP App from the dock via the × button
 * in the iframe header. Dismissal is tracked per dock key by the
 * `toolCallId` that was visible when dismissed, so a *new* tool call
 * for the same App (different `toolCallId`) automatically re-surfaces
 * the view. This avoids the trap where the model produces a fresh
 * result the user actually wants to see, but it stays hidden because
 * they dismissed an earlier one.
 *
 * The dock lives between the message list and the chat input so it
 * acts like a pinned "Apps panel" that's always visible while the
 * conversation scrolls above it.
 */

import { makeStyles, tokens } from "@fluentui/react-components";
import { useCallback, useMemo, useState } from "react";
import type { McpUiAppPart } from "../../../lib/message-utils";
import { McpUiApp } from "./mcp-ui-app";
import { useChat } from "./use-chat";

const useStyles = makeStyles({
  dock: {
    display: "flex",
    flexDirection: "column",
    gap: tokens.spacingVerticalXS,
    padding: `${tokens.spacingVerticalXS} ${tokens.spacingHorizontalS}`,
    borderTop: `1px solid ${tokens.colorNeutralStroke2}`,
    backgroundColor: tokens.colorNeutralBackground1,
    flexShrink: 0,
    maxHeight: "60%",
    overflowY: "auto",
  },
});

function dockKey(part: McpUiAppPart): string {
  const conn = part.ui.connectionId ?? "_";
  const uri = part.ui.uri ?? "_";
  return `${conn}::${uri}`;
}

export function McpAppDock() {
  const styles = useStyles();
  const { state } = useChat();
  // dockKey -> toolCallId that was visible when the user dismissed it.
  // Stored as a Record (not a Set) so a *newer* tool call for the same
  // App produces a different toolCallId and re-surfaces the view.
  const [dismissedAt, setDismissedAt] = useState<Record<string, string>>({});

  const latestPerApp = useMemo(() => {
    const map = new Map<string, McpUiAppPart>();
    for (const message of state.messages) {
      if (message.transient) continue;
      for (const part of message.parts) {
        if (part.type !== "mcpUiApp") continue;
        map.set(dockKey(part), part);
      }
    }
    return Array.from(map.entries());
  }, [state.messages]);

  const visible = useMemo(
    () =>
      latestPerApp.filter(
        ([key, part]) => dismissedAt[key] !== part.toolCallId,
      ),
    [latestPerApp, dismissedAt],
  );

  const handleDismiss = useCallback((key: string, toolCallId: string) => {
    setDismissedAt((prev) =>
      prev[key] === toolCallId ? prev : { ...prev, [key]: toolCallId },
    );
  }, []);

  if (visible.length === 0) return null;

  return (
    <div className={styles.dock} data-mcp-app-dock="">
      {visible.map(([key, part]) => (
        <McpUiApp
          key={key}
          part={part}
          onDismiss={() => handleDismiss(key, part.toolCallId)}
        />
      ))}
    </div>
  );
}
