/**
 * MCP invocation client (PR-3B.1).
 *
 * Defines the minimal contract the {@link adaptMCPTool} closure needs
 * to invoke a remote tool. PR-3B.1 ships a mock implementation that
 * always returns a structured `MCP_CONNECTION_UNAVAILABLE` error so the
 * registry + dispatcher routing can be exercised without any network
 * code. PR-3B.2 introduces the real SSE / streamable HTTP transports.
 *
 * See docs/mcp-connection-contract.md §7–§8 and
 * docs/agent-refactor-blueprint.md §4.1.
 */

import { createAgentError } from "../errors";
import type { ToolResult } from "../types";
import { LiveMCPTransport, type LiveMCPTransportOptions } from "./transport";
import type {
  MCPNormalizedConnection,
  MCPReadResourceResult,
  MCPRemoteResourceDescriptor,
  MCPRemoteToolDescriptor,
} from "./types";

export interface MCPCallToolRequest {
  connectionId: string;
  remoteToolName: string;
  arguments: Record<string, unknown>;
  signal?: AbortSignal;
}

export interface MCPListToolsRequest {
  connectionId: string;
  signal?: AbortSignal;
  interactiveAllowed?: boolean;
}

export interface MCPListResourcesRequest {
  connectionId: string;
  signal?: AbortSignal;
  interactiveAllowed?: boolean;
}

export interface MCPReadResourceRequest {
  connectionId: string;
  uri: string;
  signal?: AbortSignal;
  interactiveAllowed?: boolean;
}

export interface MCPInvocationClient {
  /**
   * Call a remote MCP tool. Implementations MUST throw an
   * {@link AgentError} carrying one of the canonical `MCP_*` codes
   * (see docs/mcp-connection-contract.md §8) on failure rather than
   * returning a tool result, so the dispatcher can surface a structured
   * error envelope through {@link encodeToolErrorPayload}.
   */
  callTool(request: MCPCallToolRequest): Promise<ToolResult>;
  /**
   * Resolve a `ui://...` (or any) MCP resource. Optional so mocks and
   * pre-MCP-Apps callers don't have to stub it; the adapter falls back
   * to the embedded `resource` content path when this is unavailable.
   */
  readResource?(
    request: MCPReadResourceRequest,
  ): Promise<MCPReadResourceResult>;
}

export interface MCPDiscoveryClient {
  listTools(request: MCPListToolsRequest): Promise<MCPRemoteToolDescriptor[]>;
  listResources?(
    request: MCPListResourcesRequest,
  ): Promise<MCPRemoteResourceDescriptor[]>;
  readResource?(
    request: MCPReadResourceRequest,
  ): Promise<MCPReadResourceResult>;
  closeConnection(connectionId: string): void;
}

export interface LiveMCPInvocationClientOptions
  extends LiveMCPTransportOptions {
  connections: ReadonlyMap<string, MCPNormalizedConnection>;
}

export class LiveMCPInvocationClient
  implements MCPInvocationClient, MCPDiscoveryClient
{
  private readonly connections: ReadonlyMap<string, MCPNormalizedConnection>;
  private readonly transport: LiveMCPTransport;

  constructor(options: LiveMCPInvocationClientOptions) {
    this.connections = options.connections;
    this.transport = new LiveMCPTransport(options);
  }

  async listTools(
    request: MCPListToolsRequest,
  ): Promise<MCPRemoteToolDescriptor[]> {
    const connection = this.requireConnection(request.connectionId);
    return this.transport.listTools(connection, request.signal, {
      interactiveAllowed: request.interactiveAllowed,
    });
  }

  async listResources(
    request: MCPListResourcesRequest,
  ): Promise<MCPRemoteResourceDescriptor[]> {
    const connection = this.requireConnection(request.connectionId);
    return this.transport.listResources(connection, request.signal, {
      interactiveAllowed: request.interactiveAllowed,
    });
  }

  async readResource(
    request: MCPReadResourceRequest,
  ): Promise<MCPReadResourceResult> {
    const connection = this.requireConnection(request.connectionId);
    return this.transport.readResource(
      connection,
      request.uri,
      request.signal,
      {
        interactiveAllowed: request.interactiveAllowed,
      },
    );
  }

  async callTool(request: MCPCallToolRequest): Promise<ToolResult> {
    const connection = this.requireConnection(request.connectionId);
    return this.transport.callTool(
      connection,
      request.remoteToolName,
      request.arguments,
      request.signal,
    );
  }

  closeConnection(connectionId: string): void {
    this.transport.closeConnection(connectionId);
  }

  private requireConnection(connectionId: string): MCPNormalizedConnection {
    const connection = this.connections.get(connectionId);
    if (!connection || !connection.enabled) {
      throw createAgentError(
        "MCP_CONNECTION_UNAVAILABLE",
        `MCP connection ${connectionId} is not configured or not enabled.`,
        {
          details: {
            connectionId,
            retryable: false,
          },
        },
      );
    }
    return connection;
  }
}

/**
 * Mock client used by PR-3B.1 until live transports land in PR-3B.2.
 * Always throws `MCP_CONNECTION_UNAVAILABLE` with the connection id +
 * remote tool name in {@link AgentError.details} so the dispatcher can
 * embed them in the structured tool-error payload.
 */
export class MockMCPInvocationClient implements MCPInvocationClient {
  async callTool(request: MCPCallToolRequest): Promise<ToolResult> {
    if (request.signal?.aborted) {
      throw createAgentError(
        "MCP_TOOL_ABORTED",
        `MCP tool ${request.remoteToolName} cancelled before invocation.`,
        {
          details: {
            connectionId: request.connectionId,
            toolName: request.remoteToolName,
            retryable: false,
          },
        },
      );
    }
    throw createAgentError(
      "MCP_CONNECTION_UNAVAILABLE",
      `MCP connection ${request.connectionId} is not available (mock client; live transports land in PR-3B.2).`,
      {
        details: {
          connectionId: request.connectionId,
          toolName: request.remoteToolName,
          retryable: true,
        },
      },
    );
  }
}
