/**
 * MCP App iframe renderer (host side).
 *
 * Implements the host half of the MCP Apps spec (SEP-1865 / @modelcontextprotocol/ext-apps):
 *
 *   1. Mount a sandboxed iframe whose `srcdoc` is the HTML payload returned
 *      by the server's `ui://...` resource.
 *   2. Stand up an `AppBridge` connected to the iframe via
 *      `PostMessageTransport`. We construct the bridge with `client = null`
 *      and register `oncalltool` / `onlistresources` / `onreadresource`
 *      manually so iframe-initiated MCP requests forward back to the same
 *      live `LiveMCPInvocationClient` connection that produced the
 *      original tool result — no second transport / second auth round-trip.
 *   3. After the view fires `oninitialized`, push the original tool input
 *      via `sendToolInput`, then the tool result via `sendToolResult`.
 *      The view's `ontoolinput` / `ontoolresult` handlers render the UI.
 *   4. Bridge optional host services back to the iframe: `onopenlink`
 *      opens links in the user's browser (with `noopener`), `onsizechange`
 *      grows the iframe to fit (clamped), `onloggingmessage` mirrors
 *      child logs to the host console, theme changes propagate via
 *      `sendHostContextChange`.
 *
 * This renderer intentionally uses single-iframe `srcdoc` with
 * `sandbox="allow-scripts allow-forms"` (NO `allow-same-origin`). The
 * iframe ends up on a unique opaque origin so the embedded UI cannot
 * read add-in state, cookies, or the parent DOM; it can only talk to us
 * via the `postMessage` channel the AppBridge owns. The official spec
 * also describes a double-iframe sandbox-proxy on a separate origin,
 * but that requires control of two origins which the Office Add-in
 * task pane does not have.
 */

import { Button, makeStyles, tokens } from "@fluentui/react-components";
import { DismissRegular } from "@fluentui/react-icons";
import {
  AppBridge,
  PostMessageTransport,
} from "@modelcontextprotocol/ext-apps/app-bridge";
import type {
  CallToolResult,
  ListResourcesResult,
  ReadResourceResult,
} from "@modelcontextprotocol/sdk/types.js";
import { useEffect, useRef, useState } from "react";
import type { MCPInvocationClient } from "../../../lib/agent/mcp";
import type { McpUiAppPart } from "../../../lib/message-utils";
import { useTheme } from "../../theme";
import { useChat } from "./use-chat";

const useStyles = makeStyles({
  container: {
    marginTop: tokens.spacingVerticalS,
    marginBottom: tokens.spacingVerticalS,
    border: `1px solid ${tokens.colorNeutralStroke2}`,
    borderRadius: tokens.borderRadiusMedium,
    overflow: "hidden",
    backgroundColor: tokens.colorNeutralBackground2,
  },
  header: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: tokens.spacingHorizontalS,
    padding: `${tokens.spacingVerticalXS} ${tokens.spacingHorizontalS}`,
    borderBottom: `1px solid ${tokens.colorNeutralStroke2}`,
    backgroundColor: tokens.colorNeutralBackground3,
    fontSize: tokens.fontSizeBase200,
    color: tokens.colorNeutralForeground2,
  },
  headerRight: {
    display: "flex",
    alignItems: "center",
    gap: tokens.spacingHorizontalXS,
    minWidth: 0,
  },
  serverLabel: {
    overflow: "hidden",
    textOverflow: "ellipsis",
    whiteSpace: "nowrap",
  },
  dismissButton: {
    minWidth: "auto",
    height: "20px",
    paddingTop: 0,
    paddingBottom: 0,
    paddingLeft: tokens.spacingHorizontalXXS,
    paddingRight: tokens.spacingHorizontalXXS,
  },
  iframe: {
    display: "block",
    width: "100%",
    border: "none",
    backgroundColor: "transparent",
  },
  fallback: {
    padding: tokens.spacingHorizontalS,
    fontSize: tokens.fontSizeBase200,
    color: tokens.colorNeutralForeground2,
    whiteSpace: "pre-wrap",
  },
});

const MIN_IFRAME_HEIGHT = 120;
const MAX_IFRAME_HEIGHT = 1600;
const DEFAULT_IFRAME_HEIGHT = 320;

interface McpUiAppProps {
  part: McpUiAppPart;
  /**
   * If provided, render a dismiss (×) button in the header. When the
   * user clicks it the host (typically {@link McpAppDock}) unmounts
   * this iframe — the bridge cleanup effect closes the
   * `AppBridge` so no zombie postMessage listeners survive.
   */
  onDismiss?: () => void;
}

function buildCallToolResult(part: McpUiAppPart): CallToolResult {
  const content = (part.content ?? [
    { type: "text", text: part.resultText ?? "" },
  ]) as CallToolResult["content"];
  return {
    content,
    ...(part.structuredContent !== undefined
      ? {
          structuredContent: part.structuredContent as Record<string, unknown>,
        }
      : {}),
    ...(part.meta !== undefined ? { _meta: part.meta } : {}),
  };
}

export function McpUiApp({ part, onDismiss }: McpUiAppProps) {
  const styles = useStyles();
  const { theme } = useTheme();
  const { getMcpClient } = useChat();
  const iframeRef = useRef<HTMLIFrameElement | null>(null);
  const bridgeRef = useRef<AppBridge | null>(null);
  const bridgeReadyRef = useRef(false);
  const partRef = useRef(part);
  partRef.current = part;
  const getMcpClientRef = useRef(getMcpClient);
  getMcpClientRef.current = getMcpClient;
  const [height, setHeight] = useState<number>(DEFAULT_IFRAME_HEIGHT);
  const [error, setError] = useState<string | null>(null);

  // Bridge lifecycle: re-create ONLY when the iframe's HTML or origin
  // server connection changes — NOT when a new tool call delivers fresh
  // input/result for the same view. The push effect below forwards the
  // new tool input/result via `sendToolInput`/`sendToolResult` so the
  // mounted iframe updates in place across tool calls, preserving its
  // internal state (URL bar contents, scroll position, etc.). Theme
  // changes propagate via `sendHostContextChange` in a separate effect.
  // biome-ignore lint/correctness/useExhaustiveDependencies: `theme`, `getMcpClient`, and per-call result fields are intentionally captured via refs / pushed via separate effects; rebuilding the iframe on those changes would lose the view's local state.
  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe || !iframe.contentWindow) return undefined;

    const client = getMcpClientRef.current();
    const connectionId = part.ui.connectionId;

    const bridge = new AppBridge(
      null,
      { name: "OfficeAI MCP Host", version: "1.0.0" },
      {
        openLinks: {},
        // The host advertises tools/resources support so the view feels
        // free to call back. Concrete forwarding is wired below.
        serverTools: client && connectionId ? {} : undefined,
        serverResources: client && connectionId ? {} : undefined,
      },
      {
        hostContext: {
          theme,
          platform: "web",
          containerDimensions: {
            width: iframe.clientWidth || undefined,
            maxHeight: MAX_IFRAME_HEIGHT,
          },
          displayMode: "inline",
          availableDisplayModes: ["inline"],
        },
      },
    );

    bridgeRef.current = bridge;

    // ----- Host services back to the iframe -----
    bridge.onopenlink = async ({ url }) => {
      try {
        window.open(url, "_blank", "noopener,noreferrer");
      } catch (err) {
        console.warn("[MCP UI] openlink blocked:", err);
      }
      return {};
    };

    bridge.onloggingmessage = (params) => {
      const tag = `[MCP App:${part.toolName}]`;
      const level = params.level;
      const data = params.data;
      if (level === "error") console.error(tag, data);
      else if (level === "warning") console.warn(tag, data);
      else console.log(tag, data);
    };

    bridge.onsizechange = async ({ height: requested }) => {
      if (typeof requested === "number" && Number.isFinite(requested)) {
        const clamped = Math.max(
          MIN_IFRAME_HEIGHT,
          Math.min(MAX_IFRAME_HEIGHT, Math.round(requested)),
        );
        setHeight(clamped);
      }
      return {};
    };

    // We deliberately ignore `onupdatemodelcontext` and `onmessage` in
    // v1 — surfacing those into the agent conversation needs careful
    // UX work (permissions, source attribution, dedup) and is tracked
    // separately. We still register no-op handlers so a chatty view
    // doesn't get "no handler" rejections.
    bridge.onupdatemodelcontext = async () => ({});
    bridge.onmessage = async () => ({});

    // ----- Forwarders for iframe-initiated MCP requests -----
    if (client && connectionId) {
      bridge.oncalltool = async (params, extra) => {
        const result = await client.callTool({
          connectionId,
          remoteToolName: params.name,
          arguments: (params.arguments ?? {}) as Record<string, unknown>,
          signal: extra.signal,
        });
        // Forward `_meta` and `structuredContent` through so the iframe
        // sees the same MCP shape the model does.
        const payload: CallToolResult = {
          content: result.content as CallToolResult["content"],
          _meta: result.meta,
          structuredContent: result.structuredContent as
            | Record<string, unknown>
            | undefined,
        };
        return payload;
      };

      if (client.readResource) {
        bridge.onreadresource = async (
          params,
          extra,
        ): Promise<ReadResourceResult> => {
          const read = await client.readResource!({
            connectionId,
            uri: params.uri,
            signal: extra.signal,
            interactiveAllowed: false,
          });
          return read as ReadResourceResult;
        };
      }

      const listResources = (
        client as MCPInvocationClient & {
          listResources?: (req: {
            connectionId: string;
            signal?: AbortSignal;
            interactiveAllowed?: boolean;
          }) => Promise<{ uri: string; mimeType?: string; name?: string }[]>;
        }
      ).listResources;
      if (listResources) {
        bridge.onlistresources = async (
          _params,
          extra,
        ): Promise<ListResourcesResult> => {
          const resources = await listResources({
            connectionId,
            signal: extra.signal,
            interactiveAllowed: false,
          });
          return {
            resources: resources.map((r) => ({
              uri: r.uri,
              mimeType: r.mimeType,
              name: r.name ?? r.uri,
            })),
          };
        };
      }
    }

    // ----- Connect bridge and drive the lifecycle -----
    const transport = new PostMessageTransport(
      iframe.contentWindow,
      iframe.contentWindow,
    );

    let cancelled = false;
    const oninitialized = new Promise<void>((resolve) => {
      bridge.oninitialized = () => {
        resolve();
      };
    });

    (async () => {
      try {
        await bridge.connect(transport);
        await oninitialized;
        if (cancelled) return;
        // Push the part that's current at the moment the bridge is ready
        // (which may differ from the one captured at mount-effect-start
        // if a new tool call landed during the async connect).
        const latest = partRef.current;
        bridge.sendToolInput({ arguments: latest.input });
        bridge.sendToolResult(buildCallToolResult(latest));
        bridgeReadyRef.current = true;
      } catch (err) {
        if (cancelled) return;
        const message = err instanceof Error ? err.message : String(err);
        console.error("[MCP UI] bridge connect failed:", err);
        setError(message);
      }
    })();

    return () => {
      cancelled = true;
      bridgeReadyRef.current = false;
      bridge.close().catch(() => undefined);
      if (bridgeRef.current === bridge) bridgeRef.current = null;
    };
  }, [part.ui.html, part.ui.connectionId]);

  // Push fresh tool input + result to the existing bridge whenever a new
  // tool call arrives for the same iframe. Skips the first run after a
  // (re)mount — the mount-effect already pushed the latest part itself.
  // biome-ignore lint/correctness/useExhaustiveDependencies: depending on the whole `part` object would fire on every render (parts are recreated when chat state rebuilds); we only want to push when the actual tool-result payload changes.
  useEffect(() => {
    if (!bridgeReadyRef.current) return;
    const bridge = bridgeRef.current;
    if (!bridge) return;
    try {
      bridge.sendToolInput({ arguments: part.input });
      bridge.sendToolResult(buildCallToolResult(part));
    } catch (err) {
      console.warn("[MCP UI] failed to push updated tool result:", err);
    }
  }, [
    part.toolCallId,
    part.input,
    part.content,
    part.structuredContent,
    part.meta,
    part.resultText,
  ]);

  // Push theme changes without rebuilding the iframe.
  useEffect(() => {
    const bridge = bridgeRef.current;
    if (!bridge) return;
    try {
      bridge.sendHostContextChange({ theme });
    } catch (err) {
      console.warn("[MCP UI] sendHostContextChange failed:", err);
    }
  }, [theme]);

  return (
    <div className={styles.container} data-mcp-tool={part.toolName}>
      <div className={styles.header}>
        <span>{part.toolName}</span>
        <div className={styles.headerRight}>
          <span className={styles.serverLabel}>
            {part.ui.serverLabel ?? "MCP App"}
          </span>
          {onDismiss && (
            <Button
              appearance="subtle"
              size="small"
              icon={<DismissRegular />}
              aria-label={`Dismiss ${part.toolName} MCP App view`}
              title="Dismiss this MCP App view"
              className={styles.dismissButton}
              onClick={onDismiss}
            />
          )}
        </div>
      </div>
      {error && (
        <div className={styles.fallback}>
          MCP App failed to initialize: {error}
          {part.resultText ? `\n\n${part.resultText}` : null}
        </div>
      )}
      <iframe
        ref={iframeRef}
        srcDoc={part.ui.html}
        sandbox="allow-scripts allow-forms"
        title={`MCP App: ${part.toolName}`}
        className={styles.iframe}
        style={{ height }}
      />
    </div>
  );
}
