import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import {
  type WordAnchor,
  anchorMatchesParagraphText,
  findLiteralMatchOffsets,
  getAnchorDocumentParagraphIndex,
  getAnchorOccurrenceIndex,
  getAnchorScopeParagraphIndex,
  wordAnchorSchema,
} from "./word-anchor-utils";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

type SearchOptions = {
  matchCase: boolean;
  matchWholeWord: boolean;
  matchWildcards: boolean;
};

type HyperlinkTarget = {
  target: {
    search(searchText: string, options: SearchOptions): Word.RangeCollection;
  };
  paragraphIndex: number | null;
  scopeParagraphIndex: number | null;
  paragraphText?: string;
};

export const setHyperlinkTool = defineTool({
  name: "set_hyperlink",
  category: "deliverable",
  parallelSafe: false,
  label: "Set Hyperlink",
  description:
    "Turn one existing text match in a Word document into a clickable hyperlink without changing its visible text. " +
    "Use the anchor returned by search_document to target repeated text safely. " +
    "Call this as soon as one reference and destination URL are known; do not collect every reference first. " +
    "The result confirms the outcome (changed:true for a new link, alreadyLinked:true when the match already points to this URL), so treat it as verification and never re-link the same reference to the same URL.",
  parameters: Type.Object({
    searchText: Type.String({
      description: "The exact existing visible text to make clickable",
      minLength: 1,
    }),
    url: Type.String({
      description: "Absolute http, https, or mailto destination URL",
      minLength: 1,
    }),
    scope: Type.Union(
      [
        Type.Literal("body", { description: "Search the document body" }),
        Type.Literal("selection", {
          description: "Search within the current selection",
        }),
      ],
      { description: "Where to find the visible text", default: "body" },
    ),
    matchCase: Type.Optional(
      Type.Boolean({ description: "Match case exactly. Default: false" }),
    ),
    matchWholeWord: Type.Optional(
      Type.Boolean({
        description: "Match whole words only. Default: false",
      }),
    ),
    anchor: Type.Optional(wordAnchorSchema),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the hyperlink edit (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);
      const url = normalizeHyperlinkUrl(params.url);

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          true,
          async () => {
            const hyperlinkTarget = await resolveHyperlinkTarget(
              context,
              params.scope,
              params.anchor,
              signal,
            );
            const searchResult = hyperlinkTarget.target.search(
              params.searchText,
              {
                matchCase: params.matchCase ?? false,
                matchWholeWord: params.matchWholeWord ?? false,
                matchWildcards: false,
              },
            );

            searchResult.load("items/text");
            await syncWordContext(context, signal);

            if (searchResult.items.length === 0) {
              return {
                applied: false,
                linked: 0,
                searchText: params.searchText,
                url,
                anchorUsed: Boolean(params.anchor),
                message: `No matches found for "${params.searchText}"`,
              };
            }

            const targetRange = selectTargetRange(
              searchResult.items,
              params.searchText,
              params.matchCase ?? false,
              params.anchor,
              hyperlinkTarget.paragraphText,
            );

            if (!targetRange) {
              return {
                applied: false,
                linked: 0,
                ambiguous: searchResult.items.length > 1,
                totalMatches: searchResult.items.length,
                searchText: params.searchText,
                url,
                anchorUsed: Boolean(params.anchor),
                message:
                  searchResult.items.length > 1
                    ? "Multiple matches found. Pass an anchor from search_document to select one safely."
                    : "The supplied anchor did not resolve to the text match.",
              };
            }

            throwIfToolAborted(signal);
            targetRange.load("hyperlink");
            await syncWordContext(context, signal);

            const existingHyperlink = (targetRange.hyperlink ?? "").trim();
            if (
              existingHyperlink &&
              hyperlinksEquivalent(existingHyperlink, url)
            ) {
              return {
                applied: true,
                changed: false,
                alreadyLinked: true,
                linked: 1,
                searchText: params.searchText,
                url,
                anchorUsed: Boolean(params.anchor),
                paragraphIndex: hyperlinkTarget.paragraphIndex,
                scopeParagraphIndex: hyperlinkTarget.scopeParagraphIndex,
                totalMatches: searchResult.items.length,
                message: `"${params.searchText}" is already linked to this URL; no change made.`,
              };
            }

            throwIfToolAborted(signal);
            targetRange.hyperlink = url;
            await syncWordContext(context, signal);

            return {
              applied: true,
              changed: true,
              alreadyLinked: false,
              linked: 1,
              searchText: params.searchText,
              url,
              previousUrl: existingHyperlink || undefined,
              anchorUsed: Boolean(params.anchor),
              paragraphIndex: hyperlinkTarget.paragraphIndex,
              scopeParagraphIndex: hyperlinkTarget.scopeParagraphIndex,
              totalMatches: searchResult.items.length,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown hyperlink error";
      return toolError(message);
    }
  },
});

function normalizeHyperlinkUrl(value: string): string {
  const trimmed = value.trim();
  let parsed: URL;

  try {
    parsed = new URL(trimmed);
  } catch {
    throw new Error(
      "Hyperlink URL must be an absolute http, https, or mailto URL.",
    );
  }

  if (!new Set(["http:", "https:", "mailto:"]).has(parsed.protocol)) {
    throw new Error(
      "Hyperlink URL must use the http, https, or mailto protocol.",
    );
  }

  return trimmed;
}

function hyperlinksEquivalent(a: string, b: string): boolean {
  return (
    normalizeHyperlinkForComparison(a) === normalizeHyperlinkForComparison(b)
  );
}

function normalizeHyperlinkForComparison(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) {
    return "";
  }

  return trimmed.replace(/\/+$/, "").toLowerCase();
}

async function resolveHyperlinkTarget(
  context: Word.RequestContext,
  scope: "body" | "selection",
  anchor: WordAnchor | undefined,
  signal?: AbortSignal,
): Promise<HyperlinkTarget> {
  if (!anchor) {
    return {
      target:
        scope === "selection"
          ? context.document.getSelection()
          : context.document.body,
      paragraphIndex: null,
      scopeParagraphIndex: null,
    };
  }

  const documentParagraphIndex = getAnchorDocumentParagraphIndex(anchor);
  if (documentParagraphIndex !== null) {
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    const paragraph = paragraphs.items[documentParagraphIndex];
    if (!paragraph) {
      throw new Error(
        `Anchor paragraphIndex ${documentParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }
    if (!anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
      throw new Error(
        "Anchor no longer matches the target paragraph. Read or search the target again before editing.",
      );
    }

    return {
      target: paragraph,
      paragraphIndex: documentParagraphIndex,
      scopeParagraphIndex: getAnchorScopeParagraphIndex(anchor),
      paragraphText: paragraph.text ?? "",
    };
  }

  const scopeParagraphIndex = getAnchorScopeParagraphIndex(anchor);
  if (scopeParagraphIndex === null) {
    throw new Error(
      "Anchor does not identify a paragraph. Use an anchor returned by search_document.",
    );
  }

  const paragraphs =
    scope === "selection"
      ? context.document.getSelection().paragraphs
      : context.document.body.paragraphs;
  paragraphs.load("items/text");
  await syncWordContext(context, signal);

  const paragraph = paragraphs.items[scopeParagraphIndex];
  if (!paragraph) {
    throw new Error(
      `Anchor scopeParagraphIndex ${scopeParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
    );
  }
  if (!anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
    throw new Error(
      "Anchor no longer matches the target paragraph. Read or search the target again before editing.",
    );
  }

  return {
    target: paragraph,
    paragraphIndex: scope === "body" ? scopeParagraphIndex : null,
    scopeParagraphIndex,
    paragraphText: paragraph.text ?? "",
  };
}

function selectTargetRange(
  ranges: Word.Range[],
  searchText: string,
  matchCase: boolean,
  anchor: WordAnchor | undefined,
  paragraphText: string | undefined,
): Word.Range | null {
  const occurrenceIndex = getAnchorOccurrenceIndex(anchor);
  if (occurrenceIndex !== null) {
    return ranges[occurrenceIndex] ?? null;
  }

  if (
    anchor?.startOffsetInParagraph !== undefined &&
    paragraphText !== undefined
  ) {
    const offsets = findLiteralMatchOffsets(
      paragraphText,
      searchText,
      matchCase,
    );
    const matchingRangeIndex = offsets.indexOf(anchor.startOffsetInParagraph);
    return matchingRangeIndex === -1
      ? null
      : (ranges[matchingRangeIndex] ?? null);
  }

  return ranges.length === 1 ? (ranges[0] ?? null) : null;
}
