/**
 * Structured TODO state — schema + validator (PR-A).
 *
 * See:
 *   - docs/structured-todos-blueprint.md §3, §5
 *   - docs/structured-todos-implementation-plan.md PR-A
 *
 * The model produces these via the `update_todos` tool; the orchestrator
 * intercepts the tool call, validates the payload here, and dispatches a
 * single `update_todos` action through `apply()` so the run state stays
 * the sole mutator. See `plan-schema.ts` for the sibling planner schemas
 * (`submit_plan` / `submit_qc_report`) that this file mirrors.
 */

import { type Static, Type } from "@sinclair/typebox";
import { Value } from "@sinclair/typebox/value";
import type { PlannerValidationResult } from "./plan-schema";

export type TodoStatus = "pending" | "in_progress" | "completed" | "cancelled";

export const TodoSchema = Type.Object(
  {
    id: Type.String({ minLength: 1 }),
    content: Type.String({ minLength: 1 }),
    /**
     * Present-continuous phrasing rendered in the UI while the item is
     * `in_progress` (e.g. "Reading uploaded CSV"). Mirrors deepagents'
     * `activeForm` field. Required so the UI never has to derive it from
     * `content` heuristically.
     */
    activeForm: Type.String({ minLength: 1 }),
    status: Type.Union([
      Type.Literal("pending"),
      Type.Literal("in_progress"),
      Type.Literal("completed"),
      Type.Literal("cancelled"),
    ]),
    /** Optional one-line evidence after status change (e.g. read-back result). */
    evidence: Type.Optional(Type.String()),
  },
  { additionalProperties: false },
);

export const UpdateTodosRequestSchema = Type.Object(
  { todos: Type.Array(TodoSchema, { minItems: 1 }) },
  { additionalProperties: false },
);

export type Todo = Static<typeof TodoSchema>;
export type UpdateTodosRequest = Static<typeof UpdateTodosRequestSchema>;

export const UPDATE_TODOS_TOOL_NAME = "update_todos";

function requiresExecution(status: TodoStatus): boolean {
  return status === "pending" || status === "in_progress";
}

/**
 * True when a TODO update establishes or selects executable work that was
 * not active in the previous list. Wording/evidence churn on an already
 * active item does not advance work. A first list containing only one
 * `in_progress` item is treated as retroactive bookkeeping: models commonly
 * report the item immediately after its write. Multiple items or any pending
 * item establish a real work queue.
 */
export function todosAdvanceExecutableWork(
  before: Todo[],
  after: Todo[],
): boolean {
  if (before.length === 0) {
    if (after.some((todo) => todo.status === "pending")) return true;
    return (
      after.length > 1 && after.some((todo) => todo.status === "in_progress")
    );
  }

  const previousById = new Map(before.map((todo) => [todo.id, todo]));
  return after.some((todo) => {
    if (!requiresExecution(todo.status)) return false;
    const previous = previousById.get(todo.id);
    return previous === undefined || previous.status !== todo.status;
  });
}

function collectErrors(schema: unknown, value: unknown): string[] {
  const errors: string[] = [];
  for (const error of Value.Errors(
    schema as Parameters<typeof Value.Errors>[0],
    value,
  )) {
    const path = error.path === "" ? "(root)" : error.path;
    errors.push(`${path}: ${error.message}`);
  }
  return errors;
}

/**
 * Validate a candidate `update_todos` payload. Returns a discriminated
 * union so the orchestrator can either consume the typed value or feed
 * the validator errors back as a `plan_schema_invalid` nudge.
 */
export function validateUpdateTodos(
  candidate: unknown,
): PlannerValidationResult<UpdateTodosRequest> {
  if (!Value.Check(UpdateTodosRequestSchema, candidate)) {
    return {
      ok: false,
      errors: collectErrors(UpdateTodosRequestSchema, candidate),
    };
  }
  return { ok: true, value: candidate };
}

const VERB_TO_ING: ReadonlyArray<readonly [RegExp, string]> = [
  [/^read$/i, "Reading"],
  [/^write$/i, "Writing"],
  [/^create$/i, "Creating"],
  [/^generate$/i, "Generating"],
  [/^compute$/i, "Computing"],
  [/^analyze$/i, "Analyzing"],
  [/^analyse$/i, "Analysing"],
  [/^validate$/i, "Validating"],
  [/^verify$/i, "Verifying"],
  [/^update$/i, "Updating"],
  [/^build$/i, "Building"],
  [/^run$/i, "Running"],
  [/^search$/i, "Searching"],
  [/^summarize$/i, "Summarizing"],
  [/^summarise$/i, "Summarising"],
  [/^review$/i, "Reviewing"],
  [/^check$/i, "Checking"],
  [/^plan$/i, "Planning"],
  [/^load$/i, "Loading"],
  [/^save$/i, "Saving"],
  [/^send$/i, "Sending"],
  [/^extract$/i, "Extracting"],
  [/^process$/i, "Processing"],
  [/^prepare$/i, "Preparing"],
  [/^add$/i, "Adding"],
  [/^remove$/i, "Removing"],
  [/^fix$/i, "Fixing"],
  [/^transform$/i, "Transforming"],
  [/^parse$/i, "Parsing"],
];

/**
 * Best-effort present-continuous transformer for seeding `Todo.activeForm`
 * from a plan step's title (PR-B). When the heuristic does not match the
 * first token, the original title is returned verbatim — the model is
 * expected to rewrite it on the first `update_todos` call.
 *
 * Examples:
 *   "Read CSV"          → "Reading CSV"
 *   "Validate totals"   → "Validating totals"
 *   "Unknown phrasing"  → "Unknown phrasing" (no leading verb match)
 */
export function derivedActiveForm(title: string): string {
  const trimmed = title.trim();
  if (!trimmed) return title;
  const match = trimmed.match(/^(\S+)(.*)$/);
  if (!match) return trimmed;
  const firstWord = match[1];
  const rest = match[2] ?? "";
  for (const [pattern, replacement] of VERB_TO_ING) {
    if (pattern.test(firstWord)) {
      return `${replacement}${rest}`;
    }
  }
  return trimmed;
}
