import type { QuickJSContext, QuickJSHandle } from "quickjs-emscripten-core";
import type { JsRunError } from "./types";

function toErrorLike(value: unknown): JsRunError {
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return {
      name: typeof record.name === "string" ? record.name : "Error",
      message:
        typeof record.message === "string" ? record.message : String(value),
      stack: typeof record.stack === "string" ? record.stack : undefined,
    };
  }

  return {
    name: "Error",
    message: String(value),
  };
}

export function errorFromUnknown(error: unknown): JsRunError {
  if (error instanceof Error) {
    return {
      name: error.name || "Error",
      message: error.message,
      stack: error.stack,
    };
  }
  return toErrorLike(error);
}

export function errorFromHandle(
  context: QuickJSContext,
  handle: QuickJSHandle,
): JsRunError {
  try {
    return toErrorLike(context.dump(handle));
  } catch {
    try {
      return {
        name: "Error",
        message: context.getString(handle),
      };
    } catch {
      return {
        name: "Error",
        message: "QuickJS execution failed",
      };
    }
  }
}

function assertJsonSafe(value: unknown, seen: WeakSet<object>): void {
  if (value === null || value === undefined) return;
  const valueType = typeof value;
  if (valueType === "function" || valueType === "symbol") {
    throw new Error(`Cannot report ${valueType} values`);
  }
  if (valueType === "bigint") {
    throw new Error("Cannot report bigint values; convert them to strings");
  }
  if (valueType !== "object") return;
  const objectValue = value as object;

  if (seen.has(objectValue)) {
    throw new Error("Cannot report cyclic objects");
  }
  seen.add(objectValue);

  if (Array.isArray(value)) {
    for (const item of value) assertJsonSafe(item, seen);
    return;
  }

  for (const item of Object.values(value as Record<string, unknown>)) {
    assertJsonSafe(item, seen);
  }
}

export function marshalHandle(
  context: QuickJSContext,
  handle: QuickJSHandle,
): unknown {
  const handleType = context.typeof(handle);
  if (handleType === "function" || handleType === "symbol") {
    throw new Error(`Cannot report ${handleType} values`);
  }

  const dumped = context.dump(handle);
  assertJsonSafe(dumped, new WeakSet());

  if (dumped === undefined) return undefined;
  return JSON.parse(JSON.stringify(dumped)) as unknown;
}

export function formatHostValue(value: unknown): string {
  if (typeof value === "string") return value;
  if (value === undefined) return "undefined";
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}
