import type { AccessToken, GetTokenOptions } from "@azure/core-auth";
import {
  AuthenticationRequiredError,
  InteractiveBrowserCredential,
} from "@azure/identity";
import { captureEntraIdentityFromAccessToken } from "../../entra-identity";
import type { MCPAuthConfig } from "./types";

type EntraAuthConfig = Extract<MCPAuthConfig, { type: "entra" }>;

export interface EntraTokenRequest {
  connectionId: string;
  auth: EntraAuthConfig;
  interactiveAllowed?: boolean;
  signal?: AbortSignal;
}

export type EntraTokenError =
  | { kind: "interactive_required" }
  | { kind: "unauthorized"; cause: unknown }
  | { kind: "aborted" }
  | { kind: "transient"; cause: unknown };

export interface EntraTokenProvider {
  getToken(request: EntraTokenRequest): Promise<string>;
  invalidate(request: Pick<EntraTokenRequest, "connectionId" | "auth">): void;
}

export interface TokenCredentialLike {
  getToken(
    scopes: string | string[],
    options?: GetTokenOptions,
  ): Promise<AccessToken | null>;
}

export interface BrowserEntraTokenProviderOptions {
  now?: () => number;
  credentialFactory?: (options: {
    tenantId: string;
    clientId: string;
    redirectUri?: string;
    disableAutomaticAuthentication?: boolean;
  }) => TokenCredentialLike;
}

interface CacheEntry {
  token: string | null;
  expiresOnMs: number;
  inflight: Promise<string> | null;
  silentCredential: TokenCredentialLike | null;
  interactiveCredential: TokenCredentialLike | null;
}

const TOKEN_EXPIRY_SKEW_MS = 5 * 60 * 1000;

export function isEntraTokenError(value: unknown): value is EntraTokenError {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    (value as { kind?: unknown }).kind !== undefined
  );
}

function defaultRedirectUri(): string | undefined {
  if (typeof window === "undefined") return undefined;
  return `${window.location.origin}/taskpane.html`;
}

function cacheKey(auth: EntraAuthConfig): string {
  const redirectUri = auth.redirectUri?.trim() || defaultRedirectUri() || "";
  const scopes = [...auth.scopes].sort().join(" ");
  return `${auth.tenantId}|${auth.clientId}|${redirectUri}|${scopes}`;
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

function isAuthenticationRequired(error: unknown): boolean {
  return (
    error instanceof AuthenticationRequiredError ||
    (error instanceof Error && error.name === "AuthenticationRequiredError")
  );
}

function credentialFor(
  entry: CacheEntry,
  auth: EntraAuthConfig,
  interactiveAllowed: boolean,
  credentialFactory: NonNullable<
    BrowserEntraTokenProviderOptions["credentialFactory"]
  >,
): TokenCredentialLike {
  const redirectUri = auth.redirectUri?.trim() || defaultRedirectUri();
  if (interactiveAllowed) {
    if (!entry.interactiveCredential) {
      entry.interactiveCredential = credentialFactory({
        tenantId: auth.tenantId,
        clientId: auth.clientId,
        redirectUri,
      });
    }
    return entry.interactiveCredential;
  }

  if (!entry.silentCredential) {
    entry.silentCredential = credentialFactory({
      tenantId: auth.tenantId,
      clientId: auth.clientId,
      redirectUri,
      disableAutomaticAuthentication: true,
    });
  }
  return entry.silentCredential;
}

export class BrowserEntraTokenProvider implements EntraTokenProvider {
  private readonly now: () => number;
  private readonly credentialFactory: NonNullable<
    BrowserEntraTokenProviderOptions["credentialFactory"]
  >;
  private readonly cache = new Map<string, CacheEntry>();

  constructor(options: BrowserEntraTokenProviderOptions = {}) {
    this.now = options.now ?? (() => Date.now());
    this.credentialFactory =
      options.credentialFactory ??
      ((credentialOptions) =>
        new InteractiveBrowserCredential(credentialOptions));
  }

  async getToken(request: EntraTokenRequest): Promise<string> {
    if (request.signal?.aborted) {
      throw { kind: "aborted" } satisfies EntraTokenError;
    }

    const key = cacheKey(request.auth);
    const entry = this.cache.get(key) ?? {
      token: null,
      expiresOnMs: 0,
      inflight: null,
      silentCredential: null,
      interactiveCredential: null,
    };
    this.cache.set(key, entry);

    if (entry.token && entry.expiresOnMs - this.now() > TOKEN_EXPIRY_SKEW_MS) {
      return entry.token;
    }

    if (entry.inflight) {
      return entry.inflight;
    }

    const interactiveAllowed = request.interactiveAllowed !== false;
    entry.inflight = this.acquire(entry, request, interactiveAllowed);
    try {
      return await entry.inflight;
    } finally {
      entry.inflight = null;
    }
  }

  invalidate(request: Pick<EntraTokenRequest, "connectionId" | "auth">): void {
    void request.connectionId;
    const entry = this.cache.get(cacheKey(request.auth));
    if (!entry) return;
    entry.token = null;
    entry.expiresOnMs = 0;
    entry.inflight = null;
  }

  private async acquire(
    entry: CacheEntry,
    request: EntraTokenRequest,
    interactiveAllowed: boolean,
  ): Promise<string> {
    const credential = credentialFor(
      entry,
      request.auth,
      interactiveAllowed,
      this.credentialFactory,
    );

    try {
      const token = await credential.getToken(request.auth.scopes, {
        abortSignal: request.signal,
      });
      if (!token?.token) {
        throw {
          kind: "unauthorized",
          cause: new Error("Entra returned no access token"),
        } satisfies EntraTokenError;
      }
      entry.token = token.token;
      entry.expiresOnMs = token.expiresOnTimestamp;
      captureEntraIdentityFromAccessToken(token.token);
      return token.token;
    } catch (error) {
      if (isEntraTokenError(error)) {
        throw error;
      }
      if (request.signal?.aborted || isAbortError(error)) {
        throw { kind: "aborted" } satisfies EntraTokenError;
      }
      if (isAuthenticationRequired(error)) {
        throw (
          interactiveAllowed
            ? { kind: "unauthorized", cause: error }
            : { kind: "interactive_required" }
        ) satisfies EntraTokenError;
      }
      throw { kind: "transient", cause: error } satisfies EntraTokenError;
    }
  }
}

export const defaultEntraTokenProvider = new BrowserEntraTokenProvider();
