type TerminalLineKind = "command" | "stdout" | "stderr" | "meta";
type FileRenderMode = "text" | "html" | "pdf" | "image" | "binary";

interface TerminalLine {
  id: string;
  kind: TerminalLineKind;
  text: string;
}

const DEFAULT_TERMINAL_HEIGHT = 240;
const MIN_TERMINAL_HEIGHT = 160;
const MIN_EDITOR_HEIGHT = 200;
const TERMINAL_RESIZE_STEP = 24;
const TERMINAL_SPLITTER_SIZE = 12;

const IMAGE_MIME_TYPES: Record<string, string> = {
  apng: "image/apng",
  avif: "image/avif",
  gif: "image/gif",
  jpeg: "image/jpeg",
  jpg: "image/jpeg",
  png: "image/png",
  svg: "image/svg+xml",
  webp: "image/webp",
};

const BINARY_FILE_EXTENSIONS = new Set([
  "7z",
  "doc",
  "docx",
  "gz",
  "heic",
  "heif",
  "mov",
  "mp3",
  "mp4",
  "ppt",
  "pptx",
  "rar",
  "tar",
  "wav",
  "xls",
  "xlsm",
  "xlsx",
  "zip",
]);

function getFileExtension(path: string): string {
  const filename = path.split("/").pop() ?? path;
  const extensionStart = filename.lastIndexOf(".");
  if (extensionStart < 0 || extensionStart === filename.length - 1) return "";
  return filename.slice(extensionStart + 1).toLowerCase();
}

function getFileRenderMode(path: string): FileRenderMode {
  const extension = getFileExtension(path);
  if (extension === "pdf") return "pdf";
  if (extension === "html" || extension === "htm") return "html";
  if (IMAGE_MIME_TYPES[extension]) return "image";
  if (BINARY_FILE_EXTENSIONS.has(extension)) return "binary";
  return "text";
}

function getBinaryFileDescription(path: string): string {
  const extension = getFileExtension(path);
  return extension ? `.${extension.toUpperCase()} binary file` : "Binary file";
}

function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const copy = new Uint8Array(new ArrayBuffer(bytes.byteLength));
  copy.set(bytes);
  return copy.buffer;
}

