/**
 * Fresh-per-turn context reset (blueprint: chat-context.tsx + agent.prompt).
 *
 * The Office Add-in agent normally retains its entire message history (user
 * prompts, assistant turns, tool calls, tool results) across every user
 * turn. With MCP tool schemas, large tool-result payloads, and per-prompt
 * `<wb_context>` / `<attachments>` / `<llm_wiki>` enrichment, this quickly
 * blows the model's max-prompt-tokens budget.
 *
 * This module supplies the building blocks for a "fresh context per user
 * turn" mode: at the top of {@link Agent.prompt} we replace the agent's
 * `internalState.messages` with a single bounded synthetic summary message
 * before pushing the new user turn. The model still receives a compact
 * record of what happened in earlier turns, but the verbose history (tool
 * payloads, redundant assistant prose, enrichment headers) is dropped.
 *
 * The summary is rendered as a `[SYSTEM: ...]`-style user message so it
 * works across every provider without requiring a new role. A markdown
 * mirror can optionally be written to {@link CONVERSATION_SUMMARY_WIKI_PATH}
 * so the model can `bash cat` / `read` the longer form on demand.
 */

import { stripEnrichment } from "../message-utils";
import type {
  AgentMessage,
  AssistantMessage,
  ToolResultMessage,
  UserMessage,
} from "./types";

/**
 * `stripEnrichment` only peels one `^`-anchored prefix block per call, so
 * a user prompt with stacked `<attachments>` + `<wb_context>` enrichment
 * needs a fix-point loop to reach the real prose.
 */
function stripAllEnrichment(content: string): string {
  let previous = content;
  let next = stripEnrichment(previous);
  while (next !== previous) {
    previous = next;
    next = stripEnrichment(previous);
  }
  return next;
}

/** Default cap for the synthetic summary user message, in characters. */
export const DEFAULT_CONTEXT_SUMMARY_MAX_CHARS = 2000;

/** Hard floor so the cap can never collapse the summary to nothing. */
export const MIN_CONTEXT_SUMMARY_MAX_CHARS = 200;

/** VFS path for the optional long-form summary mirror. */
export const CONVERSATION_SUMMARY_WIKI_PATH =
  "/home/user/uploads/working-set/conversation-summary.md";

export interface PriorTurnSummaryOptions {
  /**
   * Hard cap on the synthetic summary user message body, in characters.
   * Defaults to {@link DEFAULT_CONTEXT_SUMMARY_MAX_CHARS}. Values below
   * {@link MIN_CONTEXT_SUMMARY_MAX_CHARS} are clamped.
   */
  maxChars?: number;
  /**
   * Optional cap on the markdown working-set mirror. Defaults to
   * `maxChars * 8`, so the long-form artifact can carry more detail
   * (the model can `cat` it on demand) without itself being unbounded.
   */
  wikiMaxChars?: number;
}

export interface PriorTurnSummary {
  /** Compact one-line-per-section text safe to inject as a single message. */
  summaryText: string;
  /** Longer markdown form intended for the working-set artifact. */
  wikiMarkdown: string;
  /** Number of distinct user turns observed in the prior history. */
  turnsCount: number;
  /** Number of executed tool calls observed in the prior history. */
  toolCallsCount: number;
  /** True when {@link summaryText} reached the configured `maxChars` cap. */
  truncated: boolean;
}

interface ToolExecution {
  name: string;
  ok: boolean;
  resultText: string;
}

interface ExtractedTrace {
  userPrompts: string[];
  toolExecutions: ToolExecution[];
  lastAssistantText: string;
  writtenPaths: Set<string>;
  dirtyRangeCount: number;
  /**
   * Inner payload of the most recent `[SYSTEM: Conversation summary
   * (older turns dropped for fresh context): ...]` message observed in
   * the prior history, if any. Carried forward so that successive resets
   * do not silently drop older turns — turn N still sees a compacted
   * trace of turns 1..N-1 instead of only turn N-1.
   */
  priorSummaryText: string;
}

/**
 * Marker used to recognize a prior fresh-context summary message so we
 * can carry its inner text forward across successive resets. Must match
 * the literal prefix produced by {@link buildFreshContextMessage}.
 */
const PRIOR_SUMMARY_PREFIX =
  "[SYSTEM: Conversation summary (older turns dropped for fresh context): ";

function extractPriorSummaryPayload(content: string): string | null {
  const trimmed = content.trim();
  if (!trimmed.startsWith(PRIOR_SUMMARY_PREFIX)) return null;
  if (!trimmed.endsWith("]")) return null;
  const inner = trimmed
    .slice(PRIOR_SUMMARY_PREFIX.length, trimmed.length - 1)
    .trim();
  return inner.length > 0 ? inner : null;
}

function clampMaxChars(value: number | undefined): number {
  if (!Number.isFinite(value ?? Number.NaN) || (value as number) <= 0) {
    return DEFAULT_CONTEXT_SUMMARY_MAX_CHARS;
  }
  return Math.max(MIN_CONTEXT_SUMMARY_MAX_CHARS, Math.floor(value as number));
}

function toolResultText(msg: ToolResultMessage): string {
  return msg.content
    .filter((c): c is { type: "text"; text: string } => c.type === "text")
    .map((c) => c.text)
    .join("\n");
}

function safeJsonParse(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

function extractWrittenPath(toolName: string, args: unknown): string | null {
  if (!args || typeof args !== "object") return null;
  const lowered = toolName.toLowerCase();
  if (lowered === "write_file" || lowered === "append_file") {
    const path = (args as { path?: unknown }).path;
    if (typeof path === "string" && path.trim().length > 0) {
      return path;
    }
  }
  return null;
}

function compactWhitespace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function truncateText(text: string, max: number): string {
  if (text.length <= max) return text;
  if (max <= 3) return text.slice(0, max);
  const keepEach = Math.floor((max - 3) / 2);
  return `${text.slice(0, keepEach)}...${text.slice(-keepEach)}`;
}

function extractTrace(messages: AgentMessage[]): ExtractedTrace {
  const userPrompts: string[] = [];
  const toolExecutions: ToolExecution[] = [];
  const writtenPaths = new Set<string>();
  const toolCallNamesById = new Map<string, string>();
  const toolCallArgsById = new Map<string, unknown>();
  let lastAssistantText = "";
  let dirtyRangeCount = 0;
  let priorSummaryText = "";

  for (const msg of messages) {
    if (msg.role === "user") {
      const stripped = stripAllEnrichment((msg as UserMessage).content);
      const compact = compactWhitespace(stripped);
      if (compact.length === 0) continue;
      const carriedSummary = extractPriorSummaryPayload(compact);
      if (carriedSummary !== null) {
        // Latest carried summary wins so successive resets layer cleanly.
        priorSummaryText = carriedSummary;
        continue;
      }
      if (compact.startsWith("[SYSTEM:")) {
        // Other synthetic system-style markers (e.g. TODO state, legacy
        // token-manager compaction) are bookkeeping, not user turns.
        continue;
      }
      userPrompts.push(compact);
      continue;
    }

    if (msg.role === "assistant") {
      const assistant = msg as AssistantMessage;
      for (const block of assistant.content) {
        if (block.type === "text") {
          const compact = compactWhitespace(block.text);
          if (compact.length > 0) lastAssistantText = compact;
        } else if (block.type === "tool_call") {
          toolCallNamesById.set(block.id, block.name);
          toolCallArgsById.set(block.id, block.arguments);
          const path = extractWrittenPath(block.name, block.arguments);
          if (path) writtenPaths.add(path);
        }
      }
      continue;
    }

    if (msg.role === "tool") {
      const toolMsg = msg as ToolResultMessage;
      const name = toolCallNamesById.get(toolMsg.toolCallId) ?? "tool";
      const text = toolResultText(toolMsg);
      toolExecutions.push({
        name,
        ok: !toolMsg.isError,
        resultText: text,
      });
      const parsed = safeJsonParse(text);
      if (parsed && typeof parsed === "object") {
        const dirty = (parsed as { _dirtyRanges?: unknown })._dirtyRanges;
        if (Array.isArray(dirty)) dirtyRangeCount += dirty.length;
      }
    }
  }

  return {
    userPrompts,
    toolExecutions,
    lastAssistantText,
    writtenPaths,
    dirtyRangeCount,
    priorSummaryText,
  };
}

function summarizeToolExecutions(executions: ToolExecution[]): {
  line: string;
  countByName: Map<string, { ok: number; err: number }>;
} {
  const counts = new Map<string, { ok: number; err: number }>();
  for (const exec of executions) {
    const entry = counts.get(exec.name) ?? { ok: 0, err: 0 };
    if (exec.ok) entry.ok++;
    else entry.err++;
    counts.set(exec.name, entry);
  }
  const parts: string[] = [];
  for (const [name, { ok, err }] of counts) {
    const total = ok + err;
    parts.push(
      err > 0 ? `${name} x${total} (${err} err)` : `${name} x${total}`,
    );
  }
  return { line: parts.join(", "), countByName: counts };
}

/**
 * Produce a compact summary of prior turns suitable for injection at the
 * top of a fresh agent context. Strips enrichment headers, collapses tool
 * calls into name + ok/err counts, captures up to two recent user prompts
 * plus the most recent assistant prose, and hard-caps the output at
 * `opts.maxChars` (defaults to {@link DEFAULT_CONTEXT_SUMMARY_MAX_CHARS}).
 */
export function summarizePriorTurns(
  messages: AgentMessage[],
  opts: PriorTurnSummaryOptions = {},
): PriorTurnSummary {
  const maxChars = clampMaxChars(opts.maxChars);
  const wikiMaxChars = clampMaxChars(opts.wikiMaxChars ?? maxChars * 8);

  if (messages.length === 0) {
    return {
      summaryText: "",
      wikiMarkdown: "",
      turnsCount: 0,
      toolCallsCount: 0,
      truncated: false,
    };
  }

  const trace = extractTrace(messages);
  const turnsCount = trace.userPrompts.length;
  const toolCallsCount = trace.toolExecutions.length;
  const toolSummary = summarizeToolExecutions(trace.toolExecutions);

  const recentPrompts = trace.userPrompts.slice(-2);
  const writtenPathsArr = [...trace.writtenPaths].slice(-6);

  const lines: string[] = [];
  if (trace.priorSummaryText) {
    lines.push(`Earlier: ${trace.priorSummaryText}`);
  }
  lines.push(
    `Prior session: ${turnsCount} user turn${turnsCount === 1 ? "" : "s"}, ${toolCallsCount} tool call${toolCallsCount === 1 ? "" : "s"}.`,
  );
  if (recentPrompts.length > 0) {
    const renderedPrompts = recentPrompts
      .map((p, i) => `(${i + 1}) ${truncateText(p, 240)}`)
      .join(" | ");
    lines.push(`Recent user asks: ${renderedPrompts}`);
  }
  if (toolSummary.line) {
    lines.push(`Tools run: ${toolSummary.line}`);
  }
  if (writtenPathsArr.length > 0) {
    lines.push(`Files written: ${writtenPathsArr.join(", ")}`);
  }
  if (trace.dirtyRangeCount > 0) {
    lines.push(`Workbook dirty ranges touched: ${trace.dirtyRangeCount}`);
  }
  if (trace.lastAssistantText) {
    lines.push(
      `Last assistant reply: ${truncateText(trace.lastAssistantText, 320)}`,
    );
  }
  lines.push(
    `Older history was dropped to keep context fresh; see ${CONVERSATION_SUMMARY_WIKI_PATH} (if enabled) for more detail.`,
  );

  const joined = lines.join(" ");
  const truncated = joined.length > maxChars;
  const summaryText = truncated ? truncateText(joined, maxChars) : joined;

  const wikiLines: string[] = [];
  wikiLines.push("# Conversation summary");
  wikiLines.push("");
  if (trace.priorSummaryText) {
    wikiLines.push("## Carried forward from earlier resets");
    wikiLines.push(trace.priorSummaryText);
    wikiLines.push("");
  }
  wikiLines.push(
    `- Prior user turns: **${turnsCount}**, prior tool calls: **${toolCallsCount}**`,
  );
  if (recentPrompts.length > 0) {
    wikiLines.push("");
    wikiLines.push("## Recent user prompts");
    for (const prompt of recentPrompts) {
      wikiLines.push(`- ${truncateText(prompt, 600)}`);
    }
  }
  if (toolSummary.countByName.size > 0) {
    wikiLines.push("");
    wikiLines.push("## Tools executed");
    for (const [name, { ok, err }] of toolSummary.countByName) {
      wikiLines.push(`- \`${name}\`: ${ok} ok, ${err} err`);
    }
  }
  if (writtenPathsArr.length > 0) {
    wikiLines.push("");
    wikiLines.push("## Files written");
    for (const p of writtenPathsArr) {
      wikiLines.push(`- ${p}`);
    }
  }
  if (trace.dirtyRangeCount > 0) {
    wikiLines.push("");
    wikiLines.push("## Workbook impact");
    wikiLines.push(`- Dirty ranges touched: ${trace.dirtyRangeCount}`);
  }
  if (trace.lastAssistantText) {
    wikiLines.push("");
    wikiLines.push("## Last assistant reply");
    wikiLines.push(truncateText(trace.lastAssistantText, 1200));
  }
  const wikiJoined = wikiLines.join("\n");
  const wikiMarkdown =
    wikiJoined.length > wikiMaxChars
      ? truncateText(wikiJoined, wikiMaxChars)
      : wikiJoined;

  return {
    summaryText,
    wikiMarkdown,
    turnsCount,
    toolCallsCount,
    truncated,
  };
}

/**
 * Wrap the summary text in the `[SYSTEM: ...]` user-message shape already
 * used by {@link token-manager}'s history compactor so providers do not
 * need a new role. Returns `null` when the summary is empty so callers
 * can simply skip injection.
 */
export function buildFreshContextMessage(
  summary: PriorTurnSummary,
  nowMs: () => number = Date.now,
): UserMessage | null {
  if (!summary.summaryText) return null;
  return {
    role: "user",
    content: `[SYSTEM: Conversation summary (older turns dropped for fresh context): ${summary.summaryText}]`,
    timestamp: nowMs(),
  };
}
