import type { QuickJSWASMModule } from "quickjs-emscripten-core";

type QuickJSModuleLoader = () => Promise<QuickJSWASMModule>;

let quickJsModulePromise: Promise<QuickJSWASMModule> | null = null;
let quickJsModuleLoaderForTests: QuickJSModuleLoader | null = null;

export function setQuickJSModuleLoaderForTests(
  loader: QuickJSModuleLoader | null,
): void {
  quickJsModuleLoaderForTests = loader;
  quickJsModulePromise = null;
}

export async function loadQuickJSModule(): Promise<QuickJSWASMModule> {
  if (quickJsModuleLoaderForTests) {
    return quickJsModuleLoaderForTests();
  }

  if (!quickJsModulePromise) {
    quickJsModulePromise = Promise.all([
      import("quickjs-emscripten-core"),
      import("@jitl/quickjs-ng-wasmfile-release-sync"),
    ])
      .then(([core, variant]) =>
        core.newQuickJSWASMModuleFromVariant(variant.default),
      )
      .catch((error) => {
        quickJsModulePromise = null;
        throw error;
      });
  }

  return quickJsModulePromise;
}
