import type {
  ProviderTokenQuota,
  TokenRateLimitConfig,
  TokenRateLimitResult,
} from "./types";

const WINDOW_MS = 60000;
const DEFAULT_SAFETY_FACTOR = 0.85;

export class TokenRateLimiter {
  private configuredMaxTokensPerMinute: number | undefined;
  private serverMaxTokensPerMinute: number | undefined;
  private safetyFactor: number;
  private availableTokens = Number.POSITIVE_INFINITY;
  private lastRefillMs = Date.now();
  private blockedUntilMs = 0;

  constructor(config: TokenRateLimitConfig = {}) {
    this.configuredMaxTokensPerMinute = toPositiveInteger(
      config.maxTokensPerMinute,
    );
    this.safetyFactor = toSafetyFactor(config.safetyFactor);
    this.resetAvailableTokens();
  }

  async acquire(
    requestedTokens: number,
    timeoutMs = 30000,
  ): Promise<TokenRateLimitResult> {
    const startedAtMs = Date.now();
    while (Date.now() - startedAtMs < timeoutMs) {
      const result = this.tryAcquire(requestedTokens);
      if (result.allowed) return result;

      await sleep(Math.max(1, Math.min(result.retryAfterMs, 1000)));
    }

    return {
      allowed: false,
      remaining: this.remainingTokens(),
      retryAfterMs: this.retryAfterMs(requestedTokens),
      consumed: false,
    };
  }

  tryAcquire(requestedTokens: number): TokenRateLimitResult {
    const tokenCost = Math.max(0, Math.ceil(requestedTokens));
    this.refill();

    if (!Number.isFinite(this.capacity())) {
      return {
        allowed: true,
        remaining: Number.POSITIVE_INFINITY,
        retryAfterMs: 0,
        consumed: false,
      };
    }

    const nowMs = Date.now();
    if (nowMs < this.blockedUntilMs) {
      return {
        allowed: false,
        remaining: this.remainingTokens(),
        retryAfterMs: this.blockedUntilMs - nowMs,
        consumed: false,
      };
    }

    const capacity = this.capacity();
    // A single request larger than the entire per-minute budget can never be
    // satisfied by waiting (the bucket refills to `capacity` at most). Admit
    // it once and drain the bucket so following requests still get
    // back-pressure, instead of blocking this request forever. An active
    // server `retry-after` still blocks it via the `blockedUntilMs` check
    // above.
    if (tokenCost > capacity) {
      this.availableTokens = 0;
      return {
        allowed: true,
        remaining: 0,
        retryAfterMs: 0,
        consumed: true,
      };
    }

    if (this.availableTokens < tokenCost) {
      return {
        allowed: false,
        remaining: this.remainingTokens(),
        retryAfterMs: this.retryAfterMs(tokenCost),
        consumed: false,
      };
    }

    this.availableTokens -= tokenCost;
    return {
      allowed: true,
      remaining: this.remainingTokens(),
      retryAfterMs: 0,
      consumed: tokenCost > 0,
    };
  }

  observe(quota: ProviderTokenQuota): void {
    this.refill();
    const limitTokens = toPositiveInteger(quota.limitTokens);
    if (limitTokens !== undefined) {
      this.serverMaxTokensPerMinute = limitTokens;
      this.constrainAvailableTokens();
    }

    const remainingTokens = toNonNegativeInteger(quota.remainingTokens);
    if (remainingTokens !== undefined && Number.isFinite(this.capacity())) {
      this.availableTokens = Math.min(
        this.capacity(),
        Math.floor(remainingTokens * this.safetyFactor),
      );
      this.lastRefillMs = Date.now();
    }

    const resetTokensMs = toPositiveInteger(quota.resetTokensMs);
    if (remainingTokens === 0 && resetTokensMs !== undefined) {
      this.blockedUntilMs = Math.max(
        this.blockedUntilMs,
        Date.now() + resetTokensMs,
      );
    }
  }

  reportRateLimitHit(retryAfterMs?: number): void {
    const delayMs = toPositiveInteger(retryAfterMs);
    if (delayMs !== undefined) {
      this.blockedUntilMs = Math.max(this.blockedUntilMs, Date.now() + delayMs);
    }

    if (Number.isFinite(this.capacity())) {
      this.availableTokens = 0;
    }
  }

  updateConfig(config: TokenRateLimitConfig): void {
    if (config.maxTokensPerMinute !== undefined) {
      this.configuredMaxTokensPerMinute = toPositiveInteger(
        config.maxTokensPerMinute,
      );
    }
    if (config.safetyFactor !== undefined) {
      this.safetyFactor = toSafetyFactor(config.safetyFactor);
    }
    this.constrainAvailableTokens();
  }

  private capacity(): number {
    const configured = this.configuredMaxTokensPerMinute;
    const server = this.serverMaxTokensPerMinute;
    const rawLimit =
      configured !== undefined && server !== undefined
        ? Math.min(configured, server)
        : (configured ?? server);

    return rawLimit === undefined
      ? Number.POSITIVE_INFINITY
      : Math.max(1, Math.floor(rawLimit * this.safetyFactor));
  }

  private resetAvailableTokens(): void {
    this.availableTokens = this.capacity();
    this.lastRefillMs = Date.now();
  }

  private constrainAvailableTokens(): void {
    const capacity = this.capacity();
    this.availableTokens = Number.isFinite(capacity)
      ? Math.min(this.availableTokens, capacity)
      : Number.POSITIVE_INFINITY;
  }

  private refill(): void {
    const capacity = this.capacity();
    if (!Number.isFinite(capacity)) {
      this.availableTokens = Number.POSITIVE_INFINITY;
      this.lastRefillMs = Date.now();
      return;
    }

    const nowMs = Date.now();
    const elapsedMs = nowMs - this.lastRefillMs;
    if (elapsedMs <= 0) return;

    this.availableTokens = Math.min(
      capacity,
      this.availableTokens + (elapsedMs * capacity) / WINDOW_MS,
    );
    this.lastRefillMs = nowMs;
  }

  private remainingTokens(): number {
    return Number.isFinite(this.availableTokens)
      ? Math.max(0, Math.floor(this.availableTokens))
      : Number.POSITIVE_INFINITY;
  }

  private retryAfterMs(requestedTokens: number): number {
    const nowMs = Date.now();
    if (nowMs < this.blockedUntilMs) {
      return this.blockedUntilMs - nowMs;
    }

    const capacity = this.capacity();
    if (!Number.isFinite(capacity) || requestedTokens <= this.availableTokens) {
      return 0;
    }
    if (requestedTokens > capacity) {
      return WINDOW_MS;
    }

    return Math.ceil(
      ((requestedTokens - this.availableTokens) * WINDOW_MS) / capacity,
    );
  }
}

function toPositiveInteger(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : undefined;
}

function toNonNegativeInteger(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) && value >= 0
    ? Math.floor(value)
    : undefined;
}

function toSafetyFactor(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return DEFAULT_SAFETY_FACTOR;
  }
  return Math.max(0.1, Math.min(1, value));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
