/**
 * MCP user settings (Phase 1 of mcp-settings-ui-plan).
 *
 * Implements the data layer for the upcoming MCP settings UI:
 *   - the persisted shape stored under `officeai-mcp-connections`
 *   - secret storage helpers backed by sessionStorage / localStorage
 *   - a deployment ⊕ user merge helper that produces the effective
 *     {@link MCPConnectionsConfig} consumed by the agent
 *
 * No UI is rendered from this module. See
 * docs/mcp-settings-ui-plan.md §"Data model" / §"Secret storage" /
 * §"Settings integration" for the contract this implements.
 *
 * Secrets are NEVER stored inside `UserMCPSettings`; only secret
 * references (scope + key) are persisted. Raw values live solely in
 * the chosen browser storage (`session` by default, `local` only with
 * explicit user opt-in).
 */

import type {
  MCPAuthConfig,
  MCPConnectionConfig,
  MCPConnectionsConfig,
  MCPSecretRef,
  MCPSecretScope,
  MCPTransportKind,
} from "./types";

/** localStorage key for the persisted user-managed MCP settings blob. */
export const USER_MCP_SETTINGS_KEY = "officeai-mcp-connections";

/**
 * Copy shown to the user when they choose `local` secret scope.
 * Surfaced by the UI alongside the confirm checkbox; kept here so
 * tests/services can assert on the canonical wording.
 */
export const LOCAL_PERSISTENCE_WARNING =
  "Storing this secret locally keeps it on this device until you remove the connection or clear browser storage. Use session storage instead unless you need the secret to survive reloads.";

/** UI-side status the settings UI persists per connection. */
export type UserMCPConnectionStatus =
  | "not_tested"
  | "testing"
  | "connected"
  | "degraded"
  | "unauthorized"
  | "failed"
  | "disabled";

/**
 * Persisted, user-managed MCP connection. The auth shape mirrors
 * {@link MCPAuthConfig} so user entries can be merged directly into
 * the runtime {@link MCPConnectionsConfig} without translation.
 *
 * Last-test metadata lives here so the settings UI can show "last
 * tested at …" without re-running discovery; runtime code MUST ignore
 * these fields.
 */
export interface UserMCPConnection {
  id: string;
  label: string;
  description?: string;
  transport: MCPTransportKind;
  endpoint: string;
  enabled: boolean;
  alwaysActive?: boolean;
  auth: MCPAuthConfig;
  requestTimeoutMs?: number;
  /**
   * Operator-managed allowlist of remote tool names safe for parallel
   * read dispatch. Mirrors
   * {@link MCPConnectionConfig.parallelSafeRemoteTools}; persisted so
   * the settings UI round-trips it without translation.
   */
  parallelSafeRemoteTools?: string[];
  lastTestedAt?: string;
  lastStatus?: UserMCPConnectionStatus;
  lastToolCount?: number;
}

export interface UserMCPSettings {
  version: 1;
  connections: UserMCPConnection[];
}

export interface MCPMergeDiagnostic {
  connectionId: string;
  field: "id";
  message: string;
}

export interface MCPMergeResult {
  /** Combined deployment + user connections in the runtime contract shape. */
  config: MCPConnectionsConfig;
  diagnostics: MCPMergeDiagnostic[];
}

/** Read-only storage accessor (matches transport's StorageLike). */
export interface ReadStorageLike {
  getItem(key: string): string | null;
}

/** Mutable storage accessor used for save / delete operations. */
export interface WriteStorageLike extends ReadStorageLike {
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/** Bundle of (session, local) storages used by the secret helpers. */
export interface SecretStorageBundle {
  session?: WriteStorageLike;
  local?: WriteStorageLike;
}

const DEFAULT_USER_SETTINGS: UserMCPSettings = {
  version: 1,
  connections: [],
};

const SECRET_KEY_PREFIX = "officeai-mcp";

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function resolveDefaultStorage(
  kind: "sessionStorage" | "localStorage",
): WriteStorageLike | undefined {
  try {
    if (typeof globalThis === "undefined") return undefined;
    const candidate = (globalThis as unknown as Record<string, unknown>)[kind];
    if (
      candidate &&
      typeof (candidate as WriteStorageLike).getItem === "function" &&
      typeof (candidate as WriteStorageLike).setItem === "function" &&
      typeof (candidate as WriteStorageLike).removeItem === "function"
    ) {
      return candidate as WriteStorageLike;
    }
    return undefined;
  } catch {
    return undefined;
  }
}

function defaultBundle(): SecretStorageBundle {
  return {
    session: resolveDefaultStorage("sessionStorage"),
    local: resolveDefaultStorage("localStorage"),
  };
}

function pickStorage(
  scope: MCPSecretScope,
  bundle: SecretStorageBundle,
): WriteStorageLike | undefined {
  return scope === "session" ? bundle.session : bundle.local;
}

function isSecretRef(value: unknown): value is MCPSecretRef {
  if (!isPlainObject(value)) return false;
  const scope = value.scope;
  const key = value.key;
  return (
    (scope === "session" || scope === "local") &&
    isString(key) &&
    key.length > 0
  );
}

function isAuthConfig(value: unknown): value is MCPAuthConfig {
  if (!isPlainObject(value)) return false;
  const type = value.type;
  if (type === "none") return true;
  if (type === "bearer") return isSecretRef(value.tokenRef);
  if (type === "header") {
    return isString(value.headerName) && isSecretRef(value.headerValueRef);
  }
  if (type === "entra") {
    return (
      isString(value.tenantId) &&
      isString(value.clientId) &&
      Array.isArray(value.scopes) &&
      value.scopes.every(isString) &&
      (value.redirectUri === undefined || isString(value.redirectUri))
    );
  }
  return false;
}

function isUserMCPConnection(value: unknown): value is UserMCPConnection {
  if (!isPlainObject(value)) return false;
  if (!isString(value.id) || value.id.length === 0) return false;
  if (!isString(value.label)) return false;
  if (value.description !== undefined && !isString(value.description)) {
    return false;
  }
  if (value.transport !== "sse" && value.transport !== "streamable_http") {
    return false;
  }
  if (!isString(value.endpoint)) return false;
  if (typeof value.enabled !== "boolean") return false;
  if (
    value.alwaysActive !== undefined &&
    typeof value.alwaysActive !== "boolean"
  ) {
    return false;
  }
  if (!isAuthConfig(value.auth)) return false;
  if (
    value.requestTimeoutMs !== undefined &&
    typeof value.requestTimeoutMs !== "number"
  ) {
    return false;
  }
  if (value.parallelSafeRemoteTools !== undefined) {
    if (!Array.isArray(value.parallelSafeRemoteTools)) return false;
    if (!value.parallelSafeRemoteTools.every(isString)) return false;
  }
  return true;
}

/**
 * Build the storage key used for a connection's bearer token or
 * custom-header secret. Stable, deterministic, and contains no
 * secret material — safe to log or include in diagnostics.
 *
 * Format: `officeai-mcp-{connectionId}-{token|header}`. The
 * connection id is sanitized to the contract's allowed character set
 * (`[a-z0-9_-]`). Returns `null` for ids that cannot satisfy the
 * runtime secret-key pattern (`^[A-Za-z0-9._:-]{3,120}$`).
 */
export function buildSecretKey(
  connectionId: string,
  kind: "token" | "header",
): string | null {
  if (!isString(connectionId) || connectionId.length === 0) return null;
  const sanitized = connectionId.replace(/[^a-z0-9_-]/g, "-");
  if (sanitized.length === 0) return null;
  const candidate = `${SECRET_KEY_PREFIX}-${sanitized}-${kind}`;
  if (!/^[A-Za-z0-9._:-]{3,120}$/.test(candidate)) return null;
  return candidate;
}

/**
 * Resolve the secret reference embedded in a connection's auth config,
 * or `null` for auth modes that do not use browser-stored secrets.
 */
export function getSecretRef(
  auth: MCPAuthConfig,
): { scope: MCPSecretScope; key: string; kind: "token" | "header" } | null {
  if (auth.type === "none" || auth.type === "entra") return null;
  if (auth.type === "bearer") {
    return {
      scope: auth.tokenRef.scope,
      key: auth.tokenRef.key,
      kind: "token",
    };
  }
  return {
    scope: auth.headerValueRef.scope,
    key: auth.headerValueRef.key,
    kind: "header",
  };
}

/**
 * Read a secret value from the given scope. Returns `null` when the
 * storage is unavailable or the key is unset. Never throws.
 */
export function getSecret(
  scope: MCPSecretScope,
  key: string,
  bundle: SecretStorageBundle = defaultBundle(),
): string | null {
  const storage = pickStorage(scope, bundle);
  if (!storage) return null;
  try {
    return storage.getItem(key);
  } catch {
    return null;
  }
}

/**
 * Write a secret value to the given scope. Silently no-ops when the
 * storage is unavailable so caller code does not have to feature-detect
 * sessionStorage in non-browser environments.
 */
export function setSecret(
  scope: MCPSecretScope,
  key: string,
  value: string,
  bundle: SecretStorageBundle = defaultBundle(),
): void {
  const storage = pickStorage(scope, bundle);
  if (!storage) return;
  try {
    storage.setItem(key, value);
  } catch {
    // Quota or security errors must not crash the settings UI.
  }
}

/** Remove a secret from the given scope. Idempotent and best-effort. */
export function removeSecret(
  scope: MCPSecretScope,
  key: string,
  bundle: SecretStorageBundle = defaultBundle(),
): void {
  const storage = pickStorage(scope, bundle);
  if (!storage) return;
  try {
    storage.removeItem(key);
  } catch {
    // Best-effort cleanup.
  }
}

/**
 * Clear every stored secret reachable from a user connection. Used when
 * the connection is deleted or its auth shape changes. Safe to call on
 * `auth.type === "none"` connections.
 */
export function removeConnectionSecrets(
  connection: Pick<UserMCPConnection, "auth">,
  bundle: SecretStorageBundle = defaultBundle(),
): void {
  const ref = getSecretRef(connection.auth);
  if (!ref) return;
  removeSecret(ref.scope, ref.key, bundle);
}

/**
 * When a connection's secret scope changes (session ↔ local) the same
 * key may exist in the previous scope. Removes the stale entry so the
 * UI does not leave a copy in localStorage after a downgrade to
 * session, or vice versa.
 */
export function purgeStaleSecretScope(
  key: string,
  keepScope: MCPSecretScope,
  bundle: SecretStorageBundle = defaultBundle(),
): void {
  const stale: MCPSecretScope = keepScope === "session" ? "local" : "session";
  removeSecret(stale, key, bundle);
}

/**
 * Load the persisted user MCP settings from `localStorage`. Returns the
 * empty default when the blob is missing, malformed, or unparsable.
 * Connections that fail the shape guard are dropped silently — they
 * will be regenerated on the next save and the UI can re-collect
 * malformed entries from telemetry/logs.
 */
export function loadUserMCPSettings(
  storage: ReadStorageLike | undefined = resolveDefaultStorage("localStorage"),
): UserMCPSettings {
  if (!storage) return cloneDefault();
  let raw: string | null;
  try {
    raw = storage.getItem(USER_MCP_SETTINGS_KEY);
  } catch {
    return cloneDefault();
  }
  if (!raw) return cloneDefault();

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return cloneDefault();
  }

  if (!isPlainObject(parsed) || parsed.version !== 1) return cloneDefault();
  const connectionsRaw = Array.isArray(parsed.connections)
    ? parsed.connections
    : [];
  const connections: UserMCPConnection[] = [];
  for (const entry of connectionsRaw) {
    if (!isUserMCPConnection(entry)) continue;
    connections.push(stripExtraFields(entry));
  }
  return { version: 1, connections };
}

/** Persist the user MCP settings to `localStorage` (or the supplied storage). */
export function saveUserMCPSettings(
  settings: UserMCPSettings,
  storage: WriteStorageLike | undefined = resolveDefaultStorage("localStorage"),
): void {
  if (!storage) return;
  const normalized: UserMCPSettings = {
    version: 1,
    connections: settings.connections.map(stripExtraFields),
  };
  try {
    storage.setItem(USER_MCP_SETTINGS_KEY, JSON.stringify(normalized));
  } catch {
    // Quota or security errors must not crash the settings UI.
  }
}

/** Convert a user-managed connection into the runtime config shape. */
export function userConnectionToConnectionConfig(
  connection: UserMCPConnection,
): MCPConnectionConfig {
  const base: MCPConnectionConfig = {
    id: connection.id,
    label: connection.label,
    transport: connection.transport,
    endpoint: connection.endpoint,
    enabled: connection.enabled,
    auth: connection.auth,
  };
  const description = connection.description?.replace(/\s+/g, " ").trim();
  if (description) {
    base.description = description;
  }
  if (connection.alwaysActive === true) {
    base.alwaysActive = true;
  }
  if (typeof connection.requestTimeoutMs === "number") {
    base.requestTimeoutMs = connection.requestTimeoutMs;
  }
  if (
    Array.isArray(connection.parallelSafeRemoteTools) &&
    connection.parallelSafeRemoteTools.length > 0
  ) {
    base.parallelSafeRemoteTools = [...connection.parallelSafeRemoteTools];
  }
  return base;
}

interface MergeInputs {
  /** Raw deployment-managed MCP config from runtime-config.json. */
  deployment: unknown;
  /** Persisted user MCP settings. */
  user: UserMCPSettings;
}

/**
 * Merge deployment-managed MCP config with user-managed connections
 * into a single {@link MCPConnectionsConfig}.
 *
 * Precedence rules (per docs/mcp-settings-ui-plan.md §"Data model"):
 *   - Deployment-managed connections win on id collisions.
 *   - User-managed duplicates are dropped with a diagnostic so the UI
 *     can surface the rejection.
 *
 * The merged config is handed back as raw runtime config — downstream
 * `validateMCPConnectionsConfig` is the single source of truth for
 * field-level validation, so we deliberately avoid re-validating here.
 */
export function mergeMCPConnectionsConfig(inputs: MergeInputs): MCPMergeResult {
  const deploymentConnections = extractRawConnections(inputs.deployment);
  const deploymentIds = new Set<string>();
  for (const entry of deploymentConnections) {
    if (isPlainObject(entry) && isString(entry.id)) {
      deploymentIds.add(entry.id);
    }
  }

  const diagnostics: MCPMergeDiagnostic[] = [];
  const merged: MCPConnectionConfig[] = [];
  const seenUserIds = new Set<string>();

  // Pass deployment entries through verbatim so the existing validator
  // owns field-level diagnostics for runtime-config.json.
  for (const entry of deploymentConnections) {
    merged.push(entry as MCPConnectionConfig);
  }

  for (const userConn of inputs.user.connections) {
    if (deploymentIds.has(userConn.id)) {
      diagnostics.push({
        connectionId: userConn.id,
        field: "id",
        message:
          "user connection id collides with a deployment-managed connection; user entry was dropped",
      });
      continue;
    }
    if (seenUserIds.has(userConn.id)) {
      diagnostics.push({
        connectionId: userConn.id,
        field: "id",
        message: "duplicate user connection id; later entry was dropped",
      });
      continue;
    }
    seenUserIds.add(userConn.id);
    merged.push(userConnectionToConnectionConfig(userConn));
  }

  return {
    config: { version: 1, connections: merged },
    diagnostics,
  };
}

function extractRawConnections(deployment: unknown): unknown[] {
  if (!isPlainObject(deployment)) return [];
  const list = deployment.connections;
  return Array.isArray(list) ? list : [];
}

function stripExtraFields(connection: UserMCPConnection): UserMCPConnection {
  const out: UserMCPConnection = {
    id: connection.id,
    label: connection.label,
    transport: connection.transport,
    endpoint: connection.endpoint,
    enabled: connection.enabled,
    auth: cloneAuth(connection.auth),
  };
  const description = connection.description?.replace(/\s+/g, " ").trim();
  if (description) {
    out.description = description;
  }
  if (connection.alwaysActive === true) {
    out.alwaysActive = true;
  }
  if (typeof connection.requestTimeoutMs === "number") {
    out.requestTimeoutMs = connection.requestTimeoutMs;
  }
  if (
    Array.isArray(connection.parallelSafeRemoteTools) &&
    connection.parallelSafeRemoteTools.length > 0
  ) {
    const dedup: string[] = [];
    const seen = new Set<string>();
    for (const name of connection.parallelSafeRemoteTools) {
      if (typeof name !== "string") continue;
      const trimmed = name.trim();
      if (!trimmed || seen.has(trimmed)) continue;
      seen.add(trimmed);
      dedup.push(trimmed);
    }
    if (dedup.length > 0) {
      out.parallelSafeRemoteTools = dedup;
    }
  }
  if (typeof connection.lastTestedAt === "string") {
    out.lastTestedAt = connection.lastTestedAt;
  }
  if (typeof connection.lastStatus === "string") {
    out.lastStatus = connection.lastStatus;
  }
  if (typeof connection.lastToolCount === "number") {
    out.lastToolCount = connection.lastToolCount;
  }
  return out;
}

function cloneAuth(auth: MCPAuthConfig): MCPAuthConfig {
  if (auth.type === "none") return { type: "none" };
  if (auth.type === "bearer") {
    return { type: "bearer", tokenRef: { ...auth.tokenRef } };
  }
  if (auth.type === "entra") {
    return {
      type: "entra",
      tenantId: auth.tenantId,
      clientId: auth.clientId,
      scopes: [...auth.scopes],
      ...(auth.redirectUri ? { redirectUri: auth.redirectUri } : {}),
    };
  }
  return {
    type: "header",
    headerName: auth.headerName,
    headerValueRef: { ...auth.headerValueRef },
  };
}

function cloneDefault(): UserMCPSettings {
  return { version: 1, connections: [...DEFAULT_USER_SETTINGS.connections] };
}
