import { Type } from "@sinclair/typebox";
import { defineTool, toolText } from "../../tools/types";
import type { ChildAgentRunner } from "./types";

export function createTaskTool(runner: ChildAgentRunner) {
  return defineTool({
    name: "task",
    label: "Read-only task",
    description:
      "Delegate a focused multi-step read/research task to an isolated child context. The child is read-only, has no Bash or mutation tools, cannot delegate recursively, and returns one concise final report. Do not use for one-step reads or deliverable creation.",
    category: "read",
    parallelSafe: false,
    maxRetries: 0,
    parameters: Type.Object({
      description: Type.String({
        minLength: 1,
        maxLength: 4000,
        description: "Self-contained objective for the child agent.",
      }),
      outputSchema: Type.Optional(
        Type.Record(Type.String(), Type.Unknown(), {
          description:
            "Optional JSON Schema. When supplied, the child must return matching JSON.",
        }),
      ),
    }),
    execute: async (toolCallId, params, signal) => {
      try {
        const result = await runner(
          {
            taskId: toolCallId,
            description: params.description,
            outputSchema: params.outputSchema,
          },
          signal ?? new AbortController().signal,
        );
        return toolText(
          JSON.stringify({
            taskId: result.taskId,
            output: result.output,
            ...(result.structuredResponse !== undefined
              ? { structuredResponse: result.structuredResponse }
              : {}),
          }),
        );
      } catch (error) {
        throw error instanceof Error ? error : new Error("Child task failed.");
      }
    },
  });
}
