import { Type } from "@sinclair/typebox";
import { getRangeAsCsv } from "../excel/api";
import {
  type PowerBiSourceScope,
  getPowerBiSourceRanges,
} from "../excel/powerbi-source";
import {
  type PowerBiTableInput,
  buildPowerBiPackage,
} from "../powerbi/pbip-package";
import { fileExists, listUploads, readFile, writeFile } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

const MAX_ROWS_PER_TABLE = 100_000;
const MAX_COLUMNS_PER_TABLE = 100;

function throwIfAborted(signal?: AbortSignal): void {
  if (!signal?.aborted) return;
  if (signal.reason instanceof Error) throw signal.reason;
  throw new DOMException("Power BI report creation was aborted", "AbortError");
}

const NO_WORKBOOK_ERROR =
  "No Excel workbook is available in this host. Provide csvPaths with one or more CSV files from the virtual filesystem, e.g. csvPaths: ['sales.csv'].";

function isMissingExcelHostError(error: unknown): boolean {
  if (error instanceof ReferenceError) return true;
  const message = error instanceof Error ? error.message : String(error);
  return /\bExcel\b.*(is not defined|is undefined)/i.test(message);
}

function resolveVfsPath(path: string): string {
  return path.startsWith("/") ? path : `/home/user/uploads/${path}`;
}

function tableNameFromPath(path: string): string {
  const base = path.split("/").pop() ?? path;
  const withoutExtension = base.replace(/\.(csv|tsv|txt)$/i, "");
  return withoutExtension.trim() || "Data";
}

async function readTablesFromVfs(
  csvPaths: string[],
  signal?: AbortSignal,
): Promise<PowerBiTableInput[]> {
  const tables: PowerBiTableInput[] = [];
  for (const rawPath of csvPaths) {
    throwIfAborted(signal);
    const path = resolveVfsPath(rawPath);
    if (!(await fileExists(path))) {
      const uploads = await listUploads();
      const hint =
        uploads.length === 0
          ? "No files have been uploaded yet."
          : `Available files: ${uploads.join(", ")}`;
      throw new Error(`File not found: ${path}. ${hint}`);
    }
    const csv = await readFile(path);
    if (csv.trim().length === 0) {
      throw new Error(`File is empty: ${path}`);
    }
    tables.push({ csv, tableName: tableNameFromPath(path) });
  }
  return tables;
}

export const createPowerBiReportTool = defineTool({
  name: "create_powerbi_report",
  category: "deliverable",
  parallelSafe: false,
  label: "Create Power BI Report",
  description:
    "Create a portable Power BI Desktop project from Excel data and write it as a downloadable .pbip.zip file in the virtual filesystem. " +
    "The generated project uses enhanced PBIR report definitions and a TMDL semantic model. CSV snapshots are gzip-compressed, Base64-embedded in Power Query M, and require no original data source after download. " +
    "Inside Excel, use scope='sheet' for the active or specified worksheet, optionally limited to an A1 range, or scope='workbook' to include every non-empty worksheet as a separate model table. " +
    "Outside Excel (for example the standalone web host), pass csvPaths with one or more CSV files from the virtual filesystem; each file becomes a model table. " +
    "The report uses a deterministic template with a row-count card, an inferred category or time-series chart when possible, and a detail table. " +
    "The user extracts the ZIP, opens the .pbip file in Power BI Desktop, selects Refresh once, and can then use File > Save as to create a PBIX file.",
  parameters: Type.Object({
    projectName: Type.String({
      description:
        "Name for the Power BI project and output ZIP, e.g. 'Sales Dashboard'.",
      minLength: 1,
      maxLength: 80,
    }),
    scope: Type.Optional(
      Type.Union([Type.Literal("sheet"), Type.Literal("workbook")], {
        description:
          "Export one worksheet or every non-empty worksheet. Default: sheet.",
        default: "sheet",
      }),
    ),
    sheetId: Type.Optional(
      Type.Number({
        description:
          "Stable worksheet ID for scope='sheet'. Omit to use the active worksheet.",
      }),
    ),
    range: Type.Optional(
      Type.String({
        description:
          "A1 range for scope='sheet', e.g. 'A1:H500'. Omit to use the worksheet's used range.",
      }),
    ),
    csvPaths: Type.Optional(
      Type.Array(Type.String(), {
        description:
          "CSV files in the virtual filesystem to use as model tables, e.g. ['sales.csv']. Paths may be absolute or relative to /home/user/uploads/. Required when no Excel workbook is available; overrides scope/sheetId/range when provided.",
        minItems: 1,
        maxItems: 20,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      throwIfAborted(signal);
      const csvPaths = params.csvPaths;
      const useVfsSource = Array.isArray(csvPaths) && csvPaths.length > 0;
      const scope = (params.scope ?? "sheet") as PowerBiSourceScope;

      let tables: PowerBiTableInput[];
      if (useVfsSource) {
        tables = await readTablesFromVfs(csvPaths, signal);
      } else {
        let sources: Awaited<ReturnType<typeof getPowerBiSourceRanges>>;
        try {
          sources = await getPowerBiSourceRanges({
            scope,
            sheetId: params.sheetId,
            range: params.range,
          });
        } catch (error) {
          if (isMissingExcelHostError(error))
            return toolError(NO_WORKBOOK_ERROR);
          throw error;
        }
        if (sources.length === 0) {
          return toolError("No non-empty worksheet data was found to export");
        }

        for (const source of sources) {
          const dataRows = Math.max(0, source.rowCount - 1);
          if (dataRows > MAX_ROWS_PER_TABLE) {
            return toolError(
              `Worksheet '${source.sheetName}' has ${dataRows} data rows; the embedded Power BI limit is ${MAX_ROWS_PER_TABLE}`,
            );
          }
          if (source.columnCount > MAX_COLUMNS_PER_TABLE) {
            return toolError(
              `Worksheet '${source.sheetName}' has ${source.columnCount} columns; the embedded Power BI limit is ${MAX_COLUMNS_PER_TABLE}`,
            );
          }
        }

        tables = [];
        for (const source of sources) {
          throwIfAborted(signal);
          const result = await getRangeAsCsv(source.sheetId, source.range, {
            includeHeaders: true,
            maxRows: MAX_ROWS_PER_TABLE,
            convertDateSerials: true,
          });
          if (result.hasMore) {
            return toolError(
              `Worksheet '${source.sheetName}' exceeds the embedded Power BI row limit`,
            );
          }
          tables.push({ csv: result.csv, tableName: source.sheetName });
        }
      }

      const report = buildPowerBiPackage({
        projectName: params.projectName,
        tables,
        maxColumns: MAX_COLUMNS_PER_TABLE,
        maxRows: MAX_ROWS_PER_TABLE,
      });
      throwIfAborted(signal);
      await writeFile(report.fileName, report.bytes);
      const path = `/home/user/uploads/${report.fileName}`;

      return toolSuccess({
        success: true,
        path,
        fileName: report.fileName,
        projectName: report.projectName,
        source: useVfsSource ? "vfs" : "excel",
        scope: useVfsSource ? undefined : scope,
        template: report.template,
        totalRows: report.rowCount,
        tables: report.tables.map((table) => ({
          name: table.tableName,
          rows: table.rowCount,
          columns: table.columnCount,
        })),
        nextStep:
          "Download and extract the ZIP, open the .pbip file in Power BI Desktop, enable the PBIP/PBIR/TMDL preview features if prompted, then select Refresh.",
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error creating Power BI report";
      return toolError(message);
    }
  },
});
