import { Type } from "@sinclair/typebox";
import type { DirtyRange } from "../dirty-tracker";
import { createTrackedContext } from "../excel/tracked-context";
import { sandboxedEval } from "../sandbox";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";

/* global Excel Word Office */

const MUTATION_PATTERNS = [
  /\.(values|formulas|numberFormat)\s*=/,
  /\.clear\s*\(/,
  /\.delete\s*\(/,
  /\.insert\s*\(/,
  /\.copyFrom\s*\(/,
  /\.add\s*\(/,
];

function looksLikeMutation(code: string): boolean {
  return MUTATION_PATTERNS.some((p) => p.test(code));
}

function getHostType(): "excel" | "word" | "outlook" | "unknown" {
  if (typeof Office === "undefined") return "unknown";
  if (Office.context?.mailbox) return "outlook";
  if (Office.context?.host === Office.HostType.Word) return "word";
  if (Office.context?.host === Office.HostType.Excel) return "excel";
  return "unknown";
}

export const evalOfficeJsTool = defineTool({
  name: "eval_officejs",
  category: "non_idempotent",
  parallelSafe: false,
  label: "Execute Office.js Code",
  description:
    "Execute arbitrary Office.js code within the appropriate host context (Excel.run or Word.run). " +
    "Use this as an escape hatch when existing tools don't cover your use case. " +
    "In Excel: runs inside `Excel.run(async (context) => { ... })` with `context` available. " +
    "In Word: runs inside `Word.run(async (context) => { ... })` with `context` available. " +
    "Return a value to get it back as the result. Always call `await context.sync()` before returning.",
  parameters: Type.Object({
    code: Type.String({
      description:
        "JavaScript code to execute. Has access to `context` (RequestContext) and host API (Excel or Word). " +
        "Must be valid async code. Return a value to get it as result. " +
        "Excel example: `const range = context.workbook.worksheets.getActiveWorksheet().getRange('A1'); range.load('values'); await context.sync(); return range.values;` " +
        "Word example: `const body = context.document.body; body.load('text'); await context.sync(); return body.text;`",
    }),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of what this code does (max 100 chars)",
        maxLength: 100,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const host = getHostType();
      let dirtyRanges: DirtyRange[] = [];
      let result: unknown;

      if (host === "word") {
        if (typeof Word === "undefined") {
          return toolError(
            "Word API is not available. Make sure you are running in Microsoft Word.",
          );
        }
        result = await Word.run(async (context) => {
          return withTemporaryChangeTracking(context, true, async () => {
            const execResult = await sandboxedEval(params.code, {
              context,
              Word,
            });
            await context.sync();
            return execResult;
          });
        });
      } else if (host === "excel") {
        if (typeof Excel === "undefined") {
          return toolError(
            "Excel API is not available. Make sure you are running in Microsoft Excel.",
          );
        }
        result = await Excel.run(async (context) => {
          const { trackedContext, getDirtyRanges } =
            createTrackedContext(context);

          const execResult = await sandboxedEval(params.code, {
            context: trackedContext,
            Excel,
          });

          dirtyRanges = getDirtyRanges();
          return execResult;
        });

        if (dirtyRanges.length === 0 && looksLikeMutation(params.code)) {
          dirtyRanges = [{ sheetId: -1, range: "*" }];
        }
      } else {
        return toolError(
          `Unsupported host: ${host}. This tool requires Excel or Word.`,
        );
      }

      const response: Record<string, unknown> = {
        success: true,
        result: result ?? null,
      };
      if (dirtyRanges.length > 0) {
        response._dirtyRanges = dirtyRanges;
      }
      return toolSuccess(response);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error executing code";
      return toolError(message);
    }
  },
});
