/**
 * `WriteFileStreamingSession` — Phase B.
 *
 * Owns the per-stream state for a single `write_file` tool call whose
 * arguments are being streamed in by an OpenAI-compatible provider.
 * The controller (Phase C) creates one session per `(turnIndex,
 * streamIndex)` pair and forwards the events emitted by the per-call
 * {@link StreamingArgsExtractor}:
 *
 *   - `onValue(key, value)` for non-string top-level args
 *     (`append`, `overwrite`, and the like).
 *   - `onStringStart(key)` / `onStringDelta(key, decoded)` /
 *     `onStringEnd(key)` for `path` (accumulated to a string) and
 *     `content` (buffered then flushed to a temp file).
 *
 * `finalize({ truncated })` commits the temp file to the model's
 * target path (overwrite or append per the captured `append` flag)
 * and returns a {@link StreamingWriteResult} the dispatcher can
 * surface to the model without ever calling
 * `writeFileTool.execute()`. `abort()` deletes the temp file and
 * never touches the target — matching the user-intuition that an
 * aborted run shouldn't half-write user files.
 *
 * Sessions are intentionally side-effect-isolated to a single temp
 * file path so failures cannot corrupt the target file or other
 * sessions' state.
 */

import { appendFile, commitTempFile, deleteFile, writeFile } from "../../vfs";
import {
  STREAM_TAIL_ANCHOR_CHARS,
  STREAM_TEMP_ROOT,
  STREAM_WRITE_FLUSH_CHARS,
  type StreamingWriteErrorCode,
  type StreamingWriteResult,
  type WriteFileStreamingSessionInit,
} from "./types";

type State = "open" | "failed" | "aborted" | "finalized";

export class WriteFileStreamingSession {
  private readonly init: WriteFileStreamingSessionInit;
  private readonly tempPath: string;
  private readonly flushChars: number;
  private readonly tailAnchorChars: number;
  private readonly encoder = new TextEncoder();

  private state: State = "open";

  private pathBuf = "";
  private pathString = false;
  private path?: string;

  private append?: boolean;
  private overwrite?: boolean;

  private contentStarted = false;
  private contentEnded = false;
  private pendingChars: string[] = [];
  private pendingCharCount = 0;
  private bytesFlushed = 0;
  private tailWindow = "";

  /**
   * Serial flush queue. The session is driven from the extractor's
   * synchronous events, so `onStringDelta` cannot await its own VFS
   * appends — concurrent invocations would race on the temp file.
   * Each time the buffered chars cross `flushChars`, the session
   * snapshots the chunk into a closure and chains an
   * {@link appendBytesToTemp} call onto this queue. The controller
   * awaits `drainFlushes()` to backpressure the decoder loop.
   */
  private flushQueue: Promise<void> = Promise.resolve();

  private failure?: { code: StreamingWriteErrorCode; message: string };

  constructor(init: WriteFileStreamingSessionInit) {
    this.init = init;
    this.flushChars = init.flushChars ?? STREAM_WRITE_FLUSH_CHARS;
    this.tailAnchorChars = init.tailAnchorChars ?? STREAM_TAIL_ANCHOR_CHARS;
    this.tempPath = buildTempPath(init.runId, init.turnIndex, init.streamIndex);
  }

  // ---------- public state inspection ----------

  hasFailed(): boolean {
    return this.state === "failed";
  }

  isAborted(): boolean {
    return this.state === "aborted";
  }

  /**
   * Returns the resolved target path the session will commit to, or
   * `undefined` if the path hasn't fully streamed in yet. Used by
   * the controller (Phase C / D10) to detect same-target conflicts
   * across concurrent sessions in the same turn.
   */
  getTargetPath(): string | undefined {
    return this.path;
  }

  /** Internal temp file path. Exposed for tests and telemetry. */
  getTempPath(): string {
    return this.tempPath;
  }

  /** Bytes already flushed to the temp file. */
  getBytesFlushed(): number {
    return this.bytesFlushed;
  }

  // ---------- extractor event sinks ----------

  onValue(key: string, value: unknown): void {
    if (this.state !== "open") return;
    switch (key) {
      case "append":
        if (typeof value === "boolean") {
          this.append = value;
        } else if (value !== undefined && value !== null) {
          this.fail(
            "STREAM_INVALID_ARGS",
            `'append' must be a boolean, got ${typeof value}`,
          );
        }
        break;
      case "overwrite":
        if (typeof value === "boolean") {
          this.overwrite = value;
        } else if (value !== undefined && value !== null) {
          this.fail(
            "STREAM_INVALID_ARGS",
            `'overwrite' must be a boolean, got ${typeof value}`,
          );
        }
        break;
      case "path":
        // A non-string `path` is invalid — the public schema requires string.
        this.fail(
          "STREAM_INVALID_ARGS",
          `'path' must be a string, got ${typeof value}`,
        );
        break;
      case "content":
        // Non-string `content` would have arrived as a primitive value,
        // not a streaming string. That violates the public schema.
        this.fail(
          "STREAM_INVALID_ARGS",
          `'content' must be a string, got ${typeof value}`,
        );
        break;
      default:
        // Ignore unknown top-level keys (e.g. legacy `purpose`).
        break;
    }
  }

  onStringStart(key: string): void {
    if (this.state !== "open") return;
    if (key === "path") {
      this.pathString = true;
      this.pathBuf = "";
    } else if (key === "content") {
      this.contentStarted = true;
    }
    // Other top-level string keys are ignored (none in write_file schema).
  }

  async onStringDelta(key: string, decoded: string): Promise<void> {
    if (this.state !== "open" || !decoded) return;
    if (key === "path") {
      this.pathBuf += decoded;
      return;
    }
    if (key === "content") {
      this.enqueueContentDelta(decoded);
      // Awaiting the queue gives test callers and direct users the
      // same "flush settled" semantics they had pre-queue. The
      // controller calls `drainFlushes()` instead from
      // `onArgumentsDelta` after the extractor has emitted all events
      // for a delta, so this await is cheap when there's nothing to do.
      await this.flushQueue;
    }
  }

  onStringEnd(key: string): void {
    if (this.state !== "open") return;
    if (key === "path") {
      this.path = this.pathBuf;
      this.pathString = false;
    } else if (key === "content") {
      this.contentEnded = true;
    }
  }

  /**
   * Externally force the session into the failed state. Used by the
   * controller for D10 same-target conflicts and other policy
   * decisions detected outside the session itself. Subsequent
   * extractor events become no-ops; `finalize(...)` will return a
   * `StreamingWriteResult` with the supplied error code.
   */
  markFailed(code: StreamingWriteErrorCode, message: string): void {
    if (this.state !== "open") return;
    this.state = "failed";
    this.failure = { code, message };
  }

  /**
   * Resolves once all flushes that have been queued by the session
   * (via `onStringDelta`) have settled. Used by the controller's
   * `onArgumentsDelta` hook to backpressure the decoder loop.
   */
  async drainFlushes(): Promise<void> {
    await this.flushQueue;
  }

  // ---------- finalize / abort ----------

  /**
   * Commit any buffered bytes to the target path and return a
   * `StreamingWriteResult`. `truncated` should be set when the
   * stream ended because the model hit `finish_reason: "length"`.
   *
   * Always returns a result (success or error). Never throws.
   */
  async finalize(opts: { truncated: boolean }): Promise<StreamingWriteResult> {
    if (this.state === "aborted") {
      // Defensive: aborts should not be finalized; the controller
      // discards aborted sessions. If this happens, return an error
      // result so the dispatcher has something to surface.
      return this.makeErrorResult(
        "STREAM_SINK_ERROR",
        "write_file streaming session was aborted before finalize",
        opts.truncated,
      );
    }
    if (this.state === "finalized") {
      throw new Error("WriteFileStreamingSession.finalize called twice");
    }

    if (this.state === "failed") {
      await this.safeCleanupTemp();
      this.state = "finalized";
      const msg = this.failure?.message ?? "streaming session failed";
      const code = this.failure?.code ?? "STREAM_SINK_ERROR";
      return this.makeErrorResult(code, msg, opts.truncated);
    }

    // Drain any queued flushes from in-flight `onStringDelta` calls so
    // we have an accurate byte count before flushing the tail.
    await this.flushQueue;
    if (this.state === ("failed" as State)) {
      await this.safeCleanupTemp();
      this.state = "finalized";
      const msg = this.failure?.message ?? "streaming session failed";
      const code = this.failure?.code ?? "STREAM_SINK_ERROR";
      return this.makeErrorResult(code, msg, opts.truncated);
    }

    // Flush any sub-threshold tail to the temp file. We chain onto the
    // queue (not run inline) so a concurrent flush triggered by a
    // racing event cannot interleave bytes.
    if (this.pendingChars.length > 0) {
      const chunk = this.pendingChars.join("");
      this.pendingChars = [];
      this.pendingCharCount = 0;
      const bytes = this.encoder.encode(chunk);
      this.flushQueue = this.flushQueue.then(() =>
        this.appendBytesToTemp(bytes),
      );
      await this.flushQueue;
    }
    if (this.state === ("failed" as State)) {
      await this.safeCleanupTemp();
      this.state = "finalized";
      const msg = this.failure?.message ?? "streaming session failed";
      const code = this.failure?.code ?? "STREAM_SINK_ERROR";
      return this.makeErrorResult(code, msg, opts.truncated);
    }

    // Missing path: never commit; report error.
    if (!this.path) {
      await this.safeCleanupTemp();
      this.state = "finalized";
      return this.makeErrorResult(
        "STREAM_MISSING_PATH",
        "write_file streaming finished without a 'path' argument",
        opts.truncated,
      );
    }

    // Missing content: the model started arguments but never emitted
    // `content`. Treat as error; the schema requires `content` and the
    // model would have to retry anyway.
    if (!this.contentStarted) {
      await this.safeCleanupTemp();
      this.state = "finalized";
      return this.makeErrorResult(
        "STREAM_MISSING_CONTENT",
        `write_file streaming finished without 'content' for ${this.path}`,
        opts.truncated,
      );
    }

    const mode: "overwrite" | "append" =
      this.append === true ? "append" : "overwrite";

    let bytesWritten = this.bytesFlushed;
    let cleanupError: unknown | undefined;
    try {
      if (this.bytesFlushed === 0) {
        await writeFile(this.tempPath, new Uint8Array());
      }
      const commit = await commitTempFile(this.tempPath, this.path, mode);
      bytesWritten = commit.bytesWritten;
      cleanupError = commit.cleanupError;
    } catch (err) {
      await this.safeCleanupTemp();
      this.state = "finalized";
      const message = err instanceof Error ? err.message : String(err);
      return this.makeErrorResult(
        "STREAM_COMMIT_FAILED",
        `write_file commit failed for ${this.path}: ${message}`,
        opts.truncated,
      );
    }

    this.state = "finalized";
    const tailAnchor = this.tailWindow.length > 0 ? this.tailWindow : undefined;
    return {
      toolCallId: this.init.toolCallId,
      streamIndex: this.init.streamIndex,
      name: "write_file",
      arguments: this.makeCompactArgs(bytesWritten, opts.truncated, tailAnchor),
      resultText: this.makeSuccessText(
        bytesWritten,
        opts.truncated,
        mode,
        cleanupError,
      ),
      isError: false,
      bytesWritten,
      truncated: opts.truncated,
      tailAnchor,
    };
  }

  /**
   * Discard any buffered bytes and delete the temp file. The target
   * file is never touched. Idempotent.
   */
  async abort(): Promise<void> {
    if (this.state === "finalized") return;
    this.state = "aborted";
    // Drain queued flushes so safeCleanupTemp does not race with an
    // in-flight `appendFile`. Errors are swallowed: queued flushes
    // bail early when state !== "open" but a flush that began before
    // the state change may still complete.
    try {
      await this.flushQueue;
    } catch {
      // ignore
    }
    await this.safeCleanupTemp();
  }

  // ---------- internals ----------

  private enqueueContentDelta(decoded: string): void {
    this.pendingChars.push(decoded);
    this.pendingCharCount += decoded.length;
    if (decoded.length >= this.tailAnchorChars) {
      this.tailWindow = decoded.slice(-this.tailAnchorChars);
    } else {
      this.tailWindow = (this.tailWindow + decoded).slice(
        -this.tailAnchorChars,
      );
    }
    if (this.pendingCharCount >= this.flushChars) {
      // Snapshot the chunk so the queued flush operates on a stable
      // input even if more deltas arrive while it is in flight.
      const chunk = this.pendingChars.join("");
      this.pendingChars = [];
      this.pendingCharCount = 0;
      const bytes = this.encoder.encode(chunk);
      this.flushQueue = this.flushQueue.then(() =>
        this.appendBytesToTemp(bytes),
      );
    }
  }

  private async appendBytesToTemp(bytes: Uint8Array): Promise<void> {
    if (this.state !== "open") return;
    try {
      await appendFile(this.tempPath, bytes);
      this.bytesFlushed += bytes.byteLength;
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.fail("STREAM_SINK_ERROR", message);
    }
  }

  private fail(code: StreamingWriteErrorCode, message: string): void {
    if (this.state !== "open") return;
    this.state = "failed";
    this.failure = { code, message };
  }

  private async safeCleanupTemp(): Promise<void> {
    try {
      await deleteFile(this.tempPath);
    } catch {
      // Best-effort. The temp file may not exist if no flush ever
      // happened; nothing to do.
    }
  }

  private makeCompactArgs(
    bytesWritten: number,
    truncated: boolean,
    tailAnchor: string | undefined,
  ): Record<string, unknown> {
    const args: Record<string, unknown> = {
      path: this.path,
      content: makeContentPlaceholder(this.path, bytesWritten),
      __streamed: {
        bytesWritten,
        truncated,
        ...(tailAnchor ? { tailAnchor } : {}),
      },
    };
    if (this.append !== undefined) args.append = this.append;
    if (this.overwrite !== undefined) args.overwrite = this.overwrite;
    return args;
  }

  private makeSuccessText(
    bytesWritten: number,
    truncated: boolean,
    mode: "overwrite" | "append",
    cleanupError: unknown | undefined,
  ): string {
    const verb = mode === "append" ? "Appended" : "Wrote";
    const target = this.path ?? "<unknown>";
    const base = `${verb} ${bytesWritten} bytes to ${target}`;
    const suffix = truncated
      ? " (truncated; continue with append: true and no overlap)"
      : "";
    const cleanupSuffix = cleanupError
      ? " [temp cleanup failed; non-fatal]"
      : "";
    return `${base}${suffix}${cleanupSuffix}`;
  }

  private makeErrorResult(
    code: StreamingWriteErrorCode,
    message: string,
    truncated: boolean,
  ): StreamingWriteResult {
    return {
      toolCallId: this.init.toolCallId,
      streamIndex: this.init.streamIndex,
      name: "write_file",
      arguments: {
        ...(this.path !== undefined ? { path: this.path } : {}),
        ...(this.append !== undefined ? { append: this.append } : {}),
        ...(this.overwrite !== undefined ? { overwrite: this.overwrite } : {}),
        content: "",
        __streamed: {
          bytesWritten: 0,
          truncated,
          errorCode: code,
        },
      },
      resultText: `write_file failed: ${message}`,
      isError: true,
      errorCode: code,
      bytesWritten: 0,
      truncated,
    };
  }
}

export function buildTempPath(
  runId: string,
  turnIndex: number,
  streamIndex: number,
): string {
  const safeRunId = sanitizePathSegment(runId);
  return `${STREAM_TEMP_ROOT}/${safeRunId}/${turnIndex}-${streamIndex}.partial`;
}

function sanitizePathSegment(s: string): string {
  // Replace characters that are unsafe inside a VFS path segment.
  return s.replace(/[^\w.-]+/g, "_");
}

function makeContentPlaceholder(
  path: string | undefined,
  bytesWritten: number,
): string {
  const target = path ?? "<unknown path>";
  return `[streamed content omitted: ${bytesWritten} bytes already written to ${target}; use read_file if content is needed]`;
}
