function parseAddressParts(input: string): {
  city?: string;
  state?: string;
  zip?: string;
} {
  const text = input.trim();

  // Typical pattern: "street, city, ST 12345"
  const withCommas = text.match(
    /,\s*([^,]+?)\s*,\s*([A-Za-z]{2}|[A-Za-z ]+)\s*(\d{5}(?:-\d{4})?)?\s*$/,
  );
  if (withCommas) {
    const city = withCommas[1]?.trim();
    const rawState = withCommas[2]?.trim();
    const zip = withCommas[3]?.trim();
    const state = rawState
      ? (US_STATE_ABBR_TO_NAME[rawState.toUpperCase()] ?? rawState)
      : undefined;
    return { city, state, zip };
  }

  // Fallback pattern without commas near the end: "... City ST 12345"
  const tailPattern = text.match(
    /\b([A-Za-z][A-Za-z .'-]+?)\s+([A-Za-z]{2})\s*(\d{5}(?:-\d{4})?)?\s*$/,
  );
  if (tailPattern) {
    const city = tailPattern[1]?.trim();
    const stateAbbr = tailPattern[2]?.toUpperCase();
    const zip = tailPattern[3]?.trim();
    const state = stateAbbr ? US_STATE_ABBR_TO_NAME[stateAbbr] : undefined;
    return { city, state, zip };
  }

  return {};
}

function buildAddressFallbackQueries(input: string): {
  queries: string[];
  stateHint?: string;
  preferCityMatch: boolean;
  usedAddressFallback: boolean;
} {
  const trimmedInput = input.trim();
  const normalized = normalizeLocationName(trimmedInput);
  const parts = parseAddressParts(input);
  const querySet = new Set<string>([normalized]);

  const cityStyleInput = /\bcity\b/i.test(trimmedInput);

  // Handle common country suffixes like ", USA" / ", United States".
  const withoutCountrySuffix = trimmedInput
    .replace(
      /,?\s*(usa|u\.?s\.?a\.?|us|u\.?s\.?|united states( of america)?)\s*$/i,
      "",
    )
    .trim();
  if (withoutCountrySuffix && withoutCountrySuffix !== trimmedInput) {
    querySet.add(normalizeLocationName(withoutCountrySuffix));
  }

  // If user provides a city-style phrase, try variant without trailing "City".
  const withoutCitySuffix = withoutCountrySuffix
    .replace(/\bcity\b\s*$/i, "")
    .replace(/\s+,/g, ",")
    .trim();
  if (withoutCitySuffix && withoutCitySuffix !== withoutCountrySuffix) {
    querySet.add(normalizeLocationName(withoutCitySuffix));
  }

  if (parts.city && parts.state) {
    querySet.add(normalizeLocationName(`${parts.city}, ${parts.state}`));
    querySet.add(normalizeLocationName(`${parts.city} ${parts.state}`));
  }
  if (parts.city) {
    querySet.add(normalizeLocationName(parts.city));
  }
  if (parts.state) {
    querySet.add(normalizeLocationName(parts.state));
  }

  return {
    queries: Array.from(querySet),
    stateHint: parts.state,
    preferCityMatch: cityStyleInput,
    usedAddressFallback:
      Boolean(parts.city || parts.state || parts.zip) &&
      (input.includes(",") || /\d/.test(input)),
  };
}

/**
 * Suggest the best base map based on resolved locations
 */
function suggestBaseMap(
  resolved: Array<{
    bestMatch: {
      country?: string;
      type?: string;
      name?: string;
      admin1?: string;
      lat?: number;
      lng?: number;
    } | null;
  }>,
): { mapId: string; reason: string } {
  const allCountries = resolved
    .map((r) => r.bestMatch?.country)
    .filter((c): c is string => !!c);

  const uniqueCountries = [...new Set(allCountries)];

  // Single country focus
  if (uniqueCountries.length === 1) {
    const country = uniqueCountries[0];
    const countryMapId = country.toLowerCase().replace(/\s+/g, "-");
    return { mapId: countryMapId, reason: `All locations in ${country}` };
  }

  // Check for US state-level focus when all locations are in the US
  const usMatches = resolved.filter(
    (r) => r.bestMatch?.country === "United States",
  );
  const usCount = usMatches.length;
  const totalLocations = resolved.length;

  if (usCount > 0 && usCount === totalLocations) {
    // Check if all US locations have the same state (admin1 field)
    const stateNames = usMatches
      .map((r) => r.bestMatch?.admin1)
      .filter((n): n is string => !!n && US_STATE_MAP[n] !== undefined);

    const uniqueStates = [...new Set(stateNames)];

    // If only one US state detected from admin1, use the state map
    if (uniqueStates.length === 1 && US_STATE_MAP[uniqueStates[0]]) {
      return {
        mapId: US_STATE_MAP[uniqueStates[0]],
        reason: `All locations in ${uniqueStates[0]}`,
      };
    }

    // Check if locations fall within Virginia's bounds (coordinate-based detection)
    const allLats = usMatches
      .map((r) => r.bestMatch?.lat)
      .filter((n): n is number => n !== undefined);
    const allLngs = usMatches
      .map((r) => r.bestMatch?.lng)
      .filter((n): n is number => n !== undefined);

    if (allLats.length > 0 && allLngs.length > 0) {
      const minLat = Math.min(...allLats);
      const maxLat = Math.max(...allLats);
      const minLng = Math.min(...allLngs);
      const maxLng = Math.max(...allLngs);

      // Virginia bounds (approximate): lat 36.5-39.5, lng -83.7 to -75.2
      const inVirginia =
        minLat >= 36.5 && maxLat <= 39.5 && minLng >= -83.7 && maxLng <= -75.2;

      if (inVirginia) {
        return { mapId: "usa-va", reason: "All locations within Virginia" };
      }
    }

    return {
      mapId: "usa",
      reason: `${usCount} locations in the United States`,
    };
  }

  // European focus
  const europeanCountries = [
    "Germany",
    "France",
    "Italy",
    "Spain",
    "United Kingdom",
    "Netherlands",
    "Belgium",
    "Austria",
    "Switzerland",
  ];
  const euroCount = uniqueCountries.filter((c) =>
    europeanCountries.includes(c),
  ).length;
  if (euroCount > 1 && euroCount / uniqueCountries.length > 0.6) {
    return {
      mapId: "world",
      reason: "European locations detected - using world map for full context",
    };
  }

  // Global data
  if (uniqueCountries.length > 5) {
    return {
      mapId: "world",
      reason: `${uniqueCountries.length} countries - global view recommended`,
    };
  }

  return {
    mapId: "world",
    reason: "Multiple regions - world view recommended",
  };
}

export const resolveLocationsTool = defineTool({
  name: "resolve_locations",
  category: "read",
  parallelSafe: true,
  label: "Resolve Locations",
  description:
    "Convert place names (countries, cities, states, regions) and address-like strings into geographic coordinates. " +
    "Perfect for datasets without lat/lng columns. Handles fuzzy matching, aliases, and common variations. " +
    "For full street addresses in offline mode, falls back to city/state centroid matching. Returns confidence and method used. " +
    "Use when: (1) You have location names like 'Germany' or 'Tokyo' and need coordinates, " +
    "(2) Address fields need approximate plotting via city/state, " +
    "(3) Location data may have typos or variations, " +
    "(4) Creating maps or calculating distances between places.",
  parameters: Type.Object({
    locations: Type.Array(Type.String(), {
      description:
        "Array of place names to resolve, e.g., ['Germany', 'Tokyo', 'New York']",
    }),
    maxMatches: Type.Optional(
      Type.Number({
        description: "Maximum match candidates per location (default: 3)",
        default: 3,
        minimum: 1,
        maximum: 10,
      }),
    ),
    includeAlternatives: Type.Optional(
      Type.Boolean({
        description:
          "Include close alternative matches when ambiguous (default: true)",
        default: true,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're resolving (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const { locations, maxMatches = 3, includeAlternatives = true } = params;

      if (!locations.length) {
        return toolError("No locations provided");
      }

      // Limit to avoid excessive processing
      if (locations.length > 1000) {
        return toolError("Too many locations. Maximum is 1000 at a time.");
      }

      // Resolve all locations (address-aware fallback)
      const resolved = locations.map((input) => {
        const { queries, stateHint, preferCityMatch, usedAddressFallback } =
          buildAddressFallbackQueries(input);

        const scoredMatches = new Map<
          string,
          {
            name: string;
            country: string;
            admin1?: string;
            lat: number;
            lng: number;
            score: number;
            type: "country" | "city" | "region";
            population?: number;
          }
        >();

        for (let i = 0; i < queries.length; i++) {
          const q = queries[i];
          const matches = fuzzySearch(q, maxMatches + 2);
          const queryPenalty = i === 0 ? 0 : 0.07 * i;

          for (const m of matches) {
            let adjustedScore = Math.max(0, m.score - queryPenalty);

            // If we extracted a US state from the address, prefer matches in that state.
            if (stateHint && m.admin1 === stateHint) {
              adjustedScore = Math.min(1, adjustedScore + 0.1);
            }

            // If input explicitly says "City", prefer city entities over regions.
            if (preferCityMatch) {
              if (m.type === "city") {
                adjustedScore = Math.min(1, adjustedScore + 0.08);
              } else if (m.type === "region") {
                adjustedScore = Math.max(0, adjustedScore - 0.05);
              }
            }

            const key = `${m.name}|${m.country}|${m.lat}|${m.lng}`;
            const existing = scoredMatches.get(key);
            if (!existing || adjustedScore > existing.score) {
              scoredMatches.set(key, {
                name: m.name,
                country: m.country,
                admin1: m.admin1,
                lat: m.lat,
                lng: m.lng,
                score: adjustedScore,
                type: m.type,
                population: m.population,
              });
            }
          }
        }

        const matches = Array.from(scoredMatches.values())
          .sort((a, b) => {
            if (b.score !== a.score) return b.score - a.score;
            return (b.population || 0) - (a.population || 0);
          })
          .slice(0, maxMatches);

        const bestMatch = matches.length > 0 ? matches[0] : null;
        const hasMultipleMatches =
          matches.length > 1 && matches[1].score > matches[0].score * 0.9;

        return {
          query: input,
          matches,
          bestMatch,
          hasMultipleMatches,
          resolutionMethod: usedAddressFallback
            ? "address_fallback_city_state"
            : "name_match",
        };
      });

      // Build output
      const results = resolved.map((result) => {
        const matches = includeAlternatives
          ? result.matches
          : result.matches.slice(0, 1);

        return {
          input: result.query,
          resolutionMethod:
            (result as { resolutionMethod?: string }).resolutionMethod ||
            "name_match",
          bestMatch: result.bestMatch
            ? {
                name: result.bestMatch.name,
                country: result.bestMatch.country,
                admin1: result.bestMatch.admin1,
                latitude: result.bestMatch.lat,
                longitude: result.bestMatch.lng,
                confidence: Math.round(result.bestMatch.score * 100) / 100,
                type: result.bestMatch.type,
                population: result.bestMatch.population,
              }
            : null,
          matches: matches.map((m) => ({
            name: m.name,
            country: m.country,
            admin1: m.admin1,
            latitude: m.lat,
            longitude: m.lng,
            confidence: Math.round(m.score * 100) / 100,
            type: m.type,
            population: m.population,
          })),
          isAmbiguous: result.hasMultipleMatches && matches.length > 1,
        };
      });

      const totalResolved = results.filter((r) => r.bestMatch !== null).length;
      const failedLocations = results
        .filter((r) => r.bestMatch === null)
        .map((r) => r.input);

      // Suggest best base map for visualization
      const mapSuggestion = suggestBaseMap(resolved);

      return toolSuccess({
        totalInput: locations.length,
        totalResolved,
        failedCount: failedLocations.length,
        failedLocations:
          failedLocations.length > 0 ? failedLocations : undefined,
        results,
        mapSuggestion: {
          baseMap: mapSuggestion.mapId,
          reason: mapSuggestion.reason,
          note: "Use this baseMap value with generate_map_chart for airgapped maps",
        },
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error resolving locations";
      return toolError(message);
    }
  },
});
