/**
 * Lightweight dev-only logging gate for workflow internals.
 *
 * The `[WorkflowManager]` / `[RequestQueue]` tracing is invaluable when
 * triaging tool-dispatch issues in a development build, but it floods
 * the browser console for every MCP / Office tool call in production.
 * This helper centralizes the Vite `import.meta.env`-based gate so the
 * call sites can use the same shape as
 * {@link ../agent/concurrency-invariant.ts:isDevBuild}.
 *
 * Warnings and errors are intentionally NOT gated — those should always
 * surface so operators can see actual failures in production builds.
 */

let cachedIsDev: boolean | null = null;

function detectDev(): boolean {
  try {
    const env = (
      import.meta as unknown as Record<string, Record<string, unknown>>
    ).env;
    const devFlag = env?.DEV;
    if (typeof devFlag === "boolean") {
      return devFlag;
    }
    if (devFlag === "true") {
      return true;
    }
    if (devFlag === "false") {
      return false;
    }
    const mode = env?.MODE;
    if (typeof mode === "string") {
      return mode !== "production";
    }
  } catch {
    // Ignore environments without Vite-style import.meta.env.
  }
  return false;
}

export function isDevBuild(): boolean {
  if (cachedIsDev === null) {
    cachedIsDev = detectDev();
  }
  return cachedIsDev;
}

export function debugLog(...args: unknown[]): void {
  if (!isDevBuild()) return;
  console.log(...args);
}
