import type { AzureEnvironment } from "./agent/providers/azure-entra-cloud";

export interface EndpointRuntimeTuning {
  maxContextTokens?: number;
  maxRetries?: number;
  rateLimitDelayMs?: number;
  maxOutputTokens?: number;
  workflowMaxRequestsPerMinute?: number;
  workflowMaxConcurrent?: number;
  /**
   * Per-request time-to-first-response timeout (ms). Overrides
   * `AIRGAP_CONFIG.timeouts.requestTimeoutMs`. Raise for deployments where
   * reasoning models or large document generations delay the first response.
   */
  requestTimeoutMs?: number;
  /** Maximum silence between streamed response-body chunks. */
  streamIdleTimeoutMs?: number;
  /** Maximum time without model-visible content while keepalives arrive. */
  meaningfulStreamTimeoutMs?: number;
}

export interface AzureEndpointRuntimeTuning extends EndpointRuntimeTuning {
  /** Azure OpenAI data-plane API version for the selected API mode. */
  apiVersion?: string;
  /** Optional Azure deployment token-per-minute quota. */
  workflowMaxTokensPerMinute?: number;
}

export interface RuntimeAgentTuningConfig {
  azure?: AzureEndpointRuntimeTuning;
  openai?: EndpointRuntimeTuning;
  /** Optional lower completion-token cap used only for Word turns. */
  wordMaxOutputTokens?: number;
  /**
   * Deprecated rollout flag retained for compatibility with existing
   * runtime-config files. The first-party workflow state path now always
   * uses structured TODOs.
   */
  structuredTodos?: boolean;
  /** Alpha flag for per-run MCP lazy loading. Defaults false. */
  mcpLazyLoading?: boolean;
  /**
   * Fresh-per-turn context (see `src/lib/agent/turn-context-reset.ts`).
   * When `true`, every `agent.prompt(...)` resets the agent's outbound
   * message history and prepends a single bounded synthetic summary so
   * MCP tool schemas + tool-result payloads from earlier turns can never
   * blow the model's max-prompt-tokens budget. Defaults to `false` so
   * the model keeps the real conversation across turns and only falls
   * back to summarization via `prepareMessagesForApi` when
   * `maxContextTokens` is actually exceeded. Set to `true` to re-enable
   * the unconditional per-turn reset.
   */
  freshContextPerTurn?: boolean;
  /**
   * Hard cap on the synthetic summary user message body, in characters.
   * Defaults to 2000. Clamped to a 200-char floor at use time.
   */
  contextSummaryMaxChars?: number;
  /**
   * When `true`, the longer markdown summary is mirrored to
   * `/home/user/uploads/working-set/conversation-summary.md` so the model can
   * `bash cat` / `read` it on demand. Defaults to `false`.
   */
  writeContextSummaryToWiki?: boolean;
  /** Losslessly stage oversized tool results in the session VFS. Defaults true. */
  toolResultOffloadEnabled?: boolean;
  /** Absolute per-result token ceiling before VFS offload. Defaults 6000. */
  toolResultOffloadMaxTokens?: number;
}

export interface RuntimeAgentLoopConfig {
  /** Wall-clock run budget in ms. Defaults to 10 minutes when omitted. */
  maxWallClockMs?: number;
  /** Max provider turns per run. Defaults to 50 when omitted. */
  maxIterations?: number;
  /** PR-5: allow all-parallel-safe read batches to execute concurrently. */
  enableParallelTools?: boolean;
  /** PR-5 guardrail: max concurrent parallel-safe read tools in one batch. */
  maxParallelReadTools?: number;
  /** Per-tool execution timeout; defaults to the AIRGAP timeout. */
  toolExecutionTimeoutMs?: number;
  /** Pause sensitive Office tools for in-tab review. Defaults false. */
  toolApprovalEnabled?: boolean;
  /** Expose the bounded read-only `task` child tool. Defaults false. */
  childAgentsEnabled?: boolean;
  /** Provider-turn ceiling per child task. Defaults 10. */
  childAgentMaxIterations?: number;
}

/**
 * Deploy-time defaults for the Settings tab. Every field is optional; a value
 * set here pre-fills the corresponding Settings input so end users do not have
 * to type it unless they want to change it. Saved user config always wins over
 * these defaults. Field names/types intentionally mirror `ProviderConfig` in
 * `provider-config.ts` (which maps them across without re-normalizing).
 *
 * Note: `apiKey` and `documentIntelligenceKey` are secrets. Only embed them in
 * `runtime-config.json` for trusted, self-hosted deployments — the file is
 * served to the browser in clear text.
 */
export interface RuntimeProviderDefaults {
  provider?: "azure" | "my-ai";
  model?: string;
  apiKey?: string;
  useProxy?: boolean;
  proxyUrl?: string;
  thinking?: "none" | "low" | "medium" | "high";
  followMode?: boolean;
  azureEndpoint?: string;
  azureDeploymentName?: string;
  azureApiMode?: "chat-completions" | "responses";
  useEntraId?: boolean;
  azureClientId?: string;
  /** Microsoft Entra tenant ID (GUID or `common`/`organizations`/`consumers`). */
  azureTenantId?: string;
  /** Azure cloud used for Entra authentication and Azure OpenAI tokens. */
  azureEntraCloud?: "commercial" | "gcc" | "usnat";
  /** Entra authority host supplied by the operator for restricted clouds. */
  azureEntraAuthorityHost?: string;
  /** Azure OpenAI token scope supplied by the operator for restricted clouds. */
  azureEntraTokenScope?: string;
  documentIntelligenceEndpoint?: string;
  documentIntelligenceKey?: string;
  openaiBaseUrl?: string;
  myAiBaseUrl?: string;
}

export interface RuntimeConfig {
  appInsightsEnabled: boolean;
  appInsightsConnectionString: string;
  includeUsernameForEntra: boolean;
  airGappedMode: boolean;
  /** Network boundary controlling which Azure Entra clouds may be selected. */
  azureEnvironment: AzureEnvironment;
  captureUserInput: boolean;
  agentTuning: RuntimeAgentTuningConfig;
  agentLoop: RuntimeAgentLoopConfig;
  /**
   * Phase E: master flag for the stream-to-VFS pipeline. When `true`
   * AND `provider.supportsStreamingHooks === true`, the Agent passes
   * a `StreamingToolController`'s hooks to `provider.runTurn`, so
   * `write_file.content` deltas land directly in the VFS instead of
   * being buffered in `tool_calls[i].function.arguments`. Defaults to
   * `false` to keep parity with the existing salvage path until the
   * Phase F rollout. Tests opt in explicitly.
   */
  streamingToolSinks: boolean;
  /** Deploy-time defaults for the Settings tab (see {@link RuntimeProviderDefaults}). */
  providerDefaults: RuntimeProviderDefaults;
  /** Raw MCP connections config; validated by the agent layer at runtime. */
  mcp?: unknown;
}

const DEFAULT_WORD_MAX_OUTPUT_TOKENS = 4096;
export const DEFAULT_TOOL_RESULT_OFFLOAD_MAX_TOKENS = 6000;
export const DEFAULT_CHILD_AGENT_MAX_ITERATIONS = 10;

const DEFAULT_CONFIG: RuntimeConfig = {
  appInsightsEnabled: false,
  appInsightsConnectionString: "",
  includeUsernameForEntra: false,
  airGappedMode: false,
  azureEnvironment: "internet",
  captureUserInput: false,
  agentTuning: {
    wordMaxOutputTokens: DEFAULT_WORD_MAX_OUTPUT_TOKENS,
    freshContextPerTurn: false,
    toolResultOffloadEnabled: true,
    toolResultOffloadMaxTokens: DEFAULT_TOOL_RESULT_OFFLOAD_MAX_TOKENS,
  },
  agentLoop: {
    enableParallelTools: true,
    maxParallelReadTools: 3,
    toolApprovalEnabled: false,
    childAgentsEnabled: false,
    childAgentMaxIterations: DEFAULT_CHILD_AGENT_MAX_ITERATIONS,
  },
  streamingToolSinks: false,
  providerDefaults: {},
  mcp: undefined,
};

function toPositiveInteger(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return Math.floor(value);
  }

  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) {
      return undefined;
    }

    const parsed = Number.parseInt(trimmed, 10);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed;
    }
  }

  return undefined;
}

function normalizeEndpointTuning(value: unknown): EndpointRuntimeTuning {
  const tuning =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};

  return {
    maxContextTokens: toPositiveInteger(tuning.maxContextTokens),
    maxRetries: toPositiveInteger(tuning.maxRetries),
    rateLimitDelayMs: toPositiveInteger(tuning.rateLimitDelayMs),
    maxOutputTokens: toPositiveInteger(tuning.maxOutputTokens),
    workflowMaxRequestsPerMinute: toPositiveInteger(
      tuning.workflowMaxRequestsPerMinute,
    ),
    workflowMaxConcurrent: toPositiveInteger(tuning.workflowMaxConcurrent),
    requestTimeoutMs: toPositiveInteger(tuning.requestTimeoutMs),
    streamIdleTimeoutMs: toPositiveInteger(tuning.streamIdleTimeoutMs),
    meaningfulStreamTimeoutMs: toPositiveInteger(
      tuning.meaningfulStreamTimeoutMs,
    ),
  };
}

function normalizeAzureEndpointTuning(
  value: unknown,
): AzureEndpointRuntimeTuning {
  const tuning = normalizeEndpointTuning(value);
  const raw =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};
  const apiVersion = toOptionalString(raw.apiVersion)?.trim();
  return {
    ...tuning,
    ...(apiVersion ? { apiVersion } : {}),
    workflowMaxTokensPerMinute: toPositiveInteger(
      raw.workflowMaxTokensPerMinute,
    ),
  };
}

function normalizeAgentLoop(value: unknown): RuntimeAgentLoopConfig {
  const loop =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};
  const maxWallClockMs = toPositiveInteger(loop.maxWallClockMs);
  const maxIterations = toPositiveInteger(loop.maxIterations);
  const enableParallelTools =
    typeof loop.enableParallelTools === "boolean"
      ? loop.enableParallelTools
      : true;
  const maxParallelReadTools =
    toPositiveInteger(loop.maxParallelReadTools) ?? 3;
  const toolExecutionTimeoutMs = toPositiveInteger(loop.toolExecutionTimeoutMs);
  const toolApprovalEnabled = loop.toolApprovalEnabled === true;
  const childAgentsEnabled = loop.childAgentsEnabled === true;
  const childAgentMaxIterations =
    toPositiveInteger(loop.childAgentMaxIterations) ??
    DEFAULT_CHILD_AGENT_MAX_ITERATIONS;
  return {
    maxWallClockMs,
    maxIterations,
    enableParallelTools,
    maxParallelReadTools,
    toolExecutionTimeoutMs,
    toolApprovalEnabled,
    childAgentsEnabled,
    childAgentMaxIterations,
  };
}

function toOptionalString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function toOptionalBoolean(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

function toOptionalStringEnum<T extends string>(
  value: unknown,
  allowed: readonly T[],
): T | undefined {
  return typeof value === "string" &&
    (allowed as readonly string[]).includes(value)
    ? (value as T)
    : undefined;
}

function normalizeProviderDefaults(value: unknown): RuntimeProviderDefaults {
  const raw =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};

  const out: RuntimeProviderDefaults = {};

  const provider = toOptionalStringEnum(raw.provider, [
    "azure",
    "my-ai",
  ] as const);
  if (provider !== undefined) out.provider = provider;

  const model = toOptionalString(raw.model);
  if (model !== undefined) out.model = model;

  const apiKey = toOptionalString(raw.apiKey);
  if (apiKey !== undefined) out.apiKey = apiKey;

  const useProxy = toOptionalBoolean(raw.useProxy);
  if (useProxy !== undefined) out.useProxy = useProxy;

  const proxyUrl = toOptionalString(raw.proxyUrl);
  if (proxyUrl !== undefined) out.proxyUrl = proxyUrl;

  const thinking = toOptionalStringEnum(raw.thinking, [
    "none",
    "low",
    "medium",
    "high",
  ] as const);
  if (thinking !== undefined) out.thinking = thinking;

  const followMode = toOptionalBoolean(raw.followMode);
  if (followMode !== undefined) out.followMode = followMode;

  const azureEndpoint = toOptionalString(raw.azureEndpoint);
  if (azureEndpoint !== undefined) out.azureEndpoint = azureEndpoint;

  const azureDeploymentName = toOptionalString(raw.azureDeploymentName);
  if (azureDeploymentName !== undefined)
    out.azureDeploymentName = azureDeploymentName;

  const azureApiMode = toOptionalStringEnum(raw.azureApiMode, [
    "chat-completions",
    "responses",
  ] as const);
  if (azureApiMode !== undefined) out.azureApiMode = azureApiMode;

  const useEntraId = toOptionalBoolean(raw.useEntraId);
  if (useEntraId !== undefined) out.useEntraId = useEntraId;

  const azureClientId = toOptionalString(raw.azureClientId);
  if (azureClientId !== undefined) out.azureClientId = azureClientId;

  const azureTenantId = toOptionalString(raw.azureTenantId);
  if (azureTenantId !== undefined) out.azureTenantId = azureTenantId;

  const azureEntraCloud = toOptionalStringEnum(raw.azureEntraCloud, [
    "commercial",
    "gcc",
    "usnat",
  ] as const);
  if (azureEntraCloud !== undefined) out.azureEntraCloud = azureEntraCloud;

  const azureEntraAuthorityHost = toOptionalString(raw.azureEntraAuthorityHost);
  if (azureEntraAuthorityHost !== undefined)
    out.azureEntraAuthorityHost = azureEntraAuthorityHost;

  const azureEntraTokenScope = toOptionalString(raw.azureEntraTokenScope);
  if (azureEntraTokenScope !== undefined)
    out.azureEntraTokenScope = azureEntraTokenScope;

  const documentIntelligenceEndpoint = toOptionalString(
    raw.documentIntelligenceEndpoint,
  );
  if (documentIntelligenceEndpoint !== undefined)
    out.documentIntelligenceEndpoint = documentIntelligenceEndpoint;

  const documentIntelligenceKey = toOptionalString(raw.documentIntelligenceKey);
  if (documentIntelligenceKey !== undefined)
    out.documentIntelligenceKey = documentIntelligenceKey;

  const openaiBaseUrl = toOptionalString(raw.openaiBaseUrl);
  if (openaiBaseUrl !== undefined) out.openaiBaseUrl = openaiBaseUrl;

  const myAiBaseUrl = toOptionalString(raw.myAiBaseUrl);
  if (myAiBaseUrl !== undefined) out.myAiBaseUrl = myAiBaseUrl;

  return out;
}

function normalizeAgentTuning(value: unknown): RuntimeAgentTuningConfig {
  const tuning =
    value && typeof value === "object"
      ? (value as Record<string, unknown>)
      : {};

  const freshContextPerTurn =
    typeof tuning.freshContextPerTurn === "boolean"
      ? tuning.freshContextPerTurn
      : false;

  return {
    azure: normalizeAzureEndpointTuning(tuning.azure),
    openai: normalizeEndpointTuning(tuning.openai),
    wordMaxOutputTokens:
      toPositiveInteger(tuning.wordMaxOutputTokens) ??
      DEFAULT_WORD_MAX_OUTPUT_TOKENS,
    structuredTodos: tuning.structuredTodos === true,
    mcpLazyLoading: tuning.mcpLazyLoading === true,
    freshContextPerTurn,
    contextSummaryMaxChars: toPositiveInteger(tuning.contextSummaryMaxChars),
    writeContextSummaryToWiki: tuning.writeContextSummaryToWiki === true,
    toolResultOffloadEnabled:
      typeof tuning.toolResultOffloadEnabled === "boolean"
        ? tuning.toolResultOffloadEnabled
        : true,
    toolResultOffloadMaxTokens:
      toPositiveInteger(tuning.toolResultOffloadMaxTokens) ??
      DEFAULT_TOOL_RESULT_OFFLOAD_MAX_TOKENS,
  };
}

let cachedConfig: RuntimeConfig | null = null;

export async function loadRuntimeConfig(): Promise<RuntimeConfig> {
  if (cachedConfig) return cachedConfig;

  try {
    const response = await fetch("runtime-config.json", {
      cache: "no-store",
    });

    if (!response.ok) {
      cachedConfig = DEFAULT_CONFIG;
      return cachedConfig;
    }

    const raw = (await response.json()) as Partial<RuntimeConfig>;
    const azureEnvironment =
      toOptionalStringEnum(raw.azureEnvironment, ["internet", "ts"] as const) ??
      DEFAULT_CONFIG.azureEnvironment;
    cachedConfig = {
      ...DEFAULT_CONFIG,
      ...raw,
      azureEnvironment,
      agentTuning: normalizeAgentTuning(raw.agentTuning),
      agentLoop: normalizeAgentLoop(raw.agentLoop),
      streamingToolSinks: raw.streamingToolSinks === true,
      providerDefaults: normalizeProviderDefaults(raw.providerDefaults),
      mcp: raw.mcp,
    };
    return cachedConfig;
  } catch {
    cachedConfig = DEFAULT_CONFIG;
    return cachedConfig;
  }
}

export function getRuntimeConfigSync(): RuntimeConfig {
  return cachedConfig ?? DEFAULT_CONFIG;
}
