import { throwIfToolAborted } from "./word-tool-utils";

/* global Word */

// The Word integration intentionally does NOT toggle
// document.changeTrackingMode programmatically. Track changes is treated as a
// user-controlled setting: the agent honors whatever mode the user has set in
// Word and never flips it on or off as part of a tool execution. This helper
// is preserved as a pass-through so existing callers can keep their structure
// without special-casing the no-op behavior.
export async function withTemporaryChangeTracking<T>(
  _context: Word.RequestContext,
  _enabled: boolean | undefined,
  action: () => Promise<T>,
  signal?: AbortSignal,
): Promise<T> {
  throwIfToolAborted(signal);
  return action();
}
