import { Type } from "@sinclair/typebox";
import { appendFile } from "../vfs";
import { findInternalContentPlaceholder } from "./file-content-guard";
import { defineTool, toolError, toolSuccess } from "./types";

export const appendFileTool = defineTool({
  name: "append_file",
  category: "deliverable",
  parallelSafe: false,
  label: "Append File",
  description:
    "Append text content to a file in the virtual filesystem without rewriting existing bytes. " +
    "Use this to continue or extend an existing/generated artifact with ONLY the missing suffix. It creates the file if it does not exist. " +
    "For a middle-of-file change, use `edit_file` instead. For a brand-new small file or true full replacement, use `write_file`. " +
    "For bulk generated outputs from uploaded files, sheets, or CSV data, prefer a bash/js command with VFS redirection such as `js build.mjs > matches.json` or `>> matches.json`, then validate with read/count/parse; do not pass huge generated data through tool arguments.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file in the virtual filesystem (e.g. 'matches.json' or '/home/user/uploads/matches.json').",
    }),
    content: Type.String({
      description:
        "Text content to append. Include only new bytes that are not already present in the target file.",
    }),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const placeholder = findInternalContentPlaceholder(params.content);
      if (placeholder) {
        return toolError(
          `Refusing to append to ${params.path}: content includes an internal placeholder (${placeholder}). This placeholder is not file content; use read_file on the target path if existing content is needed, then append only real file bytes.`,
        );
      }

      await appendFile(params.path, params.content);
      return toolSuccess(`Appended to ${params.path}`);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error appending file";
      return toolError(message);
    }
  },
});
