/**
 * Workflow Manager - Centralized Request Orchestration
 *
 * Coordinates rate limiting, request queuing, circuit breaking, and tool execution
 * to prevent rate limit errors and manage API request flow across the application.
 */

import { debugLog } from "./dev-log";
import {
  extractRetryAfterMsFromError,
  isAdaptiveThrottleError,
  isExpectedToolFailure,
} from "./error-classification";
import { type RateLimiter, createRateLimiter } from "./rate-limiter";
import { type RequestQueue, createRequestQueue } from "./request-queue";
import { TokenRateLimiter } from "./token-rate-limiter";
import type {
  BatchedReadRequest,
  CircuitBreakerConfig,
  CircuitBreakerState,
  CircuitState,
  ProviderTokenQuota,
  QueueConfig,
  RateLimitConfig,
  RequestPriority,
  RetryConfig,
  TokenRateLimitConfig,
  TokenRateLimitResult,
  ToolExecutionConfig,
  ToolExecutionStatusHandler,
  WorkflowEvent,
  WorkflowEventHandler,
  WorkflowManagerConfig,
  WorkflowSession,
  WorkflowStats,
} from "./types";

const DEFAULT_CIRCUIT_BREAKER_CONFIG: Required<CircuitBreakerConfig> = {
  failureThreshold: 5,
  resetTimeoutMs: 60000,
  successThreshold: 3,
  halfOpenTimeoutMs: 30000,
};

const DEFAULT_TOOL_EXECUTION_CONFIG: Required<ToolExecutionConfig> = {
  toolCallsPerMinute: 60,
  interToolDelayMs: 1000,
  maxConcurrentTools: 2,
  enableBatching: true,
  batchWindowMs: 50,
};

export class WorkflowManager {
  private provider: string;
  private rateLimiter: RateLimiter;
  private tokenRateLimiter: TokenRateLimiter;
  private requestQueue: RequestQueue;
  private circuitBreakerState: CircuitBreakerState;
  private circuitBreakerConfig: Required<CircuitBreakerConfig>;
  private toolExecutionConfig: Required<ToolExecutionConfig>;
  private eventHandlers: WorkflowEventHandler[] = [];
  private sessions = new Map<string, WorkflowSession>();
  private activeSession: WorkflowSession | null = null;

  // Batching
  private batchedReads: BatchedReadRequest[] = [];
  private batchTimeout: ReturnType<typeof setTimeout> | null = null;

  // Metrics
  private lastActivity = Date.now();
  private eventCount = new Map<string, number>();
  private lastHealthStatus: boolean | null = null;

  constructor(config: WorkflowManagerConfig) {
    this.provider = config.provider;

    // Initialize rate limiter
    this.rateLimiter = createRateLimiter(this.provider, config.rateLimit);
    this.tokenRateLimiter = new TokenRateLimiter(config.tokenRateLimit);

    // Initialize request queue
    this.requestQueue = createRequestQueue(this.provider, config.queue);

    // Initialize circuit breaker
    this.circuitBreakerConfig = {
      ...DEFAULT_CIRCUIT_BREAKER_CONFIG,
    };
    this.circuitBreakerState = {
      state: "closed",
      failures: 0,
      successes: 0,
      lastFailureTime: 0,
      lastSuccessTime: 0,
      openedAt: 0,
    };

    // Initialize tool execution config
    this.toolExecutionConfig = {
      ...DEFAULT_TOOL_EXECUTION_CONFIG,
    };

    // Subscribe to sub-component events
    this.subscribeToComponents();

    // Start periodic health checks
    this.startHealthCheckLoop();
  }

  /**
   * Subscribe to workflow events
   */
  subscribe(handler: WorkflowEventHandler): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emit(event: WorkflowEvent): void {
    this.lastActivity = Date.now();
    this.eventCount.set(event.type, (this.eventCount.get(event.type) ?? 0) + 1);

    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error("[WorkflowManager] Event handler error:", err);
      }
    }
  }

  /**
   * Acquire a rate limit token (for external API calls)
   */
  async acquireRateLimitToken(timeoutMs = 30000): Promise<{
    allowed: boolean;
    remaining: number;
    retryAfterMs: number;
    consumed: boolean;
  }> {
    return this.rateLimiter.acquire(timeoutMs);
  }

  /** Acquire capacity from the optional provider token-per-minute budget. */
  async acquireTokenBudget(
    estimatedTokens: number,
    timeoutMs = 30000,
  ): Promise<TokenRateLimitResult> {
    return this.tokenRateLimiter.acquire(estimatedTokens, timeoutMs);
  }

  /** Synchronize the local token budget with provider response headers. */
  observeProviderTokenQuota(quota: ProviderTokenQuota): void {
    this.tokenRateLimiter.observe(quota);
  }

  updateTokenRateLimitConfig(config: TokenRateLimitConfig): void {
    this.tokenRateLimiter.updateConfig(config);
  }

  /**
   * Report a rate limit hit to enable adaptive throttling
   */
  reportRateLimitHit(retryAfterMs?: number): void {
    this.reportRecoverableHttpError(429, retryAfterMs);
  }

  /**
   * Report a recoverable provider HTTP error (e.g. LLM endpoint 429/400).
   *
   * This only feeds the *rate limiter* so future provider requests are
   * slowed down adaptively. It deliberately does NOT trip the
   * `WorkflowManager` circuit breaker, because that breaker gates
   * `executeTool` / `executeRequest` — which is used for *local* tool
   * execution (Office.js, VFS, etc.). Tripping it on remote LLM failures
   * would block unrelated local tools and produce a death spiral
   * (failed local tool → result fed back to LLM → another provider call
   * → another 429 → counter climbs further).
   *
   * Provider-level health is tracked separately by the run-level
   * `RunCircuitBreaker` in `agent.ts`, which is the correct place to
   * shed load against a degraded provider.
   */
  reportRecoverableHttpError(statusCode: number, retryAfterMs?: number): void {
    this.rateLimiter.reportRateLimitHit(retryAfterMs);
    if (statusCode === 429) {
      this.tokenRateLimiter.reportRateLimitHit(retryAfterMs);
    }
  }

  /**
   * Report a successful request
   */
  reportSuccess(): void {
    this.recordSuccess();
  }

  /**
   * Execute an API request with full workflow management
   */
  async executeRequest<R>(
    operation: string,
    execute: (signal?: AbortSignal) => Promise<R>,
    options: {
      priority?: RequestPriority;
      timeoutMs?: number;
      maxRetries?: number;
      dedupKey?: string;
      onStatus?: ToolExecutionStatusHandler;
    } = {},
  ): Promise<R> {
    const { onStatus, ...queueOptions } = options;

    // Check circuit breaker
    this.checkCircuitBreaker();
    if (this.circuitBreakerState.state === "open") {
      throw new Error(
        `Circuit breaker is open. Service temporarily unavailable. Will retry after ${this.getCircuitBreakerRetryAfter()}ms`,
      );
    }

    // Wait for rate limit token
    debugLog(`[WorkflowManager] Acquiring token for: ${operation}`);
    const initialRateLimitState = this.rateLimiter.peek();
    if (
      !initialRateLimitState.allowed &&
      initialRateLimitState.retryAfterMs > 0
    ) {
      emitToolStatus(
        onStatus,
        `Waiting ${formatDurationMs(initialRateLimitState.retryAfterMs)} for rate limit`,
      );
    }
    const rateLimitResult = await this.rateLimiter.acquire();
    debugLog(
      `[WorkflowManager] Token acquired: ${rateLimitResult.allowed} for: ${operation}`,
    );
    if (!rateLimitResult.allowed) {
      throw new Error("Rate limit exceeded. Please try again later.");
    }

    // Enqueue and execute
    debugLog(`[WorkflowManager] Enqueuing: ${operation}`);
    const queuedAt = Date.now();
    emitToolStatus(onStatus, "Queued in workflow");
    return this.requestQueue.enqueue(
      { operation },
      async (_payload: unknown, signal?: AbortSignal) => {
        try {
          const queueWaitMs = Date.now() - queuedAt;
          emitToolStatus(
            onStatus,
            queueWaitMs > 100
              ? `Running after ${formatDurationMs(queueWaitMs)} in queue`
              : "Running",
          );
          const result = await execute(signal);
          this.recordSuccess();
          return result;
        } catch (error) {
          this.recordFailure(error);
          throw error;
        }
      },
      queueOptions,
    );
  }

  /**
   * Check if a request can be made (dry-run check)
   */
  canMakeRequest(): { allowed: boolean; reason?: string } {
    // Check circuit breaker
    if (this.circuitBreakerState.state === "open") {
      return {
        allowed: false,
        reason: `Circuit breaker is open. Will retry after ${this.getCircuitBreakerRetryAfter()}ms`,
      };
    }

    // Check rate limiter
    const rateLimitResult = this.rateLimiter.peek();
    if (!rateLimitResult.allowed) {
      return {
        allowed: false,
        reason: `Rate limited. Retry after ${rateLimitResult.retryAfterMs}ms`,
      };
    }

    // Check queue capacity
    const queueStats = this.requestQueue.getStats();
    if (queueStats.pending > 50) {
      return {
        allowed: false,
        reason: "Request queue is heavily loaded. Please wait.",
      };
    }

    return { allowed: true };
  }

  /**
   * Execute a tool with rate limiting and delays between calls
   */
  async executeTool<R>(
    toolName: string,
    params: Record<string, unknown>,
    execute: () => Promise<R>,
    options: {
      isReadOperation?: boolean;
      maxRetries?: number;
      dedupKey?: string;
      /**
       * Bypass request-queue coalescing for calls whose policy requires every
       * invocation to execute, even when tool name and arguments match.
       */
      disableDeduplication?: boolean;
      onStatus?: ToolExecutionStatusHandler;
      /**
       * Skip the configured `interToolDelayMs` sleep before dispatching
       * this tool. Set by callers that already own the inter-tool
       * pacing decision (e.g. the OrchestratorDispatcher, which paces
       * write operations via its own serial queue and runs read-batches
       * in parallel chunks). Has no effect on rate-limit token
       * acquisition or the request queue.
       */
      skipInterToolDelay?: boolean;
    } = {},
  ): Promise<R> {
    const {
      isReadOperation = false,
      maxRetries = 2,
      dedupKey,
      disableDeduplication = false,
      onStatus,
      skipInterToolDelay = false,
    } = options;
    debugLog(
      `[WorkflowManager] executeTool called: ${toolName} (readOp=${isReadOperation})`,
    );

    // For read operations, try to batch
    if (isReadOperation && this.toolExecutionConfig.enableBatching) {
      debugLog(`[WorkflowManager] Batching read tool: ${toolName}`);
      emitToolStatus(onStatus, "Queued for batched read");
      return this.queueBatchedRead(toolName, params, execute, onStatus);
    }

    // Add delay between tool executions
    const delay = this.toolExecutionConfig.interToolDelayMs;
    if (!skipInterToolDelay && delay > 0) {
      emitToolStatus(
        onStatus,
        `Waiting ${formatDurationMs(delay)} before execution`,
      );
      debugLog(`[WorkflowManager] Delaying ${delay}ms before: ${toolName}`);
      await sleep(delay);
    }

    debugLog(`[WorkflowManager] Executing through request queue: ${toolName}`);
    return this.executeRequest(
      toolName,
      async (signal) => {
        if (signal?.aborted) {
          throw new Error("Tool execution cancelled");
        }
        debugLog(`[WorkflowManager] Actually executing: ${toolName}`);
        return execute();
      },
      {
        priority: "normal",
        maxRetries,
        dedupKey: disableDeduplication
          ? undefined
          : (dedupKey ?? this.generateDedupKey(toolName, params)),
        onStatus,
      },
    );
  }

  /**
   * Start a new workflow session
   */
  startSession(): WorkflowSession {
    const session: WorkflowSession = {
      id: generateSessionId(),
      provider: this.provider,
      startedAt: Date.now(),
      lastActivity: Date.now(),
      requestCount: 0,
      tokenCount: 0,
      errorCount: 0,
      isActive: true,
    };

    this.sessions.set(session.id, session);
    this.activeSession = session;

    debugLog(`[WorkflowManager] Started session ${session.id}`);

    return session;
  }

  /**
   * End a workflow session
   */
  endSession(sessionId: string): void {
    const session = this.sessions.get(sessionId);
    if (session) {
      session.isActive = false;
      debugLog(
        `[WorkflowManager] Ended session ${sessionId}. ` +
          `Requests: ${session.requestCount}, Errors: ${session.errorCount}`,
      );
    }

    if (this.activeSession?.id === sessionId) {
      this.activeSession = null;
    }
  }

  /**
   * Get the current active session
   */
  getActiveSession(): WorkflowSession | null {
    return this.activeSession;
  }

  /**
   * Get workflow statistics
   */
  getStats(): WorkflowStats {
    const rateLimitState = this.rateLimiter.getState();
    const queueStats = this.requestQueue.getStats();
    const healthStatus = this.getHealthStatus();

    return {
      rateLimit: rateLimitState,
      queue: queueStats,
      isHealthy: healthStatus.healthy,
      lastActivity: this.lastActivity,
      healthReasons: healthStatus.reasons,
    };
  }

  /**
   * Check if the workflow is healthy
   */
  isHealthy(): boolean {
    const rateLimitState = this.rateLimiter.getState();
    const queueStats = this.requestQueue.getStats();

    // Circuit breaker should not be open for too long
    if (this.circuitBreakerState.state === "open") {
      const openDuration = Date.now() - this.circuitBreakerState.openedAt;
      if (openDuration > 300000) {
        // 5 minutes
        return false;
      }
    }

    // Queue shouldn't be overloaded
    if (queueStats.pending > 80) {
      return false;
    }

    // Too many rate limit hits is concerning
    if (rateLimitState.rateLimitHits > 10) {
      return false;
    }

    // Check if throttled by rate limiting
    if (rateLimitState.isThrottled) {
      return false;
    }

    return true;
  }

  /**
   * Get detailed health status with reasons if unhealthy
   */
  getHealthStatus(): { healthy: boolean; reasons: string[] } {
    const reasons: string[] = [];
    const rateLimitState = this.rateLimiter.getState();
    const queueStats = this.requestQueue.getStats();

    if (this.circuitBreakerState.state === "open") {
      const openDuration = Date.now() - this.circuitBreakerState.openedAt;
      if (openDuration > 300000) {
        reasons.push(
          `circuit breaker open for ${Math.floor(openDuration / 1000)}s`,
        );
      }
    }

    if (queueStats.pending > 80) {
      reasons.push(`queue overloaded (${queueStats.pending} pending)`);
    }

    if (rateLimitState.rateLimitHits > 10) {
      reasons.push(`rate limit hits high (${rateLimitState.rateLimitHits})`);
    }

    if (rateLimitState.isThrottled) {
      reasons.push("currently throttled (rate limit recovery)");
    }

    return { healthy: reasons.length === 0, reasons };
  }

  /**
   * Update configuration at runtime
   */
  updateRateLimitConfig(config: Partial<RateLimitConfig>): void {
    this.rateLimiter.updateConfig(config);
  }

  updateQueueConfig(config: Partial<QueueConfig>): void {
    this.requestQueue.updateConfig(config);
  }

  updateCircuitBreakerConfig(config: Partial<CircuitBreakerConfig>): void {
    this.circuitBreakerConfig = { ...this.circuitBreakerConfig, ...config };
  }

  updateToolExecutionConfig(config: Partial<ToolExecutionConfig>): void {
    this.toolExecutionConfig = { ...this.toolExecutionConfig, ...config };
  }

  /**
   * Reset all workflow state
   */
  reset(): void {
    this.rateLimiter.reset();
    this.requestQueue.clearStats();
    this.resetCircuitBreaker();
    this.sessions.clear();
    this.activeSession = null;
    this.eventCount.clear();
  }

  /**
   * Pause all workflow processing
   */
  pause(): void {
    this.requestQueue.pause();
    this.emit({
      type: "queue_stalled",
      timestamp: Date.now(),
      data: { reason: "manual_pause" },
    });
  }

  /**
   * Resume workflow processing
   */
  resume(): void {
    this.requestQueue.resume();
    this.emit({
      type: "queue_resumed",
      timestamp: Date.now(),
    });
  }

  /**
   * Dispose of the workflow manager
   */
  dispose(): void {
    this.requestQueue.dispose();
    this.rateLimiter.dispose();
    this.eventHandlers = [];
    this.sessions.clear();

    if (this.batchTimeout) {
      clearTimeout(this.batchTimeout);
    }
  }

  // ============== Private Methods ==============

  private subscribeToComponents(): void {
    // Rate limiter events
    this.rateLimiter.subscribe((event) => {
      if (event.type === "rate_limit_hit") {
        this.emit({
          type: "rate_limit_hit",
          timestamp: Date.now(),
          data: event.data,
        });
      } else if (event.type === "rate_limit_throttled") {
        this.emit({
          type: "rate_limit_throttled",
          timestamp: Date.now(),
          data: event.data,
        });
      } else if (event.type === "rate_limit_recovered") {
        this.emit({
          type: "rate_limit_recovered",
          timestamp: Date.now(),
          data: event.data,
        });
      }
    });

    // Request queue events
    this.requestQueue.subscribe((event) => {
      if (event.type === "request_queued") {
        this.emit({
          type: "request_queued",
          timestamp: Date.now(),
          requestId: (event.data as { requestId: string }).requestId,
          data: event.data,
        });
      } else if (event.type === "request_started") {
        this.emit({
          type: "request_started",
          timestamp: Date.now(),
          requestId: (event.data as { requestId: string }).requestId,
          data: event.data,
        });
      } else if (event.type === "request_completed") {
        this.emit({
          type: "request_completed",
          timestamp: Date.now(),
          requestId: (event.data as { requestId: string }).requestId,
          data: event.data,
        });
      } else if (event.type === "request_failed") {
        this.emit({
          type: "request_failed",
          timestamp: Date.now(),
          requestId: (event.data as { requestId: string }).requestId,
          data: event.data,
        });
      }
    });
  }

  private checkCircuitBreaker(): void {
    const now = Date.now();

    // If open, check if we should transition to half-open
    if (this.circuitBreakerState.state === "open") {
      const timeSinceOpen = now - this.circuitBreakerState.openedAt;
      if (timeSinceOpen >= this.circuitBreakerConfig.resetTimeoutMs) {
        debugLog(
          "[WorkflowManager] Circuit breaker transitioning to half-open",
        );
        this.circuitBreakerState.state = "half_open";
        this.circuitBreakerState.successes = 0;
      }
    }
  }

  private recordSuccess(): void {
    this.circuitBreakerState.lastSuccessTime = Date.now();
    this.rateLimiter.reportSuccess();

    if (this.circuitBreakerState.state === "half_open") {
      this.circuitBreakerState.successes++;
      if (
        this.circuitBreakerState.successes >=
        this.circuitBreakerConfig.successThreshold
      ) {
        debugLog(
          "[WorkflowManager] Circuit breaker closing (recovery successful)",
        );
        this.resetCircuitBreaker();
      }
    } else {
      // Gradually reduce failure count on success
      this.circuitBreakerState.failures = Math.max(
        0,
        this.circuitBreakerState.failures - 1,
      );
    }

    // Update session stats
    if (this.activeSession) {
      this.activeSession.requestCount++;
      this.activeSession.lastActivity = Date.now();
    }
  }

  private recordFailure(error: unknown): void {
    if (isExpectedToolFailure(error)) {
      if (this.activeSession) {
        this.activeSession.errorCount++;
      }
      return;
    }

    this.circuitBreakerState.failures++;
    this.circuitBreakerState.lastFailureTime = Date.now();

    // Update session stats
    if (this.activeSession) {
      this.activeSession.errorCount++;
    }

    // Check if we should open the circuit
    if (
      this.circuitBreakerState.failures >=
      this.circuitBreakerConfig.failureThreshold
    ) {
      console.warn(
        `[WorkflowManager] Circuit breaker opening due to ${this.circuitBreakerState.failures} failures`,
      );
      this.circuitBreakerState.state = "open";
      this.circuitBreakerState.openedAt = Date.now();
    }

    if (isAdaptiveThrottleError(error)) {
      const retryAfter = extractRetryAfterMsFromError(error);
      this.rateLimiter.reportRateLimitHit(retryAfter);
    }
  }

  private resetCircuitBreaker(): void {
    this.circuitBreakerState = {
      state: "closed",
      failures: 0,
      successes: 0,
      lastFailureTime: 0,
      lastSuccessTime: 0,
      openedAt: 0,
    };
  }

  private getCircuitBreakerRetryAfter(): number {
    if (this.circuitBreakerState.state !== "open") return 0;
    const elapsed = Date.now() - this.circuitBreakerState.openedAt;
    return Math.max(0, this.circuitBreakerConfig.resetTimeoutMs - elapsed);
  }

  private async queueBatchedRead<R>(
    toolName: string,
    params: Record<string, unknown>,
    executeFn: () => Promise<R>,
    onStatus?: ToolExecutionStatusHandler,
  ): Promise<R> {
    return new Promise((resolve, reject) => {
      this.batchedReads.push({
        toolName,
        params,
        execute: executeFn,
        resolve,
        reject,
        onStatus,
      });

      // Schedule batch flush
      if (!this.batchTimeout) {
        this.batchTimeout = setTimeout(() => {
          this.flushReadBatch();
        }, this.toolExecutionConfig.batchWindowMs);
      }
    });
  }

  private async flushReadBatch(): Promise<void> {
    if (this.batchedReads.length === 0) return;

    const batch = [...this.batchedReads];
    this.batchedReads = [];
    this.batchTimeout = null;

    debugLog(
      `[WorkflowManager] Flushing batch of ${batch.length} read requests`,
    );

    // Execute all reads with minimal delay
    for (let i = 0; i < batch.length; i++) {
      const request = batch[i];
      request.onStatus?.(
        batch.length > 1
          ? `Running batched read ${i + 1}/${batch.length}`
          : "Running batched read",
      );
      debugLog(
        `[WorkflowManager] Executing batch request ${i + 1}/${batch.length}: ${request.toolName}`,
      );
      try {
        const result = await request.execute();
        debugLog(
          `[WorkflowManager] Batch request ${i + 1} completed: ${request.toolName}`,
        );
        request.resolve(result);
      } catch (error) {
        console.error(
          `[WorkflowManager] Batch request ${i + 1} failed: ${request.toolName}`,
          error,
        );
        request.reject(
          error instanceof Error ? error : new Error(String(error)),
        );
      }

      // Small delay between batched reads
      if (batch.length > 1) {
        await sleep(50);
      }
    }
    debugLog("[WorkflowManager] Batch flush complete");
  }

  private generateDedupKey(
    toolName: string,
    params: Record<string, unknown>,
  ): string {
    // Sort keys for consistent hashing
    const sortedParams = Object.keys(params)
      .sort()
      .reduce<Record<string, unknown>>((acc, key) => {
        acc[key] = params[key];
        return acc;
      }, {});

    return `${toolName}:${JSON.stringify(sortedParams)}`;
  }

  private startHealthCheckLoop(): void {
    const checkInterval = setInterval(() => {
      const healthStatus = this.getHealthStatus();

      // Only log when health status changes
      if (
        this.lastHealthStatus !== null &&
        this.lastHealthStatus !== healthStatus.healthy
      ) {
        if (!healthStatus.healthy) {
          console.warn(
            `[WorkflowManager] Health check failed: ${healthStatus.reasons.join(", ")}`,
            this.getStats(),
          );
        } else {
          debugLog("[WorkflowManager] Health check recovered");
        }
      }

      this.lastHealthStatus = healthStatus.healthy;
    }, 30000);

    // Clean up on unload
    if (typeof window !== "undefined") {
      window.addEventListener("beforeunload", () => {
        clearInterval(checkInterval);
      });
    }
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function emitToolStatus(
  onStatus: ToolExecutionStatusHandler | undefined,
  statusText: string,
): void {
  onStatus?.(statusText);
}

function formatDurationMs(ms: number): string {
  const roundedMs = Math.max(1, Math.round(ms));
  if (roundedMs < 1000) {
    return `${roundedMs}ms`;
  }

  const seconds = roundedMs / 1000;
  return seconds >= 10 ? `${Math.round(seconds)}s` : `${seconds.toFixed(1)}s`;
}

function generateSessionId(): string {
  return `session-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 7)}`;
}

/**
 * Create a workflow manager for a specific provider
 */
export function createWorkflowManager(
  provider: string,
  customConfig?: Partial<Omit<WorkflowManagerConfig, "provider">>,
): WorkflowManager {
  const defaultRateLimit: Partial<RateLimitConfig> = {
    maxRequests: 60,
    windowMs: 60000,
    adaptiveLimiting: true,
  };

  const defaultQueue: Partial<QueueConfig> = {
    maxConcurrent: 2,
    maxQueueSize: 50,
    enableDeduplication: true,
  };

  return new WorkflowManager({
    provider,
    rateLimit: { ...defaultRateLimit, ...customConfig?.rateLimit },
    tokenRateLimit: customConfig?.tokenRateLimit,
    queue: { ...defaultQueue, ...customConfig?.queue },
    debug: customConfig?.debug ?? false,
  });
}
