/**
 * MCP Apps (SEP-1865) host-side helpers.
 *
 * The MCP Apps extension lets a server attach an interactive UI to a
 * tool by:
 *   1. Declaring `_meta.ui.resourceUri = "ui://..."` on the tool
 *      (modern format) — OR `_meta["ui/resourceUri"] = "ui://..."`
 *      (legacy format kept for backward compatibility with early
 *      OpenAI Apps SDK servers).
 *   2. Registering a resource at that URI whose first content block
 *      uses `mimeType = "text/html;profile=mcp-app"`.
 *   3. Optionally embedding the same `resource` block directly in the
 *      tool result's `content[]` so a host can render without a
 *      follow-up `resources/read`.
 *
 * This file is dependency-free on purpose: the transport / adapter /
 * chat layers all import these helpers, and we don't want to drag the
 * `@modelcontextprotocol/ext-apps` runtime into the agent core.
 *
 * Spec: see `/tmp/mcp-ext-apps/specification/draft/apps.mdx` and
 * `getToolUiResourceUri` in `src/app-bridge.ts` of that repo.
 */

import type { ToolContent, ToolUiResourcePayload } from "../types";

/** MIME type a server uses to mark an HTML resource as an MCP App view. */
export const MCP_UI_RESOURCE_MIME = "text/html;profile=mcp-app";

/** Legacy flat metadata key (predates the nested `ui` object). */
export const MCP_UI_LEGACY_RESOURCE_URI_KEY = "ui/resourceUri";

/** All `ui://` URIs are MCP App resources by convention. */
export const MCP_UI_URI_SCHEME = "ui://";

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Extract an MCP App UI resource URI from a `_meta` bag (or anything
 * shaped like one). Accepts both the modern nested form
 * `_meta.ui.resourceUri` and the legacy flat form
 * `_meta["ui/resourceUri"]`. Returns `undefined` if neither is present
 * or if the value is not a `ui://` string.
 */
export function getUiResourceUriFromMeta(
  meta: Record<string, unknown> | undefined | null,
): string | undefined {
  if (!isPlainObject(meta)) return undefined;

  const nested = meta.ui;
  if (isPlainObject(nested) && typeof nested.resourceUri === "string") {
    const candidate = nested.resourceUri.trim();
    if (candidate) return candidate;
  }

  const legacy = meta[MCP_UI_LEGACY_RESOURCE_URI_KEY];
  if (typeof legacy === "string" && legacy.trim()) {
    return legacy.trim();
  }

  return undefined;
}

/**
 * Higher-level convenience: pull a UI resource URI from any object that
 * may carry a `_meta` field — typically a tool descriptor returned by
 * `tools/list` or the `result` object returned by `tools/call`.
 */
export function getToolUiResourceUri(
  source: { _meta?: Record<string, unknown> } | null | undefined,
): string | undefined {
  if (!source) return undefined;
  return getUiResourceUriFromMeta(source._meta);
}

export interface EmbeddedUiResource {
  uri: string;
  html: string;
  mimeType: string;
  csp?: Record<string, unknown>;
  permissions?: Record<string, unknown>;
  meta?: Record<string, unknown>;
}

function uiMetaFromContents(meta: Record<string, unknown> | undefined): {
  csp?: Record<string, unknown>;
  permissions?: Record<string, unknown>;
} {
  if (!isPlainObject(meta)) return {};
  const ui = meta.ui;
  if (!isPlainObject(ui)) return {};
  return {
    csp: isPlainObject(ui.csp) ? ui.csp : undefined,
    permissions: isPlainObject(ui.permissions) ? ui.permissions : undefined,
  };
}

function decodeBlob(blob: string): string | null {
  try {
    if (typeof atob === "function") return atob(blob);
    if (typeof Buffer !== "undefined") {
      return Buffer.from(blob, "base64").toString("utf-8");
    }
  } catch {
    return null;
  }
  return null;
}

/**
 * Scan tool-call `content[]` for an embedded MCP App resource block.
 * Returns the first matching resource whose `mimeType` is the MCP App
 * profile. Honors both `text` and base64 `blob` payloads per the spec.
 */
export function extractEmbeddedUiResource(
  content: ToolContent[] | undefined,
): EmbeddedUiResource | undefined {
  if (!content) return undefined;

  for (const item of content) {
    if (item.type !== "resource") continue;
    const res = item.resource;
    if (!res || typeof res.uri !== "string") continue;
    const mime = typeof res.mimeType === "string" ? res.mimeType : "";
    if (!mime.startsWith("text/html")) continue;
    if (
      mime !== MCP_UI_RESOURCE_MIME &&
      !res.uri.startsWith(MCP_UI_URI_SCHEME)
    ) {
      continue;
    }

    let html: string | null = null;
    if (typeof res.text === "string") {
      html = res.text;
    } else if (typeof res.blob === "string") {
      html = decodeBlob(res.blob);
    }
    if (html === null) continue;

    const { csp, permissions } = uiMetaFromContents(res._meta);
    return {
      uri: res.uri,
      html,
      mimeType: mime || MCP_UI_RESOURCE_MIME,
      csp,
      permissions,
      meta: res._meta,
    };
  }

  return undefined;
}

/**
 * Resolve an MCP App UI payload from a `resources/read` response. The
 * response shape mirrors `ReadResourceResult` from the MCP SDK:
 * `{ contents: Array<{ uri, mimeType?, text?, blob?, _meta? }> }`.
 * Returns `undefined` if the first content block is not an MCP App
 * HTML payload.
 */
export function payloadFromReadResourceResult(
  uri: string,
  result: { contents?: unknown } | null | undefined,
): ToolUiResourcePayload | undefined {
  if (
    !result ||
    !Array.isArray(result.contents) ||
    result.contents.length === 0
  ) {
    return undefined;
  }
  const first = result.contents[0];
  if (!isPlainObject(first)) return undefined;

  const mime = typeof first.mimeType === "string" ? first.mimeType : "";
  if (mime && mime !== MCP_UI_RESOURCE_MIME && !mime.startsWith("text/html")) {
    return undefined;
  }

  let html: string | null = null;
  if (typeof first.text === "string") {
    html = first.text;
  } else if (typeof first.blob === "string") {
    html = decodeBlob(first.blob);
  }
  if (html === null) return undefined;

  const meta = isPlainObject(first._meta) ? first._meta : undefined;
  const { csp, permissions } = uiMetaFromContents(meta);

  return {
    uri,
    html,
    mimeType: mime || MCP_UI_RESOURCE_MIME,
    csp,
    permissions,
    meta,
  };
}

/** Cheap predicate: does this string look like an MCP App resource URI? */
export function isUiResourceUri(uri: string | undefined | null): boolean {
  return typeof uri === "string" && uri.startsWith(MCP_UI_URI_SCHEME);
}
