import type { Tool } from "../types";
import type { ToolCallToDispatch } from "./dispatcher";

export interface ToolPolicyContext {
  runId: string;
  call: ToolCallToDispatch;
  tool: Tool;
  runCallCount: number;
  toolRunCallCount: number;
}

export type ToolPolicyDecision =
  | { type: "allow"; arguments?: Record<string, unknown> }
  | {
      type: "deny";
      reason: string;
      code?: "policy_denied" | "call_limit_exceeded";
    }
  | {
      type: "require_approval";
      reason: string;
      arguments?: Record<string, unknown>;
    };

export interface ToolExecutionPolicy {
  name: string;
  beforeTool(
    context: ToolPolicyContext,
  ): ToolPolicyDecision | Promise<ToolPolicyDecision>;
}

export interface ToolCallLimits {
  globalRunLimit?: number;
  perToolRunLimit?: Readonly<Record<string, number>>;
}

function normalizeLimit(value: number | undefined): number | undefined {
  if (value === undefined || !Number.isFinite(value) || value < 1) {
    return undefined;
  }
  return Math.floor(value);
}

export function createToolCallLimitPolicy(
  limits: ToolCallLimits,
): ToolExecutionPolicy {
  const globalRunLimit = normalizeLimit(limits.globalRunLimit);
  const perToolRunLimit = new Map<string, number>();
  for (const [toolName, value] of Object.entries(
    limits.perToolRunLimit ?? {},
  )) {
    const normalized = normalizeLimit(value);
    if (normalized !== undefined) perToolRunLimit.set(toolName, normalized);
  }

  return {
    name: "tool-call-limits",
    beforeTool(context) {
      if (
        globalRunLimit !== undefined &&
        context.runCallCount >= globalRunLimit
      ) {
        return {
          type: "deny",
          code: "call_limit_exceeded",
          reason: `Global tool-call limit (${globalRunLimit}) reached for this run.`,
        };
      }

      const toolLimit = perToolRunLimit.get(context.tool.name);
      if (toolLimit !== undefined && context.toolRunCallCount >= toolLimit) {
        return {
          type: "deny",
          code: "call_limit_exceeded",
          reason: `Tool ${context.tool.name} reached its run limit (${toolLimit}).`,
        };
      }
      return { type: "allow" };
    },
  };
}

export async function evaluateToolPolicies(
  policies: readonly ToolExecutionPolicy[],
  context: ToolPolicyContext,
): Promise<ToolPolicyDecision> {
  let arguments_: Record<string, unknown> | undefined;
  for (const policy of policies) {
    const decision = await policy.beforeTool({
      ...context,
      call: arguments_
        ? { ...context.call, arguments: arguments_ }
        : context.call,
    });
    if (decision.type !== "allow") {
      return decision.type === "require_approval" && arguments_
        ? { ...decision, arguments: arguments_ }
        : decision;
    }
    if (decision.arguments) arguments_ = decision.arguments;
  }
  return arguments_
    ? { type: "allow", arguments: arguments_ }
    : { type: "allow" };
}

export function createOfficeApprovalPolicy(): ToolExecutionPolicy {
  return {
    name: "office-sensitive-actions",
    beforeTool({ call, tool }) {
      if (tool.destructive === true) {
        return {
          type: "require_approval",
          reason: `${tool.label} can irreversibly remove user data.`,
        };
      }
      if (tool.name === "eval_officejs") {
        return {
          type: "require_approval",
          reason:
            "Raw Office.js can perform operations outside the typed tool safeguards.",
        };
      }
      if (
        tool.name === "modify_workbook_structure" &&
        call.arguments.operation === "delete"
      ) {
        return {
          type: "require_approval",
          reason:
            "Deleting a worksheet cannot be automatically undone by OfficeAI.",
        };
      }
      if (
        tool.name === "modify_sheet_structure" &&
        call.arguments.operation === "delete"
      ) {
        return {
          type: "require_approval",
          reason: "Deleting rows or columns can remove workbook data.",
        };
      }
      return { type: "allow" };
    },
  };
}
