import { Type } from "@sinclair/typebox";
import { resolveStagedTextContent } from "./staged-content";
import { defineTool, toolError, toolSuccess } from "./types";

const COMPOSE_BODY_WRITTEN_PROPERTY = "officeaiComposeBodyWrittenV1";
const composeItemsWithInsertedReply = new WeakSet<object>();

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function convertReplyBody(
  body: string,
  sourceFormat: "html" | "text",
  targetFormat: Office.CoercionType,
): string {
  if (sourceFormat === "html" && targetFormat === Office.CoercionType.Text) {
    if (typeof DOMParser === "undefined") {
      throw new Error("HTML-to-text conversion is unavailable in this client");
    }
    const document = new DOMParser().parseFromString(body, "text/html");
    const blockTags = new Set([
      "address",
      "blockquote",
      "div",
      "h1",
      "h2",
      "h3",
      "h4",
      "h5",
      "h6",
      "p",
      "pre",
      "tr",
    ]);
    const renderNode = (node: Node): string => {
      if (node.nodeType === 3) return node.textContent ?? "";

      const tagName = node.nodeName.toLowerCase();
      if (tagName === "br") return "\n";
      if (tagName === "script" || tagName === "style") return "";

      const content = Array.from(node.childNodes).map(renderNode).join("");
      if (tagName === "li") return `- ${content.trim()}\n`;
      if (tagName === "td" || tagName === "th") return `${content}\t`;
      return blockTags.has(tagName) ? `${content}\n` : content;
    };

    return renderNode(document.body)
      .replace(/\u00a0/g, " ")
      .replace(/[ \t]+\n/g, "\n")
      .replace(/\n[ \t]+/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  if (sourceFormat === "text" && targetFormat === Office.CoercionType.Html) {
    return escapeHtml(body).replace(/\r?\n/g, "<br>");
  }

  return body;
}

export const emailReplyTool = defineTool({
  name: "email_reply",
  category: "non_idempotent",
  parallelSafe: false,
  maxRetries: 0,
  label: "Reply to Email",
  description:
    "Reply to the currently open email in Outlook, or edit the current compose draft. " +
    "In read mode (viewing an email), can reply to all recipients or just the sender with a new draft. " +
    "In compose mode (editing a draft), safely inserts one reply above the existing body so signatures and the quoted message are preserved. " +
    "A second insertion into the same compose item is rejected rather than stacking content or rewriting the whole body. " +
    "Supports both text and HTML body formats.",
  parameters: Type.Object({
    replyAll: Type.Optional(
      Type.Boolean({
        description:
          "If true, reply to all recipients (To + Cc). If false, reply only to sender. Default: false",
        default: false,
      }),
    ),
    body: Type.Optional(
      Type.String({
        description:
          "Reply body content. Optional when bodyFromFile is provided.",
      }),
    ),
    bodyFromFile: Type.Optional(
      Type.String({
        description:
          "VFS path containing the reply body. Stage substantial replies with write_file and prefer this over an inline body.",
      }),
    ),
    bodyFormat: Type.Optional(
      Type.String({
        enum: ["text", "html"],
        description:
          "Format of the reply body. Use 'html' for professional formatting. Default: 'html'",
        default: "html",
      }),
    ),
    preserveExistingBody: Type.Optional(
      Type.Boolean({
        description:
          "Compose mode only. When true (default), insert once above the existing draft without replacing the signature or quoted message. Set to false only when the user explicitly requests replacing the entire draft body.",
        default: true,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the reply purpose (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const stagedBody = await resolveStagedTextContent({
        content: params.body,
        fromFile: params.bodyFromFile,
        inlineFieldName: "body",
        fileFieldName: "bodyFromFile",
      });
      if ("error" in stagedBody) return toolError(stagedBody.error);
      const body = stagedBody.content;
      const bodyFormat = params.bodyFormat === "text" ? "text" : "html";

      const item = Office.context.mailbox.item;

      if (!item) {
        return toolError("No email item is currently open");
      }

      if (item.itemType !== Office.MailboxEnums.ItemType.Message) {
        return toolError("Current item is not an email message");
      }

      const messageCompose = item as Office.MessageCompose;
      const hasWritableComposeBody =
        typeof messageCompose.body?.setAsync === "function";

      // Handle compose mode: update the current draft body
      if (hasWritableComposeBody) {
        const composeBody = messageCompose.body;
        const replaceEntireBody = params.preserveExistingBody === false;

        const runAsync = <T>(
          op: (callback: (result: Office.AsyncResult<T>) => void) => void,
        ): Promise<T> =>
          new Promise<T>((resolve, reject) => {
            op((result) => {
              if (result.status === Office.AsyncResultStatus.Succeeded) {
                resolve(result.value);
              } else {
                reject(
                  new Error(result.error?.message || "Office operation failed"),
                );
              }
            });
          });

        try {
          let customProperties: Office.CustomProperties | undefined;
          let guardWarning: string | undefined;
          if (typeof messageCompose.loadCustomPropertiesAsync === "function") {
            try {
              customProperties = await runAsync<Office.CustomProperties>((cb) =>
                messageCompose.loadCustomPropertiesAsync(cb),
              );
            } catch (error) {
              if (!replaceEntireBody) {
                return toolError(
                  `Could not verify whether OfficeAI already modified this draft: ${error instanceof Error ? error.message : String(error)}`,
                );
              }
              guardWarning =
                "The repeat-write guard could not be persisted for this draft.";
            }
          } else if (!replaceEntireBody) {
            return toolError(
              "This Outlook client cannot load the item metadata required to prevent duplicate reply insertion.",
            );
          } else {
            guardWarning =
              "The repeat-write guard is unavailable in this Outlook client.";
          }

          if (
            !replaceEntireBody &&
            (composeItemsWithInsertedReply.has(messageCompose) ||
              customProperties?.get(COMPOSE_BODY_WRITTEN_PROPERTY) === "true")
          ) {
            return toolError(
              "OfficeAI already inserted a reply into this compose item. " +
                "The draft was left unchanged to avoid duplicate content or replacing user edits.",
            );
          }

          if (typeof composeBody.getTypeAsync !== "function") {
            return toolError(
              "This Outlook client cannot determine the compose body format safely.",
            );
          }

          const coercionType = await runAsync<Office.CoercionType>((cb) =>
            composeBody.getTypeAsync(cb),
          );
          if (
            coercionType !== Office.CoercionType.Html &&
            coercionType !== Office.CoercionType.Text
          ) {
            return toolError("Outlook returned an unsupported body format");
          }
          const convertedBody = convertReplyBody(
            body,
            bodyFormat,
            coercionType,
          );

          const persistWriteGuard = async (): Promise<string | undefined> => {
            composeItemsWithInsertedReply.add(messageCompose);
            if (!customProperties) {
              return guardWarning;
            }

            try {
              customProperties.set(COMPOSE_BODY_WRITTEN_PROPERTY, "true");
              await runAsync<void>((cb) => customProperties.saveAsync(cb));
              if (typeof messageCompose.saveAsync === "function") {
                await runAsync<string>((cb) => messageCompose.saveAsync(cb));
              }
              return guardWarning;
            } catch (error) {
              return `The reply was inserted, but Outlook could not persist the repeat-write guard: ${error instanceof Error ? error.message : String(error)}`;
            }
          };

          // Explicit, user-requested full replacement of the entire draft body.
          if (replaceEntireBody) {
            await runAsync<void>((cb) =>
              composeBody.setAsync(convertedBody, { coercionType }, cb),
            );
            const warning = await persistWriteGuard();
            return toolSuccess({
              success: true,
              message: "Compose draft body replaced",
              mode: "compose",
              action: "replaced",
              ...(warning ? { warning } : {}),
            });
          }

          if (typeof composeBody.prependAsync !== "function") {
            return toolError(
              "This Outlook client cannot insert a reply without replacing the existing message body. " +
                "Re-run with preserveExistingBody: false to overwrite the draft instead.",
            );
          }

          const separator =
            coercionType === Office.CoercionType.Html ? "<br><br>" : "\n\n";
          await runAsync<void>((cb) =>
            composeBody.prependAsync(
              `${convertedBody}${separator}`,
              { coercionType },
              cb,
            ),
          );
          const warning = await persistWriteGuard();
          return toolSuccess({
            success: true,
            message: "Reply inserted above the quoted message",
            mode: "compose",
            action: "inserted",
            ...(warning ? { warning } : {}),
          });
        } catch (e) {
          return toolError(
            `Failed to update compose draft: ${e instanceof Error ? e.message : String(e)}`,
          );
        }
      }

      // Handle read mode: create reply draft
      const messageRead = item as Office.MessageRead;
      const hasReplyMethod = typeof messageRead.displayReplyForm === "function";
      const hasReplyAllMethod =
        typeof messageRead.displayReplyAllForm === "function";

      if (params.replyAll && !hasReplyAllMethod) {
        return toolError(
          "Reply all is not supported in this Outlook context. " +
            "This may be due to permission restrictions or Outlook version limitations.",
        );
      }
      if (!params.replyAll && !hasReplyMethod) {
        return toolError(
          "Reply is not supported in this Outlook context. " +
            "This may be due to permission restrictions or Outlook version limitations.",
        );
      }

      // Build form parameters
      const formParams: {
        body?: string;
        htmlBody?: string;
      } = {};

      if (bodyFormat === "html") {
        formParams.htmlBody = body;
      } else {
        formParams.body = body;
      }

      // Use displayReplyForm or displayReplyAllForm
      try {
        if (params.replyAll) {
          messageRead.displayReplyAllForm(formParams);
        } else {
          messageRead.displayReplyForm(formParams);
        }
      } catch (e) {
        return toolError(
          `Failed to open reply form: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      const successMessage = `Reply${params.replyAll ? "-all" : ""} draft created and opened`;

      return toolSuccess({
        success: true,
        message: successMessage,
        replyAll: params.replyAll || false,
        mode: "read",
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error creating reply";
      return toolError(message);
    }
  },
});
