/**
 * Tool dispatcher.
 *
 * PR-2 extracted the duplicated `executeTool` body, dedup-window
 * bookkeeping, and `runToolWithTimeout` into this shared dispatcher.
 * Metadata is read via {@link normalizeToolMetadata}
 * so dispatch policy keys off `Tool.category` / `Tool.parallelSafe`
 * instead of legacy string-matched allowlists.
 *
 * PR-5 enables bounded parallel dispatch by default:
 * - If every call in a model-emitted batch is a `read` with
 *   `parallelSafe: true`,
 *   calls run concurrently in chunks of `maxParallelReadTools`.
 * - If any call is not parallel-safe, the entire batch runs serially
 *   in model-emitted order.
 * - Dispatcher-owned paths always bypass WorkflowManager read batching
 *   (`isReadOperation: false`) to preserve the single-owner invariant.
 *
 * See docs/agent-refactor-blueprint.md §6 / §6.1 and
 * docs/agent-refactor-implementation-plan.md PR-2 step 1.3 + PR-5.
 */

import { AIRGAP_CONFIG } from "../../airgap-config";
import { trackEvent } from "../../telemetry";
import type { WorkflowManager } from "../../workflow";
import { isExpectedToolFailure } from "../../workflow/error-classification";
import { ReadConcurrencyOwnershipError } from "../concurrency-invariant";
import { assertSingleReadConcurrencyOwner } from "../concurrency-invariant";
import {
  type AgentErrorCode,
  asAgentError,
  createAgentError,
  encodeToolErrorPayload,
} from "../errors";
import { validateJsonSchema } from "../json-schema";
import { type Clock, systemClock } from "../loop/clock";
import type { MCPToolFailureCode } from "../mcp";
import { normalizeToolMetadata } from "../tool-metadata";
import { getTurnRecorder } from "../turn-recorder";
import type { AgentEvent, Tool, ToolResult, ToolResultMessage } from "../types";
import type {
  ToolApprovalDecision,
  ToolApprovalRequest,
  ToolApprovalResolver,
} from "./approval";
import {
  type ToolCallLimits,
  type ToolExecutionPolicy,
  createToolCallLimitPolicy,
  evaluateToolPolicies,
} from "./policy";

export const NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS = 120000;
export const DEFAULT_MAX_PARALLEL_READ_TOOLS = 3;

export interface ToolCallToDispatch {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
}

export type DispatchEmitter = (event: AgentEvent) => void;

export interface ToolDispatcherOptions {
  /** Optional log prefix for agent-specific warnings. */
  logPrefix?: string;
  /** Tool execution timeout. Defaults to AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs. */
  toolExecutionTimeoutMs?: number;
  /** Optional turn-recorder run id; events are tagged with this id. */
  runId?: string;
  /** Whether all-parallel-safe model-emitted batches may run concurrently. */
  enableParallelTools?: boolean;
  /** PR-5 guardrail for concurrent parallel-safe reads. */
  maxParallelReadTools?: number;
  /** Optional MCP runtime hooks for availability checks and breaker accounting. */
  mcpRuntime?: MCPToolDispatchRuntime;
  /** Clock for replay determinism (PR-8a). Defaults to {@link systemClock}. */
  clock?: Clock;
  /** Ordered deterministic policies evaluated before every real tool call. */
  policies?: readonly ToolExecutionPolicy[];
  /** Optional per-run call ceilings, implemented as the first policy. */
  callLimits?: ToolCallLimits;
  /** Resolves one complete approval batch before any sibling call executes. */
  approvalResolver?: ToolApprovalResolver;
}

export interface MCPToolDispatchRuntime {
  isToolUnavailable(connectionId: string, toolName: string): boolean;
  recordToolResult(
    connectionId: string,
    toolName: string,
    outcome: "success" | MCPToolFailureCode,
    namespacedToolName?: string,
  ): void;
}

interface RecentToolExecution {
  toolCallId: string;
  completedAt: number;
}

export interface DispatchResult {
  /** Tool result message to append to agent state.messages. */
  message: ToolResultMessage;
  /** Whether the dispatch errored out (also reflected in `message.isError`). */
  isError: boolean;
  /** Structured error/suppression code when the dispatcher constructs one. */
  code?: AgentErrorCode;
  /** True when dispatcher short-circuited a duplicate non-idempotent call. */
  dedupSuppressed?: boolean;
  /**
   * Phase E: `true` when the dispatcher served a precomputed result
   * produced by the stream-to-VFS pipeline. Distinguishes streamed
   * deliveries from real local/MCP dispatches in telemetry / replay.
   */
  precomputed?: boolean;
  /** Arguments actually executed after policy/approval edits. */
  effectiveArguments?: Record<string, unknown>;
}

/**
 * Phase E: a precomputed tool result the orchestrator hands to the
 * dispatcher in lieu of executing the tool. Used by the stream-to-VFS
 * pipeline — the bytes already landed in the VFS while the LLM stream
 * was decoding, so the dispatcher must NOT call `tool.execute`. It
 * still emits the standard `tool_execution_start` / `_end` events,
 * records a `tool_call` row on the turn recorder, and produces a
 * normal {@link ToolResultMessage} so downstream code (assistant
 * message persistence, FSM `apply`, ephemeral truncation nudges)
 * cannot tell the difference between a streamed and a dispatched
 * call.
 *
 * `arguments` MUST be the compact D3 sentinel shape (no raw `content`)
 * because the dispatcher uses them as the canonical record-keeping
 * value. `resultText` becomes the single text content block of the
 * result message; callers MAY craft it to nudge the model toward a
 * `{ append: true }` continuation on truncated streams.
 */
export interface PrecomputedToolResult {
  toolCallId: string;
  name: string;
  arguments: Record<string, unknown>;
  resultText: string;
  isError: boolean;
  errorCode?: string;
}

function normalizeMaxParallelReadTools(value: number | undefined): number {
  if (value === undefined || !Number.isFinite(value) || value < 1) {
    return DEFAULT_MAX_PARALLEL_READ_TOOLS;
  }
  return Math.floor(value);
}

/**
 * Per-agent tool dispatcher. Owns the non-idempotent dedup window and
 * runs each tool through the {@link WorkflowManager} for rate limiting
 * and retry policy.
 */
export class ToolDispatcher {
  private readonly recentToolExecutions = new Map<
    string,
    RecentToolExecution
  >();
  private readonly toolExecutionTimeoutMs: number;
  private readonly logPrefix?: string;
  private enableParallelTools: boolean;
  private maxParallelReadTools: number;
  private runId: string;
  private mcpRuntime?: MCPToolDispatchRuntime;
  private readonly clock: Clock;
  private readonly policies: readonly ToolExecutionPolicy[];
  private runCallCount = 0;
  private readonly toolRunCallCounts = new Map<string, number>();
  private readonly approvalResolver?: ToolApprovalResolver;

  constructor(options: ToolDispatcherOptions = {}) {
    this.toolExecutionTimeoutMs =
      options.toolExecutionTimeoutMs ??
      AIRGAP_CONFIG.timeouts.toolExecutionTimeoutMs;
    this.logPrefix = options.logPrefix;
    this.enableParallelTools = options.enableParallelTools ?? true;
    this.maxParallelReadTools = normalizeMaxParallelReadTools(
      options.maxParallelReadTools,
    );
    this.runId = options.runId ?? "";
    this.mcpRuntime = options.mcpRuntime;
    this.clock = options.clock ?? systemClock;
    this.policies = [
      ...(options.callLimits
        ? [createToolCallLimitPolicy(options.callLimits)]
        : []),
      ...(options.policies ?? []),
    ];
    this.approvalResolver = options.approvalResolver;
  }

  /** Set the run id used to tag turn-recorder events. */
  setRunId(runId: string): void {
    this.runId = runId;
  }

  updateParallelConfig(config: {
    enableParallelTools?: boolean;
    maxParallelReadTools?: number;
  }): void {
    if (config.enableParallelTools !== undefined) {
      this.enableParallelTools = config.enableParallelTools;
    }
    if (config.maxParallelReadTools !== undefined) {
      this.maxParallelReadTools = normalizeMaxParallelReadTools(
        config.maxParallelReadTools,
      );
    }
  }

  setMcpRuntime(runtime: MCPToolDispatchRuntime | undefined): void {
    this.mcpRuntime = runtime;
  }

  /** Reset dedup state (called by `agent.reset()` / `agent.dispose()`). */
  clear(): void {
    this.recentToolExecutions.clear();
    this.runCallCount = 0;
    this.toolRunCallCounts.clear();
  }

  /**
   * Dispatch a single tool call. Returns the tool result message to push
   * onto agent state.messages. Emits `tool_execution_start` /
   * `tool_execution_update` / `tool_execution_end` events through `emit`.
   */
  async dispatch(
    toolCall: ToolCallToDispatch,
    tools: Tool[],
    workflowManager: WorkflowManager,
    signal: AbortSignal,
    emit: DispatchEmitter,
  ): Promise<DispatchResult> {
    const [result] = await this.dispatchBatch(
      [toolCall],
      tools,
      workflowManager,
      signal,
      emit,
    );
    return result;
  }

  async dispatchBatch(
    toolCalls: ToolCallToDispatch[],
    tools: Tool[],
    workflowManager: WorkflowManager,
    signal: AbortSignal,
    emit: DispatchEmitter,
  ): Promise<DispatchResult[]> {
    return this.dispatchBatchWithPrecomputed(
      toolCalls,
      tools,
      workflowManager,
      signal,
      emit,
      undefined,
    );
  }

  /**
   * Phase E: dispatch a batch where some calls already have a
   * precomputed result (e.g. the stream-to-VFS pipeline already
   * persisted the bytes). Precomputed entries bypass `tool.execute`,
   * `workflowManager.executeTool`, MCP availability gating, and the
   * dedup window — they emit `tool_execution_start` / `_end` events
   * and a turn-recorder row so downstream consumers cannot distinguish
   * them from a real dispatch.
   *
   * `precomputed` is keyed by `toolCallId`. Any entry whose toolCallId
   * is NOT in `precomputed` follows the normal dispatch path.
   *
   * Parallelism gate (PR-5 `allParallelSafe`) considers ONLY the
   * non-precomputed subset — precomputed entries are zero-cost and
   * are returned in model-emitted order regardless of batch mode.
   */
  async dispatchBatchWithPrecomputed(
    toolCalls: ToolCallToDispatch[],
    tools: Tool[],
    workflowManager: WorkflowManager,
    signal: AbortSignal,
    emit: DispatchEmitter,
    precomputed: ReadonlyMap<string, PrecomputedToolResult> | undefined,
  ): Promise<DispatchResult[]> {
    if (toolCalls.length === 0) {
      return [];
    }

    const preflight = await this.preflightBatch(
      toolCalls,
      tools,
      precomputed,
      signal,
    );
    const preparedCalls = preflight.calls;
    const dispatchable = preparedCalls.filter(
      (call) => !precomputed?.has(call.id) && !preflight.blocked.has(call.id),
    );

    const allParallelSafe =
      this.enableParallelTools &&
      dispatchable.length > 1 &&
      dispatchable.every((toolCall) => {
        const found = tools.find((tool) => tool.name === toolCall.name);
        if (!found) return false;
        const metadata = normalizeToolMetadata(found);
        return metadata.category === "read" && metadata.parallelSafe === true;
      });

    if (!allParallelSafe) {
      const serialResults: DispatchResult[] = [];
      for (const toolCall of preparedCalls) {
        const pre = precomputed?.get(toolCall.id);
        if (pre) {
          serialResults.push(this.emitPrecomputedResult(toolCall, pre, emit));
        } else if (preflight.blocked.has(toolCall.id)) {
          serialResults.push(
            this.emitPolicyBlockedResult(
              toolCall,
              preflight.blocked.get(toolCall.id)!,
              emit,
            ),
          );
        } else {
          const result = await this.dispatchOne(
            toolCall,
            tools,
            workflowManager,
            signal,
            emit,
          );
          serialResults.push({
            ...result,
            effectiveArguments: toolCall.arguments,
          });
        }
      }
      return serialResults;
    }

    const results = new Array<DispatchResult>(preparedCalls.length);
    // Settle precomputed entries up-front (synchronously) in model-
    // emitted order; only the dispatchable subset goes through the
    // bounded-parallel read chunks.
    for (let index = 0; index < preparedCalls.length; index++) {
      const pre = precomputed?.get(preparedCalls[index].id);
      if (pre) {
        results[index] = this.emitPrecomputedResult(
          preparedCalls[index],
          pre,
          emit,
        );
      } else {
        const blocked = preflight.blocked.get(preparedCalls[index].id);
        if (blocked) {
          results[index] = this.emitPolicyBlockedResult(
            preparedCalls[index],
            blocked,
            emit,
          );
        }
      }
    }

    const dispatchableIndexes: number[] = [];
    for (let index = 0; index < preparedCalls.length; index++) {
      if (
        !precomputed?.has(preparedCalls[index].id) &&
        !preflight.blocked.has(preparedCalls[index].id)
      ) {
        dispatchableIndexes.push(index);
      }
    }

    for (
      let offset = 0;
      offset < dispatchableIndexes.length;
      offset += this.maxParallelReadTools
    ) {
      const chunkIndexes = dispatchableIndexes.slice(
        offset,
        offset + this.maxParallelReadTools,
      );
      const chunkResults = await Promise.all(
        chunkIndexes.map((idx) =>
          this.dispatchOne(
            preparedCalls[idx],
            tools,
            workflowManager,
            signal,
            emit,
          ),
        ),
      );
      for (let i = 0; i < chunkIndexes.length; i++) {
        const index = chunkIndexes[i];
        results[index] = {
          ...chunkResults[i],
          effectiveArguments: preparedCalls[index].arguments,
        };
      }
    }

    return results;
  }

  private async preflightBatch(
    toolCalls: ToolCallToDispatch[],
    tools: Tool[],
    precomputed: ReadonlyMap<string, PrecomputedToolResult> | undefined,
    signal: AbortSignal,
  ): Promise<{
    calls: ToolCallToDispatch[];
    blocked: Map<string, { code: AgentErrorCode; reason: string }>;
  }> {
    const calls = toolCalls.map((call) => ({ ...call }));
    const blocked = new Map<string, { code: AgentErrorCode; reason: string }>();
    const approvalRequests: ToolApprovalRequest[] = [];
    let projectedRunCallCount = this.runCallCount;
    const projectedToolCounts = new Map(this.toolRunCallCounts);

    for (let index = 0; index < calls.length; index++) {
      const call = calls[index];
      if (precomputed?.has(call.id)) continue;
      const found = tools.find((tool) => tool.name === call.name);
      if (!found) continue;
      const tool = normalizeToolMetadata(found);
      const decision = await evaluateToolPolicies(this.policies, {
        runId: this.runId,
        call,
        tool,
        runCallCount: projectedRunCallCount,
        toolRunCallCount: projectedToolCounts.get(tool.name) ?? 0,
      });

      if (decision.type === "deny") {
        blocked.set(call.id, {
          code:
            decision.code === "call_limit_exceeded"
              ? "TOOL_CALL_LIMIT_EXCEEDED"
              : "TOOL_POLICY_DENIED",
          reason: decision.reason,
        });
        continue;
      }
      if (decision.type === "require_approval") {
        const approvalArguments = decision.arguments ?? call.arguments;
        if (decision.arguments) {
          calls[index] = { ...call, arguments: decision.arguments };
        }
        approvalRequests.push({
          toolCallId: call.id,
          name: tool.name,
          label: tool.label,
          arguments: approvalArguments,
          reason: decision.reason,
          allowedDecisions: ["approve", "edit", "reject"],
        });
      } else if (decision.arguments) {
        calls[index] = { ...call, arguments: decision.arguments };
      }

      projectedRunCallCount += 1;
      projectedToolCounts.set(
        tool.name,
        (projectedToolCounts.get(tool.name) ?? 0) + 1,
      );
    }

    if (approvalRequests.length === 0) return { calls, blocked };
    if (!this.approvalResolver) {
      for (const request of approvalRequests) {
        blocked.set(request.toolCallId, {
          code: "TOOL_APPROVAL_REQUIRED",
          reason: request.reason,
        });
      }
      return { calls, blocked };
    }

    let decisions: readonly ToolApprovalDecision[];
    try {
      decisions = await this.approvalResolver(approvalRequests, signal);
    } catch (error) {
      const reason =
        error instanceof Error ? error.message : "Approval was interrupted.";
      for (const request of approvalRequests) {
        blocked.set(request.toolCallId, {
          code: signal.aborted ? "TOOL_ABORTED" : "TOOL_POLICY_DENIED",
          reason,
        });
      }
      return { calls, blocked };
    }

    const byId = new Map(
      decisions.map((decision) => [decision.toolCallId, decision]),
    );
    for (const request of approvalRequests) {
      const decision = byId.get(request.toolCallId);
      const index = calls.findIndex((call) => call.id === request.toolCallId);
      const found = tools.find((tool) => tool.name === request.name);
      if (!decision || decision.type === "reject") {
        blocked.set(request.toolCallId, {
          code: "TOOL_POLICY_DENIED",
          reason:
            decision?.type === "reject"
              ? decision.message
              : "Approval decision was not provided; the tool was not executed.",
        });
        continue;
      }
      if (decision.type === "edit") {
        if (
          !found ||
          !validateJsonSchema(found.parameters, decision.arguments)
        ) {
          blocked.set(request.toolCallId, {
            code: "TOOL_POLICY_DENIED",
            reason: "Edited tool arguments did not match the tool schema.",
          });
          continue;
        }
        calls[index] = { ...calls[index], arguments: decision.arguments };
      }
    }
    return { calls, blocked };
  }

  private emitPolicyBlockedResult(
    toolCall: ToolCallToDispatch,
    blocked: { code: AgentErrorCode; reason: string },
    emit: DispatchEmitter,
  ): DispatchResult {
    const recorder = getTurnRecorder();
    const startedAt = this.clock.now();
    const result = toolErrorContent(blocked.reason, blocked.code, {
      toolName: toolCall.name,
      retryable: false,
    });
    emit({
      type: "tool_execution_start",
      toolCallId: toolCall.id,
      name: toolCall.name,
      arguments: toolCall.arguments,
    });
    emit({
      type: "tool_execution_end",
      toolCallId: toolCall.id,
      result,
      isError: true,
    });
    recorder?.record({
      type: "tool_call",
      runId: this.runId,
      timestampMs: startedAt,
      toolCallId: toolCall.id,
      name: toolCall.name,
      arguments: toolCall.arguments,
      result,
      isError: true,
      durationMs: 0,
    });
    return {
      message: this.createToolResultMessage(toolCall.id, result, true),
      isError: true,
      code: blocked.code,
    };
  }

  private emitPrecomputedResult(
    toolCall: ToolCallToDispatch,
    pre: PrecomputedToolResult,
    emit: DispatchEmitter,
  ): DispatchResult {
    const recorder = getTurnRecorder();
    const startedAt = this.clock.now();

    const result: ToolResult = {
      content: [{ type: "text", text: pre.resultText }],
    };

    emit({
      type: "tool_execution_start",
      toolCallId: toolCall.id,
      name: pre.name,
      // Surface the compact D3 shape (not the raw streamed deltas)
      // so consumers see the same record-keeping value the model will
      // see on the next outbound turn.
      arguments: pre.arguments,
    });
    emit({
      type: "tool_execution_update",
      toolCallId: toolCall.id,
      partialResult: result,
    });
    emit({
      type: "tool_execution_end",
      toolCallId: toolCall.id,
      result,
      isError: pre.isError,
    });

    recorder?.record({
      type: "tool_call",
      runId: this.runId,
      timestampMs: startedAt,
      toolCallId: toolCall.id,
      name: pre.name,
      arguments: pre.arguments,
      result,
      isError: pre.isError,
      durationMs: 0,
    });

    const message = this.createToolResultMessage(
      toolCall.id,
      result,
      pre.isError,
    );

    const dispatchResult: DispatchResult = {
      message,
      isError: pre.isError,
      precomputed: true,
    };
    if (pre.errorCode) {
      dispatchResult.code = pre.errorCode as AgentErrorCode;
    }
    return dispatchResult;
  }

  private async dispatchOne(
    toolCall: ToolCallToDispatch,
    tools: Tool[],
    workflowManager: WorkflowManager,
    signal: AbortSignal,
    emit: DispatchEmitter,
  ): Promise<DispatchResult> {
    const found = tools.find((t) => t.name === toolCall.name);
    if (!found) {
      const message = this.createToolResultMessage(
        toolCall.id,
        toolErrorContent(`Tool ${toolCall.name} not found`, "TOOL_NOT_FOUND"),
        true,
      );
      return { message, isError: true, code: "TOOL_NOT_FOUND" };
    }

    // PR-1b: read normalized metadata (defaults applied at registration).
    const tool = normalizeToolMetadata(found);
    this.runCallCount += 1;
    this.toolRunCallCounts.set(
      tool.name,
      (this.toolRunCallCounts.get(tool.name) ?? 0) + 1,
    );
    const isNonIdempotent = tool.category === "non_idempotent";
    const disableWorkflowDeduplication = !isNonIdempotent;
    const mcpRef = tool.origin === "mcp" ? tool.mcpRef : undefined;

    emit({
      type: "tool_execution_start",
      toolCallId: toolCall.id,
      name: toolCall.name,
      arguments: toolCall.arguments,
    });

    const recorder = getTurnRecorder();
    const startedAt = this.clock.now();

    if (mcpRef) {
      trackEvent("mcp_tool_call_start", {
        connectionId: mcpRef.connectionId,
        toolName: mcpRef.remoteToolName,
        namespacedToolName: tool.name,
      });
      if (
        this.mcpRuntime?.isToolUnavailable(
          mcpRef.connectionId,
          mcpRef.remoteToolName,
        )
      ) {
        const unavailable = toolErrorContent(
          `MCP tool ${tool.name} is unavailable for the remainder of this run.`,
          "MCP_CONNECTION_UNAVAILABLE",
          {
            connectionId: mcpRef.connectionId,
            toolName: mcpRef.remoteToolName,
            retryable: false,
          },
        );
        const message = this.createToolResultMessage(
          toolCall.id,
          unavailable,
          true,
        );
        emit({
          type: "tool_execution_end",
          toolCallId: toolCall.id,
          result: unavailable,
          isError: true,
        });
        trackEvent(
          "mcp_tool_call_error",
          {
            connectionId: mcpRef.connectionId,
            toolName: mcpRef.remoteToolName,
            namespacedToolName: tool.name,
            code: "MCP_CONNECTION_UNAVAILABLE",
          },
          { durationMs: this.clock.now() - startedAt },
        );
        recorder?.record({
          type: "tool_call",
          runId: this.runId,
          timestampMs: startedAt,
          toolCallId: toolCall.id,
          name: tool.name,
          arguments: toolCall.arguments,
          result: unavailable,
          isError: true,
          durationMs: this.clock.now() - startedAt,
        });
        return {
          message,
          isError: true,
          code: "MCP_CONNECTION_UNAVAILABLE",
        };
      }
    }

    try {
      if (tool.category === "read") {
        assertSingleReadConcurrencyOwner({
          owner: "OrchestratorDispatcher",
          isReadOperationFlag: false,
        });
      }

      const fingerprint = this.createFingerprint(tool.name, toolCall.arguments);
      this.pruneRecentToolExecutions();

      if (isNonIdempotent) {
        const recent = this.recentToolExecutions.get(fingerprint);
        if (recent) {
          const skipped: ToolResult = {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  code: "TOOL_DEDUP_SUPPRESSED",
                  message:
                    "Skipped duplicate email drafting action because an identical draft was already opened recently.",
                  success: true,
                  skippedDuplicate: true,
                  originalToolCallId: recent.toolCallId,
                }),
              },
            ],
          };

          const message = this.createToolResultMessage(
            toolCall.id,
            skipped,
            false,
          );
          emit({
            type: "tool_execution_update",
            toolCallId: toolCall.id,
            partialResult: skipped,
          });
          emit({
            type: "tool_execution_end",
            toolCallId: toolCall.id,
            result: skipped,
            isError: false,
            dedupSuppressed: true,
          });
          recorder?.record({
            type: "tool_call",
            runId: this.runId,
            timestampMs: startedAt,
            toolCallId: toolCall.id,
            name: tool.name,
            arguments: toolCall.arguments,
            result: skipped,
            isError: false,
            durationMs: this.clock.now() - startedAt,
          });
          return {
            message,
            isError: false,
            code: "TOOL_DEDUP_SUPPRESSED",
            dedupSuppressed: true,
          };
        }
      }

      const result = await workflowManager.executeTool(
        tool.name,
        toolCall.arguments,
        async () => {
          if (signal.aborted) {
            throw new Error("Tool execution cancelled");
          }
          return runToolWithTimeout(
            (toolSignal) =>
              tool.execute(toolCall.id, toolCall.arguments, toolSignal),
            this.toolExecutionTimeoutMs,
            `Tool '${tool.name}' timed out after ${this.toolExecutionTimeoutMs}ms`,
            signal,
          );
        },
        {
          isReadOperation: false,
          // OrchestratorDispatcher owns inter-tool pacing: read batches
          // dispatch in bounded-parallel chunks and writes serialize
          // through `dispatchOne`. Forcing an additional 1s gap before
          // each tool here would re-serialize parallel MCP read batches
          // (cf. docs/agent-concurrency-map.md §3 and the rationale
          // for `parallelSafeRemoteTools`).
          skipInterToolDelay: true,
          maxRetries: tool.maxRetries ?? (tool.category === "read" ? 2 : 0),
          dedupKey: isNonIdempotent ? fingerprint : undefined,
          disableDeduplication: disableWorkflowDeduplication,
          onStatus: (statusText) => {
            emit({
              type: "tool_execution_update",
              toolCallId: toolCall.id,
              partialResult: undefined,
              statusText,
            });
          },
        },
      );

      if (isNonIdempotent) {
        this.recentToolExecutions.set(fingerprint, {
          toolCallId: toolCall.id,
          completedAt: this.clock.now(),
        });
      }

      const toolResult = result as ToolResult;
      const message = this.createToolResultMessage(
        toolCall.id,
        toolResult,
        false,
      );

      emit({
        type: "tool_execution_update",
        toolCallId: toolCall.id,
        partialResult: toolResult,
      });
      emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: toolResult,
        isError: false,
        ...(toolResult.ui
          ? {
              ui: toolResult.ui,
              uiInput: toolCall.arguments,
              uiToolName: tool.name,
            }
          : {}),
      });
      recorder?.record({
        type: "tool_call",
        runId: this.runId,
        timestampMs: startedAt,
        toolCallId: toolCall.id,
        name: tool.name,
        arguments: toolCall.arguments,
        result: toolResult,
        isError: false,
        durationMs: this.clock.now() - startedAt,
      });
      if (mcpRef) {
        this.mcpRuntime?.recordToolResult(
          mcpRef.connectionId,
          mcpRef.remoteToolName,
          "success",
          tool.name,
        );
        trackEvent(
          "mcp_tool_call_end",
          {
            connectionId: mcpRef.connectionId,
            toolName: mcpRef.remoteToolName,
            namespacedToolName: tool.name,
          },
          { durationMs: this.clock.now() - startedAt },
        );
      }
      return {
        message,
        isError: false,
        effectiveArguments: toolCall.arguments,
      };
    } catch (error) {
      const typedError = classifyToolDispatchError(error, signal);
      const errorMessage = typedError.message;
      if (this.logPrefix && !isExpectedToolFailure(error)) {
        console.error(`${this.logPrefix} Tool dispatch error:`, error);
      }

      // PR-3B.1: surface AgentError.details (e.g. MCP connectionId/toolName)
      // through the structured tool-error payload so downstream consumers
      // can render contract §8 envelopes without losing context.
      const errorExtras = typedError.details ?? undefined;
      const message = this.createToolResultMessage(
        toolCall.id,
        toolErrorContent(errorMessage, typedError.code, errorExtras),
        true,
      );

      const endResult: Record<string, unknown> = {
        code: typedError.code,
        error: errorMessage,
      };
      if (errorExtras) {
        Object.assign(endResult, errorExtras);
      }

      emit({
        type: "tool_execution_end",
        toolCallId: toolCall.id,
        result: endResult,
        isError: true,
      });
      recorder?.record({
        type: "tool_call",
        runId: this.runId,
        timestampMs: startedAt,
        toolCallId: toolCall.id,
        name: tool.name,
        arguments: toolCall.arguments,
        result: endResult,
        isError: true,
        durationMs: this.clock.now() - startedAt,
      });

      if (mcpRef) {
        const mcpCode = asMcpToolFailureCode(typedError.code);
        if (mcpCode) {
          this.mcpRuntime?.recordToolResult(
            mcpRef.connectionId,
            mcpRef.remoteToolName,
            mcpCode,
            tool.name,
          );
        }
        trackEvent(
          "mcp_tool_call_error",
          {
            connectionId: mcpRef.connectionId,
            toolName: mcpRef.remoteToolName,
            namespacedToolName: tool.name,
            code: typedError.code,
          },
          { durationMs: this.clock.now() - startedAt },
        );
      }

      return { message, isError: true, code: typedError.code };
    }
  }

  private createFingerprint(
    toolName: string,
    args: Record<string, unknown>,
  ): string {
    const normalizedArgs = Object.keys(args)
      .sort()
      .reduce<Record<string, unknown>>((acc, key) => {
        acc[key] = args[key];
        return acc;
      }, {});
    return `${toolName}:${JSON.stringify(normalizedArgs)}`;
  }

  private createToolResultMessage(
    toolCallId: string,
    content: ToolResult,
    isError: boolean,
  ): ToolResultMessage {
    return {
      role: "tool",
      toolCallId,
      content: content.content,
      isError,
      timestamp: this.clock.now(),
    };
  }

  private pruneRecentToolExecutions(now = this.clock.now()): void {
    for (const [fingerprint, execution] of this.recentToolExecutions) {
      if (now - execution.completedAt > NON_IDEMPOTENT_TOOL_DEDUP_WINDOW_MS) {
        this.recentToolExecutions.delete(fingerprint);
      }
    }
  }
}

function classifyToolDispatchError(
  error: unknown,
  signal: AbortSignal,
): ReturnType<typeof createAgentError> {
  const typed = asAgentError(error, "TOOL_EXCEPTION", "Tool execution failed");

  if (typed.code === "TOOL_EXCEPTION") {
    const message = typed.message.toLowerCase();

    if (
      signal.aborted ||
      message.includes("aborted") ||
      message.includes("cancel")
    ) {
      return createAgentError("TOOL_ABORTED", typed.message, {
        cause: error,
      });
    }

    if (error instanceof ReadConcurrencyOwnershipError) {
      return createAgentError("TOOL_PARALLEL_GUARD_VIOLATION", typed.message, {
        cause: error,
      });
    }

    if (message.includes("timed out") || message.includes("timeout")) {
      return createAgentError("TOOL_TIMEOUT", typed.message, {
        cause: error,
      });
    }

    return typed;
  }

  // PR-3B.1: preserve MCP_* codes (and any other tool-relevant code
  // surfaced by adapters) instead of re-wrapping them as TOOL_EXCEPTION.
  if (!typed.code.startsWith("TOOL_") && !typed.code.startsWith("MCP_")) {
    return createAgentError("TOOL_EXCEPTION", typed.message, {
      cause: error,
    });
  }

  return typed;
}

/**
 * Race a tool execution against a timeout. Extracted from the duplicated
 * Legacy `runToolWithTimeout` implementation kept as a shared helper.
 */
export async function runToolWithTimeout<R>(
  run: (signal: AbortSignal) => Promise<R>,
  timeoutMs: number,
  timeoutMessage: string,
  outerSignal?: AbortSignal,
): Promise<R> {
  const controller = new AbortController();
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  const onOuterAbort = () => controller.abort(outerSignal?.reason);
  if (outerSignal?.aborted) controller.abort(outerSignal.reason);
  else outerSignal?.addEventListener("abort", onOuterAbort, { once: true });

  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => {
      const error = new DOMException(timeoutMessage, "TimeoutError");
      controller.abort(error);
      reject(error);
    }, timeoutMs);
  });
  const abortPromise = controller.signal.aborted
    ? Promise.reject(
        controller.signal.reason ??
          new DOMException("Tool execution aborted", "AbortError"),
      )
    : new Promise<never>((_, reject) => {
        controller.signal.addEventListener(
          "abort",
          () =>
            reject(
              controller.signal.reason ??
                new DOMException("Tool execution aborted", "AbortError"),
            ),
          { once: true },
        );
      });

  try {
    return await Promise.race([
      run(controller.signal),
      timeoutPromise,
      abortPromise,
    ]);
  } finally {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    outerSignal?.removeEventListener("abort", onOuterAbort);
  }
}

function toolErrorContent(
  message: string,
  code: AgentErrorCode,
  extra?: Record<string, unknown>,
): ToolResult {
  return {
    content: [
      {
        type: "text",
        text: encodeToolErrorPayload(code, message, extra),
      },
    ],
  };
}

function asMcpToolFailureCode(code: AgentErrorCode): MCPToolFailureCode | null {
  switch (code) {
    case "MCP_TOOL_INVOCATION_FAILED":
    case "MCP_TOOL_TIMEOUT":
    case "MCP_TOOL_ABORTED":
    case "MCP_TOOL_NOT_FOUND":
    case "MCP_RESPONSE_INVALID":
    case "MCP_CONNECTION_UNAUTHORIZED":
    case "MCP_CONNECTION_UNAVAILABLE":
      return code;
    default:
      return null;
  }
}
