/**
 * MCPRuntime — owns MCP lifecycle, tool registry, and breaker-driven
 * per-turn system notes (PR-10b).
 *
 * Pre-PR-10b the agent class kept five private surfaces interleaved with
 * orchestrator state:
 *   - the `MCPRuntime` interface plus `mcpRuntime` field
 *   - `initializeMcpRuntime` (validation + lifecycle wiring)
 *   - `createMcpDispatchRuntime` (dispatcher hook)
 *   - `ensureMcpCatalogReady`, `buildAvailableToolsSnapshot`, the
 *     `mcpRegistryWarnings` dedup set
 *   - `pendingTurnSystemNotes` plus its three helpers
 *     (`queue`, `clear`, `buildTurnSystemPrompt` consumer)
 *
 * All MCP-only state and behaviour now lives inside this single class.
 * The agent owns one nullable `mcpRuntime` field and forwards lifecycle
 * calls (`dispose`, `resetCircuitBreakers`, `clearPendingTurnNotes`) and
 * the per-turn snapshot builder (`buildToolSnapshot`,
 * `ensureCatalogReady`). The breaker-open system note is queued
 * internally from `createDispatchRuntime` so the agent never sees the
 * note string directly — it only drains the queue when composing the
 * next turn's system prompt.
 *
 * See:
 *   - docs/post-pr7-cleanup-plan.md §PR-10b
 *   - docs/agent-refactor-blueprint.md §3 (module layout)
 */

import type { Tool } from "../../tools/types";
import type { Clock } from "../loop/clock";
import type { MCPToolDispatchRuntime } from "../tools/dispatcher";
import { LiveMCPInvocationClient } from "./client";
import {
  type MCPServerActivationResult,
  topLevelArgumentNames,
} from "./lazy-loading";
import { MCPLifecycleManager } from "./lifecycle-manager";
import { buildMCPRegistry } from "./registry";
import type { MCPNormalizedConnection, MCPRemoteToolDescriptor } from "./types";
import { validateMCPConnectionsConfig } from "./validation";

export interface SetupMcpRuntimeOptions {
  /** Used to prefix console diagnostics (e.g. `[OpenAIAgent]`). */
  logPrefix: string;
  /** Replay-deterministic clock (PR-8a) shared with the rest of the agent. */
  clock: Clock;
  /**
   * Telemetry sink injected so this module stays decoupled from the
   * concrete `trackEvent` import. The agent passes
   * `(name, props) => trackEvent(name, props)`.
   */
  emitTelemetry?: (name: string, properties: Record<string, string>) => void;
  /**
   * Storage providers for OAuth / refresh tokens used by the live MCP
   * transport. Defaults to `globalThis.sessionStorage` /
   * `globalThis.localStorage` when available.
   */
  storage?: {
    sessionStorage?: Storage;
    localStorage?: Storage;
  };
}

/**
 * Live MCP runtime. Constructed via {@link setupMcpRuntime}; the agent
 * keeps a nullable reference and forwards lifecycle / per-turn calls.
 */
export class MCPRuntime {
  readonly connections: ReadonlyMap<string, MCPNormalizedConnection>;
  readonly client: LiveMCPInvocationClient;
  readonly lifecycle: MCPLifecycleManager;

  private readonly logPrefix: string;
  private readonly registryWarnings = new Set<string>();
  private pendingTurnSystemNotes: string[] = [];

  constructor(args: {
    connections: ReadonlyMap<string, MCPNormalizedConnection>;
    client: LiveMCPInvocationClient;
    lifecycle: MCPLifecycleManager;
    logPrefix: string;
  }) {
    this.connections = args.connections;
    this.client = args.client;
    this.lifecycle = args.lifecycle;
    this.logPrefix = args.logPrefix;
  }

  /**
   * Connect any disconnected MCP servers in parallel before the next
   * turn's tool catalog snapshot. Idempotent: already-connected
   * connections are skipped.
   */
  async ensureCatalogReady(): Promise<void> {
    const pending: Promise<void>[] = [];
    for (const connection of this.connections.values()) {
      const state = this.lifecycle.getState(connection.id);
      if (state === "disconnected") {
        pending.push(this.lifecycle.connect(connection.id));
      }
    }
    if (pending.length > 0) {
      await Promise.all(pending);
    }
  }

  /**
   * Combine local agent tools with the live MCP-derived registry.
   * Registry diagnostics are de-duplicated across calls — each unique
   * `(connectionId, toolName, message)` triple logs once per agent
   * lifetime to avoid console spam from the periodic refresh loop.
   */
  buildToolSnapshot(
    localTools: readonly Tool[],
    options: {
      lazyLoading?: boolean;
      activeServerIds?: ReadonlySet<string>;
    } = {},
  ): Tool[] {
    const snapshot = this.lifecycle.snapshotCatalog().catalog;
    const catalog = options.lazyLoading
      ? this.filterCatalog(snapshot, options.activeServerIds ?? new Set())
      : snapshot;
    const registry = this.buildRegistry(localTools, catalog);

    return [...localTools, ...registry.tools];
  }

  defaultActiveServerIds(): Set<string> {
    const ids = new Set<string>();
    for (const connection of this.connections.values()) {
      if (connection.enabled && connection.alwaysActive) {
        ids.add(connection.id);
      }
    }
    return ids;
  }

  buildAvailableServersBlock(
    activeServerIds: ReadonlySet<string> = new Set(),
  ): string | null {
    const lines: string[] = [];
    const catalog = this.lifecycle.snapshotCatalog().catalog;
    for (const connection of this.connections.values()) {
      if (!connection.enabled) continue;
      const toolCount = catalog.get(connection.id)?.length ?? 0;
      const countText = `${toolCount} tool${toolCount === 1 ? "" : "s"}`;
      const active = activeServerIds.has(connection.id) ? " [active]" : "";
      const summary = connection.description
        ? `${connection.description} (${countText})`
        : `(${countText})`;
      lines.push(`- "${connection.id}"${active} - ${summary}`);
    }

    if (lines.length === 0) return null;
    return [
      "Available MCP servers (call enable_mcp_server with server_id to activate before use):",
      ...lines,
    ].join("\n");
  }

  activateServer(
    serverId: string,
    localTools: readonly Tool[],
    activeServerIds: ReadonlySet<string>,
  ): MCPServerActivationResult {
    const connection = this.connections.get(serverId);
    if (!connection) {
      return {
        ok: false,
        errorCode: "MCP_UNKNOWN_SERVER",
        payload: {
          ok: false,
          error: {
            code: "MCP_UNKNOWN_SERVER",
            message: `No registered MCP server matches server_id '${serverId}'.`,
            server_id: serverId,
            retryable: false,
          },
        },
      };
    }

    if (!connection.enabled) {
      return {
        ok: false,
        errorCode: "MCP_CONNECTION_UNAVAILABLE",
        payload: {
          ok: false,
          error: {
            code: "MCP_CONNECTION_UNAVAILABLE",
            message: `MCP server '${serverId}' is disabled and cannot be activated for this run.`,
            server_id: serverId,
            retryable: false,
          },
        },
      };
    }

    const catalog = this.lifecycle.snapshotCatalog().catalog;
    const descriptors = catalog.get(serverId) ?? [];
    const registry = this.buildRegistry(
      localTools,
      new Map([[serverId, descriptors]]),
    );
    const tools = registry.tools
      .filter((tool) => tool.mcpRef?.connectionId === serverId)
      .map((tool) => ({
        name: tool.name,
        description:
          tool.description.length > 240
            ? `${tool.description.slice(0, 237)}...`
            : tool.description,
        argumentNames: topLevelArgumentNames(tool),
      }));

    return {
      ok: true,
      payload: {
        ok: true,
        server_id: serverId,
        label: connection.label,
        already_active: activeServerIds.has(serverId),
        tool_count: tools.length,
        tools,
      },
    };
  }

  private buildRegistry(
    localTools: readonly Tool[],
    catalog: ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>>,
  ) {
    const registry = buildMCPRegistry({
      connections: this.connections,
      catalog,
      existingToolNames: new Set(localTools.map((tool) => tool.name)),
      client: this.client,
    });

    for (const diagnostic of registry.diagnostics) {
      const key = `${diagnostic.connectionId}:${diagnostic.toolName ?? ""}:${diagnostic.message}`;
      if (this.registryWarnings.has(key)) {
        continue;
      }
      this.registryWarnings.add(key);
      console.warn(`${this.logPrefix} MCP registry diagnostic:`, diagnostic);
    }

    return registry;
  }

  private filterCatalog(
    catalog: ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>>,
    activeServerIds: ReadonlySet<string>,
  ): ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>> {
    const filtered = new Map<string, ReadonlyArray<MCPRemoteToolDescriptor>>();
    for (const [connectionId, descriptors] of catalog) {
      if (activeServerIds.has(connectionId)) {
        filtered.set(connectionId, descriptors);
      }
    }
    return filtered;
  }

  /**
   * Return the dispatcher hook the orchestrator wires into
   * {@link ToolDispatcher}. The hook owns the breaker-open path:
   * when `recordToolResult` reports a newly-opened breaker the runtime
   * queues a user-facing system note describing which tool was
   * disabled for the rest of the run.
   */
  createDispatchRuntime(): MCPToolDispatchRuntime {
    return {
      isToolUnavailable: (connectionId, toolName) =>
        this.lifecycle.isToolUnavailable(connectionId, toolName),
      recordToolResult: (
        connectionId,
        toolName,
        outcome,
        namespacedToolName,
      ) => {
        const opened = this.lifecycle.recordToolResult(
          connectionId,
          toolName,
          outcome,
        );
        if (opened) {
          this.queuePendingTurnNote(
            `Tool ${namespacedToolName ?? toolName} disabled for this run after repeated failures.`,
          );
        }
      },
    };
  }

  /** Queue a system note to surface at the top of the next turn. */
  private queuePendingTurnNote(note: string): void {
    if (!note || this.pendingTurnSystemNotes.includes(note)) {
      return;
    }
    this.pendingTurnSystemNotes = [...this.pendingTurnSystemNotes, note];
  }

  /** Snapshot pending notes (the agent appends them to the system prompt). */
  pendingTurnNotes(): readonly string[] {
    return this.pendingTurnSystemNotes;
  }

  hasPendingTurnNotes(): boolean {
    return this.pendingTurnSystemNotes.length > 0;
  }

  clearPendingTurnNotes(): void {
    if (this.pendingTurnSystemNotes.length === 0) return;
    this.pendingTurnSystemNotes = [];
  }

  /** Forwarded for callers that need to clear breakers between runs. */
  resetCircuitBreakers(): void {
    this.lifecycle.resetCircuitBreakers();
  }

  /**
   * Stop the periodic refresh timer and close every transport. Safe to
   * call multiple times.
   */
  dispose(): void {
    this.lifecycle.stopPeriodicRefresh();
    for (const connectionId of this.connections.keys()) {
      this.client.closeConnection(connectionId);
    }
  }
}

/**
 * Validate raw MCP config and build a live `MCPRuntime`. Returns `null`
 * when no usable connections are present (validation failed or config
 * was empty/missing) so the agent can skip MCP wiring entirely.
 *
 * Pre-PR-10b this lived inline in `Agent.initializeMcpRuntime`. The
 * extraction keeps every byte of behaviour identical:
 *   - validator diagnostics still log via `console.warn` with the
 *     agent's prefix;
 *   - lifecycle's `now` callback is sourced from the injected `Clock`
 *     so replay parity is preserved (PR-8a);
 *   - telemetry events are forwarded via the optional sink so callers
 *     without `trackEvent` (e.g. unit tests) get a quiet no-op.
 */
export function setupMcpRuntime(
  rawConfig: unknown,
  opts: SetupMcpRuntimeOptions,
): MCPRuntime | null {
  if (rawConfig === undefined || rawConfig === null) {
    return null;
  }

  const validation = validateMCPConnectionsConfig(rawConfig);
  for (const diagnostic of validation.diagnostics) {
    console.warn(`${opts.logPrefix} MCP config diagnostic:`, diagnostic);
  }

  if (validation.valid.length === 0) {
    return null;
  }

  const connections = new Map(
    validation.valid.map((connection) => [connection.id, connection] as const),
  );

  const storage = opts.storage ?? {
    sessionStorage: resolveDefaultStorage("sessionStorage"),
    localStorage: resolveDefaultStorage("localStorage"),
  };

  const client = new LiveMCPInvocationClient({
    connections,
    sessionStorage: storage.sessionStorage,
    localStorage: storage.localStorage,
  });

  const emit = opts.emitTelemetry ?? (() => undefined);
  const lifecycle = new MCPLifecycleManager({
    connections,
    client,
    telemetry: { emit: (name, properties) => emit(name, properties) },
    now: () => opts.clock.now(),
  });
  lifecycle.startPeriodicRefresh();

  return new MCPRuntime({
    connections,
    client,
    lifecycle,
    logPrefix: opts.logPrefix,
  });
}

function resolveDefaultStorage(
  key: "sessionStorage" | "localStorage",
): Storage | undefined {
  try {
    if (typeof globalThis === "undefined") return undefined;
    return globalThis[key] ?? undefined;
  } catch {
    return undefined;
  }
}
