/**
 * enable_mcp_server — MCP lazy-loading activation tool.
 *
 * Calls are handled inline by the FSM reducer, which mutates the
 * run-scoped active MCP server set and emits a synthetic tool result.
 * The execute() body is a dispatcher fallback kept for shape parity.
 */

import { Type } from "@sinclair/typebox";
import { ENABLE_MCP_SERVER_TOOL_NAME } from "../agent/mcp/lazy-loading";
import { defineTool, toolSuccess } from "./types";

export const enableMcpServerTool = defineTool({
  name: ENABLE_MCP_SERVER_TOOL_NAME,
  category: "bookkeeping",
  parallelSafe: true,
  label: "Enable MCP server",
  description:
    "Activate a connected MCP server for the rest of this run so its tools become callable. " +
    "Use server_id from the available MCP servers system prompt block. Call once per server, " +
    "then issue the actual MCP tool call on the next turn. This is bookkeeping and does not satisfy the deliverable requirement.",
  parameters: Type.Object({
    server_id: Type.String({
      description:
        "Connection id from the available MCP servers system prompt block.",
      minLength: 1,
    }),
  }),
  execute: async (_toolCallId, params) =>
    toolSuccess({
      ok: true,
      server_id: params.server_id,
      message:
        "MCP server activation is handled by the agent runtime. Continue with the MCP tool call on the next turn.",
    }),
});
