import type { AgentPhase, AgentStopReason } from "../../../lib/agent";
import type { ChatAgentAction, ChatAgentActivity } from "./types";

const MAX_RUN_ACTIONS = 24;

export type AgentProgressSurface = "todo" | "activity" | "none";

export function selectAgentProgressSurface(
  todoCount: number,
  hasActivity: boolean,
): AgentProgressSurface {
  if (todoCount > 0) return "todo";
  return hasActivity ? "activity" : "none";
}

function phaseIteration(phase: AgentPhase): number {
  return "iteration" in phase ? phase.iteration : 0;
}

function fallbackActivity(nowMs: number): ChatAgentActivity {
  return {
    runId: "pending",
    phase: { kind: "executing", iteration: 0 },
    actions: [],
    lastIteration: 0,
    startedAtMs: nowMs,
    updatedAtMs: nowMs,
  };
}

function upsertAction(
  activity: ChatAgentActivity | null,
  toolCallId: string,
  nowMs: number,
  update: (current: ChatAgentAction | undefined) => ChatAgentAction,
): ChatAgentActivity {
  const current = activity ?? fallbackActivity(nowMs);
  const existingIndex = current.actions.findIndex(
    (action) => action.id === toolCallId,
  );
  const actions = [...current.actions];
  const nextAction = update(
    existingIndex >= 0 ? actions[existingIndex] : undefined,
  );
  if (existingIndex >= 0) actions[existingIndex] = nextAction;
  else actions.push(nextAction);

  return {
    ...current,
    actions: actions.slice(-MAX_RUN_ACTIONS),
    updatedAtMs: nowMs,
  };
}

export function projectAgentPhase(
  activity: ChatAgentActivity | null,
  phase: AgentPhase,
  runId: string,
  timestampMs: number,
): ChatAgentActivity {
  const isNewRun = activity?.runId !== runId;
  return {
    runId,
    phase,
    actions: isNewRun ? [] : (activity?.actions ?? []),
    lastIteration: Math.max(
      isNewRun ? 0 : (activity?.lastIteration ?? 0),
      phaseIteration(phase),
    ),
    startedAtMs: isNewRun
      ? timestampMs
      : (activity?.startedAtMs ?? timestampMs),
    updatedAtMs: timestampMs,
  };
}

export function startAgentAction(
  activity: ChatAgentActivity | null,
  input: { id: string; name: string },
  nowMs: number,
): ChatAgentActivity {
  return upsertAction(activity, input.id, nowMs, (current) => ({
    id: input.id,
    name: input.name,
    status: "running",
    iteration: activity ? phaseIteration(activity.phase) : 0,
    startedAtMs: current?.startedAtMs ?? nowMs,
  }));
}

export function updateAgentAction(
  activity: ChatAgentActivity | null,
  toolCallId: string,
  statusText: string | undefined,
  nowMs: number,
): ChatAgentActivity | null {
  if (!activity || !statusText) return activity;
  const current = activity.actions.find((action) => action.id === toolCallId);
  if (!current) return activity;
  return upsertAction(activity, toolCallId, nowMs, (action) => ({
    ...(action ?? current),
    statusText,
  }));
}

export function finishAgentAction(
  activity: ChatAgentActivity | null,
  input: { id: string; name: string; isError: boolean },
  nowMs: number,
): ChatAgentActivity {
  return upsertAction(activity, input.id, nowMs, (current) => ({
    id: input.id,
    name: current?.name ?? input.name,
    status: input.isError ? "error" : "complete",
    iteration:
      current?.iteration ?? (activity ? phaseIteration(activity.phase) : 0),
    startedAtMs: current?.startedAtMs ?? nowMs,
    completedAtMs: nowMs,
  }));
}

export function recordAgentIteration(
  activity: ChatAgentActivity | null,
  iteration: number,
  timestampMs: number,
): ChatAgentActivity | null {
  if (!activity) return null;
  return {
    ...activity,
    lastIteration: Math.max(activity.lastIteration, iteration),
    updatedAtMs: timestampMs,
  };
}

export function finishAgentRun(
  activity: ChatAgentActivity | null,
  stopReason: AgentStopReason,
  nowMs: number,
): ChatAgentActivity | null {
  if (!activity) return null;
  return {
    ...activity,
    phase: { kind: "done", stopReason },
    actions: activity.actions.map((action) =>
      action.status === "running"
        ? {
            ...action,
            status: stopReason === "complete" ? "complete" : "error",
            completedAtMs: nowMs,
          }
        : action,
    ),
    updatedAtMs: nowMs,
  };
}
