/**
 * Calculate Levenshtein distance between two strings
 */
export function levenshteinDistance(a: string, b: string): number {
  const matrix: number[][] = [];

  for (let i = 0; i <= b.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= a.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1), // insertion, deletion
        );
      }
    }
  }

  return matrix[b.length][a.length];
}

/**
 * Calculate similarity score between 0 and 1
 */
export function similarityScore(a: string, b: string): number {
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  const distance = levenshteinDistance(a.toLowerCase(), b.toLowerCase());
  return 1 - distance / maxLen;
}

/**
 * Fuzzy search for multiple matches with scores
 */
export interface FuzzyMatch {
  name: string;
  country: string;
  admin1?: string;
  lat: number;
  lng: number;
  score: number;
  type: "country" | "city" | "region";
  population?: number;
}

export function fuzzySearch(query: string, maxResults = 5): FuzzyMatch[] {
  const normalizedQuery = query.toLowerCase().trim();

  // Quick return for empty query
  if (!normalizedQuery) return [];

  const matches: FuzzyMatch[] = [];

  for (const record of WORLD_CITIES) {
    let score = 0;
    const nameLower = record.name.toLowerCase();
    const countryLower = record.country.toLowerCase();

    // Exact match
    if (nameLower === normalizedQuery || countryLower === normalizedQuery) {
      score = 1.0;
    }
    // Starts with
    else if (nameLower.startsWith(normalizedQuery)) {
      score = 0.9;
    }
    // Contains at word boundary
    else if (
      nameLower.includes(` ${normalizedQuery}`) ||
      nameLower.includes(`${normalizedQuery} `)
    ) {
      score = 0.8;
    }
    // Contains anywhere
    else if (nameLower.includes(normalizedQuery)) {
      score = 0.7;
    }
    // Country name match
    else if (countryLower === normalizedQuery) {
      score = 0.85;
    }
    // Country contains query
    else if (
      countryLower.includes(normalizedQuery) &&
      record.type === "country"
    ) {
      score = 0.75;
    }
    // Fuzzy match for typos
    else {
      const nameSim = similarityScore(normalizedQuery, record.name);
      const countrySim = similarityScore(normalizedQuery, record.country);
      const bestSim = Math.max(nameSim, countrySim);
      if (bestSim > 0.7) {
        score = bestSim * 0.6;
      }
    }

    if (score > 0) {
      // Boost by population for cities with same score
      const populationBoost = record.population
        ? Math.min(record.population / 10000000, 0.1)
        : 0;
      const typeBoost =
        record.type === "country" ? 0.05 : record.type === "city" ? 0.03 : 0;

      matches.push({
        name: record.name,
        country: record.country,
        admin1: record.admin1,
        lat: record.lat,
        lng: record.lng,
        score: Math.min(score + populationBoost + typeBoost, 1.0),
        type: record.type,
        population: record.population,
      });
    }
  }

  // Sort by score descending, then by population descending
  matches.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return (b.population || 0) - (a.population || 0);
  });

  return matches.slice(0, maxResults);
}

/**
 * Batch resolve multiple location queries
 */
export interface ResolvedLocation {
  query: string;
  matches: FuzzyMatch[];
  bestMatch: FuzzyMatch | null;
  hasMultipleMatches: boolean;
}

export function resolveLocations(
  queries: string[],
  maxMatchesPerQuery = 3,
): ResolvedLocation[] {
  return queries.map((query) => {
    const matches = fuzzySearch(query, maxMatchesPerQuery);
    const bestMatch = matches.length > 0 ? matches[0] : null;
    const hasMultipleMatches =
      matches.length > 1 && matches[1].score > matches[0].score * 0.9;

    return {
      query,
      matches,
      bestMatch,
      hasMultipleMatches,
    };
  });
}

