/**
 * Pure decision function for the agent FSM.
 *
 * PR-4A. `decide(turn, state, nowMs)` is invoked once per loop iteration
 * after `provider.runTurn(...)` returns. It returns exactly one
 * {@link Action}; the orchestrator calls `apply()` with that action and
 * advances state. `decide()` MUST be deterministic — it never reads
 * `Date.now()` (the orchestrator passes `nowMs`).
 *
 * Rule numbering matches blueprint §5 rules 1–10.
 */

import type { LLMTurnResult } from "../providers/provider";
import type { AssistantContentBlock } from "../types";
import type { Action } from "./actions";
import type { NudgeReason } from "./nudges";
import { nudgeCeiling, nudgeText } from "./nudges";
import type { AgentRunState } from "./state";

export interface DecideContext {
  /** Wall-clock sample (real or injected). */
  nowMs: number;
}

const SHORT_AFFIRMATIVE_WORDS = new Set([
  "all",
  "yes",
  "y",
  "ok",
  "okay",
  "sure",
  "go ahead",
  "do it",
  "please do",
  "continue",
  "proceed",
  "a",
  "b",
  "c",
  "d",
  "a+d",
]);

/**
 * Returns true for short user replies that are equivalent to "do it" /
 * picking a numbered/lettered option. Mirrors the legacy
 * `shouldNudgeForActionWithoutTools` predicate but is exposed as a pure
 * helper so unit tests can pin the contract.
 */
export function isShortAffirmativeOrOptionPick(text: string): boolean {
  const t = text.trim().toLowerCase();
  if (!t) return false;
  if (SHORT_AFFIRMATIVE_WORDS.has(t)) return true;
  // Single digit 1-9 or letter a-d (option pick).
  if (/^[1-9]$/.test(t)) return true;
  if (/^[a-d]$/.test(t)) return true;
  if (t.length <= 24 && /^(yes|all|ok|sure|go ahead|do it|proceed)\b/.test(t)) {
    return true;
  }
  return false;
}

export function onlyThinking(blocks: AssistantContentBlock[]): boolean {
  if (blocks.length === 0) return false;
  return blocks.every((b) => b.type === "thinking");
}

/**
 * Threshold (in trimmed characters of `text`-typed assistant content blocks)
 * above which the current turn's prose alone is accepted as the deliverable.
 *
 * Tuned to filter out short acknowledgments ("Done.", "OK, I've made the
 * changes.") while accepting real research / Q&A answers. Any prose at or
 * above this length combined with a non-affirmative user prompt is treated
 * as the user-visible deliverable for purposes of the planner gate.
 */
export const PROSE_DELIVERABLE_MIN_CHARS = 280;

/**
 * Lower prose threshold used by the informational Q&A acceptance path
 * (see {@link proseAcceptedAsDeliverable}). Filters out one-line
 * acknowledgments ("Done.", "Got it.") while accepting short factual
 * answers like "Your most recent email was: …".
 */
export const PROSE_QNA_MIN_CHARS = 80;

/**
 * Heuristic for "the user's prompt is an informational question".
 *
 * Matches prompts that open with a question word or auxiliary verb, or
 * that end with a question mark. Used by {@link proseAcceptedAsDeliverable}
 * to recognize Q&A turns where a successful `read`-category tool call
 * plus a prose answer IS the deliverable, so the planner gate does not
 * keep nudging the model for a write-back that was never requested.
 *
 * Deliberately narrow: action verbs ("make", "create", "build",
 * "generate", "write", "insert", …) are NOT matched, so prompts like
 * "make a chart" or "create a table" continue to require a
 * `deliverable`-category tool call.
 */
const INFORMATIONAL_QUESTION_OPENER =
  /^(what|who|whom|whose|when|where|why|how|which|is|are|was|were|am|do|does|did|can|could|should|would|will|has|have|had|may|might|show|tell|list|find|get|give|name|describe|explain|summari[sz]e|read)\b/;

export function isInformationalQuestion(text: string): boolean {
  const t = text.trim().toLowerCase();
  if (!t) return false;
  if (t.endsWith("?")) return true;
  return INFORMATIONAL_QUESTION_OPENER.test(t);
}

const CONCRETE_ACTION_VERB_SOURCE =
  "add|align|append|apply|autofit|bold|build|center|change|clear|color|colour|compose|copy|create|delete|draft|duplicate|edit|execute|fill|filter|fix|format|forward|freeze|generate|hide|hyperlink|indent|insert|italicise|italicize|link|make|merge|modify|move|outdent|patch|populate|remove|rename|replace|reply|resize|run|save|send|set|shade|sort|style|underline|unfreeze|unhide|update|upload|wrap|write";
const CONCRETE_ACTION_VERB = new RegExp(
  `\\b(?:${CONCRETE_ACTION_VERB_SOURCE})\\b`,
);
const EXPLICIT_COMPOUND_ACTION = new RegExp(
  `\\b(?:and|then)\\s+(?:please\\s+)?(?:${CONCRETE_ACTION_VERB_SOURCE})\\b`,
);
const CONCRETE_TRANSFORMATION_PHRASE =
  /\bturn\s+(?:(?:the|this|these|selected|existing)\s+)?(?:cell|cells|content|document|range|table|text)\s+into\s+(?:a\s+|an\s+)?(?:chart|document|file|hyperlink|image|link|table)\b/;
const EXPLICIT_COMPOUND_TRANSFORMATION =
  /\b(?:and|then)\s+(?:please\s+)?turn\s+(?:(?:the|this|these|selected|existing)\s+)?(?:cell|cells|content|document|range|table|text)\s+into\s+(?:a\s+|an\s+)?(?:chart|document|file|hyperlink|image|link|table)\b/;
const EXPLICIT_SEQUENTIAL_ACTION = new RegExp(
  `\\bthen\\s+(?:please\\s+)?(?:${CONCRETE_ACTION_VERB_SOURCE})\\b`,
);
const EXPLICIT_SEQUENTIAL_TRANSFORMATION =
  /\bthen\s+(?:please\s+)?turn\s+(?:(?:the|this|these|selected|existing)\s+)?(?:cell|cells|content|document|range|table|text)\s+into\s+(?:a\s+|an\s+)?(?:chart|document|file|hyperlink|image|link|table)\b/;
/**
 * A negation cue ("don't", "do not", "without", "instead of", …) directly
 * modifying a concrete action verb within a few words, e.g. "please don't
 * update", "no need to modify". Used to suppress a false mutation
 * classification for prompts like "don't update this workbook; just
 * summarize it".
 */
const NEGATION_CUE =
  "(?:do not|don'?t|never|no need to|without|instead of|rather than|avoid|refrain from)";
const NEGATED_CONCRETE_ACTION = new RegExp(
  `\\b${NEGATION_CUE}\\s+(?:\\w+\\s+){0,2}?(?:${CONCRETE_ACTION_VERB_SOURCE})\\b`,
);
const NEGATED_CONCRETE_ACTION_GLOBAL = new RegExp(
  NEGATED_CONCRETE_ACTION.source,
  "g",
);
const NEGATED_CONCRETE_TRANSFORMATION = new RegExp(
  `\\b${NEGATION_CUE}\\s+(?:\\w+\\s+){0,2}?${CONCRETE_TRANSFORMATION_PHRASE.source}`,
);
const NEGATED_CONCRETE_TRANSFORMATION_GLOBAL = new RegExp(
  NEGATED_CONCRETE_TRANSFORMATION.source,
  "g",
);

/**
 * True when every concrete-action signal in the prompt is negated. The
 * negated clause is stripped and the remainder re-checked: if a positive
 * concrete directive survives ("don't email it but update the sheet"), the
 * request is still a mutation and this returns false.
 */
function isNegatedConcreteRequest(normalized: string): boolean {
  if (
    !NEGATED_CONCRETE_ACTION.test(normalized) &&
    !NEGATED_CONCRETE_TRANSFORMATION.test(normalized)
  ) {
    return false;
  }
  const withoutNegated = normalized
    .replace(NEGATED_CONCRETE_ACTION_GLOBAL, " ")
    .replace(NEGATED_CONCRETE_TRANSFORMATION_GLOBAL, " ");
  const stillConcrete =
    (CONCRETE_ACTION_VERB.test(withoutNegated) &&
      CONCRETE_ACTION_TARGET.test(withoutNegated)) ||
    CONCRETE_TRANSFORMATION_PHRASE.test(withoutNegated);
  return !stillConcrete;
}
const CONCRETE_ACTION_TARGET =
  /\b(appointment|attachment|body|calendar|cell|cells|chart|code|column|columns|content|diagram|document|draft|email|event|file|folder|heading|headings|hyperlink|hyperlinks|image|introduction|issue|it|link|links|map|message|object|objects|paragraph|paragraphs|pivot|pivots|presentation|range|repo|repository|row|rows|section|sections|selection|sentence|sentences|sheet|slide|spacing|spreadsheet|spreadsheets|tab|tabs|table|text|them|these|this|title|titles|word|words|workbook|worksheet)\b/;

/**
 * Interrogative / display openers that unambiguously request information
 * rather than a mutation. Auxiliary-led questions are handled separately so
 * direct second-person requests ("can you update the workbook?") remain
 * concrete while capability/advice questions ("can I rename this sheet?")
 * remain informational.
 */
const PURE_INFORMATIONAL_OPENER =
  /^(what|who|whom|whose|when|where|why|which|how|show|tell|list|describe|explain|summari[sz]e|read)\b/;
const AUXILIARY_QUESTION_OPENER =
  /^(is|are|was|were|am|do|does|did|has|have|had|may|might|should|can|could|would|will)\b/;
const DIRECT_SECOND_PERSON_ACTION_REQUEST = /^(can|could|would|will)\s+you\b/;
const SECOND_PERSON_INFORMATION_REQUEST =
  /^(can|could|would|will)\s+you\s+(?:please\s+)?(?:advise|describe|explain|find|get|give|help\s+(?:me\s+)?(?:decide|figure\s+out|learn|understand)|list|name|read|recommend|show|suggest|summari[sz]e|tell)\b/;
const INFORMATIONAL_WRAPPER =
  /\b(?:how|whether|why|which)\b|\bwhat\s+(?:can|could|should|to|would)\b/;

/**
 * Narrow heuristic for requests that require changing a concrete artifact.
 * Used only after the bookkeeping-loop guard fires, so prose-first research
 * and architecture requests keep their existing acceptance behavior.
 *
 * LOAD-BEARING — do NOT "simplify" this away in favor of the deliverable
 * gate. At the point the bookkeeping-execution guard consults this
 * predicate, {@link deliverableGateSatisfied} is `false` AND
 * {@link proseAcceptedAsDeliverable} (path A) is `true` for BOTH a
 * fabricated "task complete" prose dodge on a concrete mutation AND a
 * legitimate long research / architecture answer. The gate value is
 * identical in the two branches, so the ONLY signal that separates "reject
 * the prose, force execution" from "accept the prose" is the user's intent
 * as expressed in text. Removing this heuristic re-opens the
 * completion-claim hallucination it was added to close (see the
 * "bookkeeping guard rejects long prose for a concrete document mutation"
 * decide test).
 *
 * A leading pure-informational opener (WH-word / display verb)
 * short-circuits to `false` so questions that merely mention an action verb
 * + artifact ("how do I format this document?", "what cells should I
 * update?") are not misclassified as mutations. Residual false positives
 * remain possible for prose deliverables phrased as commands ("create a
 * summary of the document"); those are accepted as an intentional
 * imperfection rather than risking false negatives on real mutations.
 */
export function requestsConcreteToolExecution(text: string): boolean {
  const normalized = text.trim().toLowerCase();
  if (!normalized) return false;
  if (isShortAffirmativeOrOptionPick(normalized)) return true;
  if (isNegatedConcreteRequest(normalized)) return false;
  const informationalOpener =
    PURE_INFORMATIONAL_OPENER.test(normalized) ||
    (AUXILIARY_QUESTION_OPENER.test(normalized) &&
      (!DIRECT_SECOND_PERSON_ACTION_REQUEST.test(normalized) ||
        SECOND_PERSON_INFORMATION_REQUEST.test(normalized)));
  const hasSequentialAction =
    EXPLICIT_SEQUENTIAL_ACTION.test(normalized) ||
    EXPLICIT_SEQUENTIAL_TRANSFORMATION.test(normalized);
  if (
    informationalOpener &&
    !hasSequentialAction &&
    (!(
      EXPLICIT_COMPOUND_ACTION.test(normalized) ||
      EXPLICIT_COMPOUND_TRANSFORMATION.test(normalized)
    ) ||
      INFORMATIONAL_WRAPPER.test(normalized))
  ) {
    return false;
  }
  return (
    (CONCRETE_ACTION_VERB.test(normalized) &&
      CONCRETE_ACTION_TARGET.test(normalized)) ||
    CONCRETE_TRANSFORMATION_PHRASE.test(normalized)
  );
}

/**
 * Common greeting / acknowledgment inputs that carry no actionable
 * intent. Matched on exact (trimmed, lowercased) text so prompts like
 * "hello please make a chart" are NOT treated as greetings.
 */
const GREETING_INPUTS = new Set([
  "hi",
  "hey",
  "yo",
  "hello",
  "hellow",
  "sup",
  "howdy",
  "greetings",
  "thanks",
  "thank you",
  "ty",
  "thx",
  "cheers",
]);

/**
 * Heuristic for "the user's prompt carries no actionable intent" —
 * empty input, a single character that isn't an option pick, or a bare
 * greeting / thank-you. Used by {@link proseAcceptedAsDeliverable} to
 * accept any non-empty prose response without forcing planner-mode
 * final handoff for missing deliverable tools.
 *
 * Without this, single-character inputs like `"h"` and bare greetings
 * like `"hi"` repeatedly nudged the planner to call deliverable tools,
 * producing 4+ tool calls and 5 turns for a single keypress (see the
 * "h → 4 tool calls" regression). Short affirmatives / option picks
 * (`"yes"`, `"1"`, `"a"`) are intentionally excluded — those DO carry
 * intent ("do the proposed action").
 */
export function isTrivialOrGreetingInput(text: string): boolean {
  const t = text.trim().toLowerCase();
  if (!t) return true;
  // Affirmatives / option picks DO carry intent ("yes" = do it). Defer
  // to the existing path-B handling for those cases.
  if (isShortAffirmativeOrOptionPick(t)) return false;
  // Single character that isn't a digit/letter option pick is small talk.
  if (t.length === 1) return true;
  if (GREETING_INPUTS.has(t)) return true;
  return false;
}

function totalProseLength(blocks: AssistantContentBlock[]): number {
  let total = 0;
  for (const block of blocks) {
    if (block.type === "text" && typeof block.text === "string") {
      total += block.text.trim().length;
    }
  }
  return total;
}

/**
 * Returns true when the current turn's prose answer should be accepted as
 * the deliverable for the run, bypassing the tool-based planner gate.
 *
 * Two acceptance paths are evaluated:
 *
 *   A. **Substantial standalone prose.** The user's last message is NOT
 *      a short affirmative / option pick (preserving the `"2"`
 *      regression where the model dodges a deliverable with long
 *      prose) AND the current turn produced at least
 *      {@link PROSE_DELIVERABLE_MIN_CHARS} characters of `text`-typed
 *      assistant content. `thinking` blocks do not count (they're
 *      never user-visible).
 *
 *   B. **Read-only action with a real prose deliverable.** At least
 *      one successful `category: "read"` tool ran this step AND the
 *      prose answer is non-trivial ({@link PROSE_QNA_MIN_CHARS}). The
 *      user prompt must either be an informational question
 *      ({@link isInformationalQuestion}) or a short affirmative /
 *      option pick ({@link isShortAffirmativeOrOptionPick}). The
 *      short-affirmative case covers confirmations like `"yes"` to a
 *      prior "I can check your mailbox" offer where the read tool
 *      calls IS the implied deliverable; the model's choice of read
 *      (not deliverable) tools is treated as evidence that no
 *      write-back was expected. Action-verb prompts ("make a chart",
 *      "create a table") still fail this acceptance path because they
 *      match neither condition — `make`/`create`/etc. are deliberately
 *      excluded from {@link isInformationalQuestion}.
 *
 *      The bookkeeping-only loophole stays closed: `update_todos`
 *      alone does NOT satisfy this path because it is `bookkeeping`,
 *      not `read`. A successful read tool is required.
 *
 * Rationale (path A): when an Excel/Word/Outlook host registers many
 * `category: "deliverable"` tools (`set_cell_range`, `generate_map_chart`,
 * `drawio`, …) but the user asks a research / Q&A question (e.g. "design an
 * MCP architecture"), the model correctly answers in prose with only
 * `bookkeeping` (`update_todos`) and `read` (MCP doc search/fetch) tool
 * calls. Pre-fix the planner gate ([rule 9](#L243-L260)) fired
 * `planner_no_deliverable`, which the model interpreted as "save the
 * answer to a file" and re-emitted the same long markdown via `write_file`
 * (which IS `category: "deliverable"`). The user saw the same answer twice.
 *
 * Rationale (path B): short informational questions like "what was my
 * last email?" naturally produce short factual answers (~150–240 chars)
 * that miss path A's 280-char threshold. Pre-fix the gate fired
 * `planner_no_deliverable` after the first prose answer, the model
 * complied by issuing another annotated MCP `read` call (which still does not
 * satisfy the deliverable gate), and the user saw 2–3 progressively
 * detailed prose replies for a single question — even when the model
 * had explicitly offered to wait for permission ("If you want, I can…").
 *
 * Rationale (path B, short-affirmative extension): a follow-up `"yes"`
 * to the model's read-action offer ("I can check your mailbox") hit
 * the same nudge storm because `isShortAffirmativeOrOptionPick("yes")`
 * blocked path A entirely. Real read-tool execution this step proves
 * the model is fulfilling a read action, not dodging a deliverable, so
 * the short-affirmative block is lifted for path B specifically.
 *
 * The {@link createInitialState} `hasDeliverableTools: false` bypass only
 * helps when the *entire registered tool set* has zero deliverables, which
 * is never true for the Excel/Word/Outlook hosts. These per-turn checks
 * complement that snapshot for sessions where deliverable tools exist but
 * the user asked an information-only question.
 */
export function proseAcceptedAsDeliverable(
  blocks: AssistantContentBlock[],
  state: AgentRunState,
): boolean {
  const prose = totalProseLength(blocks);
  const shortAffirmative = isShortAffirmativeOrOptionPick(state.lastUserText);

  // Path C: trivial / greeting input — no actionable intent. Any
  // non-empty prose is accepted. Checked first so single-character
  // inputs like "h" and bare greetings like "hi" don't fall through
  // to the path-A / path-B thresholds that assume the user asked for
  // something. Regression: typing "h" against an Excel host produced
  // 4 tool calls across 5 turns because path A required ≥280 prose
  // chars, path B required a successful `read` tool, and
  // `isShortAffirmativeOrOptionPick("h")` was false — every gate
  // missed and the planner kept nudging.
  if (isTrivialOrGreetingInput(state.lastUserText) && prose > 0) return true;

  // Path A: substantial standalone prose. Blocked for short affirmatives
  // to preserve the "2 → make a chart" regression where the model
  // dodges with long prose instead of calling the deliverable tool.
  if (!shortAffirmative && prose >= PROSE_DELIVERABLE_MIN_CHARS) return true;

  // Path B: a successful `read` tool fulfilled the request and the
  // prose answer is non-trivial. Triggered for informational questions
  // and short affirmatives confirming a read-only action.
  if (prose < PROSE_QNA_MIN_CHARS) return false;
  const readToolRanThisStep = state.executedToolsThisStep.some(
    (t) => t.ok && t.category === "read",
  );
  if (!readToolRanThisStep) return false;
  if (isInformationalQuestion(state.lastUserText)) return true;
  if (shortAffirmative) return true;
  return false;
}

function nudgeAvailable(state: AgentRunState, reason: NudgeReason): boolean {
  const used = state.nudgeAttempts[reason] ?? 0;
  return used < nudgeCeiling(reason);
}

/**
 * True on a prose turn that must NOT be accepted as the deliverable because
 * the run is in a detected TODO-bookkeeping loop for a concrete mutation.
 * `bookkeepingExecutionRequired` is latched from
 * {@link requestsConcreteToolExecution} when the first bookkeeping-only
 * nudge fires, and cleared once a real deliverable runs.
 *
 * Intentionally flag-based rather than derived from
 * {@link deliverableGateSatisfied}: at this point the gate is `false` for
 * BOTH a fabricated completion dodge and a legitimate research answer, so
 * only the latched user-intent signal can tell them apart. See the
 * LOAD-BEARING note on {@link requestsConcreteToolExecution}.
 */
function bookkeepingExecutionGuardActive(state: AgentRunState): boolean {
  return state.plannerMode && state.flags.bookkeepingExecutionRequired;
}

export const BOOKKEEPING_EXECUTION_STOP_TEXT =
  "Execution stopped because the model did not invoke an available tool capable of performing the requested change after TODO bookkeeping was disabled. No additional document, workbook, email, or file changes were made during the recovery attempts. Retry the request or provide any missing input needed to perform the change.";

export function deliverableGateSatisfied(state: AgentRunState): boolean {
  if (state.plannerMode) {
    // Research-only run: no `category: "deliverable"` tools are
    // registered, so the assistant's prose IS the deliverable. Bypass
    // the tool-based gate to avoid treating a valid prose answer as an
    // incomplete deliverable.
    if (!state.hasDeliverableTools) return true;
    return state.executedToolsThisStep.some(
      (t) => t.ok && t.category === "deliverable",
    );
  }
  if (!isShortAffirmativeOrOptionPick(state.lastUserText)) return true;
  return state.executedToolsThisRun.some(
    (t) => t.ok && t.category === "deliverable",
  );
}

export function deliverableNudgeReason(state: AgentRunState): NudgeReason {
  return state.plannerMode ? "planner_no_deliverable" : "action_without_tools";
}

export function deliverableNudgeAvailable(state: AgentRunState): boolean {
  const reason = deliverableNudgeReason(state);
  // Planner-mode is a forward workflow: plan once, execute, quality check,
  // then hand control back to the user. If the deliverable gate is still
  // unsatisfied, finalize the current pass instead of injecting an
  // in-run self-correction prompt that loops execution.
  if (reason === "planner_no_deliverable") return false;
  if (!nudgeAvailable(state, reason)) return false;
  if (reason === "action_without_tools" && state.flags.actionNudgeUsed) {
    return false;
  }
  return true;
}

function finalizeAtRecoveryCeiling(
  state: AgentRunState,
  turn: LLMTurnResult,
): Extract<Action, { type: "finalize" }> {
  if (bookkeepingExecutionGuardActive(state)) {
    return {
      type: "finalize",
      blocks: [{ type: "text", text: BOOKKEEPING_EXECUTION_STOP_TEXT }],
      usage: turn.usage,
      stopReason: "complete",
      syntheticBlocks: true,
    };
  }
  return {
    type: "finalize",
    blocks: turn.blocks,
    usage: turn.usage,
    stopReason: "complete",
  };
}

export interface DecideResult {
  action: Action;
  /** 1..10 per blueprint §5; emitted as `agent.rule_fired`. */
  rule: number;
}

/**
 * decide(turn, state, ctx) — pure rule evaluator. Caller is responsible
 * for ensuring `state.iteration` has been incremented before invocation
 * (mirrors the legacy loop where `iterations++` happens at top of `while`).
 */
export function decide(
  turn: LLMTurnResult,
  state: AgentRunState,
  ctx: DecideContext,
): DecideResult {
  void ctx; // reserved for future clock-aware rules; kept for signature stability

  const finishReason = turn.finishReason;
  const blocks = turn.blocks;
  const toolCalls = turn.toolCalls;

  // Rule 1: content_filter with empty blocks → one-shot retry.
  if (
    finishReason === "content_filter" &&
    blocks.length === 0 &&
    nudgeAvailable(state, "content_filter_empty")
  ) {
    return {
      rule: 1,
      action: {
        type: "nudge_and_retry",
        reason: "content_filter_empty",
        userText: nudgeText("content_filter_empty"),
        ephemeral: true,
      },
    };
  }

  // Rule 2: any other content_filter → finalize with whatever blocks exist.
  if (finishReason === "content_filter") {
    return {
      rule: 2,
      action: {
        type: "finalize",
        blocks,
        usage: turn.usage,
        stopReason: "complete",
      },
    };
  }

  // Rule 3: empty turn (no blocks, no tool calls) → retry.
  if (blocks.length === 0 && toolCalls.length === 0) {
    if (nudgeAvailable(state, "empty_response")) {
      return {
        rule: 3,
        action: {
          type: "nudge_and_retry",
          reason: "empty_response",
          userText: nudgeText("empty_response"),
          ephemeral: true,
        },
      };
    }
    return {
      rule: 3,
      action: finalizeAtRecoveryCeiling(state, turn),
    };
  }

  // Rule 4: stream signaled tool call but parse failed → one-shot retry.
  // When the failure was caused by `finish_reason: "length"` the
  // stream-decoder has already dropped the truncated tool call(s), so we
  // can surface a length-specific nudge first that tells the model
  // exactly how to recover (smaller batches). If that ceiling is
  // exhausted, fall back to the generic parse-miss nudge.
  if (turn.sawToolCallSignal && toolCalls.length === 0) {
    if (
      finishReason === "length" &&
      nudgeAvailable(state, "length_truncated_tool_args")
    ) {
      return {
        rule: 4,
        action: {
          type: "nudge_and_retry",
          reason: "length_truncated_tool_args",
          userText: nudgeText("length_truncated_tool_args"),
          ephemeral: true,
        },
      };
    }
    if (nudgeAvailable(state, "toolcall_parse_miss")) {
      return {
        rule: 4,
        action: {
          type: "nudge_and_retry",
          reason: "toolcall_parse_miss",
          userText: nudgeText("toolcall_parse_miss"),
          ephemeral: true,
        },
      };
    }
    return {
      rule: 4,
      action: finalizeAtRecoveryCeiling(state, turn),
    };
  }

  // Rule 5: tool calls present → execute.
  if (toolCalls.length > 0) {
    return {
      rule: 5,
      action: { type: "execute_tools", calls: toolCalls },
    };
  }

  // Rule 6: only thinking blocks → nudge to act (no iter charge).
  if (onlyThinking(blocks)) {
    if (nudgeAvailable(state, "thinking_only")) {
      return {
        rule: 6,
        action: {
          type: "nudge_and_retry",
          reason: "thinking_only",
          userText: nudgeText("thinking_only"),
          ephemeral: true,
          noIterCharge: true,
        },
      };
    }
    return {
      rule: 6,
      action: finalizeAtRecoveryCeiling(state, turn),
    };
  }

  // A concrete mutation request that already tripped the TODO-loop guard
  // cannot satisfy the run with prose alone. Give the model one additional
  // turn with update_todos still withheld; if it refuses again, surface an
  // honest synthetic stop instead of accepting a long completion claim.
  //
  // Rules 9/10 are intentionally reused here (rather than new numbers):
  // telemetry disambiguates this branch from the deliverable gate below via
  // `nudgeReason: "bookkeeping_execution_required"` on the rule-9 nudge and
  // `synthetic: true` on the rule-10 finalize.
  if (bookkeepingExecutionGuardActive(state)) {
    const reason = "bookkeeping_execution_required";
    if (nudgeAvailable(state, reason)) {
      return {
        rule: 9,
        action: {
          type: "nudge_and_retry",
          reason,
          userText: nudgeText(reason),
          ephemeral: true,
        },
      };
    }
    return {
      rule: 10,
      action: {
        type: "finalize",
        blocks: [{ type: "text", text: BOOKKEEPING_EXECUTION_STOP_TEXT }],
        usage: turn.usage,
        stopReason: "complete",
        syntheticBlocks: true,
      },
    };
  }

  // Rule 7: penultimate iteration with prior tool work → grace pass.
  if (
    state.iteration === state.maxIterations - 1 &&
    !state.flags.grantedFinalizationPass &&
    state.executedToolsThisRun.length > 0
  ) {
    return {
      rule: 7,
      action: {
        type: "nudge_and_retry",
        reason: "final_finalization_pass",
        userText: nudgeText("final_finalization_pass"),
        ephemeral: true,
      },
    };
  }

  // Unified deliverable gate (rules 8–10).
  if (
    deliverableGateSatisfied(state) ||
    proseAcceptedAsDeliverable(blocks, state)
  ) {
    return {
      rule: 8,
      action: {
        type: "finalize",
        blocks,
        usage: turn.usage,
        stopReason: "complete",
      },
    };
  }

  // Rule 9: gate not satisfied; deliverable nudge still available.
  // Skipped if the iteration ceiling has already granted the grace pass
  // (blueprint §5 "Rule 7 vs rule 9 interaction").
  if (
    deliverableNudgeAvailable(state) &&
    !state.flags.grantedFinalizationPass
  ) {
    const reason = deliverableNudgeReason(state);
    return {
      rule: 9,
      action: {
        type: "nudge_and_retry",
        reason,
        userText: nudgeText(reason),
        ephemeral: true,
      },
    };
  }

  // Rule 10: gate exhausted; finalize as `complete`. The gate-exhausted
  // condition is carried by the `finalize` emit event's
  // `deliverableGateSatisfied: false` flag (blueprint §5 rule 10).
  return {
    rule: 10,
    action: {
      type: "finalize",
      blocks,
      usage: turn.usage,
      stopReason: "complete",
    },
  };
}
