import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";

/* global Word Office */

/**
 * Note: Office.js Word API does NOT provide direct access to the spell-checker results.
 * The Word COM API (used by VBA) has GetSpellingSuggestions(), but this is not exposed in Office.js.
 *
 * This tool provides workarounds:
 * 1. Open the built-in Spelling & Grammar dialog
 * 2. Provide document text for external spell checking
 * 3. Use Word's proofing annotations if available
 */

export const checkSpellingTool = defineTool({
  name: "check_spelling",
  category: "read",
  parallelSafe: true,
  label: "Check Spelling",
  description:
    "Launches Word's built-in spell checker or extracts document text for spell checking. " +
    "Since Office.js doesn't expose spell-check results directly, this tool either opens " +
    "the standard spell check dialog or returns document text for analysis.",
  parameters: Type.Object({
    method: Type.Union(
      [
        Type.Literal("dialog", {
          description: "Open Word's built-in Spelling & Grammar dialog",
        }),
        Type.Literal("extract", {
          description: "Extract document text for spell checking",
        }),
      ],
      { description: "How to check spelling", default: "dialog" },
    ),
    scope: Type.Union(
      [
        Type.Literal("document", { description: "Check entire document" }),
        Type.Literal("selection", {
          description: "Check current selection only",
        }),
      ],
      { description: "What to check", default: "document" },
    ),
    maxLength: Type.Optional(
      Type.Number({
        description:
          "Maximum text length to extract (for 'extract' method). Default: 10000",
        default: 10000,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the spell check (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      if (params.method === "dialog") {
        // Office.js doesn't provide a way to open the spell check dialog programmatically
        return toolSuccess({
          opened: false,
          method: "dialog",
          message:
            "Office.js cannot open Word's Spelling & Grammar dialog programmatically. Please press F7 in Word or go to Review > Spelling & Grammar to check spelling.",
          alternative:
            "Use method: 'extract' to get document text for spell checking.",
        });
      }

      // Extract text for external spell checking
      const result = await Word.run(async (context) => {
        let range: Word.Range;

        if (params.scope === "selection") {
          range = context.document.getSelection();
        } else {
          range = context.document.body.getRange();
        }

        range.load("text");
        await context.sync();

        let text = range.text ?? "";
        const wasTruncated = text.length > (params.maxLength ?? 10000);
        if (wasTruncated) {
          text = `${text.substring(0, params.maxLength ?? 10000)}\n\n[Text truncated...]`;
        }

        return {
          text,
          characterCount: range.text?.length ?? 0,
          wasTruncated,
          note: "Office.js Limitation: Word's spell-checker results are not accessible via Office.js. This tool extracts text for manual review or external spell checking. To see Word's spell check results, use F7 or Review > Spelling & Grammar in Word.",
        };
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error checking spelling";

      return toolError(message);
    }
  },
});
