import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import {
  type WordAnchor,
  anchorMatchesParagraphText,
  findLiteralMatchOffsets,
  getAnchorDocumentParagraphIndex,
  getAnchorOccurrenceIndex,
  getAnchorScopeParagraphIndex,
  hasMatchSpecificAnchor,
  wordAnchorSchema,
} from "./word-anchor-utils";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

const REPLACE_PREVIEW_LIMIT = 20;

type SearchOptions = {
  matchCase: boolean;
  matchWholeWord: boolean;
  matchWildcards: boolean;
};

type SearchTarget = {
  target: {
    search(searchText: string, options: SearchOptions): Word.RangeCollection;
  };
  paragraphIndex: number | null;
  scopeParagraphIndex: number | null;
  paragraphText?: string;
};

export const replaceContentTool = defineTool({
  name: "replace_content",
  category: "deliverable",
  parallelSafe: false,
  label: "Replace Content",
  description:
    "Find and replace text in the Word document. " +
    "Can search within selection, body, or entire document. " +
    "Supports wildcards and case sensitivity options. " +
    "Wildcard replacement backreferences like \\1 are not supported. " +
    "Can also narrow edits using anchor metadata from get_document_content or search_document.",
  parameters: Type.Object({
    searchText: Type.String({ description: "The text to search for" }),
    replaceText: Type.String({
      description:
        "The replacement text. When useWildcards is true, backreferences like \\1 are not supported.",
    }),
    scope: Type.Union(
      [
        Type.Literal("body", { description: "Search entire document body" }),
        Type.Literal("selection", {
          description: "Search within current selection only",
        }),
      ],
      { description: "Where to search", default: "body" },
    ),
    matchCase: Type.Optional(
      Type.Boolean({
        description: "Match case exactly. Default: false",
        default: false,
      }),
    ),
    matchWholeWord: Type.Optional(
      Type.Boolean({
        description: "Match whole words only. Default: false",
        default: false,
      }),
    ),
    useWildcards: Type.Optional(
      Type.Boolean({
        description: "Use wildcards (* and ?). Default: false",
        default: false,
      }),
    ),
    replaceAll: Type.Optional(
      Type.Boolean({
        description: "Replace all occurrences. Default: true",
        default: true,
      }),
    ),
    previewOnly: Type.Optional(
      Type.Boolean({
        description:
          "Preview planned replacements without applying them. Default: false",
        default: false,
      }),
    ),
    maxEdits: Type.Optional(
      Type.Number({
        description:
          "Maximum number of replacements allowed before the tool refuses to apply changes. Must be a positive integer.",
        minimum: 1,
      }),
    ),
    anchor: Type.Optional(
      Type.Composite([
        wordAnchorSchema,
        Type.Object({
          explanation: Type.Optional(Type.Never()),
        }),
      ]),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're replacing (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      const hasBackrefs = /\\([1-9]\d*)/.test(params.replaceText);
      if ((params.useWildcards ?? false) && hasBackrefs) {
        return toolError(
          "Wildcard replacement backreferences like \\1 are not supported safely. Use a literal replaceText, or break the change into smaller replacements.",
        );
      }

      const previewOnly = params.previewOnly ?? false;
      const maxEdits = normalizeMaxEdits(params.maxEdits);

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          !previewOnly,
          async () => {
            throwIfToolAborted(signal);
            const searchOptions = {
              matchCase: params.matchCase ?? false,
              matchWholeWord: params.matchWholeWord ?? false,
              matchWildcards: params.useWildcards ?? false,
            };

            const searchTarget = await resolveSearchTarget(
              context,
              params.scope,
              params.anchor,
              signal,
            );
            const searchResult = searchTarget.target.search(
              params.searchText,
              searchOptions,
            );

            searchResult.load("items");

            const needsMatchText =
              previewOnly ||
              maxEdits !== undefined ||
              Boolean(params.anchor?.quote) ||
              (params.useWildcards && hasBackrefs) ||
              hasMatchSpecificAnchor(params.anchor);

            if (needsMatchText) {
              searchResult.load("items/text");
            }

            await syncWordContext(context, signal);

            const matchCount = searchResult.items.length;

            if (matchCount === 0) {
              return {
                replaced: 0,
                anchorUsed: Boolean(params.anchor),
                message: `No matches found for "${params.searchText}"`,
              };
            }

            const targetRanges = selectTargetRanges({
              ranges: searchResult.items,
              anchor: params.anchor,
              replaceAll: params.replaceAll ?? true,
              paragraphText: searchTarget.paragraphText,
              searchText: params.searchText,
              matchCase: params.matchCase ?? false,
            });

            if (targetRanges.length === 0) {
              return {
                replaced: 0,
                previewOnly,
                totalMatches: matchCount,
                searchText: params.searchText,
                replaceText: params.replaceText,
                anchorUsed: Boolean(params.anchor),
                message: "Anchor did not resolve to a replaceable match.",
              };
            }

            const preview = buildReplacementPreview({
              ranges: targetRanges,
              replaceText: params.replaceText,
              searchText: params.searchText,
              maxEdits,
            });

            const exceedsMaxEdits =
              maxEdits !== undefined && targetRanges.length > maxEdits;

            if (previewOnly) {
              return {
                previewOnly: true,
                plannedEdits: targetRanges.length,
                totalMatches: matchCount,
                searchText: params.searchText,
                replaceText: params.replaceText,
                anchorUsed: Boolean(params.anchor),
                paragraphIndex: searchTarget.paragraphIndex,
                scopeParagraphIndex: searchTarget.scopeParagraphIndex,
                maxEdits,
                exceedsMaxEdits,
                preview,
                previewTruncated:
                  targetRanges.length >
                  Math.min(
                    REPLACE_PREVIEW_LIMIT,
                    maxEdits ?? REPLACE_PREVIEW_LIMIT,
                  ),
              };
            }

            if (exceedsMaxEdits) {
              return {
                applied: false,
                blockedByMaxEdits: true,
                plannedEdits: targetRanges.length,
                totalMatches: matchCount,
                searchText: params.searchText,
                replaceText: params.replaceText,
                anchorUsed: Boolean(params.anchor),
                paragraphIndex: searchTarget.paragraphIndex,
                scopeParagraphIndex: searchTarget.scopeParagraphIndex,
                maxEdits,
                preview,
                previewTruncated:
                  targetRanges.length >
                  Math.min(
                    REPLACE_PREVIEW_LIMIT,
                    maxEdits ?? REPLACE_PREVIEW_LIMIT,
                  ),
                message: `Planned ${targetRanges.length} replacements exceeds maxEdits ${maxEdits}. Use previewOnly, narrow the target, or increase maxEdits.`,
              };
            }

            throwIfToolAborted(signal);
            for (const range of targetRanges) {
              range.insertText(params.replaceText, Word.InsertLocation.replace);
            }

            // OPTIMIZATION: Single sync for all queued insert operations
            await syncWordContext(context, signal);

            return {
              replaced: targetRanges.length,
              totalMatches: matchCount,
              searchText: params.searchText,
              replaceText: params.replaceText,
              previewOnly: false,
              anchorUsed: Boolean(params.anchor),
              paragraphIndex: searchTarget.paragraphIndex,
              scopeParagraphIndex: searchTarget.scopeParagraphIndex,
              maxEdits,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error replacing content";
      return toolError(message);
    }
  },
});

async function resolveSearchTarget(
  context: Word.RequestContext,
  scope: "body" | "selection",
  anchor?: WordAnchor,
  signal?: AbortSignal,
): Promise<SearchTarget> {
  let anchorMismatch = false;
  const documentParagraphIndex = getAnchorDocumentParagraphIndex(anchor);
  if (documentParagraphIndex !== null) {
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (
      documentParagraphIndex < 0 ||
      documentParagraphIndex >= paragraphs.items.length
    ) {
      throw new Error(
        `Anchor paragraphIndex ${documentParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[documentParagraphIndex];
    if (paragraph && anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
      return {
        target: paragraph,
        paragraphIndex: documentParagraphIndex,
        scopeParagraphIndex: getAnchorScopeParagraphIndex(anchor),
        paragraphText: paragraph.text ?? "",
      };
    }

    anchorMismatch = true;
  }

  const scopeParagraphIndex = getAnchorScopeParagraphIndex(anchor);
  if (scopeParagraphIndex !== null) {
    const selection = context.document.getSelection();
    const paragraphs = selection.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (
      scopeParagraphIndex < 0 ||
      scopeParagraphIndex >= paragraphs.items.length
    ) {
      throw new Error(
        `Anchor scopeParagraphIndex ${scopeParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[scopeParagraphIndex];
    if (paragraph && anchorMatchesParagraphText(anchor, paragraph.text ?? "")) {
      return {
        target: paragraph,
        paragraphIndex: null,
        scopeParagraphIndex,
        paragraphText: paragraph.text ?? "",
      };
    }

    anchorMismatch = true;
  }

  if (anchorMismatch) {
    throw new Error(
      "Anchor no longer matches current document content. Read the target again before editing.",
    );
  }

  if (scope === "selection") {
    const selection = context.document.getSelection();
    return {
      target: selection,
      paragraphIndex: null,
      scopeParagraphIndex: null,
    };
  }

  return {
    target: context.document.body,
    paragraphIndex: null,
    scopeParagraphIndex: null,
  };
}

function selectTargetRanges(options: {
  ranges: Word.Range[];
  anchor?: WordAnchor;
  replaceAll: boolean;
  paragraphText?: string;
  searchText: string;
  matchCase: boolean;
}): Word.Range[] {
  if (!options.anchor) {
    return options.replaceAll ? options.ranges : options.ranges.slice(0, 1);
  }

  if (!hasMatchSpecificAnchor(options.anchor)) {
    return options.replaceAll ? options.ranges : options.ranges.slice(0, 1);
  }

  const occurrenceIndex = getAnchorOccurrenceIndex(options.anchor);
  if (occurrenceIndex !== null) {
    return options.ranges[occurrenceIndex]
      ? [options.ranges[occurrenceIndex]]
      : [];
  }

  if (
    options.anchor.startOffsetInParagraph !== undefined &&
    options.paragraphText !== undefined
  ) {
    const literalSearchText = options.anchor.quote ?? options.searchText;
    const offsets = findLiteralMatchOffsets(
      options.paragraphText,
      literalSearchText,
      options.matchCase,
    );
    const resolvedIndex = offsets.indexOf(
      options.anchor.startOffsetInParagraph,
    );
    if (resolvedIndex !== -1 && options.ranges[resolvedIndex]) {
      return [options.ranges[resolvedIndex]];
    }
  }

  if (options.anchor.quote) {
    const textMatches = options.ranges.filter(
      (range) => range.text === options.anchor?.quote,
    );
    if (textMatches.length > 0) {
      return [textMatches[0]];
    }
  }

  return options.ranges.slice(0, 1);
}

function normalizeMaxEdits(maxEdits?: number): number | undefined {
  if (maxEdits === undefined) {
    return undefined;
  }

  if (!Number.isInteger(maxEdits) || maxEdits < 1) {
    throw new Error("maxEdits must be a positive integer");
  }

  return maxEdits;
}

function buildReplacementPreview(options: {
  ranges: Word.Range[];
  replaceText: string;
  searchText: string;
  maxEdits?: number;
}): Array<{
  index: number;
  before: string;
  after: string;
}> {
  const previewLimit = Math.min(
    REPLACE_PREVIEW_LIMIT,
    options.maxEdits ?? REPLACE_PREVIEW_LIMIT,
  );

  return options.ranges.slice(0, previewLimit).map((range, index) => {
    const before = range.text ?? options.searchText;
    return {
      index,
      before,
      after: options.replaceText,
    };
  });
}
