export type OfficeHostType = "excel" | "word" | "outlook" | "web";

export function resolveMaxOutputTokensForHost(
  hostType: OfficeHostType,
  providerMaxOutputTokens?: number,
  wordMaxOutputTokens?: number,
): number | undefined {
  const providerLimit = normalizePositiveInteger(providerMaxOutputTokens);
  if (hostType !== "word") return providerLimit;

  const wordLimit = normalizePositiveInteger(wordMaxOutputTokens);
  if (providerLimit === undefined) return wordLimit;
  if (wordLimit === undefined) return providerLimit;
  return Math.min(providerLimit, wordLimit);
}

function normalizePositiveInteger(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : undefined;
}
