import { Type } from "@sinclair/typebox";
import { resolveStagedTextContent } from "./staged-content";
import { defineTool, toolError, toolSuccess } from "./types";

export const emailCreateTool = defineTool({
  name: "email_create",
  category: "non_idempotent",
  parallelSafe: false,
  maxRetries: 0,
  label: "Create Email",
  description:
    "Create a new email draft in Outlook with the specified recipients, subject, and body. " +
    "Use this to compose new messages. The email will be displayed for the user to review and send.",
  parameters: Type.Object({
    to: Type.Optional(
      Type.Union(
        [
          Type.String({
            description:
              "Primary recipient email address(es), comma-separated for multiple",
          }),
          Type.Array(
            Type.String({
              description: "Primary recipient email address(es)",
            }),
          ),
        ],
        {
          description:
            "Primary recipient email address(es) - can be added later by the user",
        },
      ),
    ),
    cc: Type.Optional(
      Type.Union([
        Type.String({
          description:
            "CC recipient email address(es), comma-separated for multiple",
        }),
        Type.Array(
          Type.String({
            description: "CC recipient email address(es)",
          }),
        ),
      ]),
    ),
    bcc: Type.Optional(
      Type.Union([
        Type.String({
          description:
            "BCC recipient email address(es), comma-separated for multiple",
        }),
        Type.Array(
          Type.String({
            description: "BCC recipient email address(es)",
          }),
        ),
      ]),
    ),
    subject: Type.String({
      description: "REQUIRED: Email subject line",
    }),
    body: Type.Optional(
      Type.String({
        description:
          "Email body content. Optional when bodyFromFile is provided.",
      }),
    ),
    bodyFromFile: Type.Optional(
      Type.String({
        description:
          "VFS path containing the email body. Stage substantial bodies with write_file and prefer this over an inline body.",
      }),
    ),
    bodyFormat: Type.Optional(
      Type.String({
        enum: ["text", "html"],
        description:
          "Format of the body. Use 'html' for professional formatting. Default: 'html'",
        default: "html",
      }),
    ),
    importance: Type.Optional(
      Type.String({
        enum: ["low", "normal", "high"],
        description: "Email priority. Default: 'normal'",
        default: "normal",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the email purpose (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const stagedBody = await resolveStagedTextContent({
        content: params.body,
        fromFile: params.bodyFromFile,
        inlineFieldName: "body",
        fileFieldName: "bodyFromFile",
      });
      if ("error" in stagedBody) return toolError(stagedBody.error);
      const body = stagedBody.content;
      const bodyFormat = params.bodyFormat ?? "html";

      // Debug logging
      console.log(
        "[email_create] Received params:",
        JSON.stringify(params, null, 2),
      );

      // Helper to normalize recipients to array
      const normalizeRecipients = (
        recipients: string | string[] | undefined,
      ): string[] => {
        if (!recipients) return [];
        if (typeof recipients === "string") {
          return recipients
            .split(",")
            .map((e) => e.trim())
            .filter(Boolean);
        }
        return recipients;
      };

      const toList = normalizeRecipients(params.to);
      const ccList = normalizeRecipients(params.cc);
      const bccList = normalizeRecipients(params.bcc);

      // Allow creating drafts without recipients - user can add them later
      // Outlook's displayNewMessageForm accepts empty recipient lists

      // Validate required parameters
      if (!body || typeof body !== "string" || body.trim() === "") {
        console.warn("[email_create] Missing or empty body parameter");
        return toolError("Email body is required and cannot be empty");
      }
      if (!params.subject || typeof params.subject !== "string") {
        console.warn("[email_create] Missing subject parameter");
        return toolError("Email subject is required");
      }

      // Create parameters inline - Office.js doesn't export these type names
      const messageParams: {
        toRecipients?: string[];
        subject: string;
        ccRecipients?: string[];
        bccRecipients?: string[];
        body?: string;
        htmlBody?: string;
      } = {
        subject: params.subject,
      };

      // Only add recipients if they exist
      if (toList.length > 0) {
        messageParams.toRecipients = toList;
      }

      if (ccList.length > 0) {
        messageParams.ccRecipients = ccList;
      }
      if (bccList.length > 0) {
        messageParams.bccRecipients = bccList;
      }

      // Add body - use htmlBody for better compatibility with Outlook
      // displayNewMessageForm works more reliably with htmlBody
      const isHtml = bodyFormat === "html";
      if (isHtml) {
        messageParams.htmlBody = body;
      } else {
        // Convert plain text to HTML for better compatibility
        const escapedBody = body
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/\n/g, "<br>");
        messageParams.htmlBody = `<pre style="font-family: Arial, sans-serif; white-space: pre-wrap;">${escapedBody}</pre>`;
      }

      // Debug: Log the full params being sent
      console.log(
        "[email_create] Full messageParams:",
        JSON.stringify(messageParams, null, 2),
      );
      console.log(
        "[email_create] Office.context.mailbox exists:",
        !!Office.context.mailbox,
      );
      console.log(
        "[email_create] displayNewMessageForm exists:",
        typeof Office.context.mailbox?.displayNewMessageForm,
      );

      // Open the new message form - body should be populated directly
      try {
        if (!Office.context.mailbox) {
          return toolError(
            "Office.context.mailbox is not available. Ensure you are in Outlook.",
          );
        }
        if (!Office.context.mailbox.displayNewMessageForm) {
          return toolError(
            "displayNewMessageForm is not supported in this Outlook version.",
          );
        }
        Office.context.mailbox.displayNewMessageForm(messageParams);
        console.log("[email_create] displayNewMessageForm called successfully");
      } catch (e) {
        console.error("[email_create] displayNewMessageForm failed:", e);
        return toolError(
          `Failed to open new message form: ${e instanceof Error ? e.message : String(e)}`,
        );
      }

      // Return success
      const successMessage = `Email draft created and opened${toList.length === 0 ? " (no recipient specified - add one before sending)" : ""}`;

      return toolSuccess({
        success: true,
        message: successMessage,
        to: toList,
        cc: ccList,
        bcc: bccList,
        subject: params.subject,
        importance: params.importance || "normal",
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error creating email";
      return toolError(message);
    }
  },
});
