import { Type } from "@sinclair/typebox";
import { readFileBuffer } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

function bufferToBase64(buffer: Uint8Array): string {
  // Use a more reliable method that handles all byte values correctly
  const chunks: string[] = [];
  const chunkSize = 0x8000; // 32KB chunks to avoid call stack issues
  for (let i = 0; i < buffer.length; i += chunkSize) {
    const chunk = buffer.subarray(i, i + chunkSize);
    chunks.push(String.fromCharCode.apply(null, chunk as unknown as number[]));
  }
  return btoa(chunks.join(""));
}

async function loadImageAsBase64(filePath: string): Promise<string> {
  const buffer = await readFileBuffer(filePath);
  if (!buffer) {
    throw new Error(`File not found: ${filePath}`);
  }
  return bufferToBase64(buffer);
}

async function loadSvgAsPngBase64(
  filePath: string,
  width?: number,
  height?: number,
): Promise<string> {
  const buffer = await readFileBuffer(filePath);
  if (!buffer) {
    throw new Error(`File not found: ${filePath}`);
  }

  const svgText = new TextDecoder().decode(buffer);

  return new Promise((resolve, reject) => {
    const blob = new Blob([svgText], {
      type: "image/svg+xml;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const image = new Image();

    image.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        const targetWidth =
          width && width > 0
            ? Math.round(width)
            : Math.max(1, image.naturalWidth || 1200);
        const targetHeight =
          height && height > 0
            ? Math.round(height)
            : Math.max(1, image.naturalHeight || 800);

        canvas.width = targetWidth;
        canvas.height = targetHeight;

        const ctx = canvas.getContext("2d");
        if (!ctx) {
          throw new Error("Failed to create canvas context for SVG conversion");
        }

        // Keep transparent background by default and rasterize SVG to PNG.
        ctx.drawImage(image, 0, 0, targetWidth, targetHeight);

        const dataUrl = canvas.toDataURL("image/png");
        const base64 = dataUrl.replace(/^data:image\/png;base64,/, "");
        resolve(base64);
      } catch (err) {
        reject(err instanceof Error ? err : new Error("SVG conversion failed"));
      } finally {
        URL.revokeObjectURL(url);
      }
    };

    image.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Failed to load SVG for conversion"));
    };

    image.src = url;
  });
}

async function getWorksheetById(
  context: Excel.RequestContext,
  sheetId: number,
): Promise<Excel.Worksheet | null> {
  const { preloadSheetIds } = await import("../excel/sheet-id-map");
  const sheets = context.workbook.worksheets;
  sheets.load("items");
  await context.sync();

  for (const sheet of sheets.items) {
    sheet.load("id");
  }
  await context.sync();

  const idMap = await preloadSheetIds(sheets.items);

  for (const sheet of sheets.items) {
    const stableId = idMap.get(sheet.id);
    if (stableId === sheetId) {
      return sheet;
    }
  }

  return null;
}

export const insertImageTool = defineTool({
  name: "insert_image",
  category: "deliverable",
  parallelSafe: false,
  label: "Insert Image",
  description:
    "Insert an image into the Excel worksheet. " +
    "Supports PNG, JPG, JPEG, GIF, BMP, SVG formats. " +
    "Images are positioned at a cell anchor point and can be sized. " +
    "IMPORTANT: Use the ORIGINAL image file path (e.g., 'image.png'), NOT the .parsed.txt version. " +
    "For SVG files, they will be converted to display in Excel.",
  parameters: Type.Object({
    sheetId: Type.Number({ description: "The worksheet ID (1-based index)" }),
    imagePath: Type.String({
      description:
        "Path to the ORIGINAL image file in the virtual filesystem (e.g., 'image.png' or '/home/user/uploads/image.png'). " +
        "DO NOT use .parsed.txt files - use the actual image file name.",
    }),
    anchor: Type.String({
      description:
        "Top-left cell where the image should be placed (e.g., 'A1', 'B5')",
    }),
    width: Type.Optional(
      Type.Number({
        description:
          "Image width in pixels. If not specified, uses original width",
      }),
    ),
    height: Type.Optional(
      Type.Number({
        description:
          "Image height in pixels. If not specified, uses original height",
      }),
    ),
    altText: Type.Optional(
      Type.String({
        description: "Alternative text for accessibility",
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of the image insertion (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  dirtyTracking: {
    getRanges: (p) => [
      {
        sheetId: p.sheetId,
        range: p.anchor,
      },
    ],
  },
  execute: async (_toolCallId, params) => {
    try {
      // Validate: don't allow .parsed.txt files for image insertion
      const fileName = params.imagePath.split("/").pop() || "";
      if (fileName.endsWith(".parsed.txt")) {
        const originalFile = fileName.replace(".parsed.txt", "");
        return toolError(
          `Cannot insert a parsed text file as an image. You provided '${fileName}'. Use the original image file '${originalFile}' instead.`,
        );
      }

      // Determine image format from file extension
      const ext = params.imagePath.split(".").pop()?.toLowerCase() || "png";

      // Load image from VFS as base64. Convert SVG to PNG for reliable Excel rendering.
      // readFileBuffer handles path resolution (adds /home/user/uploads/ prefix if needed)
      console.log(`[insert_image] Loading image from: ${params.imagePath}`);
      let base64Data: string;
      if (ext === "svg") {
        try {
          base64Data = await loadSvgAsPngBase64(
            params.imagePath,
            params.width,
            params.height,
          );
        } catch (error) {
          console.warn(
            "[insert_image] SVG to PNG conversion failed, falling back to raw SVG bytes:",
            error,
          );
          base64Data = await loadImageAsBase64(params.imagePath);
        }
      } else {
        base64Data = await loadImageAsBase64(params.imagePath);
      }
      console.log(
        `[insert_image] Successfully loaded image, size: ${base64Data.length} chars`,
      );

      // Debug logging
      console.log(`[insert_image] Base64 length: ${base64Data.length}`);
      console.log(
        `[insert_image] Base64 prefix: ${base64Data.substring(0, 50)}...`,
      );
      console.log(
        `[insert_image] MIME type: ${ext === "svg" ? "image/png (converted from SVG)" : ext}`,
      );

      // Execute Office.js to insert image
      const result = await Excel.run(async (context) => {
        const sheet = await getWorksheetById(context, params.sheetId);
        if (!sheet) {
          throw new Error(`Worksheet with ID ${params.sheetId} not found`);
        }

        // Get the anchor cell and load its position properties
        const anchorCell = sheet.getRange(params.anchor);
        anchorCell.load("rowIndex, columnIndex, left, top");
        await context.sync();

        // Excel.js addImage expects just the base64 string, not a data URL
        console.log(`[insert_image] Base64 length: ${base64Data.length}`);

        // Insert image as shape
        const shapes = sheet.shapes;
        const imageShape = shapes.addImage(base64Data);

        // Position at anchor cell (use default 0 if cell position not available)
        imageShape.left = anchorCell.left ?? 0;
        imageShape.top = anchorCell.top ?? 0;

        // Set dimensions if provided
        if (params.width !== undefined) {
          imageShape.width = params.width;
        }
        if (params.height !== undefined) {
          imageShape.height = params.height;
        }

        await context.sync();

        // Load shape properties for return values
        imageShape.load("id, left, top, width, height");
        await context.sync();

        return {
          success: true,
          shapeId: imageShape.id,
          anchor: params.anchor,
          left: imageShape.left,
          top: imageShape.top,
          width: imageShape.width,
          height: imageShape.height,
        };
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error inserting image";
      return toolError(message);
    }
  },
});
