import { Type } from "@sinclair/typebox";
import {
  DEFAULT_MEMORY_LIMIT_BYTES,
  DEFAULT_TIMEOUT_MS,
  evalJs,
} from "../js-runtime";
import type { JsRunResult } from "../js-runtime";
import { trackEvent } from "../telemetry";
import { defineTool, toolSuccess } from "./types";

function formatJsValue(value: unknown): unknown {
  if (typeof value === "string") return value;
  return value;
}

function telemetryMeasurements(params: {
  timeoutMs?: number;
  memoryLimitBytes?: number;
  preloadFiles?: string[];
}): Record<string, number> {
  return {
    timeoutMs: params.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    memoryLimitBytes: params.memoryLimitBytes ?? DEFAULT_MEMORY_LIMIT_BYTES,
    preloadFileCount: params.preloadFiles?.length ?? 0,
  };
}

function emitResultTelemetry(result: JsRunResult): void {
  if (result.timedOut) {
    trackEvent("js_tool_timeout");
  }
  if (result.memoryExceeded) {
    trackEvent("js_tool_memory_cap");
  }
  if (result.aborted) {
    trackEvent("js_tool_aborted");
  }
  if (result.error?.name === "QuickJSLoadError") {
    trackEvent("js_tool_load_failed");
  }
}

export const jsTool = defineTool({
  name: "js",
  category: "read",
  parallelSafe: false,
  origin: "local",
  maxRetries: 0,
  label: "JavaScript",
  description:
    "Run small JavaScript programs in QuickJS-NG WASM (not Node). Use report(value) to return a result; the last report call wins. " +
    "Supports ES modules and top-level await when module=true, but does not support guest imports from VFS. " +
    "Use preloadFiles before calling vfs.readText(path); binary inputs should be converted first with pdf-to-text, docx-to-text, or xlsx-to-csv. " +
    "No Office, DOM, network, process, require, std, os, or Node APIs are available. The tool is read-only; save returned content with write_file or append_file. " +
    "Tool results over roughly 5KB are truncated, so use the bash js command with redirection (for example: js transform.mjs > out.csv or >> out.csv) for bulk output. Use eval_officejs for Office host APIs.",
  parameters: Type.Object({
    code: Type.String({
      description:
        "JavaScript source to run. Call report(value) to return a value.",
    }),
    module: Type.Optional(
      Type.Boolean({
        description:
          "Evaluate as an ES module. Required for top-level await and export syntax.",
        default: false,
      }),
    ),
    filename: Type.Optional(
      Type.String({
        description: "Filename used in stack traces, e.g. transform.mjs.",
      }),
    ),
    preloadFiles: Type.Optional(
      Type.Array(
        Type.String({
          description:
            "VFS file path to preload for vfs.readText(path). Relative paths resolve under /home/user/uploads/.",
        }),
      ),
    ),
    stdin: Type.Optional(
      Type.String({
        description: "String exposed as global stdin inside QuickJS.",
      }),
    ),
    timeoutMs: Type.Optional(
      Type.Number({
        description: "Execution timeout in milliseconds (50..30000).",
        minimum: 50,
        maximum: 30000,
      }),
    ),
    memoryLimitBytes: Type.Optional(
      Type.Number({
        description: "QuickJS heap memory limit in bytes (1 MiB..256 MiB).",
        minimum: 1024 * 1024,
        maximum: 256 * 1024 * 1024,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    trackEvent(
      "js_tool_invoked",
      { module: String(params.module ?? false) },
      telemetryMeasurements(params),
    );

    const result = await evalJs({
      code: params.code,
      module: params.module,
      filename: params.filename,
      preloadFiles: params.preloadFiles,
      stdin: params.stdin,
      timeoutMs: params.timeoutMs,
      memoryLimitBytes: params.memoryLimitBytes,
      signal,
    });

    emitResultTelemetry(result);

    if (!result.ok) {
      return toolSuccess({
        success: false,
        error: result.error,
        console: result.console,
        reported: result.reported,
        value: result.reported ? formatJsValue(result.value) : undefined,
        timedOut: result.timedOut,
        aborted: result.aborted,
        memoryExceeded: result.memoryExceeded,
        elapsedMs: result.elapsedMs,
      });
    }

    return toolSuccess({
      success: true,
      value: result.reported ? formatJsValue(result.value) : undefined,
      reported: result.reported,
      console: result.console,
      elapsedMs: result.elapsedMs,
    });
  },
});
