import type { MCPConfigDiagnostic } from "./types";

const TENANT_ID_PATTERN = /^([0-9a-f-]{36}|common|organizations|consumers)$/i;
const CLIENT_ID_PATTERN = /^[0-9a-f-]{36}$/i;
const GRAPH_APP_ID = "00000003-0000-0000-c000-000000000000";
const GRAPH_HOST_PATTERN = /^graph\.microsoft\./i;
const LOCALHOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

export interface EntraAuthInput {
  tenantId: unknown;
  clientId: unknown;
  scopes: unknown;
  redirectUri?: unknown;
}

export interface EntraAuthValidationOptions {
  connectionId?: string;
  requireSameOriginRedirect?: boolean;
}

export interface EntraAuthValidationResult {
  tenantId?: string;
  clientId?: string;
  scopes?: string[];
  redirectUri?: string;
  diagnostics: MCPConfigDiagnostic[];
}

function pushDiag(
  diagnostics: MCPConfigDiagnostic[],
  field: string,
  message: string,
  connectionId?: string,
): void {
  diagnostics.push({
    field,
    message,
    ...(connectionId ? { connectionId } : {}),
  });
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

export function parseEntraScopes(value: string): string[] {
  return value
    .split(/[\s,]+/g)
    .map((scope) => scope.trim())
    .filter(Boolean);
}
export interface EntraScopeNormalizationOptions {
  clientId?: string;
}

export function normalizeEntraScope(
  scope: string,
  options: EntraScopeNormalizationOptions = {},
): string {
  const trimmed = scope.trim();
  const clientId = options.clientId?.trim();
  const selfClientId = CLIENT_ID_PATTERN.test(clientId ?? "")
    ? clientId?.toLowerCase()
    : undefined;

  if (CLIENT_ID_PATTERN.test(trimmed)) {
    return `${trimmed}/.default`;
  }

  if (/^api:\/\//i.test(trimmed)) {
    const rest = trimmed.slice("api://".length).replace(/\/+$/, "");
    const slashIndex = rest.indexOf("/");
    const resourceId = slashIndex >= 0 ? rest.slice(0, slashIndex) : rest;
    if (
      selfClientId &&
      CLIENT_ID_PATTERN.test(resourceId) &&
      resourceId.toLowerCase() === selfClientId
    ) {
      return slashIndex >= 0
        ? `${resourceId}/${rest.slice(slashIndex + 1)}`
        : `${resourceId}/.default`;
    }
    if (rest && slashIndex < 0) {
      return `api://${rest}/.default`;
    }
  }

  if (/^https:\/\//i.test(trimmed)) {
    try {
      const url = new URL(trimmed);
      if (
        !url.search &&
        !url.hash &&
        (url.pathname === "" || url.pathname === "/")
      ) {
        return `${url.origin}/.default`;
      }
    } catch {
      return trimmed;
    }
  }

  return trimmed;
}

export function normalizeEntraScopes(
  scopes: readonly string[],
  options: EntraScopeNormalizationOptions = {},
): string[] {
  return scopes.map((scope) => normalizeEntraScope(scope, options));
}

function audienceFromScope(scope: string): string | null {
  if (scope.startsWith("api://")) {
    const rest = scope.slice("api://".length);
    const slashIndex = rest.lastIndexOf("/");
    if (slashIndex <= 0) return null;
    return `api://${rest.slice(0, slashIndex).toLowerCase()}`;
  }

  if (scope.startsWith("https://")) {
    let url: URL;
    try {
      url = new URL(scope);
    } catch {
      return null;
    }
    const slashIndex = url.pathname.lastIndexOf("/");
    if (slashIndex <= 0) return null;
    return `${url.origin.toLowerCase()}${url.pathname.slice(0, slashIndex).toLowerCase()}`;
  }

  const slashIndex = scope.lastIndexOf("/");
  if (slashIndex <= 0) return null;
  const prefix = scope.slice(0, slashIndex);
  if (CLIENT_ID_PATTERN.test(prefix)) {
    return prefix.toLowerCase();
  }

  return null;
}

function scopeLooksValid(scope: string): boolean {
  return (
    /^api:\/\/[^\s]+\/(?:[A-Za-z0-9._-]+|\.default)$/.test(scope) ||
    /^https:\/\/[^\s/]+\/[^\s]*\/(?:[A-Za-z0-9._-]+|\.default)$/.test(scope) ||
    /^[0-9a-f-]{36}\/(?:[A-Za-z0-9._-]+|\.default)$/i.test(scope)
  );
}

function isGraphScope(scope: string): boolean {
  if (scope.toLowerCase().startsWith(`${GRAPH_APP_ID}/`)) {
    return true;
  }

  try {
    const normalized = scope.startsWith("api://")
      ? new URL(`https://${scope.slice("api://".length)}`)
      : new URL(scope);
    return GRAPH_HOST_PATTERN.test(normalized.hostname);
  } catch {
    return false;
  }
}

function validateRedirectUri(
  raw: unknown,
  diagnostics: MCPConfigDiagnostic[],
  options: EntraAuthValidationOptions,
): string | undefined {
  if (raw === undefined || raw === null || raw === "") {
    return undefined;
  }
  if (!isString(raw)) {
    pushDiag(
      diagnostics,
      "auth.redirectUri",
      "must be a string when present",
      options.connectionId,
    );
    return undefined;
  }

  const trimmed = raw.trim();
  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    pushDiag(
      diagnostics,
      "auth.redirectUri",
      "must be an absolute URL",
      options.connectionId,
    );
    return undefined;
  }

  const isHttps = url.protocol === "https:";
  const isHttpLocalhost =
    url.protocol === "http:" && LOCALHOSTS.has(url.hostname);
  if (!isHttps && !isHttpLocalhost) {
    pushDiag(
      diagnostics,
      "auth.redirectUri",
      "must use https, except http is allowed on localhost",
      options.connectionId,
    );
    return undefined;
  }

  if (options.requireSameOriginRedirect && typeof window !== "undefined") {
    try {
      if (url.origin !== window.location.origin) {
        pushDiag(
          diagnostics,
          "auth.redirectUri",
          "must use the same origin as the add-in",
          options.connectionId,
        );
        return undefined;
      }
    } catch {
      // Non-browser tests and restricted WebViews skip the UI-only check.
    }
  }

  return trimmed;
}

export function validateEntraAuthFields(
  input: EntraAuthInput,
  options: EntraAuthValidationOptions = {},
): EntraAuthValidationResult {
  const diagnostics: MCPConfigDiagnostic[] = [];
  const tenantId = isString(input.tenantId) ? input.tenantId.trim() : "";
  const clientId = isString(input.clientId) ? input.clientId.trim() : "";

  if (!tenantId || tenantId.length > 64 || !TENANT_ID_PATTERN.test(tenantId)) {
    pushDiag(
      diagnostics,
      "auth.tenantId",
      "must be a tenant GUID, 'common', 'organizations', or 'consumers'",
      options.connectionId,
    );
  }

  if (!clientId || !CLIENT_ID_PATTERN.test(clientId)) {
    pushDiag(
      diagnostics,
      "auth.clientId",
      "must be an Entra application client ID GUID",
      options.connectionId,
    );
  }

  const scopesRaw = input.scopes;
  const scopes = Array.isArray(scopesRaw)
    ? scopesRaw
        .filter(isString)
        .map((scope) => scope.trim())
        .filter(Boolean)
    : [];
  const normalizedScopes = normalizeEntraScopes(scopes, { clientId });
  if (!Array.isArray(scopesRaw)) {
    pushDiag(
      diagnostics,
      "auth.scopes",
      "must be an array",
      options.connectionId,
    );
  } else if (scopesRaw.some((scope) => !isString(scope))) {
    pushDiag(
      diagnostics,
      "auth.scopes",
      "must contain only strings",
      options.connectionId,
    );
  }

  if (normalizedScopes.length < 1 || normalizedScopes.length > 3) {
    pushDiag(
      diagnostics,
      "auth.scopes",
      "must contain 1 to 3 MCP API scopes",
      options.connectionId,
    );
  }

  let audience: string | null = null;
  for (const [index, scope] of normalizedScopes.entries()) {
    const field = `auth.scopes[${index}]`;
    if (scope.length > 256) {
      pushDiag(
        diagnostics,
        field,
        "must be 256 characters or fewer",
        options.connectionId,
      );
      continue;
    }
    if (isGraphScope(scope)) {
      pushDiag(
        diagnostics,
        field,
        "must target the MCP API, not Microsoft Graph; Graph access is acquired server-side via OBO",
        options.connectionId,
      );
      continue;
    }
    if (!scopeLooksValid(scope)) {
      pushDiag(
        diagnostics,
        field,
        "must be an api://, https:// App ID URI, or GUID-form MCP API scope",
        options.connectionId,
      );
      continue;
    }
    const nextAudience = audienceFromScope(scope);
    if (!nextAudience) {
      pushDiag(
        diagnostics,
        field,
        "must include a resource audience",
        options.connectionId,
      );
      continue;
    }
    if (!audience) {
      audience = nextAudience;
    } else if (audience !== nextAudience) {
      pushDiag(
        diagnostics,
        field,
        "must target the same MCP API audience as the other scopes",
        options.connectionId,
      );
    }
  }

  const redirectUri = validateRedirectUri(
    input.redirectUri,
    diagnostics,
    options,
  );

  return {
    ...(tenantId ? { tenantId } : {}),
    ...(clientId ? { clientId } : {}),
    scopes: normalizedScopes,
    ...(redirectUri ? { redirectUri } : {}),
    diagnostics,
  };
}
