/**
 * Agent run state + `apply()` reducer.
 *
 * PR-4A. Per blueprint §4:
 *   - `apply()` is the SOLE mutator of {@link AgentRunState}.
 *   - `apply()` MUST NOT call provider.runTurn(...). The only async work
 *     permitted is `dispatcher.dispatch(...)` and synchronous `emit()`
 *     events (fire-and-forget) into a buffered sink.
 *   - At most one `apply()` call may be in flight per Agent instance; the
 *     orchestrator enforces this externally via the `isRunning` flag (see
 *     {@link Agent.prompt}).
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §4, §5, §8, §9.1
 *   - docs/agent-refactor-implementation-plan.md PR-4A step 3.1, 3.6, 3.7
 */

import {
  ENABLE_MCP_SERVER_TOOL_NAME,
  type MCPServerActivationProvider,
  validateEnableMcpServerArguments,
} from "../mcp/lazy-loading";
import {
  type Todo,
  UPDATE_TODOS_TOOL_NAME,
  todosAdvanceExecutableWork,
  validateUpdateTodos,
} from "../planner/todo-schema";
import { isConcreteExecutionCategory } from "../tool-metadata";
import type { AgentMessage, AssistantContentBlock, UsageInfo } from "../types";
import type { ToolCategory } from "../types";
import type { Action } from "./actions";
import type { NudgeReason } from "./nudges";
import { nudgeCeiling, nudgeText } from "./nudges";

export type RunStopReason =
  | "complete"
  | "max_turns"
  | "timeout"
  | "aborted"
  | "error";

export type RunStatus =
  | { kind: "init" }
  | { kind: "planning" }
  | { kind: "executing"; deliverableCount: number }
  | { kind: "verifying" }
  | { kind: "nudging"; reason: NudgeReason; attempt: number }
  | { kind: "done"; stopReason: RunStopReason };

export interface ExecutedTool {
  name: string;
  category: ToolCategory;
  toolCallId: string;
  ok: boolean;
  /** True when dispatcher short-circuited as TOOL_DEDUP_SUPPRESSED. */
  dedupSuppressed?: boolean;
}

export interface AgentRunFlags {
  plannerNudgesUsed: number;
  actionNudgeUsed: boolean;
  grantedFinalizationPass: boolean;
  /** True after the bookkeeping-only guard grants its one prose wrap-up turn. */
  bookkeepingFinalizationPass: boolean;
  /**
   * Concrete artifact work is required after the TODO-loop guard fires.
   * Cleared only after a successful concrete tool settles.
   */
  bookkeepingExecutionRequired: boolean;
  /**
   * A TODO item was established, reopened, or advanced after the most recent
   * successful concrete tool. Updated in model-emitted call order so a write
   * followed by selecting the next TODO cannot reuse the write as evidence.
   */
  todoWorkAdvancedSinceConcreteExecution: boolean;
  /** True after the first planner directive has been sent in this run. */
  plannerDirectiveInjected: boolean;
  /**
   * Set to `true` after the model successfully emits `update_todos` at
   * least once in the current run. This is not a lock: TODOs are the
   * live workflow UI, so later calls may update statuses/evidence as the
   * run moves forward through execution and quality check.
   */
  todosEstablishedByModel: boolean;
}

export interface AgentRunState {
  status: RunStatus;
  iteration: number; // 1-based once the first turn starts; 0 before
  maxIterations: number;
  startedAtMs: number;
  maxWallClockMs: number;
  /** `startedAtMs + maxWallClockMs`, cached for fast guards. */
  timeoutAtMs: number;
  nudgeAttempts: Partial<Record<NudgeReason, number>>;
  executedToolsThisRun: ExecutedTool[];
  /** Mirrors `executedToolsThisRun` outside planner mode (blueprint §5). */
  executedToolsThisStep: ExecutedTool[];
  ephemeralMessages: AgentMessage[];
  /**
   * Number of times the current ephemeral batch has already survived a
   * failed `provider.runTurn` (blueprint §8). The orchestrator drops the
   * batch after one failed resend to avoid indefinite retention.
   */
  ephemeralResendAttempts: number;
  lastUserText: string;
  /** True when this run is operating in planner-mode. */
  plannerMode: boolean;
  /**
   * Snapshot at run start: does the registered tool set contain any
   * `category: "deliverable"` tool? When `false`, the planner-mode
   * deliverable gate (decide.ts §rules 8/9) is bypassed because the
   * assistant's prose IS the deliverable for the run (research-only /
   * pure Q&A tasks).
   */
  hasDeliverableTools: boolean;
  flags: AgentRunFlags;
  /**
   * Current ordered TODO list (structured-todos blueprint §3). Replaced
   * atomically by the `update_todos` action — no in-place merging. Empty
   * when the run is non-planner or when the model has not yet emitted a
   * checklist. The orchestrator injects this as a per-turn context
   * message via `buildTodoContext`, replacing the legacy markdown
   * progress-file VFS round-trip.
   */
  todos: Todo[];
  /** Run-scoped MCP servers whose tool schemas are visible this run. */
  activeMcpServerIds: Set<string>;
  /** Last finalize result captured by `apply()` for the orchestrator. */
  finalize?: {
    blocks: AssistantContentBlock[];
    usage?: UsageInfo;
    stopReason: RunStopReason;
  };
}

export interface InitialStateInput {
  maxIterations: number;
  maxWallClockMs: number;
  startedAtMs: number;
  lastUserText: string;
  plannerMode: boolean;
  /**
   * Optional snapshot indicating whether the registered tool set
   * contains any `category: "deliverable"` tool. Defaults to `true` so
   * that callers (and existing tests) which omit the field preserve the
   * historical strict planner gate behavior. Set to `false` for
   * research-only runs (no deliverable-category tools registered) so
   * the planner gate is bypassed and the assistant's prose answer is
   * treated as the deliverable.
   */
  hasDeliverableTools?: boolean;
  /** MCP servers pinned as active for this run start. */
  activeMcpServerIds?: Iterable<string>;
}

export function createInitialState(input: InitialStateInput): AgentRunState {
  return {
    status: { kind: "init" },
    iteration: 0,
    maxIterations: input.maxIterations,
    startedAtMs: input.startedAtMs,
    maxWallClockMs: input.maxWallClockMs,
    timeoutAtMs: input.startedAtMs + input.maxWallClockMs,
    nudgeAttempts: {},
    executedToolsThisRun: [],
    executedToolsThisStep: [],
    ephemeralMessages: [],
    ephemeralResendAttempts: 0,
    lastUserText: input.lastUserText,
    plannerMode: input.plannerMode,
    hasDeliverableTools: input.hasDeliverableTools ?? true,
    flags: {
      plannerNudgesUsed: 0,
      actionNudgeUsed: false,
      grantedFinalizationPass: false,
      bookkeepingFinalizationPass: false,
      bookkeepingExecutionRequired: false,
      todoWorkAdvancedSinceConcreteExecution: false,
      plannerDirectiveInjected: false,
      todosEstablishedByModel: false,
    },
    todos: [],
    activeMcpServerIds: new Set(input.activeMcpServerIds ?? []),
  };
}

// ============ Telemetry events ============

export type EmitEvent =
  | {
      type: "rule_fired";
      rule: number;
      iteration: number;
      runId: string;
      nudgeReason?: NudgeReason;
      /**
       * `true` when the finalize carried orchestrator-authored synthetic
       * blocks (e.g. the bookkeeping-execution honest-stop) instead of the
       * model's own prose. Lets telemetry separate the two rule-10 finalizes
       * that otherwise look identical (both have `nudgeReason: undefined`).
       */
      synthetic?: boolean;
    }
  | {
      type: "tool_dispatched";
      iteration: number;
      runId: string;
      toolNames: string[];
    }
  | {
      type: "tool_settled";
      iteration: number;
      runId: string;
      results: ExecutedTool[];
    }
  | {
      type: "nudge_appended";
      iteration: number;
      runId: string;
      reason: NudgeReason;
      /**
       * 1-based attempt counter for this {@link NudgeReason} after the
       * reducer's increment. Surfaced so the orchestrator can render
       * `"reason (2/3)"` without re-reading {@link AgentRunState}.
       */
      attempt: number;
    }
  | {
      type: "nudge_dropped_for_budget";
      iteration: number;
      runId: string;
      reason?: NudgeReason;
    }
  | {
      type: "finalize";
      iteration: number;
      runId: string;
      stopReason: RunStopReason;
      deliverableGateSatisfied: boolean;
      executedToolCount: number;
    }
  | {
      type: "todos_updated";
      iteration: number;
      runId: string;
      toolCallId: string;
      todos: Todo[];
    }
  /**
   * Emitted by `apply(execute_tools)` for every `update_todos` call it
   * handles inline (success or invalid payload). The orchestrator listens for this
   * event and constructs the corresponding {@link ToolResultMessage}
   * so the tool-call protocol contract (every assistant tool_call →
   * exactly one tool message) stays intact without the FSM having to
   * touch `internalState.messages` directly.
   *
   * `resultText` is the JSON-stringified payload the model will see
   * in the next turn; `arguments` is forwarded verbatim so the UI's
   * tool-call inspector renders the original request.
   */
  | {
      type: "synthetic_tool_result";
      iteration: number;
      runId: string;
      toolCallId: string;
      name: string;
      arguments: Record<string, unknown>;
      resultText: string;
      isError: boolean;
      errorCode?: string;
    }
  /**
   * Emitted by `apply(execute_tools)` after a successful
   * inline `update_todos` mutation. The orchestrator fire-and-forgets
   * a VFS write of the typed audit trail (`.officeai-todos.json`) so
   * the reducer never awaits I/O. Failures are logged by the
   * orchestrator and never block the FSM.
   */
  | {
      type: "todos_persist_requested";
      iteration: number;
      runId: string;
      toolCallId: string;
      todos: Todo[];
    }
  /**
   * Emitted when `apply(execute_tools)` receives an
   * `update_todos` call whose arguments fail TypeBox validation.
   * The reducer does NOT mutate `state.todos`, synthesizes an error
   * `synthetic_tool_result`, and emits this event so the orchestrator
   * can log + track telemetry without owning validator details.
   */
  | {
      type: "update_todos_invalid";
      iteration: number;
      runId: string;
      toolCallId: string;
      errors: string[];
    };

export type Emit = (event: EmitEvent) => void;

// ============ apply() reducer ============

/**
 * Tool-dispatch callback. The orchestrator owns the real
 * {@link ToolDispatcher}; tests inject a fake. apply() awaits the
 * returned promise and appends results to the run state.
 */
export type ApplyDispatch = (
  calls: { id: string; name: string; arguments: Record<string, unknown> }[],
  signal: AbortSignal,
) => Promise<ExecutedTool[]>;

export interface ApplyContext {
  runId: string;
  dispatch: ApplyDispatch;
  signal: AbortSignal;
  emit: Emit;
  /** Wall-clock sample for status-transition timestamps. */
  nowMs: number;
  /** Optional MCP lazy-loading activation hook, supplied by the orchestrator. */
  mcpActivation?: MCPServerActivationProvider;
}

/**
 * Shared nudge-append reducer primitive.
 *
 * Builds the canonical "append a nudge" state transition — bump the
 * `nudgeAttempts` counter, set the `nudging` status, optionally push the
 * ephemeral retry message, and merge any reason-specific flags. Both
 * `apply("nudge_and_retry")` and the orchestrator's post-dispatch
 * bookkeeping guard route their nudge mutations through here so the counter
 * bookkeeping lives in exactly one place. Returns the new state plus the
 * resulting attempt number (== prior + 1) for telemetry.
 *
 * Callers own budget policy: this does NOT check the nudge ceiling. The
 * `apply("nudge_and_retry")` case enforces the ceiling (emitting
 * `nudge_dropped_for_budget`) before calling in; the guard only calls in on
 * branches it already proved are under-ceiling.
 */
export function appendNudge(
  state: AgentRunState,
  reason: NudgeReason,
  nowMs: number,
  options: {
    userText?: string;
    ephemeral?: boolean;
    extraFlags?: Partial<AgentRunFlags>;
  } = {},
): { state: AgentRunState; attempt: number } {
  const attempt = (state.nudgeAttempts[reason] ?? 0) + 1;
  const ephemeral = options.ephemeral ?? true;
  const userText = options.userText ?? nudgeText(reason);
  const next: AgentRunState = {
    ...state,
    status: { kind: "nudging", reason, attempt },
    nudgeAttempts: { ...state.nudgeAttempts, [reason]: attempt },
    ephemeralMessages: ephemeral
      ? [
          ...state.ephemeralMessages,
          { role: "user", content: userText, timestamp: nowMs },
        ]
      : state.ephemeralMessages,
    flags: { ...state.flags, ...(options.extraFlags ?? {}) },
  };
  return { state: next, attempt };
}

/**
 * apply(action, state, ctx) — the only function that mutates state.
 *
 * Re-entrancy: the orchestrator MUST guarantee at most one in-flight
 * apply() per Agent. apply() does not check this itself; double-entry
 * would corrupt `executedToolsThis*` and `nudgeAttempts`.
 */
export async function apply(
  action: Action,
  state: AgentRunState,
  ctx: ApplyContext,
): Promise<AgentRunState> {
  switch (action.type) {
    case "execute_tools": {
      const next: AgentRunState = {
        ...state,
        status: {
          kind: "executing",
          deliverableCount:
            state.status.kind === "executing"
              ? state.status.deliverableCount
              : 0,
        },
      };

      // Structured TODOs (blueprint §5): `update_todos` is handled
      // entirely inside this reducer — no orchestrator-side shim, no
      // dispatcher round-trip. For each `update_todos` call:
      //   1. Invalid TypeBox payload? Synthesize an `invalid_payload`
      //      result, emit `update_todos_invalid` for orchestrator
      //      logging, do NOT mutate.
      //   2. Otherwise: replace the live TODO state, emit
      //      `todos_updated` + `todos_persist_requested` + a
      //      `synthetic_tool_result` success.
      //
      // Every branch emits exactly one `synthetic_tool_result` so the
      // orchestrator can push one `ToolResultMessage` per call and the
      // assistant tool-call → tool-result contract stays intact. The
      // dispatcher still handles every NON-`update_todos` call as
      // before; results from both paths are merged back in the
      // original `action.calls` order to preserve indexing for
      // downstream telemetry consumers.
      type Slot =
        | {
            kind: "inline";
            result: ExecutedTool;
            advancesTodoWork?: boolean;
          }
        | { kind: "dispatch"; index: number };
      const slots: Slot[] = [];
      const dispatchable: typeof action.calls = [];
      let mutatedTodos = next.todos;
      let mutatedFlags = next.flags;
      let mutatedActiveMcpServerIds = next.activeMcpServerIds;

      for (const call of action.calls) {
        if (call.name === ENABLE_MCP_SERVER_TOOL_NAME) {
          const validated = validateEnableMcpServerArguments(call.arguments);
          if (!validated.ok) {
            const invalid = validated as { ok: false; errors: string[] };
            const invalidPayload = {
              ok: false,
              error: {
                code: "INVALID_PAYLOAD",
                message:
                  "enable_mcp_server requires a non-empty string server_id argument.",
                retryable: false,
              },
              errors: invalid.errors,
            };
            ctx.emit({
              type: "synthetic_tool_result",
              iteration: state.iteration,
              runId: ctx.runId,
              toolCallId: call.id,
              name: call.name,
              arguments: call.arguments,
              resultText: JSON.stringify(invalidPayload),
              isError: true,
              errorCode: "INVALID_PAYLOAD",
            });
            slots.push({
              kind: "inline",
              result: {
                name: call.name,
                category: "bookkeeping",
                toolCallId: call.id,
                ok: false,
              },
            });
            continue;
          }

          const activation = ctx.mcpActivation?.activateServer(
            validated.serverId,
            mutatedActiveMcpServerIds,
          ) ?? {
            ok: false as const,
            errorCode: "MCP_CONNECTION_UNAVAILABLE" as const,
            payload: {
              ok: false as const,
              error: {
                code: "MCP_CONNECTION_UNAVAILABLE" as const,
                message: "MCP lazy loading is not available for this run.",
                server_id: validated.serverId,
                retryable: false,
              },
            },
          };

          if (activation.ok && !activation.payload.already_active) {
            mutatedActiveMcpServerIds = new Set(mutatedActiveMcpServerIds);
            mutatedActiveMcpServerIds.add(validated.serverId);
          }
          const activationErrorCode =
            "errorCode" in activation ? activation.errorCode : undefined;

          ctx.emit({
            type: "synthetic_tool_result",
            iteration: state.iteration,
            runId: ctx.runId,
            toolCallId: call.id,
            name: call.name,
            arguments: call.arguments,
            resultText: JSON.stringify(activation.payload),
            isError: !activation.ok,
            errorCode: activationErrorCode,
          });
          slots.push({
            kind: "inline",
            result: {
              name: call.name,
              category: "bookkeeping",
              toolCallId: call.id,
              ok: activation.ok,
            },
          });
          continue;
        }

        if (call.name !== UPDATE_TODOS_TOOL_NAME) {
          slots.push({ kind: "dispatch", index: dispatchable.length });
          dispatchable.push(call);
          continue;
        }

        const validated = validateUpdateTodos(call.arguments);
        if (!validated.ok) {
          const { errors } = validated as { ok: false; errors: string[] };
          ctx.emit({
            type: "update_todos_invalid",
            iteration: state.iteration,
            runId: ctx.runId,
            toolCallId: call.id,
            errors,
          });
          const invalidPayload = {
            ok: false,
            error: "invalid_payload",
            message:
              "update_todos arguments failed schema validation. Each item must include a stable non-empty `id`, `content`, `activeForm`, and `status`.",
            errors,
          };
          ctx.emit({
            type: "synthetic_tool_result",
            iteration: state.iteration,
            runId: ctx.runId,
            toolCallId: call.id,
            name: call.name,
            arguments: call.arguments,
            resultText: JSON.stringify(invalidPayload),
            isError: true,
            errorCode: "INVALID_PAYLOAD",
          });
          slots.push({
            kind: "inline",
            result: {
              name: call.name,
              category: "bookkeeping",
              toolCallId: call.id,
              ok: false,
            },
          });
          continue;
        }

        const advancesTodoWork = todosAdvanceExecutableWork(
          mutatedTodos,
          validated.value.todos,
        );
        mutatedTodos = validated.value.todos;
        mutatedFlags = { ...mutatedFlags, todosEstablishedByModel: true };
        ctx.emit({
          type: "todos_updated",
          iteration: state.iteration,
          runId: ctx.runId,
          toolCallId: call.id,
          todos: mutatedTodos,
        });
        ctx.emit({
          type: "todos_persist_requested",
          iteration: state.iteration,
          runId: ctx.runId,
          toolCallId: call.id,
          todos: mutatedTodos,
        });
        const successPayload = {
          ok: true,
          message: `Updated ${mutatedTodos.length} todo(s). Continue with deliverable, read, or verification tools now; do not call update_todos again until real work changes statuses or evidence.`,
          count: mutatedTodos.length,
        };
        ctx.emit({
          type: "synthetic_tool_result",
          iteration: state.iteration,
          runId: ctx.runId,
          toolCallId: call.id,
          name: call.name,
          arguments: call.arguments,
          resultText: JSON.stringify(successPayload),
          isError: false,
        });
        slots.push({
          kind: "inline",
          result: {
            name: call.name,
            category: "bookkeeping",
            toolCallId: call.id,
            ok: true,
          },
          advancesTodoWork,
        });
      }

      // tool_dispatched advertises the FULL call list (including
      // inline-handled `update_todos`) so UI listeners see the same
      // toolNames the model emitted. Dispatcher only runs the
      // dispatchable subset.
      ctx.emit({
        type: "tool_dispatched",
        iteration: state.iteration,
        runId: ctx.runId,
        toolNames: action.calls.map((c) => c.name),
      });

      const dispatchResults =
        dispatchable.length > 0
          ? await ctx.dispatch(dispatchable, ctx.signal)
          : [];

      // Merge inline + dispatch results back into the original call
      // ordering so `executedToolsThisRun` preserves submission order.
      const results: ExecutedTool[] = slots.map((slot) =>
        slot.kind === "inline" ? slot.result : dispatchResults[slot.index],
      );

      let todoWorkAdvancedSinceConcreteExecution =
        mutatedFlags.todoWorkAdvancedSinceConcreteExecution;
      for (let index = 0; index < results.length; index++) {
        const slot = slots[index];
        if (slot.kind === "inline" && slot.advancesTodoWork) {
          todoWorkAdvancedSinceConcreteExecution = true;
        }
        const result = results[index];
        if (
          result.ok &&
          !result.dedupSuppressed &&
          isConcreteExecutionCategory(result.category)
        ) {
          todoWorkAdvancedSinceConcreteExecution = false;
        }
      }
      mutatedFlags = {
        ...mutatedFlags,
        todoWorkAdvancedSinceConcreteExecution,
      };

      next.todos = mutatedTodos;
      next.flags = mutatedFlags;
      next.activeMcpServerIds = mutatedActiveMcpServerIds;

      ctx.emit({
        type: "tool_settled",
        iteration: state.iteration,
        runId: ctx.runId,
        results,
      });

      // Append all settled executions to run-scope history. In planner mode,
      // dedup-suppressed calls MUST NOT count as fresh step work.
      const settled = results;
      const stepEligible = state.plannerMode
        ? settled.filter((r) => !r.dedupSuppressed)
        : settled;
      const newRun = [...state.executedToolsThisRun, ...settled];
      const newStep = [...state.executedToolsThisStep, ...stepEligible];
      next.executedToolsThisRun = newRun;
      next.executedToolsThisStep = newStep;

      // Update deliverableCount for status visibility (blueprint §4).
      const deliverableHits = stepEligible.filter(
        (r) => r.ok && r.category === "deliverable",
      ).length;
      next.status = {
        kind: "executing",
        deliverableCount:
          (state.status.kind === "executing"
            ? state.status.deliverableCount
            : 0) + deliverableHits,
      };

      return next;
    }

    case "nudge_and_retry": {
      const reason = action.reason;
      const prior = state.nudgeAttempts[reason] ?? 0;
      const ceiling = nudgeCeiling(reason);

      // Defensive: decide() is responsible for ceiling enforcement, but if
      // a caller emits an over-ceiling nudge we drop it and emit telemetry
      // rather than corrupting state.
      if (prior >= ceiling) {
        ctx.emit({
          type: "nudge_dropped_for_budget",
          iteration: state.iteration,
          runId: ctx.runId,
          reason,
        });
        return state;
      }

      const extraFlags: Partial<AgentRunFlags> = {};
      if (reason === "action_without_tools") {
        extraFlags.actionNudgeUsed = true;
      }
      if (reason === "planner_no_deliverable") {
        extraFlags.plannerNudgesUsed = state.flags.plannerNudgesUsed + 1;
      }
      if (reason === "final_finalization_pass") {
        extraFlags.grantedFinalizationPass = true;
      }

      const { state: next, attempt } = appendNudge(state, reason, ctx.nowMs, {
        userText: action.userText,
        ephemeral: action.ephemeral,
        extraFlags,
      });

      ctx.emit({
        type: "nudge_appended",
        iteration: state.iteration,
        runId: ctx.runId,
        reason,
        attempt,
      });

      return next;
    }

    case "finalize": {
      const deliverableScope = state.plannerMode
        ? state.executedToolsThisStep
        : state.executedToolsThisRun;
      const deliverableGateSatisfied = deliverableScope.some(
        (t) => t.ok && t.category === "deliverable",
      );
      ctx.emit({
        type: "finalize",
        iteration: state.iteration,
        runId: ctx.runId,
        stopReason: action.stopReason,
        deliverableGateSatisfied,
        executedToolCount: state.executedToolsThisRun.length,
      });
      return {
        ...state,
        status: { kind: "done", stopReason: action.stopReason },
        finalize: {
          blocks: action.blocks,
          usage: action.usage,
          stopReason: action.stopReason,
        },
      };
    }

    case "abort": {
      ctx.emit({
        type: "finalize",
        iteration: state.iteration,
        runId: ctx.runId,
        stopReason: "aborted",
        deliverableGateSatisfied: false,
        executedToolCount: state.executedToolsThisRun.length,
      });
      return {
        ...state,
        status: { kind: "done", stopReason: "aborted" },
      };
    }
  }
}

// ============ Planner-mode fallback reset (blueprint §9.1) ============

/**
 * Reset planner-scoped state when the planner phase aborts mid-run and
 * execution falls back to non-planner mode.
 *
 * Per blueprint §9.1:
 *   - Clear `executedToolsThisStep` (so rule 9 starts fresh).
 *   - Clear `flags.plannerDirectiveInjected`; reset `plannerNudgesUsed` to 0.
 *   - Preserve `executedToolsThisRun` (run-scope history is still valid).
 *   - Preserve non-planner `nudgeAttempts`; only `planner_no_deliverable`
 *     and `plan_schema_invalid` counters are reset.
 */
export function resetForPlannerFallback(state: AgentRunState): AgentRunState {
  const { planner_no_deliverable, plan_schema_invalid, ...keep } =
    state.nudgeAttempts;
  void planner_no_deliverable;
  void plan_schema_invalid;
  return {
    ...state,
    plannerMode: false,
    executedToolsThisStep: [],
    nudgeAttempts: keep,
    flags: {
      ...state.flags,
      bookkeepingExecutionRequired: false,
      todoWorkAdvancedSinceConcreteExecution: false,
      plannerDirectiveInjected: false,
      plannerNudgesUsed: 0,
    },
  };
}

/**
 * Advance to the next planner step: reset `executedToolsThisStep` only.
 * `executedToolsThisRun` and `nudgeAttempts` are preserved so run-scope
 * counters keep accumulating across steps.
 */
export function advancePlannerStep(state: AgentRunState): AgentRunState {
  return {
    ...state,
    executedToolsThisStep: [],
  };
}
