import { gzipSync, strToU8, zipSync } from "fflate";
import { parseCsv } from "../csv";

const DEFAULT_MAX_ROWS = 100_000;
const DEFAULT_MAX_COLUMNS = 100;
const DEFAULT_MAX_COMPRESSED_BYTES = 10 * 1024 * 1024;
const BASE64_CHUNK_SIZE = 8_192;

export type PowerBiColumnType =
  | "boolean"
  | "dateTime"
  | "double"
  | "int64"
  | "string";

export interface PowerBiColumn {
  name: string;
  type: PowerBiColumnType;
}

export interface BuildPowerBiPackageOptions {
  csv?: string;
  projectName: string;
  tableName?: string;
  tables?: PowerBiTableInput[];
  maxRows?: number;
  maxColumns?: number;
  maxCompressedBytes?: number;
}

export interface PowerBiTableInput {
  csv: string;
  tableName: string;
}

export interface PowerBiPackageTable {
  columnCount: number;
  columns: PowerBiColumn[];
  rowCount: number;
  tableName: string;
}

export interface PowerBiPackage {
  bytes: Uint8Array;
  columnCount: number;
  columns: PowerBiColumn[];
  fileName: string;
  projectName: string;
  rowCount: number;
  tableName: string;
  tables: PowerBiPackageTable[];
  template: PowerBiTemplate;
}

export type PowerBiTemplate =
  | "category-summary"
  | "table-summary"
  | "time-series";

function normalizeLimit(value: number | undefined, fallback: number): number {
  if (value === undefined) return fallback;
  if (!Number.isInteger(value) || value < 1) {
    throw new Error("Power BI package limits must be positive integers");
  }
  return value;
}

function sanitizeProjectName(value: string): string {
  const sanitized = value
    .replace(/[<>:"/\\|?*\u0000-\u001f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[. ]+$/g, "")
    .slice(0, 80);
  if (!sanitized) {
    throw new Error("projectName must contain a valid file name character");
  }
  return sanitized;
}

function sanitizeTableName(value: string): string {
  const sanitized = value
    .replace(/[\r\n\t]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return sanitized.slice(0, 100) || "Data";
}

function normalizeTableInputs(options: BuildPowerBiPackageOptions) {
  if (options.tables && options.tables.length > 0) {
    if (options.csv !== undefined) {
      throw new Error("Provide either csv or tables, not both");
    }
    return options.tables;
  }
  if (options.csv === undefined) {
    throw new Error("Provide csv or at least one table");
  }
  return [{ csv: options.csv, tableName: options.tableName ?? "Data" }];
}

function uniqueTableNames(inputs: PowerBiTableInput[]): PowerBiTableInput[] {
  const used = new Set<string>();
  return inputs.map((input) => {
    const base = sanitizeTableName(input.tableName);
    let tableName = base;
    let suffix = 2;
    while (used.has(tableName.toLocaleLowerCase())) {
      tableName = `${base}_${suffix}`;
      suffix += 1;
    }
    used.add(tableName.toLocaleLowerCase());
    return { ...input, tableName };
  });
}

function normalizeHeaders(headers: string[]): string[] {
  const used = new Set<string>();
  return headers.map((header, index) => {
    const base =
      header
        .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
        .replace(/\s+/g, " ")
        .trim() || `Column ${index + 1}`;
    let candidate = base;
    let suffix = 2;
    while (used.has(candidate.toLocaleLowerCase())) {
      candidate = `${base}_${suffix}`;
      suffix += 1;
    }
    used.add(candidate.toLocaleLowerCase());
    return candidate;
  });
}

function encodeCsvCell(value: string): string {
  if (!/[",\r\n]/.test(value)) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

function normalizeCsv(csv: string, maxRows: number, maxColumns: number) {
  const rows = parseCsv(csv);
  if (rows.length === 0 || rows[0].length === 0) {
    throw new Error("The selected Excel range does not contain a header row");
  }

  const headers = normalizeHeaders(rows[0]);
  if (headers.length > maxColumns) {
    throw new Error(
      `The selected range has ${headers.length} columns; the Power BI package limit is ${maxColumns}`,
    );
  }

  const dataRows = rows.slice(1);
  if (dataRows.length > maxRows) {
    throw new Error(
      `The selected range has ${dataRows.length} data rows; the Power BI package limit is ${maxRows}`,
    );
  }

  for (const row of dataRows) {
    if (row.length > headers.length) {
      throw new Error(
        "The selected range contains a row with more values than the header row",
      );
    }
    while (row.length < headers.length) row.push("");
  }

  const normalizedRows = [headers, ...dataRows];
  return {
    csv: normalizedRows
      .map((row) => row.map(encodeCsvCell).join(","))
      .join("\r\n"),
    dataRows,
    headers,
  };
}

function hasLeadingZero(value: string): boolean {
  const unsigned = value.replace(/^[+-]/, "");
  return unsigned.length > 1 && unsigned.startsWith("0");
}

function inferColumnType(values: string[]): PowerBiColumnType {
  const populated = values.map((value) => value.trim()).filter(Boolean);
  if (populated.length === 0) return "string";
  if (populated.every((value) => /^(true|false)$/i.test(value))) {
    return "boolean";
  }
  if (
    populated.every(
      (value) => /^[+-]?\d+$/.test(value) && !hasLeadingZero(value),
    )
  ) {
    return "int64";
  }
  if (
    populated.every(
      (value) =>
        /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test(value) &&
        !(/^[+-]?\d+$/.test(value) && hasLeadingZero(value)),
    )
  ) {
    return "double";
  }
  if (
    populated.every(
      (value) =>
        /^\d{4}-\d{2}-\d{2}(?:[T ][0-2]\d:[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/.test(
          value,
        ) && !Number.isNaN(Date.parse(value)),
    )
  ) {
    return "dateTime";
  }
  return "string";
}

function inferColumns(headers: string[], rows: string[][]): PowerBiColumn[] {
  return headers.map((name, columnIndex) => ({
    name,
    type: inferColumnType(rows.map((row) => row[columnIndex] ?? "")),
  }));
}

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  const blockSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += blockSize) {
    binary += String.fromCharCode(
      ...bytes.subarray(offset, offset + blockSize),
    );
  }
  return btoa(binary);
}

function splitText(value: string, chunkSize: number): string[] {
  const chunks: string[] = [];
  for (let offset = 0; offset < value.length; offset += chunkSize) {
    chunks.push(value.slice(offset, offset + chunkSize));
  }
  return chunks;
}

function quoteTmdlIdentifier(value: string): string {
  return `'${value.replace(/'/g, "''")}'`;
}

function quoteTmdlText(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

function mType(type: PowerBiColumnType): string {
  switch (type) {
    case "boolean":
      return "type logical";
    case "dateTime":
      return "type datetime";
    case "double":
      return "type number";
    case "int64":
      return "Int64.Type";
    default:
      return "type text";
  }
}

function buildTableTmdl(
  tableName: string,
  columns: PowerBiColumn[],
  compressedBase64: string,
  includeRowCountMeasure: boolean,
): string {
  const table = quoteTmdlIdentifier(tableName);
  const measureDefinition = includeRowCountMeasure
    ? [
        `\tmeasure 'Row Count' = COUNTROWS(${table})`,
        "\t\tformatString: #,0",
        "",
      ]
    : [];
  const columnDefinitions = columns
    .map((column) =>
      [
        `\tcolumn ${quoteTmdlIdentifier(column.name)}`,
        `\t\tdataType: ${column.type}`,
        "\t\tsummarizeBy: none",
        `\t\tsourceColumn: ${quoteTmdlText(column.name)}`,
      ].join("\r\n"),
    )
    .join("\r\n\r\n");
  const encodedChunks = splitText(compressedBase64, BASE64_CHUNK_SIZE)
    .map((chunk) => `\t\t\t\t${quoteTmdlText(chunk)}`)
    .join(",\r\n");
  const transformations = columns
    .map((column) => `{${quoteTmdlText(column.name)}, ${mType(column.type)}}`)
    .join(", ");

  return [
    `table ${table}`,
    "",
    columnDefinitions,
    "",
    ...measureDefinition,
    `\tpartition ${table} = m`,
    "\t\tmode: import",
    "\t\tsource =",
    "\t\t\tlet",
    "\t\t\t\tEmbeddedBase64 = Text.Combine({",
    encodedChunks,
    "\t\t\t\t}),",
    "\t\t\t\tCompressed = Binary.FromText(EmbeddedBase64, BinaryEncoding.Base64),",
    "\t\t\t\tContent = Binary.Decompress(Compressed, Compression.GZip),",
    '\t\t\t\tRows = Csv.Document(Content, [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),',
    "\t\t\t\tPromotedHeaders = Table.PromoteHeaders(Rows, [PromoteAllScalars = true]),",
    `\t\t\t\tTyped = Table.TransformColumnTypes(PromotedHeaders, {${transformations}}, \"en-US\")`,
    "\t\t\tin",
    "\t\t\t\tTyped",
    "",
  ].join("\r\n");
}

function jsonFile(value: unknown): Uint8Array {
  return strToU8(
    `${JSON.stringify(value, null, 2).replace(/\n/g, "\r\n")}\r\n`,
  );
}

function textFile(value: string): Uint8Array {
  return strToU8(value);
}

function stableLogicalId(value: string): string {
  const seeds = [0x811c9dc5, 0x9e3779b9, 0x85ebca6b, 0xc2b2ae35];
  const hex = seeds
    .map((seed) => {
      let hash = seed;
      for (let index = 0; index < value.length; index++) {
        hash = Math.imul(hash ^ value.charCodeAt(index), 0x01000193);
      }
      return (hash >>> 0).toString(16).padStart(8, "0");
    })
    .join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function sourceRef(tableName: string) {
  return { SourceRef: { Entity: tableName } };
}

function columnExpression(tableName: string, columnName: string) {
  return {
    Column: {
      Expression: sourceRef(tableName),
      Property: columnName,
    },
  };
}

function measureExpression(tableName: string, measureName: string) {
  return {
    Measure: {
      Expression: sourceRef(tableName),
      Property: measureName,
    },
  };
}

function sumExpression(tableName: string, columnName: string) {
  return {
    Aggregation: {
      Expression: columnExpression(tableName, columnName),
      Function: 0,
    },
  };
}

function projection(field: object, queryRef: string) {
  return { field, queryRef };
}

function visualContainer(
  name: string,
  visualType: string,
  position: {
    height: number;
    tabOrder: number;
    width: number;
    x: number;
    y: number;
    z: number;
  },
  queryState: Record<string, { projections: object[] }>,
) {
  return {
    $schema:
      "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/visualContainer/2.4.0/schema.json",
    name,
    position,
    visual: {
      visualType,
      query: { queryState },
      objects: {},
      drillFilterOtherVisuals: true,
    },
  };
}

function selectTemplate(columns: PowerBiColumn[]): {
  category?: PowerBiColumn;
  template: PowerBiTemplate;
  value?: PowerBiColumn;
} {
  const value = columns.find(
    (column) => column.type === "double" || column.type === "int64",
  );
  const date = columns.find((column) => column.type === "dateTime");
  if (date && value) {
    return { category: date, template: "time-series", value };
  }
  const category = columns.find(
    (column) => column.type === "string" || column.type === "boolean",
  );
  if (category) {
    return { category, template: "category-summary", value };
  }
  return { template: "table-summary", value };
}

function buildVisualEntries(
  reportFolder: string,
  pageName: string,
  tableName: string,
  columns: PowerBiColumn[],
): { entries: Record<string, Uint8Array>; template: PowerBiTemplate } {
  const selection = selectTemplate(columns);
  const visualRoot = `${reportFolder}/definition/pages/${pageName}/visuals`;
  const entries: Record<string, Uint8Array> = {};
  const hasChart = Boolean(selection.category);

  entries[`${visualRoot}/KpiRowCount/visual.json`] = jsonFile(
    visualContainer(
      "KpiRowCount",
      "card",
      {
        x: 20,
        y: 20,
        z: 1000,
        height: 100,
        width: 230,
        tabOrder: 0,
      },
      {
        Values: {
          projections: [
            projection(
              measureExpression(tableName, "Row Count"),
              `${tableName}.Row Count`,
            ),
          ],
        },
      },
    ),
  );

  if (selection.category) {
    const category = selection.category;
    const valueProjection = selection.value
      ? projection(
          sumExpression(tableName, selection.value.name),
          `Sum(${tableName}.${selection.value.name})`,
        )
      : projection(
          measureExpression(tableName, "Row Count"),
          `${tableName}.Row Count`,
        );
    entries[`${visualRoot}/PrimaryChart/visual.json`] = jsonFile(
      visualContainer(
        "PrimaryChart",
        selection.template === "time-series"
          ? "lineChart"
          : "clusteredBarChart",
        {
          x: 20,
          y: 136,
          z: 1001,
          height: 300,
          width: 1240,
          tabOrder: 1,
        },
        {
          Category: {
            projections: [
              projection(
                columnExpression(tableName, category.name),
                `${tableName}.${category.name}`,
              ),
            ],
          },
          Y: { projections: [valueProjection] },
        },
      ),
    );
  }

  entries[`${visualRoot}/DetailTable/visual.json`] = jsonFile(
    visualContainer(
      "DetailTable",
      "pivotTable",
      {
        x: 20,
        y: hasChart ? 452 : 136,
        z: hasChart ? 1002 : 1001,
        height: hasChart ? 248 : 564,
        width: 1240,
        tabOrder: hasChart ? 2 : 1,
      },
      {
        Rows: {
          projections: columns
            .slice(0, 12)
            .map((column) =>
              projection(
                columnExpression(tableName, column.name),
                `${tableName}.${column.name}`,
              ),
            ),
        },
        Values: {
          projections: [
            projection(
              measureExpression(tableName, "Row Count"),
              `${tableName}.Row Count`,
            ),
          ],
        },
      },
    ),
  );

  return { entries, template: selection.template };
}

export function buildPowerBiPackage(
  options: BuildPowerBiPackageOptions,
): PowerBiPackage {
  const maxRows = normalizeLimit(options.maxRows, DEFAULT_MAX_ROWS);
  const maxColumns = normalizeLimit(options.maxColumns, DEFAULT_MAX_COLUMNS);
  const maxCompressedBytes = normalizeLimit(
    options.maxCompressedBytes,
    DEFAULT_MAX_COMPRESSED_BYTES,
  );
  const projectName = sanitizeProjectName(options.projectName);
  const tableInputs = uniqueTableNames(normalizeTableInputs(options));
  const tables = tableInputs.map((input) => {
    const normalized = normalizeCsv(input.csv, maxRows, maxColumns);
    const columns = inferColumns(normalized.headers, normalized.dataRows);
    const compressed = gzipSync(strToU8(normalized.csv), { level: 9 });
    return {
      columns,
      compressed,
      normalized,
      tableName: input.tableName,
    };
  });
  const compressedBytes = tables.reduce(
    (total, table) => total + table.compressed.byteLength,
    0,
  );
  if (compressedBytes > maxCompressedBytes) {
    throw new Error(
      `The embedded data is ${compressedBytes} compressed bytes; the Power BI package limit is ${maxCompressedBytes}`,
    );
  }
  const primaryTable =
    tables.find(
      (table) => selectTemplate(table.columns).template !== "table-summary",
    ) ?? tables[0];
  const { columns, tableName } = primaryTable;

  const root = projectName;
  const reportFolder = `${root}/${projectName}.Report`;
  const modelFolder = `${root}/${projectName}.SemanticModel`;
  const pageName = "Overview";
  const visualDefinition = buildVisualEntries(
    reportFolder,
    pageName,
    tableName,
    columns,
  );
  const tableEntries = Object.fromEntries(
    tables.map((table, index) => {
      const safeFileName = table.tableName.replace(/[\\/:*?"<>|]/g, "_");
      const fileName =
        tables.filter(
          (candidate) =>
            candidate.tableName.replace(/[\\/:*?"<>|]/g, "_") === safeFileName,
        ).length > 1
          ? `${String(index + 1).padStart(3, "0")}-${safeFileName}`
          : safeFileName;
      return [
        `${modelFolder}/definition/tables/${fileName}.tmdl`,
        textFile(
          buildTableTmdl(
            table.tableName,
            table.columns,
            toBase64(table.compressed),
            table === primaryTable,
          ),
        ),
      ];
    }),
  );
  const entries: Record<string, Uint8Array> = {
    [`${root}/${projectName}.pbip`]: jsonFile({
      version: "1.0",
      artifacts: [{ report: { path: `${projectName}.Report` } }],
      settings: { enableAutoRecovery: true },
    }),
    [`${reportFolder}/definition.pbir`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/report/definitionProperties/2.0.0/schema.json",
      version: "4.0",
      datasetReference: {
        byPath: { path: `../${projectName}.SemanticModel` },
      },
    }),
    [`${reportFolder}/.platform`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/gitIntegration/platformProperties/2.0.0/schema.json",
      metadata: { type: "Report", displayName: projectName },
      config: {
        version: "2.0",
        logicalId: stableLogicalId(`${projectName}:report`),
      },
    }),
    [`${reportFolder}/definition/version.json`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/versionMetadata/1.0.0/schema.json",
      version: "2.0.0",
    }),
    [`${reportFolder}/definition/report.json`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/report/3.0.0/schema.json",
      themeCollection: {},
      settings: {
        isPersistentUserStateDisabled: true,
        useStylableVisualContainerHeader: true,
        exportDataMode: "AllowSummarized",
        allowChangeFilterTypes: true,
        useEnhancedTooltips: true,
        defaultDrillFilterOtherVisuals: true,
      },
    }),
    [`${reportFolder}/definition/pages/pages.json`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/pagesMetadata/1.0.0/schema.json",
      pageOrder: [pageName],
      activePageName: pageName,
    }),
    [`${reportFolder}/definition/pages/${pageName}/page.json`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/page/2.0.0/schema.json",
      name: pageName,
      displayName: "Overview",
      displayOption: "FitToPage",
      height: 720,
      width: 1280,
    }),
    [`${modelFolder}/definition.pbism`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/item/semanticModel/definitionProperties/1.0.0/schema.json",
      version: "4.2",
      settings: {},
    }),
    [`${modelFolder}/.platform`]: jsonFile({
      $schema:
        "https://developer.microsoft.com/json-schemas/fabric/gitIntegration/platformProperties/2.0.0/schema.json",
      metadata: { type: "SemanticModel", displayName: projectName },
      config: {
        version: "2.0",
        logicalId: stableLogicalId(`${projectName}:semantic-model`),
      },
    }),
    [`${modelFolder}/definition/database.tmdl`]: textFile(
      `database ${quoteTmdlIdentifier(projectName)}\r\n\tcompatibilityLevel: 1600\r\n`,
    ),
    [`${modelFolder}/definition/model.tmdl`]: textFile(
      `model Model\r\n\tculture: en-US\r\n\tdefaultPowerBIDataSourceVersion: powerBI_V3\r\n\r\n${tables
        .map((table) => `ref table ${quoteTmdlIdentifier(table.tableName)}`)
        .join("\r\n")}\r\n`,
    ),
    [`${root}/README.md`]: textFile(
      `# ${projectName}\r\n\r\nThis Power BI Desktop project was generated from an Excel range by OfficeAI.\r\n\r\n${tables
        .map(
          (table) =>
            `- ${table.tableName}: ${table.normalized.dataRows.length} rows x ${table.columns.length} columns\r\n`,
        )
        .join(
          "",
        )}\r\nOpen ${projectName}.pbip in Power BI Desktop, select Refresh to load the embedded snapshot, then use File > Save as to create a PBIX file. If prompted, enable the Power BI Project (PBIP), enhanced report format (PBIR), and TMDL preview features under File > Options and settings > Options > Preview features.\r\n\r\n## Microsoft Learn\r\n\r\n- Power BI Desktop projects: https://learn.microsoft.com/power-bi/developer/projects/projects-overview\r\n- PBIR report definitions: https://learn.microsoft.com/power-bi/developer/projects/projects-report\r\n- Semantic model project files: https://learn.microsoft.com/power-bi/developer/projects/projects-dataset\r\n- TMDL: https://learn.microsoft.com/analysis-services/tmdl/tmdl-overview\r\n`,
    ),
    ...tableEntries,
    ...visualDefinition.entries,
  };

  const tableSummaries = tables.map((table) => ({
    columnCount: table.columns.length,
    columns: table.columns,
    rowCount: table.normalized.dataRows.length,
    tableName: table.tableName,
  }));

  return {
    bytes: zipSync(entries, { level: 9 }),
    columnCount: columns.length,
    columns,
    fileName: `${projectName}.pbip.zip`,
    projectName,
    rowCount: tableSummaries.reduce(
      (total, table) => total + table.rowCount,
      0,
    ),
    tableName,
    tables: tableSummaries,
    template: visualDefinition.template,
  };
}
