import { Type } from "@sinclair/typebox";
import { parseCsv } from "../csv";
import { resolveStagedTextContent } from "./staged-content";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

export const insertTableTool = defineTool({
  name: "insert_table",
  category: "deliverable",
  parallelSafe: false,
  maxRetries: 0,
  label: "Insert Table",
  description:
    "Insert a native Word table into the document. " +
    "Creates a properly formatted table with headers and rows. " +
    "Provide inline 'headers' + 'rows', OR stage a CSV in the virtual filesystem with write_file and pass its path as 'dataFromFile' (first row = headers) to avoid tool-call truncation for large tables. " +
    "Use this instead of insert_content for tables.",
  parameters: Type.Object({
    headers: Type.Optional(
      Type.Array(Type.String({ description: "Column header text" }), {
        description:
          "Column headers. Optional when 'dataFromFile' is provided.",
      }),
    ),
    rows: Type.Optional(
      Type.Array(
        Type.Array(Type.String({ description: "Cell text" }), {
          description: "Row data (array of cell values for each column)",
        }),
        {
          description:
            "Table rows data. Optional when 'dataFromFile' is provided.",
        },
      ),
    ),
    dataFromFile: Type.Optional(
      Type.String({
        description:
          "VFS path to a CSV file (first row = headers, remaining rows = data). Stage it first with write_file. Example: 'table.csv' or '/home/user/uploads/data.csv'.",
      }),
    ),
    location: Type.Union(
      [
        Type.Literal("end", { description: "Insert at end of document" }),
        Type.Literal("start", { description: "Insert at start of document" }),
        Type.Literal("selection", { description: "Replace current selection" }),
      ],
      { description: "Where to insert the table", default: "end" },
    ),
    style: Type.Optional(
      Type.Union(
        [
          Type.Literal("grid", { description: "Grid style (default)" }),
          Type.Literal("plain", { description: "Plain table" }),
          Type.Literal("list", { description: "List table style" }),
        ],
        { description: "Table style", default: "grid" },
      ),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're inserting (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      const tableData = await resolveTableData(params);
      if ("error" in tableData) {
        return toolError(tableData.error);
      }
      const { headers, rows } = tableData;

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          true,
          async () => {
            const body = context.document.body;
            const numRows = rows.length + 1;
            const numCols = headers.length;
            const values = [headers, ...rows];

            let table: Word.Table;
            if (params.location === "selection") {
              const selection = context.document.getSelection();
              const selectionTarget = selection as unknown as {
                insertTable(
                  rowCount: number,
                  columnCount: number,
                  insertLocation: Word.InsertLocation | string,
                  values?: string[][],
                ): Word.Table;
              };
              table = selectionTarget.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.replace,
                values,
              );
            } else if (params.location === "start") {
              table = body.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.start,
                values,
              );
            } else {
              table = body.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.end,
                values,
              );
            }

            context.trackedObjects.add(table);

            if (params.style) {
              switch (params.style) {
                case "plain":
                  table.style = "TableGrid";
                  break;
                case "list":
                  table.style = "TableList";
                  break;
                default:
                  break;
              }
            }

            table.load("rows,rowCount");
            await syncWordContext(context, signal);

            context.trackedObjects.remove(table);

            return {
              inserted: true,
              rows: rows.length,
              columns: headers.length,
              style: params.style ?? "default",
              location: params.location,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error inserting table";
      return toolError(message);
    }
  },
});

type ResolvedTableData =
  | { ok: true; headers: string[]; rows: string[][] }
  | { ok: false; error: string };

/**
 * Resolve table headers + rows from either inline params or a staged CSV file
 * (`dataFromFile`, first row = headers). Ragged CSV rows are normalized to the
 * header width so `getCell` never indexes out of range.
 */
async function resolveTableData(params: {
  headers?: string[];
  rows?: string[][];
  dataFromFile?: string;
}): Promise<ResolvedTableData> {
  const fromFile = params.dataFromFile?.trim();
  if (fromFile) {
    const staged = await resolveStagedTextContent({
      fromFile,
      fileFieldName: "dataFromFile",
    });
    if ("error" in staged) return { ok: false, error: staged.error };

    const parsed = parseCsv(staged.content);
    if (parsed.length === 0) {
      return {
        ok: false,
        error: `dataFromFile ${staged.sourcePath} contains no CSV rows.`,
      };
    }
    const [headerRow, ...dataRows] = parsed;
    if (headerRow.length === 0 || headerRow.every((cell) => !cell.trim())) {
      return {
        ok: false,
        error: `dataFromFile ${staged.sourcePath} has an empty header row.`,
      };
    }
    const width = headerRow.length;
    for (let index = 0; index < dataRows.length; index++) {
      if (dataRows[index].length > width) {
        return {
          ok: false,
          error: `CSV row ${index + 2} has ${dataRows[index].length} columns but the header has ${width}; refusing to discard extra cells.`,
        };
      }
    }
    const rows = dataRows.map((row) => {
      const normalized = [...row];
      while (normalized.length < width) normalized.push("");
      return normalized;
    });
    return { ok: true, headers: headerRow, rows };
  }

  const headers = params.headers ?? [];
  const rows = params.rows ?? [];
  if (headers.length === 0) {
    return {
      ok: false,
      error:
        "Provide 'headers' + 'rows', or 'dataFromFile' (a CSV staged with write_file).",
    };
  }
  for (const row of rows) {
    if (row.length !== headers.length) {
      return {
        ok: false,
        error: `Row length ${row.length} does not match header count ${headers.length}`,
      };
    }
  }
  return { ok: true, headers, rows };
}
