import type { ToolCallPart } from "../../../lib/message-utils";

export type { ToolCallPart };

export interface TodoToolCall extends ToolCallPart {
  todoId: string;
}

/**
 * Derive a `todoId -> ToolCallPart[]` mapping from workflow tool events.
 * Chat transcript messages do not own tool calls; the TODO card does.
 */
export function groupToolCallsByTodo(
  toolCalls: readonly TodoToolCall[],
): Map<string, ToolCallPart[]> {
  const groups = new Map<string, ToolCallPart[]>();

  for (const call of toolCalls) {
    const list = groups.get(call.todoId);
    if (list) {
      list.push(call);
    } else {
      groups.set(call.todoId, [call]);
    }
  }

  return groups;
}
