import { Type } from "@sinclair/typebox";
import { appendFile, fileExists, writeFile } from "../vfs";
import { findInternalContentPlaceholder } from "./file-content-guard";
import { defineTool, toolError, toolSuccess } from "./types";

/**
 * write_file — deliverable VFS write.
 *
 * PR-1c (blueprint §4 / plan step 0.3): the original `write_file`
 * silently doubled as a bookkeeping tool when callers wrote to
 * progress/log/wiki paths. The orchestrator now categorizes tools
 * explicitly:
 *
 *   - `write_file` (this tool): `category: "deliverable"` for
 *     user-visible artifacts.
 *   - `update_todos`: structured bookkeeping for workflow progress.
 *
 * The `append` parameter lets the model chunk large deliverables across
 * several tool calls. This is the documented recovery path when a
 * single-shot `write_file` is cut off by `max_completion_tokens` (the
 * FSM's `length_truncated_tool_args` nudge points the model here).
 * Append always creates the file if missing, so the first chunk can use
 * `append: true` unconditionally.
 */
export const writeFileTool = defineTool({
  name: "write_file",
  category: "deliverable",
  parallelSafe: false,
  label: "Write File",
  description:
    "Write text content to a file in the virtual filesystem. Use this to CREATE new files, or to fully overwrite a file when the entire content is being regenerated. " +
    "BEFORE calling this with a large `content` payload, ask: is this content being derived from an uploaded file, a sheet, a CSV, or any structured data source? If yes, do NOT inline the result here — generate a short `js` script and redirect its output to the target path with bash, e.g. `js build-matches.mjs > /home/user/uploads/matches.json` (use `>>` to append). The shell redirection writes bytes straight to the VFS, completely avoiding `max_completion_tokens` truncation on the tool-call arguments. " +
    "To make a PARTIAL UPDATE to an existing file (changing a section, fixing a bug, adding a control), prefer `edit_file` (literal old_str -> new_str replacement) — re-emitting the whole file here is the leading cause of `max_completion_tokens` truncations on large HTML/code. " +
    "To CONTINUE an existing generated file, prefer `append_file` or this tool with `append: true`, and include only the missing suffix. " +
    "``path`` can be absolute (starting with /) or relative to /home/user/uploads/. " +
    "For LARGE files that may exceed the output-token budget in a single call (>~6 KB of HTML/code, >~25 rows of JSON/CSV records), split the content across multiple calls: write the first chunk with `append: false` (or omitted), then issue follow-up calls with `append: true` to extend the file. Append creates the file if it does not exist, so even the first chunk may use `append: true`. " +
    "For workflow progress bookkeeping, use update_todos instead of writing markdown progress files.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file in the virtual filesystem (e.g. 'script.js' or '/home/user/uploads/script.js').",
    }),
    content: Type.String({
      description: "Text content to write to the file.",
    }),
    overwrite: Type.Optional(
      Type.Boolean({
        description:
          "If false, the tool errors when the file already exists (no-op if the file is missing). Defaults to true. Ignored when `append` is true.",
        default: true,
      }),
    ),
    append: Type.Optional(
      Type.Boolean({
        description:
          "If true, append `content` to the existing file (creating it if missing) instead of overwriting. Use this to chunk large payloads across multiple tool calls when a single write would exceed the output-token limit. Defaults to false.",
        default: false,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    if ((params as { purpose?: unknown }).purpose === "progress") {
      return toolError(
        "write_file purpose='progress' is no longer supported. Use update_todos for workflow progress bookkeeping.",
      );
    }

    try {
      const placeholder = findInternalContentPlaceholder(params.content);
      if (placeholder) {
        return toolError(
          `Refusing to write ${params.path}: content includes an internal placeholder (${placeholder}). This placeholder is not file content; use read_file on the target path if existing content is needed, then write only real file bytes.`,
        );
      }

      if (params.append === true) {
        // Append wins over `overwrite: false` — appending never destroys
        // existing content, so the "don't clobber" guard is meaningless.
        // We document this on the parameter description.
        await appendFile(params.path, params.content);
        return toolSuccess(`Appended to ${params.path}`);
      }

      if (params.overwrite === false) {
        if (await fileExists(params.path)) {
          return toolError(
            `File already exists: ${params.path}. Pass overwrite: true to replace it, or append: true to extend it.`,
          );
        }
      }

      await writeFile(params.path, params.content);
      return toolSuccess(`Wrote ${params.path}`);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error writing file";
      return toolError(message);
    }
  },
});
