/**
 * MCP per-connection lifecycle FSM (PR-3B.3).
 *
 * Implements the state set + transitions documented in
 * docs/mcp-connection-contract.md §5.2:
 *   disabled | disconnected | connecting | connected | degraded
 *   | unauthorized | failed
 *
 * The FSM is intentionally pure: it accepts events, returns the new
 * state, and lets the lifecycle manager handle side effects (telemetry,
 * catalog publication, breaker resets, etc.). Illegal transitions are
 * dropped with `changed: false` so callers can detect no-op events
 * without throwing.
 */

import type { MCPConnectionState } from "./types";

export type MCPConnectionEventType =
  | "enable"
  | "disable"
  | "connect_start"
  | "handshake_success"
  | "handshake_unauthorized"
  | "handshake_failed"
  | "transient_failure"
  | "recovered"
  | "disconnect";

export interface MCPConnectionEvent {
  type: MCPConnectionEventType;
  message?: string;
}

export interface MCPConnectionStateRecord {
  id: string;
  state: MCPConnectionState;
  /** Latest human-readable reason for the current state, when applicable. */
  message?: string;
  /** Wall-clock ms when the connection entered the current state. */
  enteredAtMs: number;
  /** Number of connect attempts since last reset to disconnected. */
  attempts: number;
}

export interface MCPConnectionTransitionResult {
  previous: MCPConnectionState;
  next: MCPConnectionState;
  changed: boolean;
  record: MCPConnectionStateRecord;
}

/**
 * Build the initial state record for a connection. `enabled === false`
 * starts in `disabled`; all other connections start in `disconnected`.
 */
export function initialConnectionRecord(
  id: string,
  enabled: boolean,
  nowMs: number,
): MCPConnectionStateRecord {
  return {
    id,
    state: enabled ? "disconnected" : "disabled",
    enteredAtMs: nowMs,
    attempts: 0,
  };
}

const TERMINAL_STATES = new Set<MCPConnectionState>(["disabled", "failed"]);

export function isTerminalState(state: MCPConnectionState): boolean {
  return TERMINAL_STATES.has(state);
}

/**
 * Apply an event to a connection state record. Returns the same
 * record (with `changed: false`) when the event does not produce a
 * legal transition for the current state.
 *
 * Transition table (per docs/mcp-connection-contract.md §5.2):
 * - disabled         + enable                   -> disconnected
 * - disconnected     + connect_start            -> connecting
 * - connecting       + handshake_success        -> connected
 * - connecting       + handshake_unauthorized   -> unauthorized
 * - connecting       + handshake_failed         -> failed
 * - connected        + transient_failure        -> degraded
 * - degraded         + recovered                -> connected
 * - connected/degraded + disconnect             -> disconnected
 * - any non-terminal + disable                  -> disabled
 *
 * `unauthorized` only leaves on explicit user action (enable/disconnect
 * from settings UI) — there is no auto-retry path.
 */
export function applyConnectionEvent(
  record: MCPConnectionStateRecord,
  event: MCPConnectionEvent,
  nowMs: number,
): MCPConnectionTransitionResult {
  const { state } = record;
  const transition = (
    next: MCPConnectionState,
    overrides?: Partial<MCPConnectionStateRecord>,
  ): MCPConnectionTransitionResult => {
    const updated: MCPConnectionStateRecord = {
      id: record.id,
      state: next,
      message: event.message ?? overrides?.message,
      enteredAtMs: nowMs,
      attempts: overrides?.attempts ?? record.attempts,
    };
    return {
      previous: state,
      next,
      changed: state !== next,
      record: updated,
    };
  };

  const noChange = (): MCPConnectionTransitionResult => ({
    previous: state,
    next: state,
    changed: false,
    record,
  });

  if (event.type === "disable") {
    if (state === "disabled") return noChange();
    return transition("disabled", { attempts: 0 });
  }

  if (event.type === "enable") {
    if (state === "disabled" || state === "failed") {
      return transition("disconnected", { attempts: 0 });
    }
    return noChange();
  }

  if (event.type === "disconnect") {
    if (
      state === "connected" ||
      state === "degraded" ||
      state === "unauthorized" ||
      state === "connecting"
    ) {
      return transition("disconnected");
    }
    return noChange();
  }

  if (event.type === "connect_start") {
    if (state === "disconnected") {
      return transition("connecting", { attempts: record.attempts + 1 });
    }
    return noChange();
  }

  if (event.type === "handshake_success") {
    if (state === "connecting") return transition("connected", { attempts: 0 });
    return noChange();
  }

  if (event.type === "handshake_unauthorized") {
    if (
      state === "connecting" ||
      state === "connected" ||
      state === "degraded"
    ) {
      return transition("unauthorized");
    }
    return noChange();
  }

  if (event.type === "handshake_failed") {
    if (state === "connecting") return transition("failed");
    return noChange();
  }

  if (event.type === "transient_failure") {
    if (state === "connected") return transition("degraded");
    return noChange();
  }

  if (event.type === "recovered") {
    if (state === "degraded") return transition("connected");
    return noChange();
  }

  return noChange();
}
