function toolResultToText(result: unknown): string {
  if (typeof result === "string") return result;
  if (
    result &&
    typeof result === "object" &&
    "content" in result &&
    Array.isArray((result as { content?: unknown }).content)
  ) {
    return (result as { content: { type: string; text: string }[] }).content
      .filter((c) => c.type === "text")
      .map((c) => c.text)
      .join("\n");
  }
  return JSON.stringify(result, null, 2);
}

function upsertTodoToolCall(
  calls: TodoToolCall[],
  nextCall: TodoToolCall,
): TodoToolCall[] {
  const index = calls.findIndex((call) => call.id === nextCall.id);
  if (index === -1) return [...calls, nextCall];

  const next = [...calls];
  next[index] = { ...calls[index], ...nextCall };
  return next;
}

function updateTodoToolCall(
  calls: TodoToolCall[],
  id: string,
  update: (call: TodoToolCall) => TodoToolCall,
): TodoToolCall[] {
  const index = calls.findIndex((call) => call.id === id);
  if (index === -1) return calls;

  const next = [...calls];
  next[index] = update(calls[index]);
  return next;
}

function parseDirtyRanges(result: string | undefined): DirtyRange[] | null {
  if (!result) return null;
  try {
    const parsed = JSON.parse(result);
    if (parsed._dirtyRanges && Array.isArray(parsed._dirtyRanges)) {
      return parsed._dirtyRanges;
    }
  } catch {
    // Not valid JSON or no dirty ranges
  }
  return null;
}

