import { Button, Caption1, Textarea } from "@fluentui/react-components";
import { ShieldLockRegular } from "@fluentui/react-icons";
import { useEffect, useState } from "react";
import type { ToolApprovalDecision } from "../../../lib/agent";
import { useChat } from "./use-chat";

type DecisionMode = "approve" | "edit" | "reject";

export function ToolApprovalPanel() {
  const { state, resolveToolApprovals } = useChat();
  const requests = state.pendingApproval;
  const [modes, setModes] = useState<Record<string, DecisionMode>>({});
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!requests) {
      setModes({});
      setDrafts({});
      setError(null);
      return;
    }
    setModes(
      Object.fromEntries(
        requests.map((request) => [request.toolCallId, "approve"]),
      ),
    );
    setDrafts(
      Object.fromEntries(
        requests.map((request) => [
          request.toolCallId,
          JSON.stringify(request.arguments, null, 2),
        ]),
      ),
    );
    setError(null);
  }, [requests]);

  if (!requests || requests.length === 0) return null;

  const submit = () => {
    try {
      const decisions: ToolApprovalDecision[] = requests.map((request) => {
        const mode = modes[request.toolCallId] ?? "approve";
        if (mode === "edit") {
          const parsed = JSON.parse(
            drafts[request.toolCallId] ?? "{}",
          ) as unknown;
          if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
            throw new Error(
              `${request.label}: arguments must be a JSON object.`,
            );
          }
          return {
            toolCallId: request.toolCallId,
            type: "edit",
            arguments: parsed as Record<string, unknown>,
          };
        }
        if (mode === "reject") {
          return {
            toolCallId: request.toolCallId,
            type: "reject",
            message:
              "The user rejected this action. Do not retry it unless asked.",
          };
        }
        return { toolCallId: request.toolCallId, type: "approve" };
      });
      if (!resolveToolApprovals(decisions)) {
        setError("This approval request is no longer active.");
      }
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Invalid arguments.");
    }
  };

  const rejectAll = () => {
    resolveToolApprovals(
      requests.map((request) => ({
        toolCallId: request.toolCallId,
        type: "reject",
        message: "The user rejected this action. Do not retry it unless asked.",
      })),
    );
  };

  return (
    <section
      aria-label="Tool approval"
      style={{
        flexShrink: 0,
        borderBottom: "1px solid var(--chat-border)",
        padding: "10px 12px",
        background: "var(--chat-bg-secondary, #111)",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "6px",
          marginBottom: "8px",
          color: "var(--chat-text-primary)",
          fontWeight: 600,
        }}
      >
        <ShieldLockRegular aria-hidden="true" />
        Review sensitive action{requests.length === 1 ? "" : "s"}
      </div>
      {requests.map((request) => {
        const mode = modes[request.toolCallId] ?? "approve";
        return (
          <div
            key={request.toolCallId}
            style={{
              borderTop: "1px solid var(--chat-border)",
              padding: "8px 0",
            }}
          >
            <div style={{ fontSize: "12px", fontWeight: 600 }}>
              {request.label}
            </div>
            <Caption1 style={{ display: "block", margin: "2px 0 6px" }}>
              {request.reason}
            </Caption1>
            <pre
              aria-label={`Arguments for ${request.label}`}
              style={{
                maxHeight: "144px",
                overflow: "auto",
                margin: "0 0 6px",
                padding: "6px",
                border: "1px solid var(--chat-border)",
                background: "var(--chat-bg, #0a0a0a)",
                color: "var(--chat-text-secondary, #a0a0a0)",
                fontFamily: "var(--chat-font-mono)",
                fontSize: "11px",
                lineHeight: 1.4,
                whiteSpace: "pre-wrap",
                overflowWrap: "anywhere",
              }}
            >
              {JSON.stringify(request.arguments, null, 2)}
            </pre>
            <select
              aria-label={`Decision for ${request.label}`}
              value={mode}
              onChange={(event) =>
                setModes((current) => ({
                  ...current,
                  [request.toolCallId]: event.target.value as DecisionMode,
                }))
              }
              style={{
                width: "100%",
                minHeight: "28px",
                marginBottom: mode === "edit" ? "6px" : 0,
              }}
            >
              <option value="approve">Approve</option>
              <option value="edit">Edit arguments</option>
              <option value="reject">Reject</option>
            </select>
            {mode === "edit" ? (
              <Textarea
                aria-label={`Edited arguments for ${request.label}`}
                resize="vertical"
                value={drafts[request.toolCallId] ?? ""}
                onChange={(_event, data) =>
                  setDrafts((current) => ({
                    ...current,
                    [request.toolCallId]: data.value,
                  }))
                }
                style={{ width: "100%", fontFamily: "var(--chat-font-mono)" }}
              />
            ) : null}
          </div>
        );
      })}
      {error ? (
        <Caption1 style={{ color: "var(--chat-error, #dc2626)" }}>
          {error}
        </Caption1>
      ) : null}
      <div style={{ display: "flex", gap: "8px", marginTop: "8px" }}>
        <Button appearance="primary" size="small" onClick={submit}>
          Continue
        </Button>
        <Button appearance="secondary" size="small" onClick={rejectAll}>
          Reject all
        </Button>
      </div>
    </section>
  );
}
