/**
 * Stable workflow surface rendered between `<StatsBar>` and `<MessageList>`.
 *
 * TODO workflows use one consolidated card: the event-driven run phase is in
 * the header and model-authored steps/actions are in the body. The generic
 * action ledger is used only when a run has no structured TODOs.
 */
export function AgentStatusBar() {
  const { state } = useChat();
  const styles = useStyles();
  const todos = state.todos?.todos ?? [];
  const warning = state.loopWarning;
  const activity = state.agentActivity;
  const surface = selectAgentProgressSurface(todos.length, !!activity);

  const toolCallsByTodoId = useMemo(
    () => groupToolCallsByTodo(state.todoToolCalls),
    [state.todoToolCalls],
  );

  if (!activity && todos.length === 0 && !warning) return null;
  const runStatus = activity ? describeActivityPhase(activity) : undefined;

  return (
    <output
      aria-live="polite"
      aria-label="Workflow status"
      className={styles.surface}
    >
      {surface === "todo" ? (
        <TodoCard
          todos={todos}
          toolCallsByTodoId={toolCallsByTodoId}
          runStatus={runStatus}
        />
      ) : surface === "activity" && activity ? (
        <AgentActivity activity={activity} />
      ) : null}
      {warning ? <WorkflowWarning warning={warning} /> : null}
    </output>
  );
}

function AgentActivity({ activity }: { activity: ChatAgentActivity }) {
  const styles = useStyles();
  const [expanded, setExpanded] = useState(true);
  const isActive = activity.phase.kind !== "done";

  useEffect(() => {
    if (isActive) setExpanded(true);
  }, [isActive]);

  const phase = describeActivityPhase(activity);

  return (
    <div className={styles.activity}>
      <div className={styles.phaseRow}>
        <PhaseIcon activity={activity} />
        <span className={styles.phaseText}>{phase.label}</span>
        <span className={styles.phaseMeta}>{phase.meta}</span>
      </div>
      {activity.actions.length > 0 ? (
        <>
          <button
            type="button"
            className={styles.actionsToggle}
            onClick={() => setExpanded((current) => !current)}
            aria-expanded={expanded}
          >
            {expanded ? (
              <ChevronDownRegular fontSize={12} />
            ) : (
              <ChevronRightRegular fontSize={12} />
            )}
            {activity.actions.length} action
            {activity.actions.length === 1 ? "" : "s"}
          </button>
          {expanded ? (
            <ul className={styles.actionList}>
              {activity.actions.map((action) => (
                <ActionRow key={action.id} action={action} />
              ))}
            </ul>
          ) : null}
        </>
      ) : null}
    </div>
  );
}

function describeActivityPhase(activity: ChatAgentActivity): {
  label: string;
  meta: string;
} {
  const phase = activity.phase;
  const iteration =
    "iteration" in phase ? phase.iteration : activity.lastIteration;
  const meta = iteration > 0 ? `turn ${iteration}` : "";

  switch (phase.kind) {
    case "idle":
      return { label: "Ready", meta: "" };
    case "planning":
      return { label: "Planning the next step", meta };
    case "executing":
      return {
        label:
          phase.toolNames && phase.toolNames.length > 0
            ? `Running ${phase.toolNames.length} action${phase.toolNames.length === 1 ? "" : "s"}`
            : "Working through the request",
        meta,
      };
    case "quality_check":
      return { label: "Checking the result", meta };
    case "awaiting_approval":
      return { label: "Waiting for your review", meta };
    case "nudging":
      return {
        label: "Adjusting the approach",
        meta: `attempt ${phase.attempt}`,
      };
    case "done":
      switch (phase.stopReason) {
        case "complete":
          return { label: "Completed", meta: formatElapsed(activity) };
        case "aborted":
          return { label: "Stopped", meta: formatElapsed(activity) };
        case "error":
          return { label: "Failed", meta: formatElapsed(activity) };
        case "max_iterations":
          return {
            label: "Turn limit reached",
            meta: formatElapsed(activity),
          };
        case "timeout":
          return { label: "Timed out", meta: formatElapsed(activity) };
      }
  }
}

function PhaseIcon({ activity }: { activity: ChatAgentActivity }) {
  if (activity.phase.kind !== "done") {
    return activity.phase.kind === "awaiting_approval" ? (
      <ShieldLockRegular fontSize={14} />
    ) : (
      <Spinner size="tiny" />
    );
  }
  if (activity.phase.stopReason === "complete") {
    return (
      <CheckmarkCircleRegular
        fontSize={14}
        color="var(--chat-success, #16a34a)"
      />
    );
  }
  return (
    <DismissCircleRegular fontSize={14} color="var(--chat-error, #dc2626)" />
  );
}

function ActionRow({ action }: { action: ChatAgentAction }) {
  const styles = useStyles();
  return (
    <li className={styles.actionRow}>
      <ActionIcon action={action} />
      <span className={styles.actionName} title={action.name}>
        {humanizeToolName(action.name)}
      </span>
      <span className={styles.actionMeta}>
        {action.status === "running"
          ? (action.statusText ?? "running")
          : formatActionDuration(action)}
      </span>
    </li>
  );
}

function ActionIcon({ action }: { action: ChatAgentAction }) {
  switch (action.status) {
    case "running":
      return <Spinner size="tiny" />;
    case "complete":
      return (
        <CheckmarkCircleRegular
          fontSize={12}
          color="var(--chat-success, #16a34a)"
        />
      );
    case "error":
      return (
        <DismissCircleRegular
          fontSize={12}
          color="var(--chat-error, #dc2626)"
        />
      );
  }
}

function humanizeToolName(name: string): string {
  const known: Record<string, string> = {
    update_todos: "Update workflow",
    task: "Delegate read task",
    bash: "Run shell command",
    js: "Analyze with JavaScript",
    read: "Read file",
    eval_officejs: "Run Office operation",
  };
  if (known[name]) return known[name];
  const nameParts = name.split("__");
  const remoteName = name.startsWith("mcp__")
    ? (nameParts[nameParts.length - 1] ?? name)
    : name;
  return remoteName
    .replace(/[_-]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function formatActionDuration(action: ChatAgentAction): string {
  if (!action.completedAtMs) return action.status;
  return formatDuration(action.completedAtMs - action.startedAtMs);
}

function formatElapsed(activity: ChatAgentActivity): string {
  return formatDuration(activity.updatedAtMs - activity.startedAtMs);
}

function formatDuration(durationMs: number): string {
  if (durationMs < 1000) return `${Math.max(0, durationMs)} ms`;
  if (durationMs < 60_000) return `${(durationMs / 1000).toFixed(1)} s`;
  const minutes = Math.floor(durationMs / 60_000);
  const seconds = Math.round((durationMs % 60_000) / 1000);
  return `${minutes}m ${seconds}s`;
}

function WorkflowWarning({ warning }: { warning: ChatLoopWarning }) {
  return (
    <div
      title={`The same tool call has repeated ${warning.count} times in a row. Detected at ${new Date(warning.detectedAtMs).toLocaleTimeString()}.`}
      style={{
        display: "flex",
        alignItems: "center",
        gap: "6px",
        padding: "4px 0 8px",
        fontSize: "11px",
        fontFamily: "var(--chat-font-mono)",
        color: "var(--chat-error, #dc2626)",
      }}
    >
      <span aria-hidden="true">⚠</span>
      <span>possible loop: {warning.summary}</span>
    </div>
  );
}
