function LoadingIndicator() {
  const styles = useStyles();
  const [frameIndex, setFrameIndex] = useState(0);

  useEffect(() => {
    const intervalId = window.setInterval(() => {
      setFrameIndex((current) => (current + 1) % LOADING_FRAMES.length);
    }, 220);

    return () => window.clearInterval(intervalId);
  }, []);

  return (
    <output aria-live="polite" className={styles.loadingIndicator}>
      <span aria-hidden="true" className={styles.loadingCharacter}>
        {LOADING_FRAMES[frameIndex]}
      </span>
      <span>Thinking</span>
    </output>
  );
}

function parseCitationUri(
  href: string,
): { sheetId: number; range?: string } | null {
  if (!href.startsWith("#cite:")) return null;
  const path = href.slice("#cite:".length);
  const bangIdx = path.indexOf("!");
  if (bangIdx === -1) {
    const sheetId = Number.parseInt(path, 10);
    return Number.isNaN(sheetId) ? null : { sheetId };
  }
  const sheetId = Number.parseInt(path.slice(0, bangIdx), 10);
  const range = path.slice(bangIdx + 1);
  return Number.isNaN(sheetId) ? null : { sheetId, range };
}

function CitationLink({
  href,
  children,
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement>) {
  const citation = href ? parseCitationUri(href) : null;

  if (!citation) {
    return (
      <a href={href} target="_blank" rel="noopener noreferrer" {...props}>
        {children}
      </a>
    );
  }

  return (
    <Button
      appearance="transparent"
      onClick={() => {
        navigateTo(citation.sheetId, citation.range).catch((err) => {
          console.error("[Citation] Navigation failed:", err);
        });
      }}
      size="small"
      style={{ color: tokens.colorBrandForeground1, cursor: "pointer" }}
    >
      {children}
    </Button>
  );
}

function splitTableRow(line: string): string[] {
  const trimmed = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  return trimmed.split("|").map((cell) => cell.trim());
}

function stableKey(prefix: string, value: string): string {
  const normalized = value.replace(/\s+/g, " ").trim() || "empty";
  return `${prefix}-${normalized.slice(0, 80)}`;
}

function withStableKeys<T>(
  values: T[],
  prefix: string,
  getValue: (value: T) => string,
): { key: string; value: T }[] {
  const seen = new Map<string, number>();
  return values.map((value) => {
    const baseKey = stableKey(prefix, getValue(value));
    const count = seen.get(baseKey) ?? 0;
    seen.set(baseKey, count + 1);
    return {
      key: count === 0 ? baseKey : `${baseKey}-${count}`,
      value,
    };
  });
}

function isTableStart(lines: string[], index: number): boolean {
  return (
    index + 1 < lines.length &&
    lines[index].includes("|") &&
    TABLE_SEPARATOR_RE.test(lines[index + 1])
  );
}

function isSpecialBlockStart(lines: string[], index: number): boolean {
  const line = lines[index];
  return (
    line.startsWith("```") ||
    isTableStart(lines, index) ||
    LIST_ITEM_RE.test(line) ||
    /^#{1,6}\s+/.test(line) ||
    /^>\s?/.test(line) ||
    /^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)
  );
}

function renderInlineMarkdown(text: string, keyPrefix: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  const tokenRe = /(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g;
  let lastIndex = 0;
  let tokenIndex = 0;

  for (const match of text.matchAll(tokenRe)) {
    const value = match[0];
    const index = match.index ?? 0;
    if (index > lastIndex) {
      nodes.push(text.slice(lastIndex, index));
    }
    const key = `${keyPrefix}-inline-${tokenIndex++}`;
    if (value.startsWith("`")) {
      nodes.push(<code key={key}>{value.slice(1, -1)}</code>);
    } else if (value.startsWith("**")) {
      nodes.push(<strong key={key}>{value.slice(2, -2)}</strong>);
    } else {
      const linkMatch = /^\[([^\]]+)\]\(([^)]+)\)$/.exec(value);
      if (linkMatch) {
        nodes.push(
          <CitationLink key={key} href={linkMatch[2]}>
            {linkMatch[1]}
          </CitationLink>,
        );
      } else {
        nodes.push(value);
      }
    }
    lastIndex = index + value.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }
  return nodes;
}

function renderMarkdownBlocks(text: string): ReactNode[] {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const blocks: ReactNode[] = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];
    if (!line.trim()) {
      index++;
      continue;
    }

    if (line.startsWith("```")) {
      const language = line.slice(3).trim();
      const codeLines: string[] = [];
      index++;
      while (index < lines.length && !lines[index].startsWith("```")) {
        codeLines.push(lines[index]);
        index++;
      }
      if (index < lines.length) index++;
      blocks.push(
        <pre key={`code-${blocks.length}`}>
          <code data-language={language || undefined}>
            {codeLines.join("\n")}
          </code>
        </pre>,
      );
      continue;
    }

    if (isTableStart(lines, index)) {
      const headerCells = withStableKeys(
        splitTableRow(lines[index]),
        `table-${blocks.length}-head`,
        (cell) => cell,
      );
      index += 2;
      const bodyRows: string[][] = [];
      while (index < lines.length && lines[index].includes("|")) {
        bodyRows.push(splitTableRow(lines[index]));
        index++;
      }
      const keyedRows = withStableKeys(
        bodyRows,
        `table-${blocks.length}-row`,
        (row) => row.join("|"),
      );
      blocks.push(
        <table key={`table-${blocks.length}`}>
          <thead>
            <tr>
              {headerCells.map(({ key, value: cell }) => (
                <th key={key}>{renderInlineMarkdown(cell, key)}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {keyedRows.map(({ key: rowKey, value: row }) => (
              <tr key={rowKey}>
                {withStableKeys(row, `${rowKey}-cell`, (cell) => cell).map(
                  ({ key, value: cell }) => (
                    <td key={key}>{renderInlineMarkdown(cell, key)}</td>
                  ),
                )}
              </tr>
            ))}
          </tbody>
        </table>,
      );
      continue;
    }

    const headingMatch = /^(#{1,6})\s+(.+)$/.exec(line);
    if (headingMatch) {
      const level = headingMatch[1].length;
      blocks.push(
        createElement(
          `h${level}`,
          { key: `heading-${blocks.length}` },
          renderInlineMarkdown(headingMatch[2], `heading-${blocks.length}`),
        ),
      );
      index++;
      continue;
    }

    if (/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)) {
      blocks.push(<hr key={`hr-${blocks.length}`} />);
      index++;
      continue;
    }

    if (/^>\s?/.test(line)) {
      const quoteLines: string[] = [];
      while (index < lines.length && /^>\s?/.test(lines[index])) {
        quoteLines.push(lines[index].replace(/^>\s?/, ""));
        index++;
      }
      blocks.push(
        <blockquote key={`quote-${blocks.length}`}>
          {renderInlineMarkdown(quoteLines.join(" "), `quote-${blocks.length}`)}
        </blockquote>,
      );
      continue;
    }

    const listMatch = LIST_ITEM_RE.exec(line);
    if (listMatch) {
      const ordered = /^\s*\d+\./.test(line);
      const items: string[] = [];
      while (index < lines.length) {
        const currentLine = lines[index];
        const currentMatch = LIST_ITEM_RE.exec(currentLine);
        if (!currentMatch || /^\s*\d+\./.test(currentLine) !== ordered) break;
        items.push(currentMatch[1]);
        index++;
      }
      const listTag = ordered ? "ol" : "ul";
      const keyedItems = withStableKeys(
        items,
        `list-${blocks.length}-item`,
        (item) => item,
      );
      blocks.push(
        createElement(
          listTag,
          { key: `list-${blocks.length}` },
          keyedItems.map(({ key, value: item }) => {
            const checkboxMatch = /^\[( |x|X)\]\s+(.+)$/.exec(item);
            return (
              <li key={key}>
                {checkboxMatch ? (
                  <>
                    <input
                      checked={checkboxMatch[1].toLowerCase() === "x"}
                      disabled
                      readOnly
                      type="checkbox"
                    />{" "}
                    {renderInlineMarkdown(checkboxMatch[2], key)}
                  </>
                ) : (
                  renderInlineMarkdown(item, key)
                )}
              </li>
            );
          }),
        ),
      );
      continue;
    }

    const paragraphLines = [line.trim()];
    index++;
    while (
      index < lines.length &&
      lines[index].trim() &&
      !isSpecialBlockStart(lines, index)
    ) {
      paragraphLines.push(lines[index].trim());
      index++;
    }
    blocks.push(
      <p key={`paragraph-${blocks.length}`}>
        {renderInlineMarkdown(
          paragraphLines.join(" "),
          `paragraph-${blocks.length}`,
        )}
      </p>,
    );
  }

  return blocks.length > 0 ? blocks : [text];
}

function MarkdownContent({
  text,
  isAnimating,
}: {
  text: string;
  isAnimating?: boolean;
}) {
  return (
    <div className="markdown-content">
      {renderMarkdownBlocks(text)}
      {isAnimating && <span className="officeai-pulse">▊</span>}
    </div>
  );
}

function McpAppStub({ part }: { part: McpUiAppPart }) {
  const styles = useStyles();
  const label = part.ui.serverLabel
    ? `${part.ui.serverLabel} · ${part.toolName}`
    : part.toolName;
  return (
    <div
      className={styles.mcpAppStub}
      title="Live MCP App is pinned in the dock below"
    >
      <span>🪟</span>
      <span>MCP App update: {label}</span>
    </div>
  );
}

function renderParts(
  parts: TranscriptPart[],
  isStreaming: boolean,
  messageId: string,
) {
  const lastPart = parts[parts.length - 1];
  const isStreamingThinking = isStreaming && lastPart?.type === "thinking";
  const isStreamingText = isStreaming && lastPart?.type === "text";

  return parts.map((part, idx) => {
    const key = `${messageId}-${part.type}-${idx}`;
    const isLastPart = idx === parts.length - 1;
    if (part.type === "thinking") {
      return (
        <ThinkingBlock
          key={key}
          thinking={part.thinking}
          isStreaming={isStreamingThinking && isLastPart}
        />
      );
    }
    if (part.type === "mcpUiApp") {
      return <McpAppStub key={key} part={part} />;
    }
    return (
      <MarkdownContent
        key={key}
        text={part.text}
        isAnimating={isStreamingText && isLastPart}
      />
    );
  });
}

function UserBubble({ message }: { message: ChatMessage }) {
  const styles = useStyles();
  return (
    <div className={`${styles.userBubble} message-user`}>
      {renderParts(message.parts, false, message.id)}
    </div>
  );
}

function AssistantBubble({
  messages,
  isStreaming,
}: {
  messages: ChatMessage[];
  isStreaming: boolean;
}) {
  const styles = useStyles();
  const allParts: {
    part: TranscriptPart;
    messageId: string;
    isLast: boolean;
  }[] = [];
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    const isLastMessage = i === messages.length - 1;
    for (let j = 0; j < msg.parts.length; j++) {
      allParts.push({
        part: msg.parts[j],
        messageId: msg.id,
        isLast: isLastMessage && j === msg.parts.length - 1,
      });
    }
  }

  return (
    <div className={styles.assistantBubble}>
      {allParts.map(({ part, messageId, isLast }, idx) => {
        const key = `${messageId}-${part.type}-${idx}`;
        if (part.type === "thinking") {
          return (
            <ThinkingBlock
              key={key}
              thinking={part.thinking}
              isStreaming={isStreaming && isLast}
            />
          );
        }
        if (part.type === "mcpUiApp") {
          return <McpAppStub key={key} part={part} />;
        }
        return (
          <MarkdownContent
            key={key}
            text={part.text}
            isAnimating={isStreaming && isLast && part.type === "text"}
          />
        );
      })}
      {isStreaming && allParts.length === 0 && (
        <span className="officeai-pulse">▊</span>
      )}
    </div>
  );
}

type MessageGroup =
  | { type: "user"; message: ChatMessage }
  | { type: "assistant"; messages: ChatMessage[] };

function groupMessages(messages: ChatMessage[]): MessageGroup[] {
  const groups: MessageGroup[] = [];
  let currentAssistantGroup: ChatMessage[] = [];

  for (const msg of messages) {
    if (msg.role === "user") {
      if (currentAssistantGroup.length > 0) {
        groups.push({ type: "assistant", messages: currentAssistantGroup });
        currentAssistantGroup = [];
      }
      groups.push({ type: "user", message: msg });
    } else {
      currentAssistantGroup.push(msg);
    }
  }

  if (currentAssistantGroup.length > 0) {
    groups.push({ type: "assistant", messages: currentAssistantGroup });
  }

  return groups;
}

export function MessageList({
  onOpenSettings,
}: {
  onOpenSettings?: () => void;
}) {
  const { state } = useChat();
  const styles = useStyles();
  const containerRef = useRef<HTMLDivElement>(null);
  const shouldAutoScroll = useRef(true);

  const handleScroll = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    const { scrollTop, scrollHeight, clientHeight } = container;
    const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
    shouldAutoScroll.current = distanceFromBottom < 100;
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: intentional - trigger scroll on message/streaming changes
  useEffect(() => {
    if (!containerRef.current || !shouldAutoScroll.current) return;

    const scrollToBottom = () => {
      const container = containerRef.current;
      if (!container) return;
      container.scrollTo({
        top: container.scrollHeight,
        behavior: state.isStreaming ? "auto" : "smooth",
      });
    };

    // Use requestAnimationFrame for reliable scroll after DOM update
    requestAnimationFrame(() => {
      scrollToBottom();
      // Double-check scroll after a short delay for dynamic content
      setTimeout(scrollToBottom, 50);
    });
  }, [state.messages, state.isStreaming]);

  if (state.messages.length === 0) {
    return (
      <div className={styles.emptyState}>
        <div className={styles.emptyStateCard}>
          <Caption2
            style={{
              color: tokens.colorNeutralForeground3,
              textTransform: "uppercase",
              letterSpacing: "0.1em",
            }}
          >
            OfficeAI
          </Caption2>
          <div className={styles.emptyStateTitle}>
            {state.providerConfig
              ? "Ready to work with your data"
              : "Connect an AI provider"}
          </div>
          <div className={styles.emptyStateDescription}>
            {state.providerConfig
              ? "Ask a question, upload a file, or request changes to the active Office document."
              : "Add your Azure OpenAI or OpenAI-compatible settings before starting a chat."}
          </div>
          <div className={styles.suggestionList} aria-label="Example prompts">
            <div className={styles.suggestionChip}>
              Summarize the active sheet
            </div>
            <div className={styles.suggestionChip}>
              Find anomalies in this data
            </div>
            <div className={styles.suggestionChip}>
              Create a chart from selected cells
            </div>
          </div>
          {!state.providerConfig && onOpenSettings && (
            <Button appearance="primary" onClick={onOpenSettings} size="small">
              Open Settings
            </Button>
          )}
        </div>
      </div>
    );
  }

  // Transient assistant messages carry FSM nudge text aimed at the LLM
  // (e.g. "Your previous tool call was cut off because the response hit
  // the max output-token limit…"). The agent emits them so the UI knows
  // a recovery is in flight, but the raw text is developer-facing and
  // briefly leaks into the visible transcript before the next real turn
  // clears it (blueprint §8 ephemeral resend-then-drop). Filter them out
  // of the rendered chat — the `LoadingIndicator` below already conveys
  // "agent is still working", and `dropTransientMessages` in
  // `chat-context` still purges them from state on the next non-transient
  // message_start.
  const visibleMessages = state.messages.filter((m) => m.transient !== true);
  const groups = groupMessages(visibleMessages);
  const showLoading = state.isStreaming;
  const lastGroup = groups[groups.length - 1];
  const isStreamingAssistant =
    state.isStreaming && lastGroup?.type === "assistant";

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      className={styles.messageList}
    >
      {groups.map((group, i) => {
        if (group.type === "user") {
          return <UserBubble key={group.message.id} message={group.message} />;
        }
        const groupKey = group.messages.map((m) => m.id).join("-");
        return (
          <div key={groupKey}>
            <AssistantBubble
              messages={group.messages}
              isStreaming={isStreamingAssistant && i === groups.length - 1}
            />
          </div>
        );
      })}
      {showLoading && <LoadingIndicator />}
    </div>
  );
}
