import { ApplicationInsights } from "@microsoft/applicationinsights-web";
import { isAirGappedMode } from "./airgap-config";
import { getRuntimeConfigSync } from "./runtime-config";

let appInsights: ApplicationInsights | null = null;
let initialized = false;

interface TelemetryConfig {
  enabled: boolean;
  connectionString: string;
  includeUsernameForEntra: boolean;
}

function getTelemetryConfig(): TelemetryConfig {
  const runtime = getRuntimeConfigSync();

  let envEnabled = false;
  let envConnectionString = "";
  let envIncludeUsername = false;

  try {
    const env = (
      import.meta as unknown as Record<string, Record<string, string>>
    ).env;
    envEnabled = env?.VITE_APPINSIGHTS_ENABLED === "true";
    envConnectionString = env?.VITE_APPINSIGHTS_CONNECTION_STRING || "";
    envIncludeUsername =
      env?.VITE_APPINSIGHTS_INCLUDE_USERNAME_FOR_ENTRA === "true";
  } catch {
    // Ignore environments without Vite-style import.meta.env.
  }

  return {
    enabled: (runtime.appInsightsEnabled || envEnabled) && !isAirGappedMode(),
    connectionString:
      runtime.appInsightsConnectionString || envConnectionString || "",
    includeUsernameForEntra:
      runtime.includeUsernameForEntra || envIncludeUsername,
  };
}

export function shouldIncludeUsernameForEntra(): boolean {
  return getTelemetryConfig().includeUsernameForEntra;
}

export function initTelemetry(): void {
  if (initialized) return;
  initialized = true;

  const config = getTelemetryConfig();
  if (!config.enabled || !config.connectionString) {
    return;
  }

  appInsights = new ApplicationInsights({
    config: {
      connectionString: config.connectionString,
      disableAjaxTracking: true,
      disableFetchTracking: true,
      enableAutoRouteTracking: false,
    },
  });

  appInsights.loadAppInsights();
  appInsights.trackPageView({ name: "taskpane" });

  window.addEventListener("error", (event) => {
    const error =
      event.error instanceof Error
        ? event.error
        : new Error(event.message || "window error");
    appInsights?.trackException({ exception: error });
  });

  window.addEventListener("unhandledrejection", (event) => {
    const error =
      event.reason instanceof Error
        ? event.reason
        : new Error(
            typeof event.reason === "string"
              ? event.reason
              : "unhandled rejection",
          );
    appInsights?.trackException({ exception: error });
  });
}

export function setAuthenticatedUser(username: string): void {
  if (!username.trim()) return;
  appInsights?.setAuthenticatedUserContext(username);
}

export function truncateForTelemetry(value: string, maxLen = 8192): string {
  return value.length > maxLen ? value.slice(0, maxLen) : value;
}

export function trackEvent(
  name: string,
  properties: Record<string, string> = {},
  measurements?: Record<string, number>,
): void {
  appInsights?.trackEvent({ name, measurements }, properties);
}
