import type {
  ToolContent,
  ToolResultMessage,
  ToolResultReference,
} from "../types";

export const TOOL_RESULT_OFFLOAD_BUDGET_FRACTION = 0.25;
export const TOOL_RESULT_REFERENCE_PREVIEW_MAX_CHARS = 1600;
export const TOOL_RESULT_OFFLOAD_MIN_THRESHOLD_TOKENS = 256;

export interface ToolResultOffloadOptions {
  enabled: boolean;
  runId: string;
  persistentBudgetTokens: number;
  absoluteMaxTokens: number;
  estimateTokens: (message: ToolResultMessage) => number;
  writeFile: (path: string, content: string) => Promise<void>;
}

export interface ToolResultOffloadOutcome {
  message: ToolResultMessage;
  offloaded: boolean;
  error?: unknown;
}

export function resolveToolResultOffloadThresholdTokens(
  persistentBudgetTokens: number,
  absoluteMaxTokens: number,
): number {
  const budgetThreshold = Math.floor(
    Math.max(0, persistentBudgetTokens) * TOOL_RESULT_OFFLOAD_BUDGET_FRACTION,
  );
  return Math.max(
    TOOL_RESULT_OFFLOAD_MIN_THRESHOLD_TOKENS,
    Math.min(Math.max(1, absoluteMaxTokens), budgetThreshold || 1),
  );
}

function textFromContent(content: ToolContent[]): string {
  return content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n");
}

function detectMediaType(text: string): ToolResultReference["mediaType"] {
  const trimmed = text.trim();
  if (!trimmed || (trimmed[0] !== "{" && trimmed[0] !== "[")) {
    return "text/plain";
  }
  try {
    JSON.parse(trimmed);
    return "application/json";
  } catch {
    return "text/plain";
  }
}

function sanitizePathSegment(value: string): string {
  const sanitized = value.replace(/[^a-zA-Z0-9_-]/g, "-").slice(0, 48);
  return sanitized || "item";
}

async function sha256Hex(text: string): Promise<string> {
  const bytes = new TextEncoder().encode(text);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)]
    .map((value) => value.toString(16).padStart(2, "0"))
    .join("");
}

export function buildToolResultPreview(
  text: string,
  maxChars = TOOL_RESULT_REFERENCE_PREVIEW_MAX_CHARS,
): string {
  const limit = Math.max(0, Math.floor(maxChars));
  if (text.length <= limit) return text;
  if (limit === 0) return "";

  const marker = "\n\n[... full result is available at the VFS path ...]\n\n";
  const retained = Math.max(0, limit - marker.length);
  const headChars = Math.floor(retained * 0.7);
  const tailChars = retained - headChars;
  return `${text.slice(0, headChars)}${marker}${
    tailChars > 0 ? text.slice(-tailChars) : ""
  }`.slice(0, limit);
}

function compactReferenceText(reference: ToolResultReference): string {
  return [
    "[Oversized tool result offloaded to the session VFS]",
    `Path: ${reference.path}`,
    `Media type: ${reference.mediaType}`,
    `Characters: ${reference.chars}`,
    `SHA-256: ${reference.sha256}`,
    "Use read with offset/limit or bash grep on this path to retrieve details.",
    "",
    "Preview:",
    reference.preview,
  ].join("\n");
}

export async function maybeOffloadToolResult(
  message: ToolResultMessage,
  options: ToolResultOffloadOptions,
): Promise<ToolResultOffloadOutcome> {
  if (!options.enabled || message.isError || message.reference) {
    return { message, offloaded: false };
  }

  const text = textFromContent(message.content);
  if (!text) return { message, offloaded: false };

  const threshold = resolveToolResultOffloadThresholdTokens(
    options.persistentBudgetTokens,
    options.absoluteMaxTokens,
  );
  if (options.estimateTokens(message) <= threshold) {
    return { message, offloaded: false };
  }

  try {
    const [contentHash, callIdHash] = await Promise.all([
      sha256Hex(text),
      sha256Hex(message.toolCallId),
    ]);
    const path = `/home/user/uploads/working-set/tool-results/${sanitizePathSegment(options.runId)}/${sanitizePathSegment(message.toolCallId)}-${callIdHash.slice(0, 8)}.txt`;
    await options.writeFile(path, text);

    const reference: ToolResultReference = {
      path,
      mediaType: detectMediaType(text),
      chars: text.length,
      sha256: contentHash,
      preview: buildToolResultPreview(text),
    };
    const nonText = message.content.filter((block) => block.type !== "text");
    return {
      offloaded: true,
      message: {
        ...message,
        content: [
          { type: "text", text: compactReferenceText(reference) },
          ...nonText,
        ],
        reference,
      },
    };
  } catch (error) {
    return { message, offloaded: false, error };
  }
}
